let customers = [];
let filteredCustomers = [];

// Is this actually a phone number? Mirrors lib/phoneNumber.mjs phoneProblem —
// change both together, test/phoneMirror.test.mjs holds them to each other.
// Catches only what CANNOT be a number (too short, too long, letters); every
// plausible international number passes, because refusing a real customer's
// number is worse than passing an odd one through.
function phoneProblem(raw) {
  const s = String(raw == null ? '' : raw).trim();
  if (!s) return { code: 'missing', message: 'No number.' };
  if (/[a-z]/i.test(s)) return { code: 'letters', message: 'That has letters in it — a number, please.' };
  if (/\+/.test(s.slice(1))) return { code: 'shape', message: 'The + belongs at the front, once.' };
  const d = s.replace(/\D/g, '');
  if (!d) return { code: 'missing', message: 'No number.' };
  if (d.length < 7) return { code: 'short', message: `Too short to be a phone number — ${d.length} digit${d.length === 1 ? '' : 's'}.` };
  if (d.length > 15) return { code: 'long', message: `Too long to be a phone number — ${d.length} digits, the most any number has is 15.` };
  // The country code that got dropped — see lib/phoneNumber.mjs for why this
  // shape and only this shape. A UK mobile typed with + for the leading 0.
  if (d.length === 10 && d.startsWith('7')) {
    return { code: 'nocc', message: 'That looks like a UK mobile with the 44 missing — try 07\u2026 or +447\u2026' };
  }
  return null;
}

// Phone numbers for HUMANS — display-only grouping; storage stays canonical
// (+447974924585). Mirrors lib/ukPhone.mjs formatPhoneDisplay: UK mobiles
// 4-3-3 (+44 7974 924 585), UK landlines 3-3-4, +972 and +1 their usual
// shapes, sender IDs / short codes untouched. Use at every render site;
// never feed the output back into a save.
function fmtPhone(raw) {
  const s = String(raw == null ? '' : raw).trim();
  if (!s) return '';
  if (/[A-Za-z]/.test(s)) return s;
  let n = s.replace(/[\s().\-]/g, '');
  if (n.startsWith('00')) n = '+' + n.slice(2);
  const digits = n.replace(/\D/g, '');
  if (!n.startsWith('+')) {
    if (n.startsWith('44') && digits.length >= 11) n = '+' + n;
    else if (n.startsWith('0') && digits.length >= 10 && digits.length <= 12) n = '+44' + n.slice(1);
    // Bare international digits — the rental inventory stores handsets this
    // way ("17185998801"), so US/Canada/Israel numbers were rendering raw on
    // the availability calendar. Mirrors formatPhoneDisplay in lib/ukPhone.mjs;
    // change both together. Only an explicit country code with the right digit
    // count is promoted — a bare 10-digit number stays as it is, because it is
    // genuinely ambiguous.
    else if (/^1\d{10}$/.test(digits)) n = '+' + digits;
    else if (/^972\d{8,9}$/.test(digits)) n = '+' + digits;
    else return s;
  }
  const cc = ['+972', '+44', '+1'].find(c => n.startsWith(c));
  if (!cc) return n;
  const rest = n.slice(cc.length).replace(/\D/g, '');
  const group = (str, sizes) => {
    const out = []; let i = 0;
    for (const sz of sizes) { if (i >= str.length) break; out.push(str.slice(i, i + sz)); i += sz; }
    if (i < str.length) out.push(str.slice(i));
    return out.join(' ');
  };
  if (cc === '+44' && rest.length === 10) return '+44 ' + (rest[0] === '7' ? group(rest, [4, 3, 3]) : group(rest, [3, 3, 4]));
  if (cc === '+972' && rest.length === 9) return '+972 ' + group(rest, [2, 3, 4]);
  if (cc === '+972' && rest.length === 8) return '+972 ' + group(rest, [1, 3, 4]);
  if (cc === '+1' && rest.length === 10) return '+1 ' + group(rest, [3, 3, 4]);
  return cc + ' ' + rest;
}

// Mirror of WHATSAPP_ENABLED in lib/flags.js — main.js is a plain script and
// cannot import it. Change both together. Off = waLink() returns '' , which
// removes every "Open in WhatsApp" button (they are all guarded on it).
const WHATSAPP_ENABLED = false;

// WhatsApp deep link for a customer's phone. Only builds a wa.me URL — staff
// press send inside WhatsApp themselves, so this stays within the app's
// nothing-is-auto-sent discipline. Returns '' when there's no usable phone.
function waPhoneDigits(phone) {
  const s = String(phone == null ? '' : phone).trim();
  let d = s.replace(/\D/g, '');
  if (!d) return '';
  if (d.startsWith('00')) d = d.slice(2);
  else if (d.startsWith('0')) d = '44' + d.slice(1); // UK local format
  else if (!s.startsWith('+') && d.length <= 10) d = '44' + d; // no country code
  return d;
}
function waLink(customer, text) {
  if (!WHATSAPP_ENABLED) return '';
  const digits = waPhoneDigits(customer && customer.phone);
  if (!digits) return '';
  return `https://wa.me/${digits}${text ? '?text=' + encodeURIComponent(text) : ''}`;
}

// Phone search that survives formatting: "07871 385566" must find a customer
// stored as "+44 7871385566". Engages only when the query holds 3+ digits.
// Mirrors lib/customerSearch.mjs — change both together
// (test/customerSearch.test.mjs holds them to the same answers).
function phoneDigitsMatch(query, customer) {
  const qd = String(query == null ? '' : query).replace(/\D/g, '');
  if (qd.length < 3 || !customer) return false;
  const hay = String(customer.phone || '').replace(/\D/g, '');
  if (!hay) return false;
  if (hay.includes(qd)) return true;
  return qd.startsWith('0') && hay.includes('44' + qd.slice(1));
}

// Every name this person is filed under — the current one first.
//
// A merged-away spelling still has to find him. When two records of one man
// are merged, the losing spelling is kept on the survivor as `aka`: Shmuel
// Bleier was also filed as "Shmiel Y Bleier" and the shop had been typing
// "Shmiel" for a year. Search that reads only the surviving name turns the old
// spelling into a dead end, which is worse than the duplicate was.
function customerNames(c) {
  const out = [`${c?.firstName || ''} ${c?.lastName || ''}`.trim()];
  const aka = c?.aka;
  for (const n of (Array.isArray(aka) ? aka : aka ? [aka] : [])) {
    const v = String(n || '').trim();
    if (v && !out.some(x => x.toLowerCase() === v.toLowerCase())) out.push(v);
  }
  return out.filter(Boolean);
}

// THE customer match — the Customers list, the picker and the palette all ask
// this, so a query can never find someone in one box and not in the next.
function customerMatches(query, c) {
  const q = String(query == null ? '' : query).toLowerCase().trim();
  if (!q) return true;
  if (!c) return false;
  if (customerNames(c).some(n => n.toLowerCase().includes(q))) return true;
  if (String(c.email || '').toLowerCase().includes(q)) return true;
  return phoneDigitsMatch(q, c);
}

// The master customers array stays sorted A–Z (first name, then surname) at
// all times: every picker in the app — rentals, bookings, SIMs, repairs,
// services, POS, VN, Kol Torah, tasks — renders straight off this array, so
// sorting here once beats sorting at nine call sites. The Customers tab still
// applies its own explicit sort (customerSort) on top when rendering rows.
// localeCompare so Hebrew/Yiddish names collate properly alongside English.
function sortCustomersAZ() {
  customers.sort((a, b) =>
    `${a.firstName || ''} ${a.lastName || ''}`.trim().localeCompare(
      `${b.firstName || ''} ${b.lastName || ''}`.trim(), undefined, { sensitivity: 'base' }));
}
let selectedId = null;
let currentTab = 'customers';
// Customer-360 page state: non-null while the full-page profile
// (/customers/<id>) is what the content column is showing. The card overlay
// and the page never show the same customer at once — renderDetailPanel
// redirects to the page when it's up.
let customerPageId = null;
let customerPageTab = 'overview'; // overview | activity
let customerPageCat = 'all';      // activity-log category filter
let searchTerm = '';
let customerSort = 'surname'; // name | surname | name_desc | surname_desc | owed | recent | services
let customerFilter = 'all'; // all | rental | flight | sim | vn | repair | arrears | passport
// The phone-book jump (owner, 23 Aug): on the Customers tab, pressing a bare
// letter narrows the list to that initial — of the SORT column, so it follows
// what the header says the rows are ordered by. Same letter again, or Escape,
// clears it. '' = off.
let customerInitial = '';

// ─────────────────────────────────────────────
//  INIT — called directly since script loads after DOM is ready
// ─────────────────────────────────────────────
// Which whole-array-saved collections failed to load. CRITICAL: rentals,
// phones and sims persist by POSTing the ENTIRE in-memory array — the server
// deletes any row not present. So if a load fails and we silently treat it as
// an empty list, the next whole-array save would DELETE every real row. We
// track the failure and hard-block those saves until a clean reload.
let loadFailed = {};

// Load an array endpoint safely: a rejected fetch, a non-OK status, or a body
// that isn't an array all count as FAILURE (not "empty") — recorded so saves
// are blocked. Returns [] for rendering either way.
async function safeLoadArray(key, url) {
  try {
    const r = await kcFetch(url);
    if (!r.ok) throw new Error('HTTP ' + r.status);
    const j = await r.json();
    if (!Array.isArray(j)) throw new Error('not an array');
    loadFailed[key] = false;
    return j;
  } catch (e) {
    loadFailed[key] = true;
    return [];
  }
}

async function initApp() {
  // Everything loads in PARALLEL — one round-trip of wall-clock time instead
  // of ten. The three whole-array-saved collections (rentals/phones/sims) go
  // through safeLoadArray so a failed load can't masquerade as "empty" and
  // trigger a fleet-wide delete on the next save.
  const arr = v => (Array.isArray(v) ? v : []);
  loadFailed = {};
  const [cust, rent, ph, sm, bk, vn, rp, so, cfg, menu, me] = await Promise.all([
    // Customers and bookings go through safeLoadArray too. They aren't
    // whole-array saved, so this isn't about delete-protection — it's that a
    // failed load used to return [] indistinguishably from "none", and the
    // customers tab then said "No customers yet." over 751 real records.
    safeLoadArray('customers', '/api/customers'),
    safeLoadArray('rentals', '/api/rentals'),
    safeLoadArray('phones', '/api/phones'),
    safeLoadArray('sims', '/api/sims'),
    safeLoadArray('bookings', '/api/bookings'),
    window.api.getVirtualNumbers().catch(() => []),
    // Repairs + service orders load up-front too, so customer badges/services
    // reflect them before their tabs are ever opened (same as bookings/SIMs).
    window.api.getRepairs().catch(() => []),
    window.api.getServiceOrders().catch(() => []),
    window.api.getSettings().catch(() => null),
    window.api.getServiceMenu('sim').catch(() => []),
    kcFetch('/api/auth/me').then(r => r.json()).catch(() => null),
  ]);
  customers = arr(cust);
  sortCustomersAZ();
  filteredCustomers = [...customers];
  rentals = arr(rent);
  phones = arr(ph);
  sims = arr(sm);
  bookings = arr(bk);
  virtualNumbers = arr(vn);
  repairs = arr(rp);
  serviceOrders = arr(so);
  pricingConfig = cfg;
  // #42 — if the pricing settings didn't load, every price silently uses a
  // built-in fallback. Never silent: warn prominently so nobody charges at
  // the wrong rate.
  if (!cfg) {
    console.warn('[settings] pricing config failed to load — using built-in fallback rates');
    showReloadBanner('Couldn’t load your pricing settings — prices may be using built-in defaults. Reload before charging.');
  }
  simMenu = arr(menu);
  if (me?.success && me.authEnabled) {
    currentStaff = me.staff || null;
    allowedTabs = Array.isArray(me.allowedTabs) ? me.allowedTabs : null;
  }
  renderSidebarUser();
  // A failed load of a whole-array collection: warn, block saves, offer reload.
  const failedKeys = Object.keys(loadFailed).filter(k => loadFailed[k]);
  if (failedKeys.length) {
    // Only the whole-array collections have their saves paused (saveBlocked).
    // Customers and bookings save per row, so promising a pause that isn't
    // happening would be its own false statement.
    const paused = failedKeys.filter(k => ['rentals', 'phones', 'sims'].includes(k));
    showReloadBanner(`Couldn’t load ${failedKeys.join(', ')} — some data is missing.` +
      (paused.length ? ' Saving is paused to protect your records.' : ' Reload before relying on what you see.'));
  }
  if (allowedTabs && allowedTabs.length === 0) {
    document.getElementById('mainContent').innerHTML = `<div class="empty-state">
      <div class="emoji kc-ic kc-ic-lock"></div>
      <p>No areas are enabled for your account.</p>
      <small>Ask the owner to set them under Settings → Team, then sign in again.</small></div>`;
    return;
  }
  applyTabVisibility();
  reconcilePhoneStatuses();
  // Open the tab named in the URL (/rentals …), defaulting to the dashboard.
  // A path a helper isn't allowed drops to their first permitted tab.
  let startTab = tabFromPath();
  if (allowedTabs && !allowedTabs.includes(startTab)) {
    startTab = allowedTabs.includes('dashboard') ? 'dashboard' : allowedTabs[0];
  }
  syncNavActive(startTab);
  // /customers/<id> deep-link: open the full-page profile, not the list.
  // (startTab already passed the allowedTabs gate above, so a helper without
  // the Customers tab never reaches the profile either.)
  const startCustomer = startTab === 'customers' ? customerIdFromPath() : null;
  if (startCustomer) {
    renderCustomerPage(startCustomer);
    pushCustomerUrl(startCustomer, true);
  } else {
    pushTabUrl(startTab, true); // canonicalise the address bar without a history entry
    renderTab(startTab);
  }
  hideBootLoader(); // first tab painted — reveal the app

  setupNav();
  setupSearch();
  setupModal();
  setupTopbarButtons();
  updateThemeBtns(); // sync the persistent topbar toggle's icon to the saved theme
  updateTextSizeBtns(); // …and the Simple Mode button's label to the saved size
  document.addEventListener('click', e => {
    if (!e.target.closest('.cs-wrap')) {
      document.querySelectorAll('.cs-list.open').forEach(el => el.classList.remove('open'));
    }
  });
  // Same-day ⏰ reminders: check every 20s while the app is open.
  checkLocalReminders();
  setInterval(checkLocalReminders, 20000);
  // Carrier post, live (owner ask #16, 20 Aug: "a small pop-up when carrier
  // mail arrived, for a few seconds? so that a worker on the app sees live
  // interaction"). One cheap poll a minute — a count and the newest lines,
  // never the mailbox — and a toast per fresh message. The watermark starts at
  // page load: mail from before you opened the app is the Mail tab's job.
  kcMailSeenAt = new Date().toISOString();
  setInterval(kcMailPulse, 60000);
  // The same for texts a customer sends (owner, 25 Aug). The first poll runs
  // straight away to set the watermark and paint the badge, so the rail is
  // right before anybody has looked at the dashboard.
  kcTextPulse();
  setInterval(kcTextPulse, 60000);
}

// ── Live carrier-post pulse (issue #16) ─────────────────────────────────────
let kcMailSeenAt = null;
let kcMailPulseBusy = false;
async function kcMailPulse() {
  // Not while hidden: twenty parked tabs polling is a tiny stampede, and the
  // person is not there to see a toast anyway.
  if (document.hidden || kcMailPulseBusy || !kcMailSeenAt) return;
  kcMailPulseBusy = true;
  try {
    const d = await kcFetch('/api/sim-mail?since=' + encodeURIComponent(kcMailSeenAt))
      .then(r => r.json()).catch(() => null);
    if (!d?.success || !d.count) return;
    // The watermark only ever advances to a SERVER timestamp. Advancing it to
    // the client's own clock would let a skewed clock skip mail forever; on a
    // quiet minute it simply stays put, which costs nothing — an empty answer
    // is the same few bytes whatever the window.
    kcMailSeenAt = d.latest[0]?.receivedAt || kcMailSeenAt;
    if (d.count <= 3 && !d.capped) {
      // A working counter sees each arrival by name, oldest first.
      for (const m of d.latest.slice(0, 3).reverse()) {
        toast(`Carrier post — ${m.carrier || 'unknown carrier'}: ${m.subject || '(no subject)'}`, 'success', 'inbox');
      }
    } else {
      // Back from lunch (or a burst): one compact catch-up, never a replay —
      // a drip of stale toasts teaches everyone to ignore the live ones.
      toast(`${d.capped ? 'More than 5' : d.count} carrier posts arrived — see Carrier Mail`, 'success', 'inbox');
    }
  } finally { kcMailPulseBusy = false; }
}

function reconcilePhoneStatuses() {
  // NEVER reconcile on incomplete data: if rentals or phones failed to load,
  // the derived statuses would be wrong and a save would persist a fleet-wide
  // wipe. This read used to trigger a destructive whole-fleet write on init.
  if (loadFailed.rentals || loadFailed.phones) return;
  const activePhoneIds = new Set(
    rentals.filter(r => r.status === 'active' || r.status === 'overdue').map(r => r.phoneId)
  );
  // A line imported from the rental sheet is 'rented' because the sheet said
  // so: the rental itself predates the app and has NO record here. Without
  // this guard the loop below reads "rented but no active rental" as "must
  // have been returned" and frees the phone — on the 114-line import that is
  // 77 phones marked available on first page load, saved, in one pass, with
  // no way to tell which. Only lines the app itself tracks get reconciled.
  const tracked = new Set(rentals.map(r => r.phoneId));
  let changed = false;
  phones.forEach(p => {
    const shouldBeRented = activePhoneIds.has(p.id);
    if (shouldBeRented && p.status !== 'rented') {
      p.status = 'rented';
      changed = true;
    } else if (!shouldBeRented && p.status === 'rented') {
      if (p.importSource && !tracked.has(p.id)) return;   // held off-system
      p.status = 'available';
      changed = true;
    }
  });
  if (changed) window.api.saveAllPhones(phones);
}

// Prominent, dismiss-proof banner when critical data failed to load. Saving
// stays blocked until the operator reloads and everything loads cleanly.
function showReloadBanner(msg) {
  if (document.getElementById('kcReloadBanner')) return;
  const b = document.createElement('div');
  b.id = 'kcReloadBanner';
  b.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:6000;background:var(--danger-solid);color:#fff;padding:11px 18px;text-align:center;font-size:var(--fs-ui);font-weight:500;box-shadow:0 2px 8px rgba(0,0,0,.2);';
  b.innerHTML = `<i class="kc-ic kc-ic-alert" aria-hidden="true"></i> ${escHtml(msg)} <button onclick="location.reload()" style="margin-left:12px;background:#fff;color:var(--danger-solid);border:none;border-radius:7px;padding:5px 14px;cursor:pointer;font-weight:700;">↻ Reload</button>`;
  document.body.appendChild(b);
}

// The three whole-array savers refuse to write while that collection's load
// failed — the save would delete every row the server still holds.
function saveBlocked(key) {
  if (loadFailed[key]) {
    toast(`${key} didn’t load fully — reload before saving so nothing is lost.`, 'error');
    showReloadBanner(`Couldn’t load ${key} — saving is paused to protect your records.`);
    return true;
  }
  return false;
}

// ─────────────────────────────────────────────
//  NAVIGATION
// ─────────────────────────────────────────────
// ── URL ⇄ tab (deep-linkable screens) ─────────────────────────────────────
// Each tab has its own path: /rentals, /customers … and the dashboard at "/".
// pages/[tab].js serves the same shell for those paths, so a refresh or a
// shared link opens the right screen. Here we keep the address bar in step as
// the operator navigates, and honour the browser Back / Forward buttons.
function tabFromPath() {
  const seg = (location.pathname || '/').replace(/^\/+|\/+$/g, '').split('/')[0].toLowerCase();
  return TAB_META[seg] ? seg : 'dashboard';
}
function tabUrl(tab) { return tab === 'dashboard' ? '/' : '/' + tab; }
function pushTabUrl(tab, replace) {
  const url = tabUrl(tab);
  if (location.pathname === url) return; // already there — no duplicate entry
  try { history[replace ? 'replaceState' : 'pushState']({ kcTab: tab }, '', url); }
  catch { /* history API blocked (e.g. sandboxed) — navigation still works */ }
}
// The Customer-360 page lives one segment deeper: /customers/<id>.
// pages/customers/[id].js serves the same shell for it, so a refresh or a
// link pasted to a colleague lands on the profile, not the list.
function customerIdFromPath() {
  const parts = (location.pathname || '/').replace(/^\/+|\/+$/g, '').split('/');
  return parts[0] === 'customers' && parts[1] ? decodeURIComponent(parts[1]) : null;
}
function pushCustomerUrl(id, replace) {
  const url = '/customers/' + encodeURIComponent(id);
  if (location.pathname === url) return; // already there — no duplicate entry
  try { history[replace ? 'replaceState' : 'pushState']({ kcTab: 'customers', kcCustomer: String(id) }, '', url); }
  catch { /* history API blocked (e.g. sandboxed) — navigation still works */ }
}
function syncNavActive(tab) {
  document.querySelectorAll('.nav-item').forEach(n => {
    const on = n.dataset.tab === tab;
    n.classList.toggle('active', on);
    // The active tab was carried by colour alone; aria-current states it.
    if (on) n.setAttribute('aria-current', 'page'); else n.removeAttribute('aria-current');
  });
}

// Small "signed in as" identity in the sidebar footer. Handy when staff share
// a counter — it makes clear who the communication log / cash-up will attribute
// actions to. Stays hidden when auth is disabled (no staff to show).
function renderSidebarUser() {
  const el = document.getElementById('sidebarUser');
  if (!el) return;
  const name = (currentStaff && String(currentStaff.full_name || currentStaff.email || '').trim()) || '';
  if (!name) { el.hidden = true; el.innerHTML = ''; return; }
  const initials = name.split(/\s+/).filter(Boolean).slice(0, 2).map(w => w[0].toUpperCase()).join('') || name[0].toUpperCase();
  const role = currentStaff.role === 'owner' ? 'Admin' : 'Helper';
  el.innerHTML = `
    <span class="su-avatar">${escHtml(initials)}</span>
    <span class="su-meta">
      <span class="su-name" title="${escHtml(name)}">${escHtml(name)}</span>
      <span class="su-role">${escHtml(role)}</span>
    </span>`;
  el.hidden = false;
}

function setupNav() {
  document.querySelectorAll('.nav-item').forEach(item => {
    // These are real <a href="/rentals"> now, so Tab/Enter and the browser's
    // own "open in a new tab" work without help. Only the plain left click is
    // ours to take: ⌘/Ctrl/Shift-click and middle-click must reach the browser
    // untouched, or the app quietly breaks a thing every other site does.
    // (Middle-click fires auxclick, not click, so it never gets here anyway —
    // the guard is for the modified left clicks.)
    item.addEventListener('click', (e) => {
      if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || e.button !== 0) return;
      e.preventDefault();
      const tab = item.dataset.tab;
      syncNavActive(tab);
      currentTab = tab;
      renderTab(tab);
      pushTabUrl(tab); // reflect the screen in the address bar (new history entry)
    });
    item.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); item.click(); }
    });
  });
  // B8 — phone drawer. The burger slides the sidebar in; the scrim, Escape,
  // or choosing any destination slides it back out.
  // On desktop the same burger instead collapses the sidebar to an icon rail
  // (body.nav-collapsed, ⌘B/Ctrl+B too), remembered per browser. Two good
  // states — full or rail — PLUS a width of your own: the grip on the rail's
  // right edge (owner, 18 Aug 2026), remembered the same way.
  const burger = document.getElementById('navBurger');
  const scrim = document.getElementById('navScrim');
  const isPhone = () => window.matchMedia('(max-width: 820px)').matches;
  // The burger stays in the top bar in every state, and that is deliberate
  // (owner, 20 Aug: "why is this button not on the sidebar?"). It cannot live
  // on the sidebar on a phone — the sidebar is off-canvas there, so the control
  // that opens it would be off-screen with it. Putting it on the sidebar only
  // while expanded would move it depending on the state, and a control that
  // changes address is one the hand has to look for. Here it is the same pixel
  // whichever of the three states the menu is in.
  //
  // What it lacked was saying so. It carried an aria-label a screen reader
  // could read and nothing a pointer could, so what it does — and that ⌘B does
  // it too — was invisible to everybody else.
  const burgerHint = (label) => {
    burger?.setAttribute('aria-label', label);
    burger?.setAttribute('title', `${label} (${navigator.platform.startsWith('Mac') ? '⌘B' : 'Ctrl B'})`);
  };
  const setNavOpen = (open) => {
    document.body.classList.toggle('nav-open', open);
    burger?.setAttribute('aria-expanded', String(open));
    burgerHint(open ? 'Close menu' : 'Open menu');
  };
  const setCollapsed = (on) => {
    document.body.classList.toggle('nav-collapsed', on);
    burgerHint(on ? 'Expand menu' : 'Collapse menu');
    // Rail rows show icons only — surface each label as a native tooltip.
    document.querySelectorAll('.sidebar .nav-item, .sidebar .nav-link, .sidebar .sb-row').forEach(el => {
      if (on) el.title = el.textContent.trim();
      else el.removeAttribute('title');
    });
    try { localStorage.setItem('kcNavCollapsed', on ? '1' : '0'); } catch { /* private mode */ }
  };
  window.kcToggleNav = () => {
    if (isPhone()) setNavOpen(!document.body.classList.contains('nav-open'));
    else setCollapsed(!document.body.classList.contains('nav-collapsed'));
  };
  try {
    if (!isPhone() && localStorage.getItem('kcNavCollapsed') === '1') setCollapsed(true);
  } catch { /* private mode */ }
  burger?.addEventListener('click', window.kcToggleNav);
  // Say the right thing before anybody presses it, not only after.
  burgerHint(isPhone()
    ? 'Open menu'
    : document.body.classList.contains('nav-collapsed') ? 'Expand menu' : 'Collapse menu');

  // ── Drag the sidebar's right edge ────────────────────────────────────────
  // The floor is where the longest label ("Contacts converter") still fits on
  // one line — narrower would truncate silently, because every nav row is
  // white-space:nowrap and the rail hides its overflow. Below that the rail
  // collapse is the right answer, and it is one keystroke away. The ceiling is
  // where the rail starts eating the working area on a laptop screen.
  const SB_W_KEY = 'kcNavWidth', SB_W_DEFAULT = 224, SB_W_MIN = 184, SB_W_MAX = 380;
  const sbGrip = document.getElementById('navGrip');
  // The width we ASKED for, not the width the box currently paints at. The
  // sidebar carries a 0.2s width transition for the ⌘B rail, so measuring the
  // element mid-animation reads a number on its way somewhere — hold an arrow
  // key and every step would compute from a stale value and crawl.
  let sbW = SB_W_DEFAULT;
  const sbApplyWidth = (px, save = true) => {
    const w = Math.min(SB_W_MAX, Math.max(SB_W_MIN, Math.round(px)));
    sbW = w;
    document.documentElement.style.setProperty('--sb-w', w + 'px');
    sbGrip?.setAttribute('aria-valuenow', String(w));
    if (save) { try { localStorage.setItem(SB_W_KEY, String(w)); } catch { /* private mode */ } }
    return w;
  };
  if (sbGrip) {
    sbGrip.setAttribute('aria-valuemin', String(SB_W_MIN));
    sbGrip.setAttribute('aria-valuemax', String(SB_W_MAX));
    sbGrip.setAttribute('aria-valuenow', String(SB_W_DEFAULT));
    try {
      const stored = Number(localStorage.getItem(SB_W_KEY)) || 0;
      if (stored) sbApplyWidth(stored, false);
    } catch { /* private mode */ }

    sbGrip.addEventListener('pointerdown', (e) => {
      // The rail and the phone drawer own their own width; the grip is hidden
      // in both, and this is the belt to that pair of braces.
      if (isPhone() || document.body.classList.contains('nav-collapsed')) return;
      e.preventDefault();
      const startX = e.clientX, startW = sbW;
      sbGrip.setPointerCapture?.(e.pointerId);
      document.body.classList.add('kc-resizing-x');
      const move = (ev) => sbApplyWidth(startW + (ev.clientX - startX), false);
      const done = (ev) => {
        sbGrip.removeEventListener('pointermove', move);
        sbGrip.removeEventListener('pointerup', done);
        sbGrip.removeEventListener('pointercancel', done);
        document.body.classList.remove('kc-resizing-x');
        // Saved once, at the end — a drag is one decision, not sixty.
        sbApplyWidth(startW + (ev.clientX - startX));
      };
      sbGrip.addEventListener('pointermove', move);
      sbGrip.addEventListener('pointerup', done);
      sbGrip.addEventListener('pointercancel', done);
    });
    sbGrip.addEventListener('keydown', (e) => {
      const step = e.shiftKey ? 40 : 12;
      if (e.key === 'ArrowRight') { e.preventDefault(); sbApplyWidth(sbW + step); }
      else if (e.key === 'ArrowLeft') { e.preventDefault(); sbApplyWidth(sbW - step); }
      else if (e.key === 'Home' || e.key === 'Enter' || e.key === ' ') { e.preventDefault(); sbApplyWidth(SB_W_DEFAULT); }
    });
    sbGrip.addEventListener('dblclick', () => sbApplyWidth(SB_W_DEFAULT));
  }
  scrim?.addEventListener('click', () => setNavOpen(false));
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && document.body.classList.contains('nav-open')) setNavOpen(false);
  });
  document.getElementById('appSidebar')?.addEventListener('click', (e) => {
    if (e.target.closest('.nav-item, .nav-link, .sb-row')) setNavOpen(false);
  });
  // U15 — click-only chips (equipment toggles, click-to-copy values) carry
  // role=button tabindex=0 in their markup; activate them on Enter/Space too.
  document.addEventListener('keydown', (e) => {
    if ((e.key === 'Enter' || e.key === ' ') && e.target?.matches?.('.eq-btn, .copy-val')) {
      e.preventDefault();
      e.target.click();
    }
  });
  // A focused type=number field takes wheel events and silently changes the
  // figure — on a trackpad, scrolling past a filled-in payment box edits the
  // amount with no keystroke and no undo. Blur instead, so the scroll scrolls.
  // Passive: we never preventDefault, the page must keep scrolling normally.
  document.addEventListener('wheel', (e) => {
    const el = document.activeElement;
    if (el && el.type === 'number' && el === e.target) el.blur();
  }, { passive: true });
  // Back / Forward: re-open whatever tab the URL now points at.
  window.addEventListener('popstate', () => {
    const tab = tabFromPath();
    if (allowedTabs && !allowedTabs.includes(tab)) {
      // Back/Forward landed on a tab this helper can't see. Don't leave the URL
      // pointing at forbidden content while the pane still shows the previous tab —
      // re-render an allowed tab and replaceState the URL to match it. audit C22.
      const safe = (allowedTabs.includes(currentTab) ? currentTab : allowedTabs[0]) || 'dashboard';
      syncNavActive(safe);
      currentTab = safe;
      renderTab(safe);
      pushTabUrl(safe, true); // replaceState — keep URL and content in step
      return;
    }
    syncNavActive(tab);
    currentTab = tab;
    // Back/Forward can land on a profile URL (/customers/<id>) as well as a
    // tab — re-open whichever the address now names.
    const cid = tab === 'customers' ? customerIdFromPath() : null;
    if (cid) renderCustomerPage(cid);
    else renderTab(tab);
  });
}

// ── Helper visibility ─────────────────────────────────────────────────────
let currentStaff = null;   // { id, role, full_name, email }
let allowedTabs = null;    // null = everything (owner / auth off)

function applyTabVisibility() {
  document.querySelectorAll('.nav-item').forEach(item => {
    item.style.display = (allowedTabs && !allowedTabs.includes(item.dataset.tab)) ? 'none' : '';
  });
  // A group heading names the rows beneath it, so it has to go when they all
  // do. Hiding the items alone left a helper looking at "SERVICES" with
  // nothing under it and the next heading directly below — a label for an
  // empty set. Walk the list in order: each heading owns every row until the
  // next heading, and survives only if one of them is still on screen.
  let label = null, kept = false;
  const settle = () => { if (label) label.style.display = kept ? '' : 'none'; };
  for (const el of document.querySelectorAll('.sidebar-nav > *')) {
    if (el.classList.contains('nav-group-label')) { settle(); label = el; kept = false; }
    else if (el.style.display !== 'none') kept = true;
  }
  settle();
  kcNavFades();
}

// ── "There is more this way", on the rail ────────────────────────────────
// The nav scrolls on short screens now that its rows no longer shrink — but
// Chromium's overlay scrollbar paints nothing at rest, so at 640px tall eight
// rows (Settings among them) sat below a fold that looked finished. Same
// promise the welcome page's chip strip makes with its trailing fade: a
// gradient at whichever edge still hides rows. CSS owns the fades
// (.sidebar-nav::before/::after); this only says which edges are live.
function kcNavFades() {
  const nav = document.querySelector('.sidebar-nav');
  if (!nav) return;
  nav.classList.toggle('kc-more-above', nav.scrollTop > 4);
  nav.classList.toggle('kc-more-below', nav.scrollTop + nav.clientHeight < nav.scrollHeight - 4);
}
(() => {
  const nav = document.querySelector('.sidebar-nav');
  if (!nav) return;
  nav.addEventListener('scroll', kcNavFades, { passive: true });
  window.addEventListener('resize', kcNavFades);
  // Row heights move without a window resize too — the text-size setting, a
  // tab hidden by role. Observing the nav and its rows catches both.
  if (window.ResizeObserver) {
    const ro = new ResizeObserver(kcNavFades);
    ro.observe(nav);
    for (const el of nav.children) ro.observe(el);
  }
  kcNavFades();
})();

// #49 / #58 — ONE source of truth per destination: its human label, its page
// title, its render fn, whether the search box shows, and (optionally) its
// create action. The sidebar, the <title>, the palette navigate list and the
// topbar's context primary button all read this map, so a rename happens once.
const TAB_META = {
  dashboard: { label: 'Dashboard',         title: 'Business <span>Dashboard</span>',    render: () => renderDashboardTab(), search: false },
  customers: { label: 'Customers',         title: 'Customer <span>Management</span>',   render: () => renderCustomersTab(), search: true,  primary: { label: '+ New customer', run: () => openAddModal() } },
  messages:  { label: 'Messages',           title: 'Customer <span>Messages</span>',     render: () => renderMessagesTab(), search: false },
  rentals:   { label: 'Phone Rentals',     title: 'Phone <span>Rentals</span>',         render: () => renderRentalsTab(),   search: false, primary: { label: '+ New rental',   run: () => openNewRentalModal() } },
  sim:       { label: 'SIM Plans',         title: 'SIM <span>Plans</span>',             render: () => renderSimsTab(),      search: false, primary: { label: '+ New SIM plan', run: () => openAddSimModal() } },
  bookings:  { label: 'Tickets & Flights', title: 'Tickets <span>&amp; Flights</span>', render: () => renderBookingsTab(),  search: false, primary: { label: '+ New booking',  run: () => openNewBookingModal() } },
  wallet:    { label: 'Wallet',            title: 'Wallet <span>&amp; Ledger</span>',   render: () => renderWalletTab(),    search: false },
  // The price list is fetched, not bundled, so every door into the repair
  // dialog has to make sure it has arrived. The palette entry and the customer
  // card's Repair button both await getServiceMenu('repair') first; this one
  // relied on renderRepairsTab() having already finished, which is true when
  // the tab has settled and not guaranteed the instant it is asked for. An
  // empty menu renders "Price list unavailable", and saveNewRepair then refuses
  // with "Pick at least one service" — a dead end with nothing to pick.
  repairs:   { label: 'Repairs',           title: 'Phone <span>Repairs</span>',         render: () => renderRepairsTab(),   search: false, primary: { label: '+ New repair',   run: async () => { if (!repairMenu.length) repairMenu = await window.api.getServiceMenu('repair'); openNewRepairModal() } } },
  services:  { label: 'Online & Print',    title: 'Online <span>&amp; Print</span>',    render: () => renderServicesTab(),  search: false, primary: { label: '+ Charge a service', run: () => openNewServiceModal() } },
  shop:      { label: 'Shop',              title: 'Shop <span>&amp; Stock</span>',      render: () => renderShopTab(),      search: false },
  koltorah:  { label: 'Kol Torah',         title: 'Kol <span>Torah</span>',             render: () => renderKolTorahTab(),  search: false, primary: { label: '+ New job',      run: () => ktFocusNewJob() } },
  tasks:     { label: 'Tasks',             title: 'Task <span>List</span>',             render: () => renderTasksTab(),     search: false },
  review:    { label: 'Confirm Data',      title: 'Confirm <span>Imported Data</span>', render: () => renderConfirmTab(),    search: false },
  mail:      { label: 'Carrier Mail',      title: 'Carrier <span>Mail</span>',          render: () => renderCarrierMailTab(), search: false },
  virtual:   { label: 'Virtual Numbers',   title: 'Virtual <span>Numbers</span>',       render: () => renderVirtualTab(),   search: false, primary: { label: '+ New number',   run: () => openNewVNModal() } },
  settings:  { label: 'Settings',          title: 'System <span>Settings</span>',       render: () => renderSettingsTab(),  search: false },
};
let tabPrimaryAction = null; // #58 — what the topbar primary button does on this tab

// Content never pops in on a single frame — each tab paint re-runs a quiet
// fade + 5px rise on the content column (DESIGN.md §Motion, "Enter"). A
// keyframe restart so rapid tab-hopping always plays from the top; the
// reduced-motion umbrella makes it effectively instant.
function kcContentEnter() {
  const el = document.getElementById('mainContent');
  if (!el) return;
  el.classList.remove('tab-enter');
  void el.offsetWidth; // reflush so re-adding the class restarts the animation
  el.classList.add('tab-enter');
}

function renderTab(tab) {
  if (allowedTabs && !allowedTabs.includes(tab)) {
    toast('That area is not enabled for your account.', 'warning');
    return;
  }
  // #6 — keep currentTab in sync no matter how we got here (nav click OR a
  // direct renderTab() on first load), so async repaints (the dashboard's
  // fresh-money pass) don't skip because currentTab still said 'customers'.
  currentTab = tab;
  // Leaving the full-page profile via any nav: drop the page state AND the
  // selection — otherwise renderCustomersTab would see selectedId and pop the
  // card overlay open the moment the list renders.
  if (customerPageId) { customerPageId = null; selectedId = null; }
  document.body.classList.remove('pos-mode'); // leaving the till via any nav
  posReturnCustomer = null; // a chosen navigation is not an exit — no bounce later
  const searchBox = document.getElementById('searchBox');
  const btnNew = document.getElementById('btnNewCustomer');
  const meta = TAB_META[tab] || TAB_META.customers; // unknown ids fall back to Customers

  document.getElementById('pageTitle').innerHTML = meta.title;
  // The customer-list filter lives IN the customer list now, not in the topbar
  // beside the find field — two search controls in one bar is a choice nobody
  // should have to make, and at 1280px both were squeezed to an ellipsis.
  // renderCustomersTab() moves this node into its section header; every other
  // tab is about to wipe #mainContent, so park it first or the wipe takes the
  // node and the listener setupSearch() bound to it.
  if (searchBox && !meta.search) kcParkSearch();
  if (searchBox) searchBox.style.display = meta.search ? '' : 'none';
  // #58 — the one topbar primary button becomes this tab's create action
  // instead of hiding on every tab but Customers.
  if (btnNew) {
    if (meta.primary) {
      btnNew.style.display = '';
      btnNew.textContent = meta.primary.label;
      tabPrimaryAction = meta.primary.run;
    } else {
      btnNew.style.display = 'none';
      tabPrimaryAction = null;
    }
  }
  kcContentEnter();
  // The row lives ABOVE #mainContent, in its own element, because every render
  // function here owns mainContent.innerHTML outright — anything injected into
  // it would be thrown away by the next repaint, and most of these renders are
  // async. Painted twice on purpose: once from what is already loaded so the
  // row is there immediately, once after the render settles with whatever it
  // fetched.
  kcPaintNextAction(tab);
  // Yield before the heavy part. `meta.render()` used to run inside the press
  // that started the navigation, which meant the browser could not paint
  // anything — not the new title, not the nav highlight — until the whole tab
  // had been built. Measured with `node ops/harness/vitals.mjs` at 4× CPU
  // (a counter tablet, not this machine): Settings answered a press in 280ms,
  // Customers, Tickets and Kol Torah in 208-232ms. Google's "good" bar for INP
  // is 200ms, and INP is the one Web Vital nothing here had ever measured —
  // Lighthouse reports TBT as a lab stand-in for it, and a stand-in is not the
  // thing.
  //
  // rAF-then-setTimeout is the standard shape: the frame callback runs before
  // the paint, the timeout after it, so the press is answered and the tab is
  // built in the next task. What changes on screen is nothing — the .tab-enter
  // animation was already covering this frame.
  //
  // The visibility guard is not decoration: requestAnimationFrame does not fire
  // in a hidden tab, so a first render kicked off in a background tab would
  // simply never happen.
  //
  // Returns a promise now, resolving when the tab is actually on screen. The
  // harness sweeps used to guess with a fixed wait; they can await it.
  const paint = () => Promise.resolve(meta.render())
    .then(() => kcPaintNextAction(tab))
    .catch(() => {});
  return new Promise((resolve) => {
    const go = () => { paint().then(resolve, resolve); };
    if (typeof requestAnimationFrame === 'function' && document.visibilityState !== 'hidden') {
      requestAnimationFrame(() => setTimeout(go, 0));
    } else {
      setTimeout(go, 0);
    }
  });
}

// ══ THE NEXT ACTION ON EVERY SCREEN ══════════════════════════════════════
//
// Port item B2. One row at the top of each screen: standing here, what does
// this person do next? Where the honest answer is "read the page and work it
// out", the screen says it instead — phrased as a verb, computed from that
// screen's own data. Where nothing is outstanding it says so and LOSES the
// button, because an empty queue is a result, not a blank space. In a shop
// where most screens are quiet most of the time, that is the common case.
//
// The decision lives in lib/nextAction.mjs and is mirrored below. This half
// owns only two things: the numbers, and what each action actually does.

// ── KC_NEXT mirror start ──
// Mirrors lib/nextAction.mjs. test/nextActionMirror.test.mjs holds the two
// together, including the check that every action a screen can name exists in
// KC_NEXT_DO below — so a row promising something nothing can perform fails a
// test rather than reaching a counter.
const KC_NEXT = (() => {
  const NOTHING = 'Nothing waiting on you here.';
  function nextAction(spec = {}) {
    if (spec.clear) return { clear: true, text: spec.text || NOTHING };
    const text = String(spec.text || '').trim();
    if (!text) throw new Error('nextAction: a row that is not clear must say what to do');
    const label = String(spec.label || '').trim();
    if (!label) throw new Error(`nextAction: "${text}" names no button`);
    if (!spec.do) throw new Error(`nextAction: "${text}" offers no way to do it — give it a do-key, or mark it clear`);
    return {
      clear: false, text, label, do: String(spec.do),
      count: Number.isFinite(spec.count) ? spec.count : null,
      tone: spec.tone === 'urgent' ? 'urgent' : 'normal',
    };
  }
  const plural = (n, one, many) => `${n} ${n === 1 ? one : many || one + 's'}`;
  const SCREEN_ACTIONS = {
    dashboard(f) {
      // A person waiting on an answer comes before the shop's own business —
      // and only counts while no reply has actually SENT.
      if (f.smsWaiting) return { text: `${plural(f.smsWaiting, 'text')} waiting for an answer`, label: 'Read them', do: 'messages.waiting', count: f.smsWaiting, tone: 'urgent' };
      if (f.overdueRentals) return { text: `${plural(f.overdueRentals, 'phone')} overdue back`, label: 'Chase them', do: 'rentals.overdue', count: f.overdueRentals, tone: 'urgent' };
      if (f.readyRepairs) return { text: `${plural(f.readyRepairs, 'repair')} ready to collect`, label: 'Tell them', do: 'repairs.ready', count: f.readyRepairs };
      if (f.lateRenewals) return { text: `${plural(f.lateRenewals, 'SIM plan')} past the renewal date`, label: 'Check them', do: 'sim.late', count: f.lateRenewals };
      if (f.dueTasks) return { text: `${plural(f.dueTasks, 'task')} due today or overdue`, label: 'Open tasks', do: 'tasks.due', count: f.dueTasks };
      if (f.mailPending) return { text: `${plural(f.mailPending, 'carrier email')} nobody has dealt with`, label: 'Open the mail', do: 'mail.pending', count: f.mailPending };
      return { clear: true };
    },
    messages(f) {
      if (f.smsWaiting) return { text: `${plural(f.smsWaiting, 'text')} waiting for an answer`, label: 'Show them', do: 'messages.waiting', count: f.smsWaiting, tone: 'urgent' };
      return { clear: true };
    },
    customers(f) {
      if (f.unreachable) return { text: `${plural(f.unreachable, 'customer')} with no way to reach them`, label: 'Show them', do: 'customers.unreachable', count: f.unreachable };
      return { clear: true };
    },
    rentals(f) {
      if (f.overdueRentals) return { text: `${plural(f.overdueRentals, 'phone')} overdue back`, label: 'Show them', do: 'rentals.overdue', count: f.overdueRentals, tone: 'urgent' };
      if (f.dueTodayRentals) return { text: `${plural(f.dueTodayRentals, 'rental')} due back today`, label: 'Show them', do: 'rentals.dueToday', count: f.dueTodayRentals };
      return { clear: true };
    },
    sim(f) {
      if (f.lateRenewals) return { text: `${plural(f.lateRenewals, 'SIM plan')} past the renewal date`, label: 'Show them', do: 'sim.late', count: f.lateRenewals, tone: 'urgent' };
      return { clear: true };
    },
    bookings(f) {
      if (f.needCheckIn) return { text: `${plural(f.needCheckIn, 'passenger')} flying soon and not checked in`, label: 'Show them', do: 'bookings.upcoming', count: f.needCheckIn, tone: 'urgent' };
      if (f.unparsedTickets) return { text: `${plural(f.unparsedTickets, 'airline email')} waiting to be read`, label: 'Read them', do: 'bookings.tickets', count: f.unparsedTickets };
      return { clear: true };
    },
    wallet(f) {
      if (f.arrears) return { text: `${plural(f.arrears, 'customer')} in arrears`, label: 'Show them', do: 'wallet.arrears', count: f.arrears };
      return { clear: true };
    },
    repairs(f) {
      if (f.readyRepairs) return { text: `${plural(f.readyRepairs, 'repair')} ready to collect`, label: 'Tell them', do: 'repairs.ready', count: f.readyRepairs };
      return { clear: true };
    },
    shop(f) {
      if (f.lowStock) return { text: `${plural(f.lowStock, 'item')} low on stock`, label: 'Show them', do: 'shop.low', count: f.lowStock };
      if (f.openReturns) return { text: `${plural(f.openReturns, 'supplier return')} still open`, label: 'Show them', do: 'shop.returns', count: f.openReturns };
      return { clear: true };
    },
    tasks(f) {
      if (f.dueTasks) return { text: `${plural(f.dueTasks, 'task')} due today or overdue`, label: 'Start at the top', do: 'tasks.due', count: f.dueTasks, tone: f.highTasks ? 'urgent' : 'normal' };
      return { clear: true };
    },
    review(f) {
      if (f.unconfirmed) return { text: `${plural(f.unconfirmed, 'imported record')} nobody has checked`, label: 'Work the batch', do: 'review.batch', count: f.unconfirmed };
      return { clear: true };
    },
    mail(f) {
      if (f.mailPending) return { text: `${plural(f.mailPending, 'carrier email')} nobody has dealt with`, label: 'Show them', do: 'mail.pending', count: f.mailPending };
      return { clear: true };
    },
    services: () => ({ clear: true }),
    koltorah: () => ({ clear: true }),
    virtual: () => ({ clear: true }),
    settings: () => ({ clear: true }),
  };
  function screenNextAction(screen, facts = {}) {
    const decide = SCREEN_ACTIONS[screen];
    if (!decide) return nextAction({ clear: true });
    return nextAction(decide(facts) || { clear: true });
  }
  return { NOTHING, nextAction, screenNextAction, SCREENS: Object.keys(SCREEN_ACTIONS) };
})();
// ── KC_NEXT mirror end ──

// What each named action DOES. Every one of these already existed — they are
// the same views the command palette offers and the dashboard's metric cards
// open, so the row lands on a list that is already filtered to exactly the
// number it just quoted, rather than on a tab with the filtering left to do.
const KC_NEXT_DO = {
  'rentals.overdue':       () => filterView('rentals', () => { kcView('rentals').dims = { balance: 'all', status: 'overdue' }; }, renderRentalRows),
  'rentals.dueToday':      () => filterView('rentals', () => { kcView('rentals').dims = { balance: 'all', status: 'due_today' }; }, renderRentalRows),
  'sim.late':              () => filterView('sim', () => { simFilterStatus = 'late'; }, renderSimRows),
  'customers.unreachable': () => filterView('customers', () => { customerFilter = 'unreachable'; }, renderTableRows),
  'wallet.arrears':        () => filterView('customers', () => { customerFilter = 'arrears'; }, renderTableRows),
  'repairs.ready':         () => filterView('repairs', () => { kcView('repairs').filter = 'ready'; }),
  'shop.low':              () => filterView('shop', () => { kcView('shop').filter = 'low'; }),
  'shop.returns':          () => { goToTab('shop'); setTimeout(() => focusPanel('shopReturns'), 120); },
  'tasks.due':             () => filterView('tasks', () => { kcView('tasks').filter = 'overdue'; }),
  'bookings.upcoming':     () => filterView('bookings', () => { kcView('bookings').filter = 'upcoming'; }),
  'bookings.tickets':      () => { goToTab('bookings'); setTimeout(() => focusPanel('tmPanel'), 120); },
  'review.batch':          () => { goToTab('review'); setTimeout(() => focusPanel('rvBatch'), 120); },
  'mail.pending':          () => filterView('mail', () => { cmFilter = 'pending'; }),
  // The log lives on Settings and does not load itself, so going there without
  // loading it would land on "press Load the log" — a button that promised to
  // show you something and then asked you to press another button.
  // Works from both ends: from the dashboard it opens the inbox already
  // narrowed; on the inbox it narrows the list you are looking at.
  'messages.waiting':      () => {
    msgFilter = 'waiting';
    if (currentTab === 'messages') paintMessages(); else goToTab('messages');
  },
};

/**
 * Open the message log with the log actually in it.
 *
 * Two callers, one behaviour: the dashboard's "Read them" row, and the command
 * palette. They used to be one caller, and the palette could not reach this
 * screen at all — Ctrl+K for "message", "text" or "reply" returned nothing,
 * so the only way to answer a customer was to know that inbound texts live in
 * Settings, eleventh card down, behind a button that loads them.
 *
 * That mattered more from 25 Aug, when the palette became the front door of
 * the app: a job the front door cannot reach is a job that is hidden.
 */
function openMessageLog() {
  goToTab('messages');
}

/**
 * Go to a panel, and mean it.
 *
 * Scrolling something into view without moving keyboard focus into it is the
 * same dead end for anyone not using a mouse: the page moved, the caret did
 * not, and the next Tab carries on from wherever it already was. Focus lands
 * on the first thing inside that can take it, or on the panel itself with
 * tabindex="-1" when it holds nothing focusable.
 */
function focusPanel(id) {
  const el = document.getElementById(id);
  if (!el) return false;
  const still = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  el.scrollIntoView({ behavior: still ? 'auto' : 'smooth', block: 'start' });
  const target = el.querySelector('a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])');
  if (target) { target.focus({ preventScroll: true }); return true; }
  if (!el.hasAttribute('tabindex')) el.setAttribute('tabindex', '-1');
  el.focus({ preventScroll: true });
  return true;
}

function kcNextDo(key) {
  const run = KC_NEXT_DO[key];
  if (!run) { toast('That view has moved — tell us if you see this.', 'warning'); return; }
  run();
}

/**
 * The counts, taken from the SAME expressions the dashboard uses for its own
 * headline numbers — so the row and the number above it can never disagree.
 */
// A line that is LIVE — billable, coverable, occupying its number. 'Renewal
// pending' is a live line mid-cycle (the sweep flips it while a lapsed date
// waits for its payment check — issue #13), not a lapsed one: every "has a
// SIM" check, count and renewal view must include it, or a line vanishes
// from the app for the days the flip lasts.
function simLive(s) { return !!s && (s.status === 'active' || s.status === 'renewal_pending'); }

function kcNextFacts() {
  const today = localISO();
  const soon = localISO(new Date(Date.now() + 2 * 86400000));
  // "Overdue BACK" is a sentence about a handset somebody is holding. A booked
  // rental is a reservation nobody collected — its date can pass without any
  // phone having left the shop, and counting it here told the Rentals screen
  // "3 phones overdue back" while the tile beside it counted 2 phones out.
  // Same computed status the tile and the list use, so all three agree; the
  // uncollected reservation is a real problem, but it is a different one and
  // it needs a different sentence than "chase the phone".
  const outRentals = (rentals || []).filter(r =>
    KC_STAGE.OUT_WITH_CUSTOMER.includes(getComputedStatus(r, today)));
  const tks = tasksList || [];
  return {
    // Stage, not "any date in the past": the day after a customer lands his
    // phone is out but not late, and "N phones overdue back — chase them" on a
    // hire that ended last night is the kind of alarm people stop reading.
    overdueRentals: outRentals.filter(r =>
      getComputedStatus(r, today) === 'overdue').length,
    dueTodayRentals: outRentals.filter(r => r.toDate === today).length,
    readyRepairs: (repairs || []).filter(r => r.status === 'Ready').length,
    lateRenewals: (sims || []).filter(s => simLive(s) && s.renewalDate && s.renewalDate < today).length,
    dueTasks: tks.filter(t => !t.done && t.dueDate && t.dueDate <= today).length,
    highTasks: tks.filter(t => !t.done && t.priority === 'High').length,
    mailPending: (cmData && cmData.counts && cmData.counts.pending) || 0,
    unreachable: (customers || []).filter(c =>
      !kcTail10(c.phone) && !kcTail10(c.altPhone) && customerSimsOf(c).length === 0).length,
    // Ours to do, flying within two days, and not done yet. A booking the
    // CUSTOMER checks in for is not work for this counter, and saying it was
    // would make the row cry wolf on every screen it appears on.
    needCheckIn: (bookings || []).filter(b => b.status !== 'Cancelled' && b.checkinBy === 'us' &&
      b.travelDate && b.travelDate >= today && b.travelDate <= soon && !b.checkinDone).length,
    unparsedTickets: ((typeof tmData !== 'undefined' && tmData && tmData.tickets) || []).length,
    arrears: (customers || []).filter(c => customerOwed(c) > 0).length,
    lowStock: (shopItems || []).filter(i => i.active && i.quantity <= i.lowStockAt).length,
    openReturns: (supplierReturns || []).filter(r => SUPPLIER_RETURN_OPEN.includes(r.status)).length,
    unconfirmed: (confirmStats && confirmStats.remaining) || 0,
    // Loaded on the dashboard for anyone whose permissions reach the message
    // log; 0 for everybody else, so the row never offers a screen the person
    // cannot open.
    smsWaiting: msgWaiting.count || 0,
  };
}

/** Paint the row for the screen currently showing. */
function kcPaintNextAction(tab) {
  const slot = document.getElementById('kcNextAction');
  if (!slot) return;
  let row;
  try {
    row = KC_NEXT.screenNextAction(tab, kcNextFacts());
  } catch (e) {
    // A broken row must never take a screen with it. lib/nextAction.mjs throws
    // on "names an action, offers no way to do it" so the tests catch it; here
    // the cost of one slipping through is a missing row and a console line.
    console.error('[next-action]', e.message);
    slot.innerHTML = '';
    return;
  }
  if (row.clear) {
    // Not `kc-next kc-next-clear`: that inherited the bordered card and the
    // accent stripe, so "nothing waiting on you here" was drawn exactly as
    // loudly as "2 phones overdue back". An empty queue is a result, and a
    // result should be quiet — otherwise the row it shares a shape with stops
    // meaning anything.
    slot.innerHTML = `<div class="kc-next-clear"><span class="kc-next-tick" aria-hidden="true">✓</span>${escHtml(row.text)}</div>`;
    return;
  }
  slot.innerHTML = `
    <div class="kc-next${row.tone === 'urgent' ? ' kc-next-urgent' : ''}">
      <span class="kc-next-text">${escHtml(row.text)}</span>
      <button class="btn btn-primary btn-sm kc-next-go" onclick="kcNextDo('${escJs(row.do)}')">${escHtml(row.label)}</button>
    </div>`;
}

// ─────────────────────────────────────────────
//  DATE FORMAT HELPER
// ─────────────────────────────────────────────
/**
 * A date with its Hebrew date underneath — for the counter screens only.
 *
 * Owner, 20 August: Hebrew dates beside the English ones on "the counter
 * screens — rentals, flights, SIM renewals and repairs", the dates actually
 * said out loud to somebody standing there. Deliberately NOT fmtDate itself:
 * that one has 78 call sites including the SMS drafts sent to customers, and
 * adding a second date to all of them is a different decision nobody made.
 *
 * Noon, not midnight, when reading the date: a bare YYYY-MM-DD parses as UTC
 * and would slip a day west of Greenwich. The Hebrew day really begins at
 * nightfall, which this does not model — the app has shown civil-day-aligned
 * Hebrew dates on the dashboard since it was built, and one shop-wide answer
 * that everybody already reads beats two that disagree after dark.
 *
 * Returns HTML, so callers must not escape it again.
 */
function fmtDateHeb(iso) {
  const en = fmtDate(iso);
  if (!iso || en === '\u2014') return escHtml(en);
  const d = new Date(String(iso).slice(0, 10) + 'T12:00:00');
  const heb = Number.isNaN(d.getTime()) ? '' : hebrewDateString(d);
  if (!heb) return escHtml(en);
  return `<span class="kc-dh">${escHtml(en)}<span class="kc-dh-heb" dir="rtl">${escHtml(heb)}</span></span>`;
}

function fmtDate(iso) {
  if (!iso) return '—';
  // Accept a plain date (YYYY-MM-DD) or a full ISO timestamp
  // (2026-07-13T16:03:02.6+00:00) — take just the date part either way.
  const [y, m, d] = String(iso).slice(0, 10).split('-');
  if (!y || !m || !d) return '—';
  // "5 Aug 2026", not "05/08/2026". Two formats were in play across the app —
  // this function at 78 call sites (including the customer-facing SMS drafts)
  // and a long-form one in SIM history, the wallet and the portal. Converging
  // here converges all 78, and the unambiguous form is the right one to send a
  // customer: 05/08 and 08/05 are different days on either side of the Atlantic.
  const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const mi = parseInt(m, 10) - 1;
  if (!(mi >= 0 && mi < 12)) return '—';
  return String(parseInt(d, 10)) + ' ' + MONTHS[mi] + ' ' + y;
}

// Date AND time, in the time the shop is standing in.
//
// Carrier mail used to build this inline as fmtDate(x) + x.slice(11,16) — the
// hours and minutes cut straight out of the stored text. Every timestamp is
// stored as UTC (lib/inboundMail.mjs writes toISOString()), so from late March
// to late October that printed an hour early: mail that arrived at 15:32 read
// 14:32, which is exactly the kind of small wrongness nobody reports and
// everybody works around. Parsing it and asking for local time fixes both
// lists at once.
//
// A plain date with no time in it (2026-08-18) stays a plain date — there is no
// time to show and midnight would be a lie.
function fmtWhen(iso) {
  if (!iso) return '—';
  const str = String(iso);
  if (!/\d{2}:\d{2}/.test(str)) return fmtDate(str);
  const d = new Date(str);
  if (Number.isNaN(d.getTime())) return fmtDate(str);
  return `${fmtDate(str)} ${d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}`;
}

// "Thu 2 Apr" — fmtDate minus the year, plus the weekday. Used inside a date
// range that already states the year, where the weekday is the load-bearing
// part: on a rental breakdown you are checking that the free day really is the
// Saturday, and "2 Apr 2026" does not let you.
function fmtDayDate(iso) {
  if (!iso) return '—';
  const d = parseLocalDate(iso);
  if (isNaN(d)) return '—';
  const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  return `${DAYS[d.getDay()]} ${d.getDate()} ${MONTHS[d.getMonth()]}`;
}

// ── Charge Gate (client mirror) ───────────────────────────────────────────
// Mirrors lib/chargeGate.mjs EXACTLY. That module is the canonical, unit-tested
// statement of the rules and the server enforces it in syncRentals; this is the
// same logic again because the browser has no bundler to import it — the same
// arrangement priceFromDays has with lib/rentalMath.mjs. Change both together.
//
// The gate asks the questions that must be answered before a rental can be
// closed and charged. It is here rather than only on the server so the operator
// finds out while the customer is still at the counter, which is the only
// moment the questions can actually be answered.
const GATE_BLOCK = 'block', GATE_VERIFY = 'verify', GATE_PASS = 'pass';
const GATE_ITEM_LABELS = { phone: 'the phone', sim: 'the SIM', charger: 'the charger' };

function gateItemStatus(r, key) {
  const st = r.itemStatus || {}, legacy = r.returnedItems || {};
  if (key === 'charger') {
    const parts = ['plug', 'cable'].map(k =>
      st[k] !== undefined ? st[k] : (legacy[k] === true ? 'returned' : 'undecided'));
    if (parts.includes('undecided')) return 'undecided';
    return parts.includes('lost') ? 'lost' : 'returned';
  }
  if (st[key] !== undefined) return st[key];
  return legacy[key] === true ? 'returned' : 'undecided';
}

function gateWasGiven(r, key) {
  const eq = r.equipmentGiven;
  if (!eq) return true;
  if (key === 'charger') return (eq.plug ?? false) || (eq.cable ?? false);
  return eq[key] ?? false;
}

function gateLostAmount(r, key) {
  const lost = r.lostCharges || {};
  if (key === 'charger') return Number(lost.plug) || Number(lost.cable) || 0;
  return Number(lost[key]) || 0;
}

function gateFor(rental, { today, verifications = [] } = {}) {
  const r = rental || {};
  const signed = new Set(verifications);
  const checks = [];
  const add = (id, state, label, detail) => checks.push({ id, state, label, detail });
  const round2 = v => Math.round(((Number(v) || 0) + Number.EPSILON) * 100) / 100;

  const undecided = [], unpriced = [];
  for (const key of ['phone', 'sim', 'charger']) {
    if (!gateWasGiven(r, key)) continue;
    const st = gateItemStatus(r, key);
    if (st === 'undecided') undecided.push(GATE_ITEM_LABELS[key]);
    else if (st === 'lost' && !(gateLostAmount(r, key) > 0)) unpriced.push(GATE_ITEM_LABELS[key]);
  }
  if (undecided.length) add('equipment', GATE_BLOCK, 'Equipment accounted for',
    `Still undecided: ${undecided.join(', ')}. Mark each one returned or lost.`);
  else if (unpriced.length) add('equipment', GATE_BLOCK, 'Equipment accounted for',
    `Marked lost with no charge: ${unpriced.join(', ')}. Put a figure on it, or £0 if you are waiving it.`);
  else add('equipment', GATE_PASS, 'Equipment accounted for', 'Every item that went out is settled.');

  if (r.fromDate && r.toDate && r.toDate < r.fromDate)
    add('dates', GATE_BLOCK, 'Dates make sense', 'The return date is before the pickup date.');
  else if (today && r.toDate && r.toDate > today)
    add('dates', GATE_VERIFY, 'Dates make sense',
      `Closing a rental that runs until ${fmtDate(r.toDate)}. Confirm the phone is back early.`);
  else add('dates', GATE_PASS, 'Dates make sense', 'Pickup and return dates are in order.');

  const deposit = Number(r.depositHeld) || 0;
  if (deposit > 0 && !r.depositSettled)
    add('deposit', GATE_BLOCK, 'Deposit settled',
      `${fmtGbp(deposit)} is still held. Refund it or apply it to the bill.`);
  else if (deposit > 0) add('deposit', GATE_PASS, 'Deposit settled', 'The deposit has been refunded or applied.');
  else add('deposit', GATE_PASS, 'Deposit settled', 'No deposit was taken.');

  const owed = round2((Number(r.price) || 0) + (Number(r.lateFee) || 0) +
    (Number(r.lostChargesTotal) || 0) - (Number(r.amountPaid) || 0));
  if (owed > 0) add('balance', signed.has('balance') ? GATE_PASS : GATE_VERIFY, 'Balance agreed',
    `${fmtGbp(owed)} will stay on the customer's account.`);
  else if (owed < 0) add('balance', signed.has('balance') ? GATE_PASS : GATE_VERIFY, 'Balance agreed',
    `${fmtGbp(Math.abs(owed))} overpaid — it will sit as credit on the account.`);
  else add('balance', GATE_PASS, 'Balance agreed', 'Paid in full.');

  for (const c of checks) if (c.state === GATE_VERIFY && signed.has(c.id)) c.state = GATE_PASS;

  const blockers = checks.filter(c => c.state === GATE_BLOCK);
  const needsVerification = checks.filter(c => c.state === GATE_VERIFY);
  return { checks, blockers, needsVerification, canClose: !blockers.length && !needsVerification.length };
}

// Sign-offs given in this Manage session, cleared when the modal opens. They
// are per-rental and deliberately not persisted client-side: a sign-off is
// about the numbers in front of you, so reopening the modal asks again.
let mgGateVerified = new Set();
let mgGateRentalId = null;

// The rental as the operator is ABOUT TO SAVE it — not as it is stored. The
// gate has to judge the pending edit, or it approves the previous state and
// blocks nothing.
function mgDraftRental(rentalId) {
  const r = rentals.find(x => x.id === rentalId);
  if (!r) return null;
  const lost = mgComputeLostCharges();
  const draft = {
    ...r,
    fromDate: document.getElementById('mgFrom')?.value || r.fromDate,
    toDate: document.getElementById('mgTo')?.value || r.toDate,
    price: parseFloat(document.getElementById('mgPrice')?.value) || 0,
    amountPaid: parseFloat(document.getElementById('mgPaid')?.value) || 0,
    lateFee: mgComputeLateFee(),
    lostChargesTotal: lost.total,
    depositSettled: document.getElementById('mgDepositSettled')?.checked || r.depositSettled || false,
    itemStatus: {},
    lostCharges: {},
    equipmentGiven: {
      phone: document.getElementById('mgGivenPhone')?.dataset.given === '1',
      sim: document.getElementById('mgGivenSim')?.dataset.given === '1',
      plug: document.getElementById('mgGivenCharger')?.dataset.given === '1',
      cable: document.getElementById('mgGivenCharger')?.dataset.given === '1',
    },
  };
  // Same charger fan-out the save does: one UI control, two stored keys.
  MG_UI_ITEMS.forEach(item => {
    const st = document.getElementById('mgItemStatus_' + item)?.value || 'undecided';
    const amt = st === 'lost' ? (parseFloat(document.getElementById('mgLostAmt_' + item)?.value) || null) : null;
    if (item === 'charger') {
      draft.itemStatus.plug = st; draft.itemStatus.cable = st;
      draft.lostCharges.plug = amt; draft.lostCharges.cable = null;
    } else {
      draft.itemStatus[item] = st;
      draft.lostCharges[item] = amt;
    }
  });
  return draft;
}

// Class names, not glyphs: this feeds .kc-gate-icon, which is a span the
// stylesheet can reach. 'pass' keeps ✓ because ✓ is monochrome text that
// already follows currentColor — it never had the theme problem.
const GATE_ICON = { block: '<i class="kc-ic kc-ic-blocked" aria-hidden="true"></i>',
                    verify: '<i class="kc-ic kc-ic-sign" aria-hidden="true"></i>',
                    pass: '✓' };

// The panel. Shown only while the Returned toggle is on — the gate is about
// closing, and a rental still running has nothing to answer for yet.
function mgRenderGate(rentalId) {
  const box = document.getElementById('mgGateBox');
  const btn = document.getElementById('mgSaveBtn');
  if (!box) return;
  const closing = document.getElementById('mgReturned')?.value === '1';
  if (!closing) {
    box.innerHTML = '';
    box.style.display = 'none';
    if (btn) { btn.disabled = false; btn.title = ''; }
    return;
  }
  const draft = mgDraftRental(rentalId);
  const gate = gateFor(draft, { today: localISO(), verifications: [...mgGateVerified] });
  box.style.display = 'block';
  box.innerHTML = `
    <div class="kc-gate-head">${gate.canClose
      ? '✓ Ready to close'
      : gate.blockers.length ? '<i class="kc-ic kc-ic-blocked" aria-hidden="true"></i> Not ready to close' : '<i class="kc-ic kc-ic-sign" aria-hidden="true"></i> Needs a sign-off'}</div>
    ${gate.checks.map(c => `
      <div class="kc-gate-row is-${c.state}">
        <span class="kc-gate-icon" aria-hidden="true">${GATE_ICON[c.state]}</span>
        <span class="kc-gate-text"><strong>${escHtml(c.label)}</strong>
          <span class="kc-gate-detail">${escHtml(c.detail)}</span></span>
        ${c.state === GATE_VERIFY ? `<button type="button" class="btn btn-outline btn-sm kc-gate-sign"
          onclick="mgSignGate('${escHtml(rentalId)}','${escHtml(c.id)}')">Sign off</button>` : ''}
      </div>`).join('')}`;
  if (btn) {
    // NOT disabled, deliberately. This dialog is taller than the screen: the
    // toggle reads "Returned ✓" at the top while the gate and this button are
    // below the fold, so a disabled button explained itself somewhere the
    // operator was not looking. The result was a close that never happened and
    // never said so — reported on a phone that WAS back (24 Aug). A control
    // that refuses and explains beats one that goes quiet: the click is still
    // taken, saveManageRental re-checks the gate, toasts the reason, and
    // scrolls the gate into view.
    btn.disabled = false;
    btn.classList.toggle('kc-blocked', !gate.canClose);
    btn.title = gate.canClose ? '' : (gate.blockers[0] || gate.needsVerification[0])?.detail || '';
  }
}

function mgSignGate(rentalId, checkId) {
  mgGateVerified.add(checkId);
  mgRenderGate(rentalId);
}

// ── Device chip ───────────────────────────────────────────────────────────
// One way to show a rental handset, everywhere one appears.
//
// The same device was being rendered several different ways on one screen. The
// Rentals table printed the raw stored string — "+15185550101" — while the
// Phone Inventory table two sections below it printed "+1 518 555 0101" for
// the same handset, because one call site ran fmtPhone and the other did not.
// The model, which is what staff actually say out loud at the counter ("the
// Nokia"), appeared on the inventory row and nowhere else. And the country was
// a flag emoji built by a ternary chain written out three separate times.
//
// A chip fixes all of that by being the only thing that knows how to draw a
// device: number formatted once, model attached, country named. Nothing here is
// new information — it is the same fields, said the same way twice.
// Real flag artwork, not the Unicode flag emoji. Windows' emoji font (Segoe
// UI Emoji) has never shipped the compound glyphs most flag emoji need —
// it falls back to the two bare regional-indicator letters, so "🇺🇸" read as
// literal "US" on the shop PC (worst inside an <option>, where it doubled
// with the "USA" label text: "US USA"). A tiny inline SVG has no font
// dependency, so it draws identically everywhere.
const FLAG_COUNTRIES = ['USA', 'UK', 'Israel', 'EU', 'Canada'];
const FLAG_SVG = {
  USA: '<svg viewBox="0 0 20 14" width="16" height="12" aria-hidden="true"><rect width="20" height="14" fill="#B22234"/><g fill="#fff"><rect y="1.08" width="20" height="1.08"/><rect y="3.23" width="20" height="1.08"/><rect y="5.38" width="20" height="1.08"/><rect y="7.54" width="20" height="1.08"/><rect y="9.69" width="20" height="1.08"/><rect y="11.85" width="20" height="1.08"/></g><rect width="8" height="7.54" fill="#3C3B6E"/></svg>',
  UK: '<svg viewBox="0 0 20 14" width="16" height="12" aria-hidden="true"><rect width="20" height="14" fill="#00247D"/><path d="M0 0L20 14M20 0L0 14" stroke="#fff" stroke-width="2.6"/><path d="M0 0L20 14M20 0L0 14" stroke="#CF142B" stroke-width="1"/><path d="M10 0V14M0 7H20" stroke="#fff" stroke-width="4.2"/><path d="M10 0V14M0 7H20" stroke="#CF142B" stroke-width="2.2"/></svg>',
  Israel: '<svg viewBox="0 0 20 14" width="16" height="12" aria-hidden="true"><rect width="20" height="14" fill="#fff"/><rect y="1.4" width="20" height="1.8" fill="#0038B8"/><rect y="10.8" width="20" height="1.8" fill="#0038B8"/><g transform="translate(10 7)" fill="none" stroke="#0038B8" stroke-width="0.7"><path d="M-3.3 1.9L0 -3.8L3.3 1.9Z"/><path d="M-3.3 -1.9L0 3.8L3.3 -1.9Z"/></g></svg>',
  Canada: '<svg viewBox="0 0 20 14" width="16" height="12" aria-hidden="true"><rect width="20" height="14" fill="#fff"/><rect width="5" height="14" fill="#D80621"/><rect x="15" width="5" height="14" fill="#D80621"/><path d="M10 2.3l1.1 2.4 2.3-1-0.6 2.3 2 0.9-2 1 0.5 1.7-2.1-0.5 0.1 2.1-1.3-1.6-1.3 1.6 0.1-2.1-2.1 0.5 0.5-1.7-2-1 2-0.9-0.6-2.3 2.3 1z" fill="#D80621"/></svg>',
  EU: `<svg viewBox="0 0 20 14" width="16" height="12" aria-hidden="true"><rect width="20" height="14" fill="#003399"/><g fill="#FFCC00">${Array.from({ length: 12 }, (_, i) => {
    const a = (i / 12) * 2 * Math.PI - Math.PI / 2;
    return `<circle cx="${(10 + 5.2 * Math.cos(a)).toFixed(2)}" cy="${(7 + 4 * Math.sin(a)).toFixed(2)}" r="0.55"/>`;
  }).join('')}</g></svg>`,
};
// Flags are decoration: they read as a blank to a screen reader (aria-hidden
// above), so the country always travels as text beside them too.
function countryFlag(country) {
  return FLAG_SVG[country] || '<svg viewBox="0 0 20 14" width="16" height="12" aria-hidden="true"><rect x="0.5" y="0.5" width="19" height="13" rx="2" fill="none" stroke="currentColor" stroke-opacity="0.35"/></svg>';
}

// A native <select><option> can only ever hold plain text — no image, no
// SVG, that's an HTML platform limit, not a font one — so the one country
// picker in the app (Manage phones → Add New Phone) is a small custom
// listbox instead, built from the same trusted-markup pattern as the
// customer combo below, so it can show the real flag next to each choice.
function kcFlagPickToggle(valueId) {
  const dd = document.getElementById(valueId + '_dd');
  const open = dd && dd.classList.toggle('open');
  document.getElementById(valueId + '_btn')?.setAttribute('aria-expanded', open ? 'true' : 'false');
}
function kcFlagPickClose(valueId) {
  document.getElementById(valueId + '_dd')?.classList.remove('open');
  document.getElementById(valueId + '_btn')?.setAttribute('aria-expanded', 'false');
}
function kcFlagPick(valueId, country) {
  const hidden = document.getElementById(valueId);
  const label = document.getElementById(valueId + '_label');
  if (hidden) hidden.value = country;
  if (label) label.innerHTML = `${countryFlag(country)}<span>${escHtml(country)}</span>`;
  document.querySelectorAll(`#${valueId}_dd .customer-dropdown-item`).forEach(el =>
    el.setAttribute('aria-selected', el.dataset.country === country ? 'true' : 'false'));
  kcFlagPickClose(valueId);
  if (hidden) hidden.dispatchEvent(new Event('change'));
}

// `device` is a phone object, or a bare number string — the rental record
// carries phoneNumber but the inventory carries the whole handset, and both
// call sites want the same chip. A string is looked up so it gains the model
// and country the record never had; an unknown number still renders, formatted.
function deviceChip(device, { flag = true, model = true, stacked = false, extra = '' } = {}) {
  const p = (device && typeof device === 'object')
    ? device
    : ((typeof phones !== 'undefined' && phones) || []).find(x => x.number === device) || { number: device };
  const number = fmtPhone(p.number) || '—';
  const country = p.country || '';
  return `<span class="kc-device${stacked ? ' is-stacked' : ''}">` +
    `<span class="kc-device-num">` +
      (flag && country ? `<span aria-hidden="true">${countryFlag(country)}</span> ` : '') +
      escHtml(number) +
      (flag && country ? `<span class="kc-sr-only"> (${escHtml(country)})</span>` : '') +
    `</span>` +
    (model && p.model ? `<span class="kc-device-model">${escHtml(p.model)}</span>` : '') +
    (extra ? `<span class="kc-device-model">${extra}</span>` : '') +
    `</span>`;
}

// The chip for a rental's handset.
//
// The NUMBER always comes from the rental. It is that rental's record of which
// handset actually went out, it survives the phone being edited or deleted from
// stock, and a contract that quietly starts naming a different device than the
// one handed over is worse than one with an out-of-date model on it.
//
// The inventory is consulted only to add the model and the country, and only
// when it still agrees about the number: a phoneId whose record now reads
// differently is a line that was re-keyed or a handset that was replaced, and
// borrowing its model would put the wrong device on the row. (The offline seed
// has exactly this shape by accident — three rentals, three numbers, one
// phoneId — which is how the rule got written down.)
// Every item that went out has been answered, and the hire is still open.
// This is a HALF-FINISHED job, not an ordinary overdue one: the shop already
// knows where everything is, so chasing the customer would be wrong. Moshe
// Bodner's rental sat in this state for days looking like an ordinary overdue
// (owner, 24 Aug), which is what made a stuck close invisible from the list.
function rentalItemsAllAnswered(r) {
  if (!r || r.status === 'returned' || r.voided) return false;
  const given = ['phone', 'sim', 'charger'].filter((k) => wasGivenUi(r, k));
  if (!given.length) return false;
  return given.every((k) => uiItemStatus(r, k) !== 'undecided');
}
// The gate's wasGiven, in the browser's own vocabulary (charger = plug|cable).
function wasGivenUi(r, key) {
  const eq = r.equipmentGiven;
  if (!eq) return true;
  if (key === 'charger') return (eq.plug ?? false) || (eq.cable ?? false);
  return eq[key] ?? false;
}

function rentalDeviceChip(rental, opts = {}) {
  const live = ((typeof phones !== 'undefined' && phones) || [])
    .find(x => x.id === rental.phoneId && x.number === rental.phoneNumber);
  return deviceChip({
    number: rental.phoneNumber,
    country: live?.country || rental.country,
    model: live?.model,
  }, opts);
}

// ── DateStamp ─────────────────────────────────────────────────────────────
// A date, plus — when there is one — the reason it was left out of a charge.
//
// The rental breakdown could previously say "3 free days (Shabbos / Yom Tov)"
// and not one word more, so nobody at the counter could check the arithmetic:
// not which three days, not why, not whether the calendar behind it was even
// right. It was not. Every yom tov in the shipped table sat a day early (see
// the DIASPORA_YOM_TOV header) and no screen in the app could have shown it,
// because no screen in the app ever printed the dates it was excluding.
//
// So this is the primitive that makes an exclusion legible: struck-through
// date, reason beside it, and a title for the pointer. Returns HTML —
// everything here is innerHTML — and escapes its own reason.
function dateStamp(iso, { excluded = false, reason = '', weekday = true } = {}) {
  const label = weekday ? fmtDayDate(iso) : fmtDate(iso);
  const why = String(reason || '');
  return `<span class="kc-datestamp${excluded ? ' is-excluded' : ''}"${why ? ` title="${escHtml(why)}"` : ''}>` +
    `<span class="kc-ds-date">${escHtml(label)}</span>` +
    (why ? `<span class="kc-ds-why">${escHtml(why)}</span>` : '') +
    `</span>`;
}

// The free days of a rental window, rendered as a wrapped row of DateStamps.
// Returns '' when nothing was excluded, so callers can drop it in unguarded.
function freeDayStamps(fromDate, toDate) {
  const days = freeDaysIn(fromDate, toDate);
  if (!days.length) return '';
  return `<div class="kc-ds-list">${days
    .map(d => dateStamp(d.iso, { excluded: true, reason: d.reason }))
    .join('')}</div>`;
}

// ─────────────────────────────────────────────
//  HEBREW DATE HELPER
// ─────────────────────────────────────────────
function numToHebrew(n) {
  const ones  = ['','א','ב','ג','ד','ה','ו','ז','ח','ט'];
  const tens  = ['','י','כ','ל','מ','נ','ס','ע','פ','צ'];
  const hunds = ['','ק','ר','ש','ת','תק','תר','תש','תת','תתק'];
  let result = '';
  // Hebrew YEARS arrive as 5786 and are written without the millennium —
  // תשפ״ו, not ה׳תשפ״ו — the way every calendar and every שטר writes them.
  // Without this the hundreds index ran off the end of the table and the
  // whole 700 vanished: 5786 printed as פ״ו, on the calendar AND on every
  // rental date field. Day numbers (1–30) are untouched.
  n = Math.round(Number(n) || 0);
  if (n >= 1000) n %= 1000;
  if (n <= 0) return result;
  result += hunds[Math.floor(n/100)] || '';
  const r = n % 100;
  if (r === 15) result += 'טו';
  else if (r === 16) result += 'טז';
  else result += (tens[Math.floor(r/10)]||'') + (ones[r%10]||'');
  // Gershayim before the last letter of a multi-letter numeral, geresh after
  // a single one — over the WHOLE numeral. The old code punctuated only the
  // tens-and-units part, so a decade year came out wrong: 5770 printed תשע׳
  // instead of תש״ע, and 5800 would print bare תת. Nothing rendered today is
  // in the broken range (תשפ״ו is identical both ways); the first year that
  // would have printed wrong is 5790. Held to lib/hebrewDate.mjs by
  // test/hebrewDateMirror.test.mjs.
  return result.length > 1 ? result.slice(0,-1) + '״' + result.slice(-1) : result ? result + '׳' : '';
}

// Compact Hebrew day-of-month, in gematria, for a column header that has no
// room for the full "day month year" string (hebrewDateString above) — the
// month/year still reach the reader via the header's title tooltip.
function hebrewDayLabel(d) {
  try {
    const parts = new Intl.DateTimeFormat('he-IL-u-ca-hebrew', { day: 'numeric' }).formatToParts(d);
    const dayNum = parseInt(parts.find(p => p.type === 'day')?.value || '0');
    return dayNum ? numToHebrew(dayNum) : '';
  } catch (e) { return ''; }
}

// Day number, month name and Hebrew year for one date.
function hebrewParts(d) {
  try {
    const parts = new Intl.DateTimeFormat('he-IL-u-ca-hebrew', {
      day: 'numeric', month: 'long', year: 'numeric',
    }).formatToParts(d);
    return {
      day: parseInt(parts.find(p => p.type === 'day')?.value || '0'),
      month: parts.find(p => p.type === 'month')?.value || '',
      year: parseInt(parts.find(p => p.type === 'year')?.value || '0'),
    };
  } catch (e) { return { day: 0, month: '', year: 0 }; }
}

// Which Hebrew month(s) a Gregorian month covers — "אב–אלול תשפ״ו". A grid of
// Hebrew day numbers alone is unreadable across a month boundary: the numbers
// simply restart at א׳ with nothing saying which month began.
function hebrewMonthSpan(y, m, daysInMonth) {
  const first = hebrewParts(new Date(y, m - 1, 1));
  const last  = hebrewParts(new Date(y, m - 1, daysInMonth));
  if (!first.month) return '';
  const years = first.year === last.year
    ? numToHebrew(first.year)
    : `${numToHebrew(first.year)}–${numToHebrew(last.year)}`;
  const months = first.month === last.month ? first.month : `${first.month}–${last.month}`;
  return `${months} ${years}`;
}

function showHebrewDate(inputId, labelId) {
  const val = document.getElementById(inputId)?.value;
  const el  = document.getElementById(labelId);
  if (!el) return;
  if (!val) { el.textContent = ''; return; }
  try {
    const d = new Date(val + 'T12:00:00');
    const parts = new Intl.DateTimeFormat('he-IL-u-ca-hebrew', {
      day: 'numeric', month: 'long', year: 'numeric'
    }).formatToParts(d);
    const dayNum   = parseInt(parts.find(p=>p.type==='day')?.value || '0');
    const monthStr = parts.find(p=>p.type==='month')?.value || '';
    const yearNum  = parseInt(parts.find(p=>p.type==='year')?.value || '0');
    // A Hebrew date is Hebrew: it reads right to left, and left-to-right it
    // arrives as year-month-day to anyone who reads it.
    el.setAttribute('dir', 'rtl');
    el.textContent = numToHebrew(dayNum) + ' ' + monthStr + ' ' + numToHebrew(yearNum);
  } catch(e) { el.textContent = ''; }
}

// MIRRORS lib/hebrewDate.mjs — the pure molad arithmetic, browser copy. The
// Intl-based helpers above stay the renderers for now; this closure exists so
// screens CAN move to one tested implementation shared with the server
// (receipts, emails) once the owner decides where Hebrew dates appear.
// Wired to nothing yet, deliberately. test/hebrewDateMirror.test.mjs lifts
// this region and holds every function to the lib over anchors and a sweep.
// ── KC_HEBREW mirror start ──
const KC_HEBREW = (() => {
  function gregorianToRd(gy, gm, gd) {
    const a = Math.floor((14 - gm) / 12);
    const y = gy + 4800 - a;
    const m = gm + 12 * a - 3;
    const jdn = gd + Math.floor((153 * m + 2) / 5) + 365 * y +
      Math.floor(y / 4) - Math.floor(y / 100) + Math.floor(y / 400) - 32045;
    return jdn - 1721425;
  }
  const HEBREW_EPOCH = -1373427;
  function isHebrewLeapYear(hy) { return ((7 * hy + 1) % 19) < 7; }
  function monthsInHebrewYear(hy) { return isHebrewLeapYear(hy) ? 13 : 12; }
  function elapsedDays(hy) {
    const monthsElapsed = Math.floor((235 * hy - 234) / 19);
    const partsElapsed = 12084 + 13753 * monthsElapsed;
    let days = monthsElapsed * 29 + Math.floor(partsElapsed / 25920);
    if (((3 * (days + 1)) % 7) < 3) days += 1;
    return days;
  }
  function roshHashanaRd(hy) {
    const ny0 = elapsedDays(hy - 1);
    const ny1 = elapsedDays(hy);
    const ny2 = elapsedDays(hy + 1);
    let delay = 0;
    if (ny2 - ny1 === 356) delay = 2;
    else if (ny1 - ny0 === 382) delay = 1;
    return HEBREW_EPOCH + ny1 + delay;
  }
  function daysInHebrewYear(hy) { return roshHashanaRd(hy + 1) - roshHashanaRd(hy); }
  function monthDays(hy, hm) {
    if (hm === 2 || hm === 4 || hm === 6 || hm === 10 || hm === 13) return 29;
    if (hm === 12 && !isHebrewLeapYear(hy)) return 29;
    if (hm === 8 && daysInHebrewYear(hy) % 10 !== 5) return 29;
    if (hm === 9 && daysInHebrewYear(hy) % 10 === 3) return 29;
    return 30;
  }
  function hebrewToRd(hy, hm, hd) {
    let rd = roshHashanaRd(hy) + hd - 1;
    if (hm < 7) {
      for (let m = 7; m <= monthsInHebrewYear(hy); m++) rd += monthDays(hy, m);
      for (let m = 1; m < hm; m++) rd += monthDays(hy, m);
    } else {
      for (let m = 7; m < hm; m++) rd += monthDays(hy, m);
    }
    return rd;
  }
  function hebrewFromGregorian(gy, gm, gd) {
    const rd = gregorianToRd(gy, gm, gd);
    let year = Math.floor((rd - HEBREW_EPOCH) / 365.2468) + 1;
    while (roshHashanaRd(year) > rd) year -= 1;
    while (roshHashanaRd(year + 1) <= rd) year += 1;
    let month = rd < hebrewToRd(year, 1, 1) ? 7 : 1;
    while (rd > hebrewToRd(year, month, monthDays(year, month))) month += 1;
    const day = rd - hebrewToRd(year, month, 1) + 1;
    return { year, month, day };
  }
  const ONES = ['', 'א', 'ב', 'ג', 'ד', 'ה', 'ו', 'ז', 'ח', 'ט'];
  const TENS = ['', 'י', 'כ', 'ל', 'מ', 'נ', 'ס', 'ע', 'פ', 'צ'];
  const HUNDREDS = ['', 'ק', 'ר', 'ש', 'ת'];
  function numeral(n) {
    let v = Math.floor(n);
    if (!(v >= 1 && v <= 999)) return String(n);
    let s = '';
    while (v >= 400) { s += 'ת'; v -= 400; }
    if (v >= 100) { s += HUNDREDS[Math.floor(v / 100)]; v %= 100; }
    if (v === 15) { s += 'טו'; v = 0; }
    else if (v === 16) { s += 'טז'; v = 0; }
    if (v >= 10) { s += TENS[Math.floor(v / 10)]; v %= 10; }
    if (v > 0) s += ONES[v];
    return s.length > 1 ? s.slice(0, -1) + '״' + s.slice(-1) : s + '׳';
  }
  const MONTHS_HE = ['', 'ניסן', 'אייר', 'סיון', 'תמוז', 'אב', 'אלול',
    'תשרי', 'חשון', 'כסלו', 'טבת', 'שבט', 'אדר', 'אדר ב׳'];
  function monthName(hy, hm) {
    if (hm === 12 && isHebrewLeapYear(hy)) return 'אדר א׳';
    return MONTHS_HE[hm] || '';
  }
  function format(gy, gm, gd) {
    const h = hebrewFromGregorian(gy, gm, gd);
    return `${numeral(h.day)} ${monthName(h.year, h.month)} ${numeral(h.year % 1000)}`;
  }
  function weekday(gy, gm, gd) {
    const dow = ((gregorianToRd(gy, gm, gd) % 7) + 7) % 7;
    return dow === 6 ? 'שבת' : ONES[dow + 1] + '׳';
  }
  return { gregorianToRd, isHebrewLeapYear, monthsInHebrewYear, roshHashanaRd,
    monthDays, hebrewToRd, hebrewFromGregorian, numeral, monthName, format, weekday };
})();
// ── KC_HEBREW mirror end ──

// ─────────────────────────────────────────────
//  CUSTOMER PICKER — shared ordering
// ─────────────────────────────────────────────

/**
 * Who to show before anything is typed.
 *
 * A picker that opens empty makes you type a name you may not be sure how to
 * spell; the phone picker beside it has always opened with its list showing
 * (owner, 08-17, comparing the two side by side). The useful default for a
 * shop is not the alphabet — it is who has been in lately, so the family that
 * brought a phone back on Sunday is one tap away on Monday.
 *
 * Most-recent rental first, then anyone left over by name.
 */
function kcCustomersByRecency(limit = 8) {
  const last = new Map();
  for (const r of rentals) {
    if (!r.customerId) continue;
    const when = r.createdAt || r.fromDate || '';
    const prev = last.get(String(r.customerId));
    if (!prev || when > prev) last.set(String(r.customerId), when);
  }
  const seen = [...customers]
    .filter(c => last.has(String(c.id)))
    .sort((a, b) => String(last.get(String(b.id))).localeCompare(String(last.get(String(a.id)))));
  const rest = [...customers]
    .filter(c => !last.has(String(c.id)))
    .sort((a, b) => `${a.firstName || ''} ${a.lastName || ''}`.trim()
      .localeCompare(`${b.firstName || ''} ${b.lastName || ''}`.trim(), undefined, { sensitivity: 'base' }));
  return [...seen, ...rest].slice(0, limit);
}

// What the rental form has to redo when the customer changes — whether that
// was a pick, a clear, or a preselect. Wired as the picker's onPick.
function rentalCustomerChanged() {
  refreshRentalPhoneOptions(); // resort the phone list — his old numbers first
  updateRentalCalc();          // customer drives the multi-phone (3rd+) auto-discount
}

document.addEventListener('click', e => {
  if (!e.target.closest('.phone-search-wrap')) {
    const pd = document.getElementById('rPhoneDropdown');
    if (pd) pd.classList.remove('open');
  }
});

