function updateRentalPhoneInfo() {
  const sel = document.getElementById('rPhone');
  const p   = phones.find(x => x.id === sel.value);
  const box = document.getElementById('rPhoneInfo');
  if (!p) { box.textContent = ''; return; }
  if (p.poolExpiry) {
    box.textContent = `Pool expires: ${p.poolExpiry}`;
    box.style.color = 'var(--gold)';
  } else {
    box.textContent = '';
  }
}

// BUSINESS_RULES §1.3: weekly virtual number is PER WEEK (minimum 1 week)
// and PER COUNTRY — £5/wk £10/30d for USA & Canada, £7/wk £15/30d for
// Israel & UK (customer price list, 30 Jun 2026). Weeks are counted over the
// rental's total calendar days, rounded up. Global settings keys remain the
// fallback when a country has no override.
function calcVNPrice(vnSub, fromDate, toDate, country = 'USA', ukPlan = 'standard') {
  const rate = rateFor(country, ukPlan);
  if (vnSub === 'monthly') return rate.vnPer30Days ?? settingNum('vn_per_30_days', 10);
  let weeks = 1;
  if (fromDate && toDate && toDate > fromDate) {
    const days = Math.round((parseLocalDate(toDate) - parseLocalDate(fromDate)) / 86400000) + 1;
    weeks = Math.max(1, Math.ceil(days / 7));
  }
  return (rate.vnWeekly ?? settingNum('vn_weekly', 5)) * weeks;
}

function updateVNPrice() {
  const priceEl = document.getElementById('rVNPrice');
  if (!priceEl) return;
  const vnSub = document.getElementById('rVNSub')?.value || 'weekly';
  const from  = document.getElementById('rFrom')?.value;
  const to    = document.getElementById('rTo')?.value;
  const selPhone = document.getElementById('rPhone');
  const phone = selPhone ? phones.find(p => p.id === selPhone.value) : null;
  const country = phone?.country || 'USA';
  const ukPlan  = phone?.ukPlan || 'standard';
  // Option labels carry the per-country figures (£7/£15 Israel & UK, £5/£10
  // elsewhere) so the dropdown never contradicts the computed price.
  const sub = document.getElementById('rVNSub');
  if (sub && sub.options.length >= 2) {
    const rate = rateFor(country, ukPlan);
    sub.options[0].textContent = `Weekly (${fmtGbp(rate.vnWeekly ?? settingNum('vn_weekly', 5))}/week)`;
    sub.options[1].textContent = `Monthly / 30 days (${fmtGbp(rate.vnPer30Days ?? settingNum('vn_per_30_days', 10))})`;
  }
  priceEl.value = calcVNPrice(vnSub, from, to, country, ukPlan);
}

let rLastTotal = 0; // #25 — the live rental total, so the payment row can pre-fill it

function updateRentalCalc() {
  updateVNPrice(); // rental dates drive the weekly VN price
  const from = document.getElementById('rFrom')?.value;
  const to   = document.getElementById('rTo')?.value;
  const box  = document.getElementById('rCalcBox');
  const txt  = document.getElementById('rCalcText');
  if (!from || !to || to <= from) { box.style.display='none'; return; }
  // Several phones → price each and show the batch total; the reasoning
  // panel below still explains the FIRST phone's rate line by line.
  const simGivenAll = document.getElementById('nrGiven_sim')?.dataset.given !== '0';
  if (nrPhones.length > 1) {
    const rows = nrPhones.map(id => {
      const ph = phones.find(x => x.id === id);
      const r = calcRentalPrice(from, to, ph?.country || 'USA', ph?.ukPlan || 'standard', simGivenAll);
      return { ph, ...r };
    });
    const gross = round2(rows.reduce((sum, r) => sum + r.price, 0));
    // The 3rd concurrent phone and beyond takes the standing 15% — applied
    // per phone by saveNewRental as each one is created, mirrored here.
    const already = multiPhoneCountFor(document.getElementById('rCustomer')?.value, from, to);
    let net = 0;
    rows.forEach((r, i) => {
      const pct = multiPhoneDiscountPctForIndex(already + i);
      r.net = pct > 0 ? round2(r.price * (1 - pct / 100)) : round2(r.price);
      r.pct = pct;
      net += r.net;
    });
    box.style.display = 'block';
    txt.innerHTML = `<strong>${rows.length} phones</strong> · ${fmtDate(from)} → ${fmtDate(to)}<br>` +
      rows.map(r => `${escHtml(fmtPhone(r.ph?.number || ''))} — ${r.chargeableDays}d · ${fmtGbp(r.price)}` +
        (r.pct > 0 ? ` <span style="color:var(--gold);">−${r.pct}% → ${fmtGbp(r.net)}</span>` : '')).join('<br>') +
      `<br><strong style="font-size:var(--fs-body);">Total: ${fmtGbp(net)}</strong>` +
      (net !== gross ? ` <span style="color:var(--gold);font-size:var(--fs-small);">(was ${fmtGbp(gross)})</span>` : '');
    // …and STORE it. This `return` used to jump straight over the two lines at
    // the bottom of this function that keep rLastTotal and the "paid now" box in
    // step with the total — so with more than one phone the batch total was
    // painted on screen and never recorded anywhere. rLastTotal kept whatever it
    // held the last time the calculator ran in single-phone mode.
    //
    // What that cost, 27 Aug: Shloime hired five phones out, ticked paid, and
    // the ledger took £237.60 against £327.60 of charges. saveMultiPhoneRental
    // caps the payment at the batch total (Math.min) and spreads it in order, so
    // a stale figure can only ever under-pay — the first three rentals were
    // settled, the fourth got £32.40 and the fifth got no payment row at all.
    // Nothing was wrong with the allocation; it was handed the wrong pot. And
    // "Full total" re-filled from the same stale number, so the one control
    // meant to fix this reproduced it.
    // A virtual number is ONE number for the customer, not one per handset, so
    // it is added once to the batch — the same weekly/monthly split the single
    // rental makes. Until 27 Aug the multi-phone branch ignored it completely:
    // the box was ticked, the price was on screen, and neither the total here
    // nor the charge below knew about it.
    const mVnMonthly = document.getElementById('rVNSub')?.value === 'monthly';
    const mVnAmt = (document.getElementById('rAddVN')?.checked && !mVnMonthly)
      ? (parseFloat(document.getElementById('rVNPrice')?.value) || 0) : 0;
    if (mVnAmt > 0) {
      txt.innerHTML += `<br><span style="color:var(--muted);">+ virtual number ${fmtGbp(mVnAmt)}</span>`
        + `<br><strong style="font-size:var(--fs-body);">With the number: ${fmtGbp(round2(net + mVnAmt))}</strong>`;
    }
    rLastTotal = round2(net + mVnAmt);
    const mPay = document.getElementById('rPayAmount');
    if (mPay && document.getElementById('rPay')?.value !== 'account' && mPay.dataset.touched !== '1') {
      mPay.value = rLastTotal.toFixed(2);
    }
    return;
  }
  const selPhone = document.getElementById('rPhone');
  const phone    = nrPhones.length ? phones.find(p => p.id === nrPhones[0])
                                   : (selPhone ? phones.find(p => p.id === selPhone.value) : null);
  const country  = phone?.country || 'USA';
  const ukPlan   = phone?.ukPlan  || 'standard';
  const simGiven = document.getElementById('nrGiven_sim')?.dataset.given !== '0';
  const { chargeableDays, totalDays, periods, price } = calcRentalPrice(from, to, country, ukPlan, simGiven);
  const excluded = totalDays - chargeableDays;
  const rate = rateFor(country, ukPlan, simGiven);
  let finalPrice = price;
  let discountLine = '';
  const addDiscount = document.getElementById('rAddDiscount')?.checked;
  if (addDiscount) {
    const dtype = document.getElementById('rDiscountType')?.value || 'percent';
    const dval  = parseFloat(document.getElementById('rDiscountValue')?.value) || 0;
    finalPrice  = dtype === 'percent' ? Math.max(0, price * (1 - dval / 100)) : Math.max(0, price - dval);
    if (dval > 0) discountLine = ` &nbsp;|&nbsp; <span style="color:var(--gold);font-size:var(--fs-small);">-${dtype==='percent'?dval+'%':fmtGbp(dval)} discount → <strong>${fmtGbp(finalPrice)}</strong></span>`;
  } else {
    // Auto multi-phone discount (3rd+ concurrent phone); a manual discount
    // replaces it — staff choice wins.
    const autoPct = multiPhoneDiscountPct(rentals, document.getElementById('rCustomer')?.value, from, to);
    if (autoPct > 0) {
      finalPrice = Math.max(0, price * (1 - autoPct / 100));
      discountLine = ` &nbsp;|&nbsp; <span style="color:var(--gold);font-size:var(--fs-small);">3rd phone+ −${autoPct}% → <strong>${fmtGbp(finalPrice)}</strong></span>`;
    }
  }
  box.style.display = 'block';
  // Full reasoning: rate math, which days were dropped for Shabbat/Yom Tov,
  // and whether the minimum or the cap kicked in.
  // The sum is now window by window, so the explanation is too: staff being
  // asked "why is a five-week hire £60?" should be able to read the answer off
  // the box rather than work it out.
  const first = periods[0] || 0;
  const rawFirst = first * rate.ratePerDay;
  const windowLen = rate.capPeriodDays || 30;
  const steps = [
    `${first} chargeable day${first === 1 ? '' : 's'} × ${fmtGbp(rate.ratePerDay)}/day = ${fmtGbp(rawFirst)}${
      periods.length > 1 ? ` (first ${windowLen} days)` : ''}`,
  ];
  if (rate.minCharge && first > 0 && rawFirst < rate.minCharge)
    steps.push(`below the ${fmtGbp(rate.minCharge)} minimum → ${fmtGbp(rate.minCharge)}`);
  if (rate.cap != null && Math.min(Math.max(rawFirst, first > 0 ? rate.minCharge : 0), rate.cap) === rate.cap)
    steps.push(`capped at ${fmtGbp(rate.cap)}`);
  periods.slice(1).forEach((cd, i) => {
    const dayRate = rate.afterCapPerDay == null ? rate.ratePerDay : rate.afterCapPerDay;
    const rawWin = cd * dayRate;
    const capped = rate.cap != null && rawWin > rate.cap;
    steps.push(`then ${cd} day${cd === 1 ? '' : 's'} × ${fmtGbp(dayRate)}/day${
      rate.afterCapPerDay == null ? '' : ' (after the cap)'} = ${fmtGbp(capped ? rate.cap : rawWin)}${
      capped ? ` (capped at ${fmtGbp(rate.cap)})` : ''}`);
  });
  if (country === 'USA' && !simGiven) steps.push('no-SIM rate applied');
  // USA pool suggestion: recommend the phone whose pool expiry best fits the
  // return date, unless the chosen phone is already the top pick.
  let poolLine = '';
  if (country === 'USA') {
    const ranked = poolPhoneSuggestions(phones, rentals, from, to, localISO());
    const best = ranked[0];
    if (best && best.phone.id !== (phone && phone.id)) {
      poolLine = `<div style="margin-top:6px;font-size:var(--fs-micro);line-height:1.5;"><i class="kc-ic kc-ic-idea" aria-hidden="true"></i> <span style="color:var(--accent);font-weight:600;">Best pool match:</span> ${deviceChip(best.phone)}
        <button type="button" class="btn btn-outline" style="padding:1px 8px;font-size:var(--fs-micro);margin-left:4px;"
          onclick="nrPickPhone('${escJs(String(best.phone.id))}')">Use</button>
        <br><span style="color:var(--muted);">${escHtml(best.reason)}</span></div>`;
    }
  }
  txt.innerHTML = `
    <span style="color:var(--muted);">Total days:</span> ${totalDays} &nbsp;|&nbsp;
    <span style="color:var(--muted);">Shabbos/Yom Tov excluded:</span> <span style="color:var(--gold);">${excluded}</span> &nbsp;|&nbsp;
    <span style="color:var(--muted);">Chargeable days:</span> ${chargeableDays} &nbsp;|&nbsp;
    <strong style="color:var(--success);font-size:var(--fs-ui);">${fmtGbp(price)}</strong>${discountLine}
    <div style="margin-top:6px;font-size:var(--fs-micro);color:var(--muted);line-height:1.6;"><i class="kc-ic kc-ic-abacus" aria-hidden="true"></i> ${steps.join(' → ')}
      ${excluded > 0 ? `<br><i class="kc-ic kc-ic-calendar" aria-hidden="true"></i> ${excluded} free day${excluded === 1 ? '' : 's'} — the phone is kept over these at no charge:${freeDayStamps(from, to)}` : ''}
    </div>${poolLine}
  `;
  // #25 — keep the payment row's default in step with the live total.
  // #29 — a monthly add-on VN bills on the VN path, so it isn't part of the
  // rental total the payment row defaults to (only a weekly one-off is).
  const vnMonthly = document.getElementById('rVNSub')?.value === 'monthly';
  const vnAmt = (document.getElementById('rAddVN')?.checked && !vnMonthly)
    ? (parseFloat(document.getElementById('rVNPrice')?.value) || 0) : 0;
  rLastTotal = Math.round((finalPrice + vnAmt) * 100) / 100;
  const payAmt = document.getElementById('rPayAmount');
  if (payAmt && document.getElementById('rPay')?.value !== 'account' && payAmt.dataset.touched !== '1') {
    payAmt.value = rLastTotal.toFixed(2);
  }
}

// #25 — the New-Rental payment row: choosing a "paid now" method reveals the
// amount (defaulted to the full total); "Full total" re-fills it.
function rPayMethodChange() {
  const method = document.getElementById('rPay')?.value;
  const wrap = document.getElementById('rPayAmountWrap');
  const amt = document.getElementById('rPayAmount');
  if (!wrap) return;
  if (method === 'account') { wrap.style.display = 'none'; }
  else { wrap.style.display = 'inline-flex'; if (amt && !amt.value) amt.value = (rLastTotal || 0).toFixed(2); }
}
function rPayFull() {
  const amt = document.getElementById('rPayAmount');
  if (amt) { amt.value = (rLastTotal || 0).toFixed(2); amt.dataset.touched = '1'; }
}

// One customer, several handsets, one trip through the form. Each phone gets
// its OWN rental record — the fleet, the calendar, returns and the ledger all
// key on one rental per line — but the dates, equipment, notes and terms are
// answered once. Discounts are NOT recomputed by hand: each rental is created
// in turn and priced by the same rule the single path uses, so the 3rd
// concurrent phone and beyond takes the standing discount exactly as it would
// have if they were entered one by one.
async function saveMultiPhoneRental(customerId, phoneIds, addAnother) {
  const from  = document.getElementById('rFrom').value;
  const to    = document.getElementById('rTo').value;
  const notes = document.getElementById('rNotes').value.trim();
  if (!from || !to || to <= from) { toast('Please enter valid dates.', 'error'); return; }

  const customer = customers.find(c => c.id === customerId);
  const today = localISO();
  const isReservation = from > today;

  // Every phone must be free for the window — one clash cancels the batch
  // rather than quietly renting out a subset the operator didn't choose.
  for (const id of phoneIds) {
    const clash = phoneConflicts(rentals, id, from, to, today)[0];
    if (clash) {
      const ph = phones.find(p => p.id === id);
      toast(`${fmtPhone(ph?.number || '')} is taken ${fmtDate(clash.fromDate)} → ${fmtDate(clash.toDate)} (${clash.customerName}) — remove it or pick another.`, 'error');
      return;
    }
  }

  const nrCharger = document.getElementById('nrGiven_charger')?.dataset.given === '1';
  const equipmentGiven = {
    phone: document.getElementById('nrGiven_phone')?.dataset.given === '1',
    sim:   document.getElementById('nrGiven_sim')?.dataset.given   === '1',
    plug:  nrCharger,
    cable: nrCharger,
  };

  // Price each phone as it would price if entered in turn.
  let already = multiPhoneCountFor(customerId, from, to);
  const lines = phoneIds.map((id, i) => {
    const phone = phones.find(p => p.id === id);
    const { chargeableDays, totalDays, price } =
      calcRentalPrice(from, to, phone.country, phone.ukPlan || 'standard', equipmentGiven.sim);
    const pct = multiPhoneDiscountPctForIndex(already + i);
    // Round at the point of storage: an unrounded discount put
    // 17.849999999999998 on the record and into the ledger behind it.
    const net = pct > 0 ? round2(Math.max(0, price * (1 - pct / 100))) : round2(price);
    return { phone, chargeableDays, totalDays, price: round2(price), pct, net };
  });
  // The virtual number, once for the batch. A weekly one is a one-off line and
  // rides on the first rental exactly as it does on a single rental; a monthly
  // one is provisioned as a real VN record and bills on the recurring path, so
  // it is deliberately NOT in this total.
  const mAddVN   = !!document.getElementById('rAddVN')?.checked;
  const mVnSub   = document.getElementById('rVNSub')?.value || 'weekly';
  const mVnPrefix = document.getElementById('rVNPrefix')?.value || '';
  const mVnPrice = mAddVN ? (parseFloat(document.getElementById('rVNPrice')?.value) || 0) : 0;
  const mVnRecurs = mAddVN && mVnSub === 'monthly';
  const vnOnBatch = mAddVN && !mVnRecurs ? round2(mVnPrice) : 0;
  const total = round2(lines.reduce((sum, l) => sum + l.net, 0) + vnOnBatch);

  // Payment taken now is spread across the batch in order, so each rental
  // carries its own true amountPaid and no rental is silently overpaid.
  const payMethod = document.getElementById('rPay')?.value || 'account';
  let payLeft = payMethod !== 'account'
    ? Math.max(0, Math.min(total, parseFloat(document.getElementById('rPayAmount')?.value) || 0)) : 0;

  if (!(await kcConfirm({
    title: isReservation ? `Reserve ${lines.length} phones` : `Confirm rental — ${lines.length} phones`,
    body: `<strong>${escName(customer.firstName)} ${escName(customer.lastName)}</strong> · ${fmtDate(from)} → ${fmtDate(to)}<br>` +
      lines.map(l => `${escHtml(fmtPhone(l.phone.number))} (${escHtml(l.phone.country)}) — ${fmtGbp(l.price)}` +
        (l.pct > 0 ? ` <span style="color:var(--gold);">−${l.pct}% → ${fmtGbp(l.net)}</span>` : '')).join('<br>') +
      (vnOnBatch > 0 ? `<br>+ virtual number ${escHtml(mVnPrefix)} — ${fmtGbp(vnOnBatch)}` : '') +
      (mVnRecurs ? `<br>+ virtual number ${escHtml(mVnPrefix)} — billed monthly, not on this rental` : '') +
      (payLeft > 0
        ? `<br><br>${fmtGbp(payLeft)} paid now, spread across them in order.`
          + (payLeft < total
              // Never silent. A short pot used to be indistinguishable from a
              // full one here, and the difference is money the shop then chases
              // a customer for who has already handed it over.
              ? `<br><span style="color:var(--danger-ink);font-weight:600;">That is ${fmtGbp(round2(total - payLeft))} less than the total — the rest goes on their account.</span>`
              : '')
        : ''),
    amount: total,
    okLabel: isReservation ? `Reserve ${lines.length} & charge` : `Charge ${lines.length} rentals`,
  }))) return;

  const created = [];
  lines.forEach((l, i) => {
    // The virtual number rides on the FIRST rental of the batch — one number,
    // charged once. Spreading it across the handsets would put a fraction of a
    // number on each, and returning one phone early would then refund part of
    // something the customer still has.
    const vnHere = i === 0 ? vnOnBatch : 0;
    const lineTotal = round2(l.net + vnHere);
    const pay = round2(Math.min(payLeft, lineTotal));
    payLeft = round2(payLeft - pay);
    const rental = {
      id: uid(), customerId,
      customerName: `${customer.firstName} ${customer.lastName}`,
      customerPhone: customer.phone || '',
      phoneId: l.phone.id, phoneNumber: l.phone.number, country: l.phone.country,
      ukPlan: l.phone.ukPlan || 'standard',
      fromDate: from, toDate: to,
      chargeableDays: l.chargeableDays, totalDays: l.totalDays,
      price: lineTotal, basePrice: l.price, rentalPrice: l.price,
      discountValue: l.pct, discountType: 'percent',
      vn: i === 0 ? mAddVN : false,
      vnPrefix: i === 0 && mAddVN ? mVnPrefix : '',
      vnSub: i === 0 && mAddVN ? mVnSub : '',
      vnPrice: i === 0 && mAddVN ? mVnPrice : 0,
      notes, amountPaid: pay,
      // Same method on every rental of the batch — one payment, one tender.
      paymentMethod: payMethod !== 'account' && pay > 0 ? payMethod : null,
      depositHeld: 0,
      termsAck: !!document.getElementById('rTerms')?.checked,
      termsAckName: document.getElementById('rTerms')?.checked
        ? (document.getElementById('rTermsName')?.value.trim() || '') : '',
      termsAckAt: document.getElementById('rTerms')?.checked ? new Date().toISOString() : '',
      status: isReservation ? 'booked' : 'active',
      createdAt: new Date().toISOString(),
      equipmentGiven,
    };
    rentals.push(rental);
    created.push(rental);
  });

  // …and the VN record itself, once, exactly as the single-rental path does it.
  if (mAddVN) {
    await window.api.addVirtualNumber({
      number: `${mVnPrefix} — pending`,
      customerId,
      platform: 'Other',
      notes: `Auto-created with rental ${lines[0]?.phone?.number || ''} · ${mVnSub} · from ${fmtDate(from)}`,
      ...(mVnRecurs ? {
        billingEnabled: true,
        monthlyPrice: mVnPrice,
        nextBillingDate: from,
        bundleLabel: `Rental add-on +${mVnPrefix}`,
      } : {}),
    }).catch(() => null);
  }

  const saveRes = await saveRentals(rentals);
  if (!saveRes || saveRes.success === false) {
    created.forEach(r => { const i = rentals.indexOf(r); if (i >= 0) rentals.splice(i, 1); });
    renderRentalsTab();
    return; // reportSave already surfaced the error
  }
  if (!isReservation) {
    created.forEach(r => {
      const p = phones.find(x => x.id === r.phoneId);
      if (p) { p.status = 'rented'; p.currentRental = r.id; }
    });
    savePhones(phones);
  }
  for (const r of created) await applyExtraCharges('rental', r.id, customerId, false).catch(() => '');
  closeDynamicModal();
  nrPhones = [];
  renderRentalsTab();
  if (addAnother) { openNewRentalModal(customerId); return; }
  showDonePanel({
    title: isReservation ? 'Reserved' : 'Rentals saved', icon: isReservation ? 'calendar' : 'check',
    customerId,
    customerName: `${customer.firstName} ${customer.lastName}`,
    customerPhone: customer.phone || '',
    summary: `${created.length} phones · ${fmtDate(from)} → ${fmtDate(to)}`
      + (isReservation ? ' · pickup at handover' : ''),
    total,
    payLine: 'on account',
    // Nothing was taken here, so the whole total is outstanding. The panel
    // states it in its own right — "on account" is a bookkeeping word, and the
    // number behind it is what decides whether you ask for money now.
    owed: total,
    method: null,
    paidNow: false,
    lines: created.map(r => ({
      name: `Phone rental ${fmtPhone(r.phoneNumber)} · ${fmtDate(from)} → ${fmtDate(to)}`,
      qty: 1, total: r.price,
    })),
    smsText: `Hi ${customer.firstName}, ${created.length} phones are booked ${fmtDate(from)} → ${fmtDate(to)}. Total ${fmtGbp(total)}. Kosher Connect, 0161 531 1386.`,
    again: { label: 'Another phone', icon: 'phone', sub: `for ${customer.firstName}`, run: () => openNewRentalModal(customerId) },
  });
}

// ── The panel that finishes a job ────────────────────────────────────────
// Every counter job used to end in a toast that said "saved!" and vanished,
// with the receipt four clicks away — customer card → Wallet → find the ledger
// row → the small ✉️ on it — at the one moment it is wanted, with the customer
// still standing there. Rentals, repairs, flights and SIM plans now all finish
// on this card instead: what just happened, and the next moves as big buttons.
//
// The recipient is printed ON the button rather than behind a second "are you
// sure?": the mistake worth catching is the right receipt sent to the wrong
// person, and naming the address in front of the press catches it without
// putting a dialog between the counter and a one-press job.
//
// d = { title, customerId, customerName, customerPhone, summary, total,
//       payLine, lines, method, paidNow, smsText, again }
//   lines  — receipt lines for /api/email (kind: 'sale')
//   smsText— the text receipt to draft; omitted, no Text button
//   again  — optional { label, sub, run } third button
let kcDone = null;

function showDonePanel(d) {
  kcDone = d;
  const c = customers.find(x => String(x.id) === String(d.customerId));
  const email = (c && c.email) || '';
  // Some rows carry OUR provider login (Lebara etc.) rather than the customer's
  // own address; a receipt sent there mails the shop.
  const ours = email && isOwnAccountEmail(email);
  const canEmail = !!email && !ours;
  const phone = (c && c.phone) || d.customerPhone || '';

  const emailBtn = canEmail
    ? `<button class="btn btn-primary rd-act kc-ic kc-ic-mail" id="rdEmail" onclick="kcDoneEmail(this)">Email receipt<span class="rd-sub">${escHtml(email)}</span></button>`
    : `<button class="btn btn-outline rd-act kc-ic kc-ic-mail" disabled title="${ours ? 'That address is a shop account login, not the customer\u2019s own' : 'No email address on this customer'}">Email receipt<span class="rd-sub">${ours ? 'shop login, not theirs' : 'no address on file'}</span></button>`;
  const smsBtn = phone && d.smsText
    ? `<button class="btn btn-outline rd-act" onclick="kcDoneText()">
         <i class="kc-ic kc-ic-chat" aria-hidden="true"></i> Text receipt<span class="rd-sub">${escHtml(fmtPhone(phone))}</span></button>`
    : '';
  const againBtn = d.again
    ? `<button class="btn btn-outline rd-act" onclick="kcDoneAgain()">
         ${escHtml(d.again.label)}<span class="rd-sub">${escHtml(d.again.sub || '')}</span></button>`
    : '';

  showDynamicModal(`
    <div class="modal-title">${d.title}</div>
    <div class="rd-summary">
      <div class="rd-who">${escName(d.customerName)}</div>
      <div class="rd-what">${escHtml(d.summary)}</div>
      ${Number.isFinite(d.total) ? `<div class="rd-money">${fmtGbp(d.total)}<span class="rd-sub">${escHtml(d.payLine || 'on account')}</span></div>` : ''}
      ${d.owed > 0 ? `<div class="rd-owed">${fmtGbp(d.owed)} still to pay</div>` : ''}
    </div>
    <div class="rd-actions">
      ${emailBtn}
      ${smsBtn}
      ${againBtn}
    </div>
    <div class="modal-actions"><button class="btn btn-outline" onclick="closeDynamicModal()">Done</button></div>
  `);
}

function kcDoneAgain() {
  const d = kcDone;
  closeDynamicModal();
  if (d && typeof d.again?.run === 'function') d.again.run();
}

function kcDoneText() {
  const d = kcDone;
  if (!d) return;
  closeDynamicModal();
  openTextReceiptModal(d.customerId, d.smsText);
}

async function kcDoneEmail(btn) {
  const d = kcDone;
  if (!d) return;
  if (btn) { btn.disabled = true; btn.innerHTML = 'Sending…'; }
  // A caller that has more to say than "name, qty, total" passes `receipt` —
  // its own shape for its own kind. A rental has a number, a start, an end and
  // a return, and squeezing those into a POS line description is how the old
  // rental receipt came to say nothing about owing anything. Everything that
  // does not pass one keeps the sale shape exactly as before.
  const body = d.receipt
    ? { ...d.receipt, customerId: d.customerId }
    : {
        kind: 'sale',
        customerId: d.customerId,
        lines: d.lines,
        total: d.total,
        method: d.method || null,
        paidNow: d.paidNow,
      };
  const res = await kcFetch('/api/email', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  }).then(r => r.json()).catch(() => null);

  const restore = () => { if (btn) { btn.disabled = false; btn.innerHTML = '<i class="kc-ic kc-ic-mail" aria-hidden="true"></i> Email receipt'; } };
  if (res && res.success && res.held) { toast(res.note || 'Email is on hold — receipt not sent.', 'warning'); restore(); }
  else if (res && res.success && res.redirected) {
    toast(res.note || `Test mode — sent to ${res.sentTo}.`, 'warning');
    if (btn) btn.innerHTML = '<i class="kc-ic kc-ic-check" aria-hidden="true"></i> Sent';
  } else if (res && res.success) {
    toast(`Receipt emailed to ${res.sentTo}.`, 'success');
    recordComm(d.customerId, { type: 'email', text: `Receipt emailed — ${fmtGbp(d.total)}` });
    if (btn) btn.innerHTML = '<i class="kc-ic kc-ic-check" aria-hidden="true"></i> Sent';
  } else { toast(res?.error || 'Could not send the receipt.', 'error'); restore(); }
}

// One text-receipt drafter for every module. Same shape as the rental status
// SMS that already existed: draft, then send / copy / open in WhatsApp — the
// send is HOLD-gated server-side like every other outbound message.
function openTextReceiptModal(customerId, text) {
  const c = customers.find(x => String(x.id) === String(customerId));
  showDynamicModal(`
    <div class="modal-title"><i class="kc-ic kc-ic-chat" aria-hidden="true"></i> Text receipt</div>
    <div style="font-size:var(--fs-small);color:var(--muted);margin-bottom:10px;">
      ${c && c.phone ? `To <span class="copy-val">${escHtml(fmtPhone(c.phone))}</span>. ` : ''}Edit it, then send — or copy it into your own messaging app.</div>
    <textarea class="form-input" id="kcTrText" rows="5" style="font-family:inherit;">${escHtml(text || '')}</textarea>
    <div class="modal-actions">
      <span class="modal-actions-group">
        <button class="btn btn-outline" onclick="closeDynamicModal()">Close</button>
        ${waLink(c || {}, '') ? `<button class="btn btn-outline kc-ic kc-ic-chat" onclick="kcTextReceiptWa('${escJs(String(customerId))}')">WhatsApp</button>` : ''}
        <button class="btn btn-outline kc-ic kc-ic-clipboard" onclick="kcTextReceiptCopy('${escJs(String(customerId))}')">Copy</button>
        <button class="btn btn-primary kc-ic kc-ic-upload" onclick="kcTextReceiptSend('${escJs(String(customerId))}')">Send</button>
      </span>
    </div>
  `);
}
async function kcTextReceiptSend(customerId) {
  const text = document.getElementById('kcTrText')?.value || '';
  if (!text.trim()) return;
  const res = await kcFetch('/api/sms', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ customerId, text }),
  }).then(x => x.json()).catch(() => ({ success: false, error: 'Network error.' }));
  if (!res.success) { toast(res.error || 'Could not send.', 'error'); return; }
  if (res.held) toast(res.note, 'warning');
  else if (res.redirected) toast(res.note, 'warning');
  else toast('Receipt texted', 'success', 'check');
  recordComm(customerId, { type: 'message', text: res.held ? 'Text receipt built (HOLD, not sent)' : res.redirected ? 'Text receipt sent to the test number, not the customer' : 'Text receipt sent' });
  closeDynamicModal();
}
async function kcTextReceiptCopy(customerId) {
  const text = document.getElementById('kcTrText')?.value || '';
  try { await navigator.clipboard.writeText(text); toast('Copied — paste it into your messaging app.', 'success'); }
  catch { toast('Select the text and copy it manually.', 'warning'); return; }
  recordComm(customerId, { type: 'message', text: 'Text receipt drafted & copied' });
  closeDynamicModal();
}
function kcTextReceiptWa(customerId) {
  const c = customers.find(x => String(x.id) === String(customerId));
  const url = waLink(c || {}, document.getElementById('kcTrText')?.value || '');
  if (!url) { toast('No usable phone number for WhatsApp.', 'warning'); return; }
  window.open(url, '_blank');
  recordComm(customerId, { type: 'message', text: 'Text receipt opened in WhatsApp' });
  closeDynamicModal();
}

async function saveNewRental(addAnother = false) {
  const customerId = document.getElementById('rCustomer').value;
  // Chips are the source of truth; a phone still sitting in the dropdown
  // unconfirmed counts too, so nobody loses a pick to a missed tap.
  const pending = document.getElementById('rPhone')?.value;
  if (pending && !nrPhones.includes(pending)) nrPhones.push(pending);
  const phoneId    = nrPhones[0] || '';
  const from       = document.getElementById('rFrom').value;
  const to         = document.getElementById('rTo').value;
  const notes      = document.getElementById('rNotes').value.trim();
  const addVN      = document.getElementById('rAddVN').checked;

  if (!customerId) { toast('Please select a customer.', 'error'); return; }
  if (!phoneId)    { toast('Please select a phone.', 'error'); return; }
  // Several phones for one customer: each becomes its own rental record, but
  // the operator answers the questions once. Handled by its own path so the
  // single-phone flow below is untouched.
  if (nrPhones.length > 1) return saveMultiPhoneRental(customerId, [...nrPhones], addAnother);
  if (!from || !to || to <= from) { toast('Please enter valid dates.', 'error'); return; }

  // Hard double-booking guard — a phone can hold one rental per date window.
  const clash = phoneConflicts(rentals, phoneId, from, to, localISO())[0];
  if (clash) {
    toast(`That phone is taken ${fmtDate(clash.fromDate)} → ${fmtDate(clash.toDate)} (${clash.customerName}${clash.status === 'booked' ? ', reserved' : ''}).`, 'error');
    return;
  }

  // Owner #7 — a pooled phone whose window runs out mid-rental is never booked
  // silently: the customer would lose service abroad. Booking it through this
  // gate creates a 🔴 high-priority activation task dated before the coverage
  // gap; the dialog also names covered alternatives so the operator can back
  // out and pick one instead.
  const gPhone = phones.find(p => p.id === phoneId);
  if (gPhone && (gPhone.country || '').toUpperCase() === 'USA' && gPhone.pool) {
    const exp = gPhone.poolExpiry || null;
    if (!exp || exp < to) {
      const covered = phones.filter(p =>
        p.id !== phoneId && (p.country || '').toUpperCase() === 'USA' && !p.maintenance &&
        p.status === 'available' && p.poolExpiry && p.poolExpiry >= to &&
        phoneConflicts(rentals, p.id, from, to, localISO()).length === 0).slice(0, 3);
      const actBy = exp && exp >= from ? exp : from;
      const ok = await kcConfirm({
        title: exp ? 'Pool runs out mid-rental' : 'Pool not activated',
        body: `<strong>${escHtml(fmtPhone(gPhone.number))}</strong> — pool “${escHtml(gPhone.pool)}” ${exp
            ? `expires <strong>${fmtDate(exp)}</strong>, before the return on ${fmtDate(to)}`
            : 'has no activation window on record'}: service would cut out mid-trip.<br>` +
          (covered.length
            ? `Covered instead: ${covered.map(p => `${escHtml(fmtPhone(p.number))} (till ${fmtDate(p.poolExpiry)})`).join(' · ')} — Cancel and pick one, or…`
            : 'No other covered phone is free for these dates, so…') +
          `<br>booking this one creates a high-priority task to activate “${escHtml(gPhone.pool)}” by <strong>${fmtDate(actBy)}</strong>.`,
        okLabel: 'Create the task & book anyway', okIcon: 'edit-note',
      });
      if (!ok) return; // operator backs out to pick a covered phone
      await window.api.addTask({
        title: `Activate pool “${gPhone.pool}” — ${fmtPhone(gPhone.number)} rented till ${fmtDate(to)}`,
        dueDate: actBy,
        priority: 'High',
        notes: `Pool ${exp ? 'expires ' + exp : 'has no window'}; rental runs ${from} → ${to}. Activate in 📶 Pools (or move the rental to a covered phone).`,
        customerId: customerId || null,
      }).catch(() => null);
      toast(`Task created: activate pool “${gPhone.pool}” by ${fmtDate(actBy)}.`, 'warning');
    }
  }
  // Future start = a reservation: the phone stays free until pickup.
  const isReservation = from > localISO();

  const customer = customers.find(c => c.id === customerId);
  const phone    = phones.find(p => p.id === phoneId);
  // One 🔌 Charger toggle drives both stored keys (plug + cable) — the
  // business treats the charger as a single item (T&C: "Charger: £10").
  const nrCharger = document.getElementById('nrGiven_charger')?.dataset.given === '1';
  const equipmentGiven = {
    phone: document.getElementById('nrGiven_phone')?.dataset.given === '1',
    sim:   document.getElementById('nrGiven_sim')?.dataset.given   === '1',
    plug:  nrCharger,
    cable: nrCharger,
  };
  const { chargeableDays, totalDays, price } =
    calcRentalPrice(from, to, phone.country, phone.ukPlan || 'standard', equipmentGiven.sim);

  let vnPrice = 0, vnPrefix = '', vnSub = '';
  if (addVN) {
    vnPrefix = document.getElementById('rVNPrefix').value;
    vnSub    = document.getElementById('rVNSub').value;
    vnPrice  = parseFloat(document.getElementById('rVNPrice').value) || 0;
  }

  const addDiscount = document.getElementById('rAddDiscount').checked;
  // Manual discount wins; otherwise the multi-phone rule applies itself
  // (price list: 3rd concurrent phone and more, 15% off).
  const autoPct       = addDiscount ? 0 : multiPhoneDiscountPct(rentals, customerId, from, to);
  const discountType  = addDiscount ? document.getElementById('rDiscountType').value : 'percent';
  const discountValue = addDiscount ? (parseFloat(document.getElementById('rDiscountValue').value) || 0) : autoPct;
  const discountedRental = discountValue > 0
    ? (discountType === 'percent' ? Math.max(0, price * (1 - discountValue / 100)) : Math.max(0, price - discountValue))
    : price;
  if (autoPct > 0) toast(`Multi-phone discount applied — 3rd phone and more, ${autoPct}% off.`, 'success');

  // #29 — one money model for virtual numbers. A MONTHLY add-on VN is now
  // provisioned as a real standalone virtual_numbers record and billed on the
  // recurring VN path (VN-<id>-<month>), so it is NOT baked into the rental
  // charge. A WEEKLY add-on has no monthly-sweep equivalent, so it stays a
  // one-off line inside the rental exactly as before.
  const vnRecurs = addVN && vnSub === 'monthly';
  const vnOnRental = addVN && !vnRecurs ? vnPrice : 0;
  const totalPrice = discountedRental + vnOnRental;
  // #25 — capture payment at rental time. "On account" = wallet debt (the old
  // behaviour); a "paid now" method settles some/all of it immediately.
  const payMethod = document.getElementById('rPay')?.value || 'account';
  const paidNow = payMethod !== 'account';
  let payAmt = paidNow ? (parseFloat(document.getElementById('rPayAmount')?.value) || 0) : 0;
  if (payAmt < 0) payAmt = 0;
  if (payAmt > totalPrice) payAmt = totalPrice; // never overpay the rental here
  if (!(await kcConfirm({
    title: isReservation ? 'Confirm reservation' : 'Confirm rental charge',
    body: `<strong>${escName(customer.firstName)} ${escName(customer.lastName)}</strong><br>
      ${escHtml(phone.number)} (${escHtml(phone.country)}) · ${fmtDate(from)} → ${fmtDate(to)} · ${chargeableDays} chargeable days${addVN ? '<br>+ virtual number' : ''}${discountValue > 0 ? '<br>discount applied' : ''}`,
    amount: totalPrice,
    okLabel: isReservation ? 'Reserve & charge' : 'Charge rental',
  }))) return;
  const rental = {
    id:           uid(),
    customerId,
    customerName: `${customer.firstName} ${customer.lastName}`,
    customerPhone: customer.phone || '',
    phoneId,
    phoneNumber:  phone.number,
    country:      phone.country,
    ukPlan:       phone.ukPlan || 'standard',
    fromDate:     from,
    toDate:       to,
    chargeableDays,
    totalDays,
    price:        totalPrice,
    basePrice:    price,
    discountValue,
    discountType,
    rentalPrice:  price,
    vn:           addVN,
    vnPrefix,
    vnSub,
    vnPrice,
    notes,
    amountPaid:   payAmt, // #25
    // HOW it was paid, not just that it was. The form has asked cash / card /
    // transfer since the beginning and the answer was read to decide whether
    // money moved, then dropped on the floor — so every rental payment reached
    // the ledger with no method, and cash-up's expected-cash total (which counts
    // only method='cash') never saw a rental. A cash hire made the till read
    // over at the end of the day, every day.
    paymentMethod: paidNow ? payMethod : null,
    // #26 — optional refundable deposit, tracked as held (not a wallet charge).
    depositHeld:  document.getElementById('rDeposit')?.checked
                    ? (parseFloat(document.getElementById('rDepositAmount')?.value) || 0) : 0,
    // #84 — lightweight signed acknowledgment of the loss/late terms at pickup.
    termsAck:     !!document.getElementById('rTerms')?.checked,
    termsAckName: document.getElementById('rTerms')?.checked
                    ? (document.getElementById('rTermsName')?.value.trim() || '') : '',
    termsAckAt:   document.getElementById('rTerms')?.checked ? new Date().toISOString() : '',
    status:       isReservation ? 'booked' : 'active',
    createdAt:    new Date().toISOString(),
    equipmentGiven,
  };

  rentals.push(rental);
  // Await the persist and only continue if it actually saved — otherwise we'd
  // create a VN for a rental that doesn't exist and toast success on a lost save.
  const saveRes = await saveRentals(rentals);
  if (!saveRes || saveRes.success === false) {
    const idx = rentals.indexOf(rental);
    if (idx >= 0) rentals.splice(idx, 1); // undo the optimistic push
    renderRentalsTab();
    return; // reportSave already surfaced the error
  }

  // #73 — persist the phone status ONLY when it actually changed. A future-
  // dated reservation leaves the phone free, so it needs no phones write.
  if (!isReservation) {
    phone.status        = 'rented';
    phone.currentRental = rental.id;
    savePhones(phones);
  }

  // #73 — no more c.history / c.totalPaid / c.services write for a rental. The
  // append-only ledger and the rental record are the single source of truth
  // (the card's balance is ledger-derived, its timeline is built from the
  // rentals array, and c.services rental entries were filtered out anyway), so
  // that third network round-trip and its parallel money mirror are dropped.

  // #29 — provision the add-on VN as a real virtual_numbers record. A monthly
  // one recurs on the VN path (billing enabled, first bill on the rental start
  // date); a weekly one is tracked but its single period was charged on the
  // rental above. Either way the number now exists as a proper VN record.
  if (addVN) {
    await window.api.addVirtualNumber({
      number: `${vnPrefix} — pending`,
      customerId,
      platform: 'Other',
      notes: `Auto-created with rental ${phone.number} · ${vnSub} · from ${fmtDate(from)}`,
      ...(vnRecurs ? {
        billingEnabled: true,
        monthlyPrice: vnPrice,
        nextBillingDate: from,
        bundleLabel: `Rental add-on +${vnPrefix}`,
      } : {}),
    }).catch(() => null);
  }

  // #25/#33/#38 — the counter payment is recorded through ONE channel: the
  // rental's amountPaid, which trueUpRentalLedger posts as PAY-RENTAL-<uuid>
  // (a 'payment' on the wallet ledger). We deliberately do NOT also post a
  // separate wallet payment here — that would double-count the same money.
  closeDynamicModal();
  // Owner-defined auto extras for rentals (posted once, keyed on the rental).
  const extraMsg = await applyExtraCharges('rental', rental.id, customerId, false);
  const payLine = paidNow && payAmt > 0
    ? (payAmt >= totalPrice ? ' Paid in full.' : ` ${fmtGbp(payAmt)} paid, ${fmtGbp((totalPrice - payAmt))} on account.`)
    : '';
  if (extraMsg) toast(`Rental saved.${extraMsg}`, 'success');
  renderRentalsTab();
  // Family trip: reopen prefilled — same customer, same dates, next phone.
  // The multi-phone discount then applies itself from the 3rd phone on.
  // Otherwise the done panel takes over: it says the same thing the toast used
  // to, and carries the receipt instead of leaving it four clicks away.
  if (addAnother) {
    openNewRentalModal(customerId);
    setTimeout(() => {
      const f = document.getElementById('rFrom'), t = document.getElementById('rTo');
      if (f) { f.value = from; showHebrewDate('rFrom', 'rFromHeb'); }
      if (t) { t.value = to; showHebrewDate('rTo', 'rToHeb'); }
      refreshRentalPhoneOptions(); updateRentalCalc(); nrSetGivenDefaults();
    }, 80);
    return;
  }
  showDonePanel({
    title: isReservation ? 'Reserved' : 'Rental saved', icon: isReservation ? 'calendar' : 'check',
    customerId,
    customerName: `${customer.firstName} ${customer.lastName}`,
    customerPhone: customer.phone || '',
    summary: `${fmtPhone(phone.number)} · ${fmtDate(from)} → ${fmtDate(to)} · ${chargeableDays} chargeable day${chargeableDays === 1 ? '' : 's'}`
      + (isReservation ? ' · pickup at handover' : ''),
    total: totalPrice,
    payLine: paidNow && payAmt > 0
      ? (payAmt >= totalPrice ? 'paid in full' : `${fmtGbp(payAmt)} paid, ${fmtGbp(totalPrice - payAmt)} on account`)
      : 'on account',
    // The same figure the pay line already carries, given its own weight: a
    // part payment left "£80 on account" in small muted grey beside a large
    // £140 total, so the number the counter has to act on was the quietest
    // thing on the card. Fully paid passes nothing and the line stays away.
    owed: Math.max(0, totalPrice - (paidNow ? payAmt : 0)),
    method: paidNow ? payMethod : null,
    paidNow,
    lines: [{ name: `Phone rental ${fmtPhone(phone.number)} · ${fmtDate(from)} → ${fmtDate(to)}`, qty: 1, total: totalPrice }],
    // The rental's own receipt shape. The dates go as ISO days, not as the
    // formatted strings on screen — the email formats them itself, and the
    // pay-by date is worked out from `to` on the server where the rule lives.
    receipt: {
      kind: 'rental',
      number: phone.number || '',
      from, to,
      days: chargeableDays,
      // The window day by day, so the email can show WHY six days cost what
      // seven days' hire cost — the free ones are Shabbos and Yom Tov.
      dayList: rentalDayList(from, to),
      total: totalPrice,
      method: paidNow ? payMethod : null,
      paidAmount: paidNow ? payAmt : 0,
      reservation: isReservation,
    },
    smsText: buildRentalSms(rental),
    again: {
      label: 'Another phone', icon: 'phone', sub: `for ${customer.firstName}`,
      run: () => {
        openNewRentalModal(customerId);
        setTimeout(() => {
          const f = document.getElementById('rFrom'), t = document.getElementById('rTo');
          if (f) { f.value = from; showHebrewDate('rFrom', 'rFromHeb'); }
          if (t) { t.value = to; showHebrewDate('rTo', 'rToHeb'); }
          refreshRentalPhoneOptions(); updateRentalCalc(); nrSetGivenDefaults();
        }, 80);
      },
    },
  });
}

// Post any auto "extra charges" for a freshly-created rental/SIM (their money
// doesn't go through a single server charge, so the client triggers it).
// Returns a short message fragment for the success toast.
async function applyExtraCharges(appliesTo, refBase, customerId, paidNow) {
  const res = await kcFetch('/api/custom-charges', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ op: 'apply', appliesTo, refBase, customerId, paidNow }),
  }).then(r => r.json()).catch(() => null);
  if (res?.success && res.extras?.length) {
    return ` Incl. ${res.extras.map(e => `${e.label} ${fmtGbp(e.amount)}`).join(', ')}.`;
  }
  return '';
}

// Reservation pickup: the customer is here, the phone goes out.
async function startReservation(rentalId) {
  const r = rentals.find(x => x.id === rentalId);
  if (!r || r.status !== 'booked') return;
  const phone = phones.find(p => p.id === r.phoneId);
  if (phone && phone.status === 'rented') {
    toast(`${phone.number} is still out on another rental — return it first.`, 'error');
    return;
  }
  // THE CHARGE RUNS FROM THE TRAVEL DATE, NOT FROM COLLECTION.
  //
  // This is a reversal, and worth saying so. The rule here was owner item #11:
  // "the charge window starts when the phone is PHYSICALLY taken, not on the
  // reserved from-date", and collecting a phone repriced the hire from that
  // day. Shloime, 27 Aug 2026, having run it in the shop: "charge should only
  // start from travel date, not pickup".
  //
  // He is describing what a customer thinks they are buying. Somebody who
  // collects on the Sunday for a Thursday flight has not had four days of
  // anything, and charging for them turns a courtesy — take it now, it saves
  // you a trip — into a surcharge nobody agreed to. It also punished the shop's
  // own convenience: handing phones out early is how a Friday rush is avoided.
  //
  // The pickup date is still recorded. It is the day the handset left the shop,
  // which matters for stock, for possession, and for the stage the hire reads
  // at (lib/rentalStage.mjs — collected but not travelling is 'fetched'). It
  // just no longer decides the money.
  const today = localISO();
  const pickup = today <= r.toDate ? today : r.toDate;
  const earlyDays = pickup < r.fromDate
    ? Math.round((Date.parse(`${r.fromDate}T00:00:00Z`) - Date.parse(`${pickup}T00:00:00Z`)) / 86400000) : 0;
  if (!(await kcConfirm({
    title: 'Hand the phone over',
    body: `<strong>${escName(r.customerName || '')}</strong> takes ${escHtml(fmtPhone(r.phoneNumber || ''))} today.<br>
      Charged window: <strong>${fmtDate(r.fromDate)} → ${fmtDate(r.toDate)}</strong> · ${r.chargeableDays} chargeable days.`
      + (earlyDays > 0
          ? `<br><span style="color:var(--muted);">Collected ${earlyDays} day${earlyDays === 1 ? '' : 's'} early — not charged for.</span>`
          : ''),
    amount: Number(r.price) || 0,
    okLabel: 'Hand it over',
  }))) return;
  r.pickupDate = pickup;
  r.status = 'active';
  saveRentals(rentals);
  if (phone) {
    phone.status = 'rented';
    phone.currentRental = r.id;
    savePhones(phones);
  }
  toast(`Handed over — ${r.customerName} has ${r.phoneNumber} until ${fmtDate(r.toDate)}.`
    + (earlyDays > 0 ? ` Charged from ${fmtDate(r.fromDate)}, not today.` : ''), 'success');
  renderRentalsTab();
}

// ══ VOID RENTAL (owner #9) ══
// Undo a wrongly-assigned rental WITHOUT deleting it: the record stays, marked
// voided with a reason, every charge reverses to £0 on the ledger (see
// bucketTargets in lib/tableStore.js), the phone frees, and the customer's
// comm log gets an entry — so every happening keeps its why. The reason list
// is owner-editable in Settings (void_reasons), like the provider list.
function voidReasons() {
  const s = pricingConfig?.settings?.find(x => x.key === 'void_reasons');
  const list = String(s?.textValue || '').split(',').map(x => x.trim()).filter(Boolean);
  return list.length ? list : ['Mistake', 'Didn’t fly', 'Other'];
}

function openVoidRentalModal(rentalId) {
  const r = rentals.find(x => x.id === rentalId);
  if (!r || r.voided) return;
  const owed = rentalGrandTotal(r);
  showDynamicModal(`
    <div class="modal-title"><i class="kc-ic kc-ic-undo" aria-hidden="true"></i> Void rental — ${escName(r.customerName || '')}</div>
    <div style="font-size:var(--fs-body);margin-bottom:12px;">
      ${escHtml(fmtPhone(r.phoneNumber || ''))} · ${fmtDate(r.fromDate)} → ${fmtDate(r.toDate)}<br>
      Every charge on this rental reverses to £0 (${fmtGbp(owed)} today).
      ${(r.amountPaid || 0) > 0 ? `<br><i class="kc-ic kc-ic-alert" aria-hidden="true"></i> ${fmtGbp(r.amountPaid)} was already paid — it stays on the wallet as credit to refund or reuse.` : ''}
      <br>The rental stays on the books marked <strong>voided</strong>, with the reason on the customer's history.
    </div>
    <div class="form-grid">
      <div class="form-group">
        <label class="form-label">Reason *</label>
        <select class="form-input" id="vrReason">
          ${voidReasons().map(x => `<option value="${escHtml(x)}">${escHtml(x)}</option>`).join('')}
        </select>
      </div>
      <div class="form-group">
        <label class="form-label">Note <span style="color:var(--muted);font-weight:400;">(optional)</span></label>
        <input class="form-input" type="text" id="vrNote" placeholder="e.g. meant for his brother">
      </div>
    </div>
    <div class="modal-actions">
      <button class="btn btn-outline" onclick="closeDynamicModal()">Cancel</button>
      <button class="btn btn-primary kc-ic kc-ic-undo" style="background:var(--danger-ink);border-color:var(--danger-ink);"
        onclick="confirmVoidRental('${rentalId}')">Void this rental</button>
    </div>
  `);
}

async function confirmVoidRental(rentalId) {
  const r = rentals.find(x => x.id === rentalId);
  if (!r || r.voided) return;
  const reason = document.getElementById('vrReason')?.value || 'Other';
  const note = document.getElementById('vrNote')?.value.trim() || '';
  const original = { price: r.price, lateFee: r.lateFee || 0, lostChargesTotal: r.lostChargesTotal || 0 };
  r.voided = { reason, note, at: localISO(), original };
  // Zero the client money fields so every display (balance, debt, dashboards)
  // agrees with the ledger reversal the server posts from bucketTargets.
  r.price = 0; r.lateFee = 0; r.lostChargesTotal = 0;
  r.status = 'returned';
  const phone = phones.find(p => p.id === r.phoneId);
  if (phone && phone.currentRental === r.id) {
    phone.status = 'available'; phone.currentRental = null;
    savePhones(phones);
  }
  const res = await saveRentals(rentals);
  if (res && res.success === false) {
    // Save refused — put the record back the way it was.
    r.price = original.price; r.lateFee = original.lateFee; r.lostChargesTotal = original.lostChargesTotal;
    r.voided = null;
    return;
  }
  await recordComm(r.customerId, {
    type: 'note',
    text: `↩ Rental voided — ${reason}${note ? ` (${note})` : ''} · ${fmtPhone(r.phoneNumber || '')} ${fmtDate(r.fromDate)} → ${fmtDate(r.toDate)} · ${fmtGbp(original.price)} reversed`,
  }).catch(() => null);
  closeDynamicModal();
  renderRentalsTab();
  toast(`Rental voided (${reason}) — charges reversed.`, 'warning');
}

