function showModal() { const m = document.getElementById('customerModal'); kcSaveReturnFocus('customerModal'); m.classList.remove('hidden'); suppressCardScrim(true); kcWindowise(m); autofocusFirstField(m); }
function closeModal() { document.getElementById('customerModal').classList.add('hidden'); suppressCardScrim(false); kcRestoreReturnFocus('customerModal'); }

function normalizeEmail(email) {
  if (!email) return '';
  const [local, domain] = email.toLowerCase().split('@');
  if (!domain) return local;
  const cleanLocal = local.replace(/\./g, '').replace(/\+.*$/, '');
  return `${cleanLocal}@${domain}`;
}

function getFullPhone() {
  const code = document.getElementById('fCountryCode').value.replace('-CA', '');
  const num = document.getElementById('fPhoneNumber').value.trim().replace(/\s/g, '');
  return num ? `${code}${num}` : '';
}

function checkPhoneDuplicate() {
  const editId = document.getElementById('editId').value;
  const phone = getFullPhone();
  const warn = document.getElementById('warnPhone');
  if (!phone) { warn.classList.remove('visible'); return; }
  const dup = customers.find(c => c.id !== editId && c.phone && c.phone.replace(/\s/g,'') === phone.replace(/\s/g,''));
  warn.classList.toggle('visible', !!dup);
}

// WHY two addresses that plainly differ count as one mailbox. normalizeEmail()
// lowercases, drops every full stop from the name part and cuts anything after
// a "+", so three different-looking lines can land on the same customer. A bare
// "this email already exists" leaves the operator staring at two addresses that
// are visibly not the same and doubting the app; this names the rule that
// actually fired. Returns ready-to-insert HTML fragments.
function emailDupWhy(typed, existing) {
  const a = String(typed || '').trim().toLowerCase();
  const b = String(existing || '').trim().toLowerCase();
  const aLocal = a.split('@')[0] || '';
  const bLocal = b.split('@')[0] || '';
  const domain = a.split('@')[1] || '';
  const gmail = /^(gmail|googlemail)\.com$/.test(domain);
  const tag = aLocal.split('+')[1] || bLocal.split('+')[1] || '';
  const aBase = aLocal.split('+')[0];
  const bBase = bLocal.split('+')[0];
  const dots = aBase !== bBase && aBase.replace(/\./g, '') === bBase.replace(/\./g, '');
  const why = [];
  if (tag) {
    why.push(gmail
      ? `The <b>+${escHtml(tag)}</b> is only a label — Gmail delivers anything after a <b>+</b> to the very same inbox.`
      : `Anything after the <b>+</b> is treated as a label here, so <b>+${escHtml(tag)}</b> doesn’t make it a different address.`);
  }
  if (dots) {
    why.push(gmail
      ? 'Gmail also ignores <b>full stops</b> in the part before the @, so both spellings reach one inbox.'
      : 'We ignore <b>full stops</b> in the part before the @. Outside Gmail a full stop <i>can</i> matter — check this really is the same person.');
  }
  // Compare the RAW strings here, not the lowercased ones — capitals are the
  // only difference left once the dot and +tag rules haven't fired.
  if (!why.length && String(typed || '').trim() !== String(existing || '').trim()) {
    why.push('Only the capitals differ, and an email address is never case-sensitive.');
  }
  return why;
}

function emailDupHtml(dup, typed) {
  const who = `${dup.firstName || ''} ${dup.lastName || ''}`.trim() || 'Another customer';
  const why = emailDupWhy(typed, dup.email);
  return `<i class="kc-ic kc-ic-alert" aria-hidden="true"></i> <b>${escHtml(who)}</b> already has this mailbox — <span class="warn-em">${escHtml(dup.email)}</span>.`
    + `<div class="warn-why">${why.map(l => `<div>${l}</div>`).join('')}`
    + '<div>One mailbox belongs to one customer, so this can’t be saved as a second person.</div></div>';
}

function checkEmailDuplicate() {
  const editId = document.getElementById('editId').value;
  const email = document.getElementById('fEmail').value.trim();
  const warn = document.getElementById('warnEmail');
  if (!email) { warn.classList.remove('visible'); return; }
  const norm = normalizeEmail(email);
  const dup = customers.find(c => c.id !== editId && c.email && normalizeEmail(c.email) === norm);
  if (!dup) { warn.classList.remove('visible'); return; }
  warn.innerHTML = emailDupHtml(dup, email);
  warn.classList.add('visible');
}

function checkNameDuplicate() {
  const editId = document.getElementById('editId').value;
  const first = document.getElementById('fFirstName').value.trim().toLowerCase();
  const last  = document.getElementById('fLastName').value.trim().toLowerCase();
  const warn = document.getElementById('warnName');
  if (!first || !last) { warn.classList.remove('visible'); return; }
  const dup = customers.find(c => c.id !== editId
    && c.firstName.toLowerCase() === first
    && c.lastName.toLowerCase() === last);
  warn.classList.toggle('visible', !!dup);
}

async function saveCustomer() {
  let valid = true;
  const title     = capName(document.getElementById('fTitle')?.value || '');
  const firstName = capName(document.getElementById('fFirstName').value);
  const lastName  = capName(document.getElementById('fLastName').value);
  const phoneNum  = document.getElementById('fPhoneNumber').value.trim();
  const code      = document.getElementById('fCountryCode').value.replace('-CA', '');
  const altPhone  = document.getElementById('fAltPhone')?.value.trim() || '';
  const email     = document.getElementById('fEmail').value.trim();
  const altEmail  = document.getElementById('fAltEmail')?.value.trim() || '';
  const address   = document.getElementById('fAddress').value.trim();
  const notes     = document.getElementById('fNotes')?.value.trim() || '';
  const popNote   = document.getElementById('fPopNote')?.value.trim().slice(0, 140) || '';
  const editId    = document.getElementById('editId').value;

  if (!firstName) { setErr('errFirstName', true); setInputErr('fFirstName', true); valid = false; }
  else { setErr('errFirstName', false); setInputErr('fFirstName', false); }

  if (!lastName) { setErr('errLastName', true); setInputErr('fLastName', true); valid = false; }
  else { setErr('errLastName', false); setInputErr('fLastName', false); }

  // Required, and then actually a number. The country code lives in its own
  // field, so what is checked here is the subscriber part on its own — a UK
  // "7911 123456" is 10 digits and must not be read as too short. The check
  // runs on the two of them joined, the way the number is stored.
  const phoneShape = phoneNum ? phoneProblem(`${code} ${phoneNum}`) : null;
  if (!phoneNum) { setErr('errPhone', 'Phone number is required'); setInputErr('fPhoneNumber', true); valid = false; }
  else if (phoneShape) { setErr('errPhone', phoneShape.message); setInputErr('fPhoneNumber', true); valid = false; }
  else { setErr('errPhone', false); setInputErr('fPhoneNumber', false); }

  if (!valid) return;

  const fullPhone = `${code} ${phoneNum}`;
  const phoneDup = customers.find(c => c.id !== editId && c.phone && c.phone.replace(/\s/g,'') === fullPhone.replace(/\s/g,''));
  if (phoneDup) {
    setErr('errPhone', '<i class="kc-ic kc-ic-cross" aria-hidden="true"></i> This phone number is already registered.');
    setInputErr('fPhoneNumber', true);
    document.getElementById('warnPhone').classList.add('visible');
    return;
  }

  // Block on a duplicate mailbox HERE, with the reason spelled out. The column
  // is uniquely indexed, so saving one anyway used to fail in the database and
  // surface as the generic "couldn't save that" — a real duplicate reported as
  // a storage fault, with no hint that a dot or a +tag was what collided.
  const emailDup = email && customers.find(c => c.id !== editId && c.email
    && normalizeEmail(c.email) === normalizeEmail(email));
  if (emailDup) {
    const warn = document.getElementById('warnEmail');
    warn.innerHTML = emailDupHtml(emailDup, email);
    warn.classList.add('visible');
    setInputErr('fEmail', true);
    warn.scrollIntoView({ block: 'center', behavior: 'smooth' });
    return;
  }
  setInputErr('fEmail', false);

  // Soft-warn on a same-name customer (schema build rule: block on email/phone
  // duplicates, WARN on name — two Moshe Katzes are legal but usually a slip).
  const nameKey = `${firstName} ${lastName}`.toLowerCase().replace(/\s+/g, ' ');
  const nameDup = customers.find(c => c.id !== editId &&
    `${c.firstName || ''} ${c.lastName || ''}`.toLowerCase().replace(/\s+/g, ' ').trim() === nameKey);
  if (nameDup) {
    const proceed = await window.api.confirmDelete(
      `A customer named "${firstName} ${lastName}" already exists (${nameDup.phone || 'no phone'}).\n\nSave anyway as a separate customer?`, 'Save anyway', { danger: false }
    );
    if (!proceed) return;
  }

  let accountEmail = document.getElementById('fAccountEmail')?.value.trim() || '';
  // Known own-address typed into the CONTACT field → offer to file it right.
  let contactEmail = email;
  if (contactEmail && isOwnAccountEmail(contactEmail)) {
    const move = await window.api.confirmDelete(
      `"${contactEmail}" is one of the business's own Gmail addresses (dot/plus variant).\n\nSave it as the ACCOUNT email instead of the customer's contact email?`, 'Use as account email', { danger: false }
    );
    if (move) { if (!accountEmail) accountEmail = contactEmail; contactEmail = ''; }
  }

  const payload = { title, firstName, lastName, phone: fullPhone, altPhone, email: contactEmail, altEmail, address, notes, popNote,
    accountEmail,
    // How this customer usually pays. '' means "ask each time" — the till and
    // the wallet start on it, they do not enforce it.
    defaultPaymentMethod: document.getElementById('fPayMethod')?.value || '',
    // How far on account before the till WARNS (the Epos Now Customer Credit
    // idea, KC-shaped: a warning, never a refusal). '' = no limit.
    creditLimit: (Number(document.getElementById('fCreditLimit')?.value) > 0
      ? Number(document.getElementById('fCreditLimit').value) : ''),
    // Only sent when the field is on screen — the PUT merges over the stored
    // row, so omitting it while the WhatsApp channel is off preserves whatever
    // was already recorded instead of silently clearing it.
    ...(document.getElementById('fHasWhatsapp')
      ? { hasWhatsapp: document.getElementById('fHasWhatsapp').checked }
      : {}),
    passportOnFile: document.getElementById('fPassportOnFile').checked,
    // Owner #2 — house account config; lastSettled survives edits untouched.
    houseAccount: document.getElementById('fHouseEnabled')?.checked
      ? {
          enabled: true,
          day: Math.min(28, Math.max(1, parseInt(document.getElementById('fHouseDay')?.value, 10) || 1)),
          min: parseFloat(document.getElementById('fHouseMin')?.value) > 0 ? parseFloat(document.getElementById('fHouseMin').value) : null,
          max: parseFloat(document.getElementById('fHouseMax')?.value) > 0 ? parseFloat(document.getElementById('fHouseMax').value) : null,
          lastSettled: (editId && customers.find(c => c.id === editId)?.houseAccount?.lastSettled) || null,
        }
      : null };

  // Both branches must survive a rejected fetch as well as {success:false} —
  // window.api.* does r.json() with no catch, so a dropped connection rejects
  // here rather than returning a body. Failure keeps the modal open with the
  // typed data intact (the convention deleteCustomer/saveCashup/reportSave
  // already follow); only success falls through to closeModal().
  const saveFailed = (res) => {
    toast((res && res.error) || 'Could not save the customer — nothing was changed. Check your connection and try again.', 'error');
  };
  if (editId) {
    payload.id = editId;
    const res = await window.api.updateCustomer(payload).catch(() => null);
    if (res && res.success) {
      const idx = customers.findIndex(c => c.id === editId);
      if (idx !== -1) customers[idx] = res.customer;
      sortCustomersAZ();  // a rename may change where they sit in A–Z
      // Silent — closeModal() + renderTableRows() below show the new values.

      const updated = customers.find(c => c.id === editId);
      if (updated) {
        const newName = `${updated.firstName} ${updated.lastName}`;
        let changed = false;
        rentals.forEach(r => {
          if (r.customerId === editId) {
            r.customerName  = newName;
            r.customerPhone = updated.phone || '';
            changed = true;
          }
        });
        if (changed) saveRentals(rentals);
        // #44/#71 — SIM rows carry a denormalized customerName too; keep it
        // fresh on rename (previously only rentals were patched, so SIM rows
        // kept the stale name forever).
        let simChanged = false;
        sims.forEach(s => {
          if (s.customerId === editId) { s.customerName = newName; simChanged = true; }
        });
        if (simChanged) saveSims(sims);
      }
    } else { saveFailed(res); return; }
  } else {
    const res = await window.api.addCustomer(payload).catch(() => null);
    if (res && res.success) {
      customers.push(res.customer);
      sortCustomersAZ();
      toast('Customer added.', 'success');
    } else { saveFailed(res); return; }
  }

  closeModal();
  applySearch();
  renderTableRows();
  const statEl = document.getElementById('statTotal');
  if (statEl) statEl.textContent = customers.length;
}

async function deleteCustomer(id) {
  const c = customers.find(x => x.id === id);
  if (!c) return;
  const today = localISO();
  // Block deletion unless every rental is returned with all given items decided
  // (returned or lost) — uses the same itemStatus model as the rentals tab.
  const hasUnreturned = rentals.some(r =>
    r.customerId === id && getComputedStatus(r, today) !== 'returned'
  );
  if (hasUnreturned) {
    toast('Cannot delete a customer who still has an unreturned rental.', 'error');
    return;
  }
  const confirmed = await window.api.confirmDelete(`Delete "${c.firstName} ${c.lastName}"?\n\nThis cannot be undone.`, 'Delete');
  if (!confirmed) return;
  // Ask the server FIRST — a customer with ledger money history is not
  // deletable (append-only wallet), and nothing local should change then.
  const res = await window.api.deleteCustomer(id);
  if (!res || res.success === false) {
    toast(res?.error || 'Could not delete this customer.', 'error');
    return;
  }
  rentals.filter(r => r.customerId === id && r.status !== 'returned').forEach(r => {
    const phone = phones.find(p => p.id === r.phoneId);
    if (phone) { phone.status = 'available'; phone.currentRental = null; }
  });
  rentals = rentals.filter(r => r.customerId !== id);
  sims    = sims.filter(s => s.customerId !== id);
  savePhones(phones);
  saveRentals(rentals);
  saveSims(sims);
  customers = customers.filter(x => x.id !== id);
  if (selectedId === id) {
    selectedId = null;
    closeCustomerCard();
  }
  applySearch();
  renderTableRows();
  const statEl = document.getElementById('statTotal');
  if (statEl) statEl.textContent = customers.length;
  toast('Customer deleted.', 'warning');
}

