function saveSims(data, deletedIds = []) {
  if (saveBlocked('sims')) return Promise.resolve({ success: false, blocked: true });
  sims = data;
  return reportSave('sims', window.api.saveAllSims(data, deletedIds));
}

let simSearchTerm = '';
let simFilterPay = 'all';     // all | through-me | direct
let simFilterStatus = 'all';  // all | active | renewing

// Provider badge — the provider column is a wall of identical grey text, and
// a quiet tint per provider lets the eye sweep for "the Lebara ones" without
// reading every row (owner, 9 Aug 2026). Same colour for the same provider
// everywhere, however it was typed ("Lebara"/"lebara"): the providers the shop
// actually deals with carry a fixed colour and tidy label; anything new hashes
// into the same 8-tint palette (.kc-prov in the stylesheet). App-palette tints
// on purpose, not the brands' own logo colours — a column of loud brand reds
// would fight the flat design and falsely read as trouble.
const KNOWN_PROVIDERS = {
  lebara: ['Lebara', 0], '1pmobile': ['1pMobile', 1], o2: ['O2', 2],
  vodafone: ['Vodafone', 3], ee: ['EE', 4], three: ['Three', 5],
  giffgaff: ['giffgaff', 6], lycamobile: ['Lycamobile', 7],
};
function providerBadge(name) {
  const raw = String(name || '').trim();
  if (!raw) return '—';
  const norm = raw.toLowerCase().replace(/[^a-z0-9]/g, '');
  const known = KNOWN_PROVIDERS[norm];
  let tint, label;
  if (known) { [label, tint] = known; }
  else {
    let h = 0;
    for (let i = 0; i < norm.length; i++) h = (h * 31 + norm.charCodeAt(i)) >>> 0;
    tint = h % 8;
    label = raw[0].toUpperCase() + raw.slice(1);
  }
  return `<span class="kc-prov kc-prov-${tint}">${escHtml(label)}</span>`;
}

// ── KC_SIMFUNDING mirror start ── (lib/simFunding.mjs)
const KC_SIMFUNDING_DEAD = new Set(['cancelled']);
function simFundingState(sim, method) {
  if (!sim || sim.paymentType === 'direct') return 'not-billed';
  if (KC_SIMFUNDING_DEAD.has(String(sim.status || ''))) return 'not-billed';
  const dd = String(method?.dd || '');
  if (dd === 'active') return 'dd';
  if (method?.card) return 'card';
  if (dd === 'pending') return 'dd-pending';
  return 'none';
}
function fundingLabel(state) {
  if (state === 'none') return 'nothing to collect from';
  if (state === 'dd-pending') return 'DD setting up';
  return '';
}
// ── KC_SIMFUNDING mirror end ──

// The marker in the Payment cell. Nothing at all until the methods have
// loaded, and nothing on a plan that is funded — a badge on every row is
// wallpaper, and the point is that these few rows are not like the others.
function fundingChip(sim) {
  const method = simMethodFor(sim);
  if (!method) return '';                 // not loaded: say nothing, claim nothing
  const state = simFundingState(sim, method);
  const label = fundingLabel(state);
  if (!label) return '';
  const cls = state === 'none' ? 'kc-unfunded' : 'kc-funding-pending';
  const title = state === 'none'
    ? 'The shop pays the network for this plan and the customer has no card on file and no Direct Debit mandate — there is no way to collect it.'
    : 'A Direct Debit mandate is set up and not yet active. Bacs takes about two working days.';
  return ` <span class="${cls}" title="${title}">${label}</span>`;
}

// What each customer has on file, as booleans — never the payment-method ids
// (see pages/api/payment-methods.js). Null until the first load returns, and
// the screen says so rather than claiming a plan is unfunded on no evidence:
// a false "nothing to collect from" on 300 rows would be read once, disproved,
// and then ignored forever.
let simPayMethods = null;
let simPayMethodsAsked = false;
function simMethodFor(sim) {
  return simPayMethods ? (simPayMethods[String(sim.customerId)] || {}) : null;
}
async function ensurePayMethods() {
  if (simPayMethodsAsked) return;
  simPayMethodsAsked = true;
  const res = await window.api.getPaymentMethods();
  // A failed load leaves it null — unknown, not "nobody has a card".
  if (!res || !res.success) { simPayMethodsAsked = false; return; }
  simPayMethods = res.methods || {};
  renderSimRows();
}

function renderSimsTab() {
  const content  = document.getElementById('mainContent');
  ensurePayMethods();
  const today    = localISO();
  const tomorrow = localISO(new Date(Date.now() + 86400000));

  const active   = sims.filter(simLive).length;
  const renewing = sims.filter(s => simLive(s) && (s.renewalDate === today || s.renewalDate === tomorrow));
  const totalRev = sims.reduce((sum, s) => sum + (s.history || []).reduce((a, h) => a + (h.amount || 0), 0), 0);

  const bannerHtml = renewing.length > 0 ? `
    <div class="renewal-banner">
      <span class="kc-ic kc-ic-alert" style="font-size:var(--fs-title);"></span>
      <span><strong>${renewing.length} SIM${renewing.length > 1 ? 's' : ''} renewing ${renewing.some(s => s.renewalDate === today) ? 'TODAY' : 'TOMORROW'}:</strong>
      ${renewing.map(s => `<span style="margin-left:8px;">· ${escHtml(capName(s.customerName))} (${escHtml(s.simNumber)})</span>`).join('')}</span>
    </div>` : '';

  // ── Which mailbox is this line's carrier account in? ────────────────────
  //
  // Owner, 17 Aug, on finding the SIM estate spread over seven of the shop's
  // own Gmail accounts: "really i WOULD like to have everything focused on 1
  // gmail only". Consolidating the REGISTERED addresses is a long job — 734
  // carrier accounts, one login at a time — so it happens opportunistically,
  // a SIM at a time, as each one is touched anyway. This is how you see where
  // it has got to: the mailbox on every row, and a filter to take one at a
  // time.
  //
  // The +tag is deliberately NOT shown in the cell and IS kept in the tooltip:
  // the tag identifies the SIM (336 of them share the gittbilig base), but
  // what you are scanning for here is the base.
  const simMailboxes = simMailboxCounts();
  const simBar = kcFilterSort('sim', [
    { value: 'all', label: 'All plans' },
    ...simMailboxes.map(m => ({
      value: `mb:${m.base}`,
      label: `${m.base.replace('@gmail.com', '')} (${m.n})`, icon: 'postbox',
      test: s => simMailboxBase(s.email) === m.base,
    })),
    { value: 'mb:none', label: 'No carrier account on file', icon: 'inbox', test: s => !simMailboxBase(s.email) },
    // The shop's own money. A through-me plan renews whether or not the
    // customer has left us any way to collect — the network takes its payment
    // either way — so this is the list of lines the shop is funding.
    { value: 'unfunded', label: 'Through me, nothing to collect from', icon: 'refund',
      test: s => simFundingState(s, simMethodFor(s)) === 'none' },
  ], [
    { value: 'name', label: 'Sort: Customer A–Z', cmp: kcCmpStr(s => s.customerName) },
    { value: 'renewal', label: 'Renewal (soonest)', cmp: (a, b) => String(a.renewalDate || '9999').localeCompare(String(b.renewalDate || '9999')) },
    { value: 'renewal_desc', label: 'Renewal (latest)', cmp: (a, b) => String(b.renewalDate || '').localeCompare(String(a.renewalDate || '')) },
    { value: 'provider', label: 'Provider A–Z', cmp: kcCmpStr(s => s.provider) },
    { value: 'recent', label: 'Recently added', cmp: kcCmpDate(s => s.createdAt || '', -1) },
  ], renderSimRows);

  content.innerHTML = `
    ${bannerHtml}
    <div class="stats-row">
      <div class="stat-card">
        <div class="stat-label">Total SIMs</div>
        <div class="stat-value blue">${sims.length}</div>
        <div class="stat-sub">All plans</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Active</div>
        <div class="stat-value green">${active}</div>
        <div class="stat-sub">Running now</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Renewing soon</div>
        <div class="stat-value ${renewing.length > 0 ? 'gold' : 'purple'}">${renewing.length}</div>
        <div class="stat-sub">Today / Tomorrow</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Total revenue</div>
        <div class="stat-value purple">${fmtGbp(totalRev)}</div>
        <div class="stat-sub">All charges</div>
      </div>
    </div>

    <div style="display:flex; gap:10px; margin-bottom:20px; flex-wrap:wrap; align-items:center;">
      <input class="search-box" type="text" id="simSearch"
        placeholder="Name, number or provider…"
        value="${escHtml(simSearchTerm)}"
        oninput="simSearchTerm=this.value; renderSimRows()">
      <select class="form-input kc-fs-sel" onchange="simFilterPay=this.value; renderSimRows()">
        <option value="all" ${simFilterPay==='all'?'selected':''}>Who pays: all</option>
        <option value="through-me" ${simFilterPay==='through-me'?'selected':''}>🔄 I pay / through me</option>
        <option value="direct" ${simFilterPay==='direct'?'selected':''}>👤 Customer pays direct</option>
      </select>
      <select class="form-input" style="width:150px;" onchange="simFilterStatus=this.value; renderSimRows()">
        <option value="all" ${simFilterStatus==='all'?'selected':''}>Status: all</option>
        <option value="active" ${simFilterStatus==='active'?'selected':''}>Active only</option>
        <option value="renewing" ${simFilterStatus==='renewing'?'selected':''}>Renewing (today/tomorrow)</option>
        <option value="week" ${simFilterStatus==='week'?'selected':''}>Renews this week</option>
        <option value="late" ${simFilterStatus==='late'?'selected':''}>⏰ Past renewal date</option>
      </select>
      ${simBar}
      <span id="simCount" style="font-size:var(--fs-small);color:var(--muted);"></span>
    </div>

    <div id="simBulkBar" style="display:none;margin:0 0 10px;padding:8px 12px;border:1px solid var(--border);border-radius:8px;background:var(--bg-secondary);align-items:center;gap:10px;flex-wrap:wrap;">
      <strong id="simBulkCount" style="font-size:var(--fs-body);"></strong>
      <button class="btn btn-outline btn-sm kc-ic kc-ic-trash" style="color:var(--danger-ink);border-color:var(--danger-ink);" onclick="deleteSelectedSims()">Delete selected</button>
      <button class="btn btn-outline btn-sm" onclick="clearSimSel()">Deselect all</button>
    </div>

    <div class="table-wrap kc-stack-sm">
      <table>
        <thead>
          <tr>
            <th style="width:28px;"><input type="checkbox" id="simSelAll" aria-label="Select every SIM plan in this view"
              onclick="toggleAllSimSel(this.checked)"></th>
            <th>Customer</th><th>Provider</th><th>SIM Number</th><th>Plan</th>
            <th>Mailbox</th><th>Renewal</th><th>Payment</th><th>Status</th><th>Actions</th>
          </tr>
        </thead>
        <tbody id="simTableBody"></tbody>
      </table>
    </div>`;

  renderSimRows();
}

/**
 * The mailbox a carrier account really lives in — the base address, tag off.
 *
 * Mirrors lib/simMailMatch.mjs::mailboxKey in the one respect that matters
 * here: Gmail ignores dots, and the shop has written the same account four
 * ways (`red.far.bilig`, `redfarbilig`). Without collapsing them, one mailbox
 * appears in the list six times.
 */
function simMailboxBase(email) {
  let v = String(email == null ? '' : email).trim().toLowerCase();
  const angled = v.match(/<([^>]+)>/);
  if (angled) v = angled[1].trim();
  const at = v.lastIndexOf('@');
  if (at < 1) return '';
  let local = v.slice(0, at);
  const domain = v.slice(at + 1);
  if (!domain) return '';
  const plus = local.indexOf('+');
  if (plus > -1) local = local.slice(0, plus);
  const gmail = domain === 'gmail.com' || domain === 'googlemail.com';
  if (gmail) local = local.replace(/\./g, '');
  if (!local) return '';
  return `${local}@${gmail ? 'gmail.com' : domain}`;
}

/** The shop's own mailboxes, busiest first — the ones worth filtering by. */
function simMailboxCounts(limit = 8) {
  const n = new Map();
  for (const s of sims) {
    const base = simMailboxBase(s.email);
    if (base) n.set(base, (n.get(base) || 0) + 1);
  }
  return [...n.entries()]
    .map(([base, count]) => ({ base, n: count }))
    .sort((a, b) => b.n - a.n)
    .slice(0, limit);
}

// "12 of 797" beside a list, so a search result is readable as a search result.
//
// A filtered list and an empty list look identical, and this shop's lists are
// big enough for that to matter: 797 SIMs, 788 customers. Somebody who types a
// name and sees three rows cannot tell whether three matched or whether the
// list failed to load — and the empty states already say so in words ("No SIM
// plans match this view"), which only helps when the answer is zero.
//
// The SIM tab and the Shop tab each grew their own copy of this line. This is
// the same line, once, so the four lists that were missing it did not become
// four more copies.
function kcListCount(el, shown, total, noun) {
  const node = typeof el === 'string' ? document.getElementById(el) : el;
  if (!node) return;
  // Unfiltered, the "of" half is noise — the reader can see the list is whole.
  // The Shop tab names its unit there ("12 items") and it reads better for it,
  // so the noun is optional rather than dropped to make the lists match.
  const whole = noun ? `${total} ${noun}${total === 1 ? '' : 's'}` : `${total}`;
  node.textContent = shown === total ? whole : `${shown} of ${total}`;
}

function renderSimRows() {
  const tbody = document.getElementById('simTableBody');
  if (!tbody) return;
  const today    = localISO();
  const tomorrow = localISO(new Date(Date.now() + 86400000));
  const in7      = localISO(new Date(Date.now() + 7 * 86400000));
  const term     = simSearchTerm.toLowerCase();

  const filtered = sims.filter(s => {
    if (term &&
      !(s.customerName || '').toLowerCase().includes(term) &&
      !(s.simNumber    || '').toLowerCase().includes(term) &&
      !(s.provider     || '').toLowerCase().includes(term) &&
      !(s.iccid        || '').toLowerCase().includes(term) &&
      !phoneDigitsMatch(term, customers.find(c => c.id === s.customerId))) return false;
    if (simFilterPay === 'direct' && s.paymentType !== 'direct') return false;
    if (simFilterPay === 'through-me' && s.paymentType === 'direct') return false;
    if (simFilterStatus === 'active' && !simLive(s)) return false;
    if (simFilterStatus === 'renewing' && !(s.renewalDate === today || s.renewalDate === tomorrow)) return false;
    if (simFilterStatus === 'week' && !(simLive(s) && s.renewalDate && s.renewalDate >= today && s.renewalDate <= in7)) return false;
    // The overdue half. The dashboard's SIM card and its attention row both
    // land here — owner, 19 Aug: the link "takes me to the normal sims tab,
    // without even the ability to filter the overdue ones".
    if (simFilterStatus === 'late' && !(simLive(s) && s.renewalDate && s.renewalDate < today)) return false;
    return true;
  });

  const sorted = kcViewApply('sim', filtered);

  const countEl = document.getElementById('simCount');
  kcListCount(countEl, sorted.length, sims.length);

  if (sorted.length === 0) {
    // Same trap as Rentals: with 800+ SIMs on file, "No SIM plans yet" reads
    // as the list having been wiped rather than filtered.
    const narrowed = sims.length > 0;
    tbody.innerHTML = `<tr><td colspan="10"><div class="empty-state"><div class="emoji kc-ic kc-ic-card"></div>
      <p>${narrowed ? 'No SIM plans match this view.' : 'No SIM plans yet.'}</p>
      <small>${narrowed ? '' : 'Click "+ New SIM plan" to add one.'}</small>
      ${narrowed ? kcClearFiltersBtn('sim') : ''}</div></td></tr>`;
    simVisibleIds = [];
    syncSimSelUi();
    return;
  }

  tbody.innerHTML = sorted.map(s => {
    const statusBadge =
      s.status === 'active'    ? `<span class="badge badge-active">Active</span>` :
      s.status === 'renewal_pending' ? `<span class="badge badge-renewal">Renewal due</span>` :
      s.status === 'suspended' ? `<span class="badge badge-suspended">Suspended</span>` :
                                 `<span class="badge badge-cancelled">Cancelled</span>`;

    const isRenewingToday    = s.renewalDate === today;
    const isRenewingTomorrow = s.renewalDate === tomorrow;
    const renewalClass = isRenewingToday ? 'color:var(--danger-ink);font-weight:700;' :
                         isRenewingTomorrow ? 'color:var(--warning);font-weight:700;' : '';
    const renewalLabel = isRenewingToday ? ` ${'<i class="kc-ic kc-ic-alert" aria-hidden="true"></i>'} Today!` : isRenewingTomorrow ? ` ${'<i class="kc-ic kc-ic-alert" aria-hidden="true"></i>'} Tomorrow` : '';

    return `<tr style="cursor:pointer;" onclick="if(!event.target.closest('button,select,a,input'))openManageSimModal('${s.id}')" title="Open SIM">
      <td class="kc-stack-lead" onclick="event.stopPropagation()">
        <input type="checkbox" aria-label="Select this SIM plan" ${simSelected.has(s.id) ? 'checked' : ''}
          onclick="toggleSimSel('${s.id}', this.checked)">
      </td>
      <td><div class="customer-name">${custNameLink(s.customerId, escHtml(capName(s.customerName) || '—'))}${unconfirmedChip(s)}</div></td>
      <td>${providerBadge(s.provider)}</td>
      <td data-label="SIM" style="font-weight:600;font-size:var(--fs-small);">${escHtml(s.simNumber || '—')}${simIsTheirContact(s) ? ' <span class="kc-contact-ours kc-ic kc-ic-telephone" title="This is also the number we ring the customer on.">contact</span>' : ''}</td>
      <td class="kc-cell-clip" data-label="Plan" style="font-size:var(--fs-small);">${escHtml(s.plan || '—')}</td>
      <td class="kc-drop-sm" data-label="Mailbox" style="font-size:var(--fs-micro);color:var(--muted);white-space:nowrap;"
        title="${s.email ? escHtml(s.email) : 'No carrier account on file — this SIM can only ever be matched by its number'}">${
        simMailboxBase(s.email) ? escHtml(simMailboxBase(s.email).replace('@gmail.com', '')) : '—'}</td>
      <td class="kc-date" data-label="Renews" style="font-size:var(--fs-small);${renewalClass}">${fmtDateHeb(s.renewalDate)}${renewalLabel}</td>
      <td data-label="Payment" style="font-size:var(--fs-small);">${s.paymentType === 'direct' ? '<i class="kc-ic kc-ic-user" aria-hidden="true"></i> Direct' : '<i class="kc-ic kc-ic-sync" aria-hidden="true"></i> Through me'}${fundingChip(s)}</td>
      <td>${statusBadge}</td>
      <td>
        <div class="row-actions">
          <button class="action-btn kc-ic kc-ic-gear" onclick="openManageSimModal('${s.id}')">Manage</button>
          ${kcRowMenuHtml([
            { label: 'Remind me about this', icon: 'clock', onclick: `openRemindModal('sim','${s.id}')` },
            { label: 'Delete this SIM plan', icon: 'trash', onclick: `deleteSim('${s.id}')`, danger: true },
          ], { label: 'More for this SIM plan' })}
        </div>
      </td>
    </tr>`;
  }).join('');
  simVisibleIds = sorted.map(s => s.id);
  syncSimSelUi();
}

// Bulk selection on the SIM table — same shape as the rentals one, for the
// family whose whole set of SIMs comes back together.
let simSelected = new Set();
let simVisibleIds = [];
function toggleSimSel(id, on) {
  if (on) simSelected.add(id); else simSelected.delete(id);
  syncSimSelUi();
}
function toggleAllSimSel(on) {
  simVisibleIds.forEach(id => on ? simSelected.add(id) : simSelected.delete(id));
  renderSimRows();
}
function clearSimSel() {
  simSelected.clear();
  renderSimRows();
}
function syncSimSelUi() {
  const live = new Set(sims.map(s => s.id));
  [...simSelected].forEach(id => { if (!live.has(id)) simSelected.delete(id); });
  const all = document.getElementById('simSelAll');
  if (all) {
    const selInView = simVisibleIds.filter(id => simSelected.has(id)).length;
    all.checked = simVisibleIds.length > 0 && selInView === simVisibleIds.length;
    all.indeterminate = selInView > 0 && selInView < simVisibleIds.length;
  }
  const bar = document.getElementById('simBulkBar');
  if (bar) {
    bar.style.display = simSelected.size ? 'flex' : 'none';
    const count = document.getElementById('simBulkCount');
    if (count) count.textContent = `${simSelected.size} SIM plan${simSelected.size === 1 ? '' : 's'} selected`;
  }
}
async function deleteSelectedSims() {
  const picked = sims.filter(s => simSelected.has(s.id));
  if (!picked.length) return;
  const names = [...new Set(picked.map(s => capName(s.customerName) || '—'))];
  if (!(await kcConfirm({
    title: `Delete ${picked.length} SIM plans?`,
    body: `<strong>${escHtml(names.slice(0, 4).join(', '))}${names.length > 4 ? ` +${names.length - 4} more` : ''}</strong><br>` +
      `Any SIM charges on the wallet are reversed. This can't be undone.`,
    okLabel: `Delete ${picked.length} SIM plans`,
    danger: true,
  }))) return;
  const ids = picked.map(s => s.id);
  sims = sims.filter(s => !ids.includes(s.id));
  simSelected.clear();
  const res = await saveSims(sims, ids);
  renderSimsTab();
  if (res && res.success === false) return; // reportSave already warned
  toast(`${ids.length} SIM plans deleted.`, 'warning');
}

function openAddSimModal(preselectCustomerId = null, prefill = null) { openSimFormModal(null, preselectCustomerId, prefill); }
function openEditSimModal(id) { openSimFormModal(id); }

function openSimFormModal(id, preselectCustomerId = null, prefill = null) {
  // `prefill` carries what a carrier email already told us (number, carrier)
  // so the operator only has to say WHOSE it is.
  const s = id ? sims.find(x => x.id === id) : (prefill ? { ...prefill } : null);
  // isEdit follows the ID, not the object: a prefilled NEW plan also has an `s`
  // (the number and carrier a carrier email supplied) and must still open as
  // "New SIM plan" and save down the create path.
  const isEdit = !!id && !!s;
  const preselect = s && s.customerId ? s.customerId : preselectCustomerId;

  showDynamicModal(`
    <div class="modal-title">${isEdit ? '<i class="kc-ic kc-ic-pencil" aria-hidden="true"></i> Edit SIM plan' : '<i class="kc-ic kc-ic-plus" aria-hidden="true"></i> New SIM plan'}</div>
    <div class="form-grid">
      <div class="form-group form-full">
        <label class="form-label">Customer *</label>
        ${customerPicker('simCustomer', { selected: preselect })}
        <span class="form-error" id="errSimCustomer">Required</span>
      </div>
      <div class="form-group">
        <label class="form-label">Provider *</label>
        ${providerPicker('simProvider', { provider: s?.provider || '', subBrand: s?.subBrand || '' })}
        <span class="form-error" id="errSimProvider">Required</span>
      </div>
      <div class="form-group">
        <label class="form-label">SIM Phone Number</label>
        <input class="form-input" id="simNumber" type="tel" inputmode="tel" dir="ltr" placeholder="+44 7700 900000"
          value="${escHtml(s?.simNumber || '')}" autocomplete="off">
      </div>
      <div class="form-group">
        <label class="form-label">ICCID</label>
        <input class="form-input" id="simIccid" type="text" placeholder="89441234567890123456"
          value="${escHtml(s?.iccid || '')}" autocomplete="off">
      </div>
      <div class="form-group">
        <label class="form-label">Email at Provider</label>
        <input class="form-input" id="simEmail" type="email" placeholder="kosherconnect+name@gmail.com"
          value="${escHtml(s?.email || '')}" autocomplete="off">
      </div>
      <div class="form-group form-full">
        <label class="form-label">Active Plan (description)</label>
        <input class="form-input" id="simPlan" type="text" placeholder="Unlimited calls + data, EU roaming"
          value="${escHtml(s?.plan || '')}" autocomplete="off">
      </div>
      <div class="form-group">
        <label class="form-label">Next Renewal Date</label>
        <input class="form-input" id="simRenewal" type="date" value="${s?.renewalDate || ''}">
      </div>
      <div class="form-group">
        <label class="form-label">Payment Type</label>
        <select class="form-input" id="simPayment" onchange="const show=this.value!=='direct';document.getElementById('simDdGroup').style.display=show?'block':'none';document.getElementById('simCostGroup').style.display=show?'block':'none';">
          <option value="through-me" ${!s || s.paymentType === 'through-me' ? 'selected' : ''}>🔄 Through me</option>
          <option value="direct" ${s?.paymentType === 'direct' ? 'selected' : ''}>👤 Customer pays directly</option>
        </select>
        <!-- Owner, 20 Aug: "suppose from now on HE gives us card details, saved
             on his customer account, will it change to 'direct'?" It will not,
             and the labels are why — they read as a question about whose money
             it is, when what they actually decide is WHOSE CARD IS ON THE
             NETWORK ACCOUNT. A card saved with us is still us collecting from
             him, which is what through me means. -->
        <span style="font-size:var(--fs-micro);color:var(--muted);">Whose card is on the network account — not whose card we hold. A card saved with us is still <em>through me</em>.</span>
      </div>
      <div class="form-group" id="simDdGroup" style="display:${(!s || s.paymentType !== 'direct') ? 'block' : 'none'};">
        <label class="form-label">DD Collection Day</label>
        <input class="form-input" id="simDdDate" type="number" min="1" max="31" placeholder="1" value="${s?.ddDate || 1}">
        <span style="font-size:var(--fs-micro);color:var(--muted);">Day of month DD is collected (e.g. 1 = 1st of each month)</span>
      </div>
      <div class="form-group" id="simCostGroup" style="display:${(!s || s.paymentType !== 'direct') ? 'block' : 'none'};">
        <label class="form-label">Provider Monthly Cost (£)</label>
        <input class="form-input" id="simMonthlyCost" type="number" min="0" step="0.01" placeholder="0.00" value="${s?.simMonthlyCost || ''}">
        <span style="font-size:var(--fs-micro);color:var(--muted);">What you pay the provider — DD charge = this + 10% (min £2)</span>
      </div>
      <div class="form-group form-full">
        <label class="form-label">Status</label>
        <select class="form-input" id="simStatus">
          <option value="active"    ${(!s || s.status === 'active')    ? 'selected' : ''}>Active</option>
          <!-- Owner settled issue #13 (23 Aug): the option exists, AND the
               sweep sets it by itself the day next_renewal_date passes,
               flipping back to active once the date is ahead again. The
               customer portal shows it as "Renewal due" in both languages
               (pages/portal.js) — picking it is visible to the customer. -->
          <option value="renewal_pending" ${s?.status === 'renewal_pending' ? 'selected' : ''}>Renewal due</option>
          <option value="suspended" ${s?.status === 'suspended' ? 'selected' : ''}>Suspended</option>
          <option value="cancelled" ${s?.status === 'cancelled' ? 'selected' : ''}>Cancelled</option>
        </select>
      </div>
    </div>
    <div class="modal-actions">
      <button class="btn btn-outline" onclick="closeDynamicModal()">Cancel</button>
      <button class="btn btn-primary kc-ic kc-ic-save" onclick="saveSimForm('${id || ''}')">Save</button>
    </div>
  `);
}

async function saveSimForm(editId) {
  const customerId = document.getElementById('simCustomer').value;
  const simProv    = providerPickerValue('simProvider', null);
  const provider   = simProv.provider;
  if (simProv.error && provider) { toast(simProv.error, 'error'); return; }

  let valid = true;
  if (!customerId) { document.getElementById('errSimCustomer').classList.add('visible'); valid = false; }
  else              { document.getElementById('errSimCustomer').classList.remove('visible'); }
  if (!provider)   { document.getElementById('errSimProvider').classList.add('visible'); valid = false; }
  else              { document.getElementById('errSimProvider').classList.remove('visible'); }
  if (!valid) return;

  const customer = customers.find(c => c.id === customerId);
  const paymentType = document.getElementById('simPayment').value;
  const fields = {
    customerId,
    customerName:   customer ? `${customer.firstName} ${customer.lastName}` : '',
    provider,
    subBrand: simProv.subBrand,
    simNumber:      document.getElementById('simNumber').value.trim(),
    iccid:          document.getElementById('simIccid').value.trim(),
    email:          document.getElementById('simEmail').value.trim(),
    plan:           document.getElementById('simPlan').value.trim(),
    renewalDate:    document.getElementById('simRenewal').value,
    paymentType,
    status:         document.getElementById('simStatus').value,
    ddDate:         paymentType !== 'direct' ? Math.min(31, Math.max(1, parseInt(document.getElementById('simDdDate')?.value) || 1)) : null,
    simMonthlyCost: paymentType !== 'direct' ? (parseFloat(document.getElementById('simMonthlyCost')?.value) || 0) : 0,
  };

  // Cancelling the only line we can reach them on (owner, 17 Aug). For 470 of
  // 609 customers the contact number IS a SIM we sell them, so ending the SIM
  // ends the shop's way of ringing them — and the moment to ask for another
  // number is now, while they are still standing there, not next year when
  // something needs saying and nothing works.
  if (editId && fields.status === 'cancelled') {
    const prev = sims.find(s => s.id === editId);
    if (prev && prev.status !== 'cancelled' && !(await simCancelContactCheck(prev, customer))) return;
  }

  let newSimId = null;
  let setupHistoryId = null;
  let setupFee = 0;
  if (editId) {
    const idx = sims.findIndex(s => s.id === editId);
    if (idx !== -1) sims[idx] = { ...sims[idx], ...fields };
  } else {
    setupFee = simChargePrice('activation'); // settings-driven, £20 fallback
    if (!(await kcConfirm({
      title: 'Confirm SIM setup charge',
      body: `<strong>${customer ? escName(customer.firstName) + ' ' + escName(customer.lastName) : 'Customer'}</strong><br>
        ${escHtml(provider)} SIM — initial setup`,
      amount: setupFee,
      okLabel: 'Charge setup',
    }))) return;
    const setupDate = new Date().toLocaleDateString('en-GB', { day:'numeric', month:'short', year:'numeric' });
    newSimId = uid();
    setupHistoryId = uid();
    sims.push({
      id: newSimId,
      ...fields,
      history: [{
        id: setupHistoryId,
        type: 'activation',
        desc: 'Initial SIM Setup',
        amount: setupFee,
        date: setupDate,
      }],
      createdAt: new Date().toISOString(),
    });
  }

  // AWAIT it. This used to be `saveSims(sims);` — fire and forget — so the
  // setup fee was billed and the "SIM plan added" card shown whether or not
  // the plan saved. On 20 Aug that put a real £20 on a customer for a SIM the
  // database had no record of, with a red failure toast sitting behind the
  // success card. Nothing below may run on a failed save: not the charge, not
  // the card, not the receipt offer.
  const simSaved = await saveSims(sims);
  if (!simSaved || simSaved.success === false) {
    // reportSave has already said what went wrong; this says what it means.
    toast('The SIM plan was NOT saved, so nothing was charged. Check the details and try again.', 'error');
    return;
  }
  // Bill the setup fee to the wallet ledger (same append-only path as every
  // other charge). Idempotent via SIM-<simId>-<historyId>; a soft failure only
  // warns — the SIM record and its history blob are already saved.
  if (newSimId && setupFee > 0) {
    window.api.chargeSim({ simId: newSimId, customerId, historyId: setupHistoryId, amount: setupFee, description: 'Initial SIM Setup' })
      .then(res => { if (!res?.success) toast(res?.error || 'SIM saved, but the setup fee was not billed to the wallet.', 'error'); })
      .catch(() => toast('SIM saved, but the setup fee was not billed to the wallet.', 'error'));
  }
  closeDynamicModal();
  // If this plan was created from a carrier email, file that email on it.
  if (newSimId) cmPairAfterSimSaved(newSimId);
  let extraMsg = '';
  if (newSimId) extraMsg = await applyExtraCharges('sim', newSimId, customerId, false);
  renderSimsTab();
  // A new plan is money changing hands with the customer in front of you, so
  // it finishes on the card, like everything else. An EDIT is now silent:
  // renderSimsTab() above has already repainted the row with the correction,
  // and a toast that says what the screen says is noise. (That supersedes an
  // earlier note here which kept a toast to mark an edit apart from a new
  // plan — the distinction is real, but it is carried by WHERE each one
  // finishes, not by an extra announcement. extraMsg is always empty on this
  // branch, since it is only filled when a NEW sim id exists, so nothing
  // invisible is being dropped.)
  if (editId) return;
  if (extraMsg) toast(`SIM plan added.${extraMsg}`, 'success');
  const sc = customers.find(x => String(x.id) === String(customerId));
  // Read the labels off the form's own selects rather than re-deriving them,
  // so the card says exactly what the person just picked.
  const fieldText = (id) => {
    const el = document.getElementById(id);
    if (!el) return '';
    if (el.tagName === 'SELECT') return (el.options[el.selectedIndex]?.textContent || '').trim();
    return (el.value || '').trim();
  };
  const simNo = fieldText('simNumber');
  const planLabel = fieldText('simPlan');
  const providerLabel = fieldText('simProvider');
  const renewal = fieldText('simRenewal');
  showDonePanel({
    title: 'SIM plan added', icon: 'card',
    customerId,
    customerName: sc ? `${sc.firstName || ''} ${sc.lastName || ''}`.trim() : '',
    customerPhone: sc?.phone || '',
    summary: [simNo && fmtPhone(simNo), providerLabel, planLabel, renewal && `renews ${fmtDate(renewal)}`]
      .filter(Boolean).join(' · ') || 'SIM plan',
    total: setupFee || 0,
    payLine: setupFee > 0 ? 'setup fee on account' : 'no setup fee',
    method: null,
    paidNow: false,
    lines: [{ name: `SIM plan${simNo ? ' ' + fmtPhone(simNo) : ''}${planLabel ? ' · ' + planLabel : ''}`, qty: 1, total: setupFee || 0 }],
    // A SIM plan is not a shop line. The customer needs the number, the network,
    // the plan and the day it renews — none of which fit in a POS description.
    receipt: {
      kind: 'sim', ref: String(newSimId || ''),
      number: simNo ? fmtPhone(simNo) : '', provider: providerLabel || '',
      plan: planLabel || '', renewalDate: renewal || '',
      total: setupFee || 0, paidAmount: 0, method: null,
    },
    smsText: `Hi${sc?.firstName ? ' ' + sc.firstName : ''}, your SIM plan${simNo ? ' on ' + fmtPhone(simNo) : ''} is set up${renewal ? ` — renews ${fmtDate(renewal)}` : ''}. Kosher Connect, 0161 531 1386.`,
    again: { label: 'Another SIM', icon: 'card', sub: sc?.firstName ? `for ${sc.firstName}` : 'new plan', run: () => openAddSimModal(customerId) },
  });
}

/**
 * The addresses this line receives carrier mail at.
 *
 * Shown on the card because it EXPLAINS the card: the mail listed underneath is
 * here because it arrived at one of these, and a message that should have been
 * filed here and was not is usually an address missing from this list.
 *
 * The primary is read-only — it is a field on the SIM form and is edited there.
 * The taught ones are removable, because teaching is a judgement made in a hurry
 * at a queue and a wrong one silently files a stranger's mail on this line.
 */
function paintSimAddresses(simLegacyId, addresses) {
  const box = document.getElementById('simMailAddresses');
  if (!box) return;
  const primary = (addresses && addresses.primary) || '';
  const alt = (addresses && Array.isArray(addresses.alt)) ? addresses.alt : [];
  if (!primary && !alt.length) {
    box.innerHTML = `<div style="color:var(--muted);font-size:var(--fs-small);padding:2px 0 8px;">
      No address on record — carrier mail for this line can only be matched by its number.</div>`;
    return;
  }
  const chip = (addr, removable) => `
    <span style="display:inline-flex;align-items:center;gap:6px;background:var(--bg);
      border:1px solid var(--border);border-radius:999px;padding:3px 10px;font-size:var(--fs-micro);">
      <span style="direction:ltr;">${escHtml(addr)}</span>
      ${removable ? `<button class="action-btn danger" style="padding:0 4px;line-height:1;"
        title="Stop filing mail sent here on this line"
        aria-label="Remove ${escHtml(addr)} from this line"
        onclick="simForgetAddress('${escJs(String(simLegacyId))}', '${escJs(addr)}')">✕</button>` : ''}
    </span>`;
  box.innerHTML = `
    <div style="display:flex;flex-wrap:wrap;gap:6px;align-items:center;padding:2px 0 10px;">
      <span style="font-size:var(--fs-micro);color:var(--muted);font-weight:600;">Receives mail at</span>
      ${primary ? chip(primary, false) : ''}
      ${alt.map(a => chip(a, true)).join('')}
      ${/* The other door onto the same list. Teaching from the carrier-mail
           queue only works once mail has ALREADY gone missing — a message has
           to arrive at an unclaimed address, fail to pair, and be found by a
           person. When the shop opens a second carrier account it knows the
           address that day, so this is how the FIRST message pairs itself
           rather than the second. */''}
      <button class="btn btn-outline btn-sm" style="font-size:var(--fs-micro);padding:2px 10px;"
        onclick="simAddAddress('${escJs(String(simLegacyId))}')"
        title="Record another address this line receives carrier mail at">+ address</button>
    </div>`;
}

/**
 * Record another address this line receives carrier mail at.
 *
 * Deliberately not a free-text field on the SIM form. The SIM form saves
 * through saveAllSims, whose round-trip writes the whole app object into
 * legacy_extras — putting the list there would give one fact two homes, and
 * the column is the one the matcher reads. So it is edited here, next to the
 * list it belongs to and beside the ✕ that removes one.
 */
async function simAddAddress(simLegacyId) {
  const address = (await kcPrompt({
    title: 'Another address for this line',
    body: 'Carrier mail sent here will be filed on this line from now on. ' +
      'One address belongs to one line only — if another line already claims it, this will say so.',
    label: 'Email address',
    placeholder: 'name+tag@gmail.com',
    okLabel: 'Add the address',
    type: 'email', inputmode: 'email',
  }) || '').trim();
  if (!address) return;
  try {
    const res = await window.api.settleCarrierMail({ op: 'addAddress', simLegacyId, address });
    if (!res || !res.success) throw new Error(res?.error || 'failed');
    toast(res.added ? `Mail to ${address} now files on this line.` : 'That address was already on this line.',
      res.added ? 'success' : 'info');
    loadSimMailInto(simLegacyId);
  } catch (e) {
    // The 409 — another line already claims it — is the message that matters
    // most here, so it is shown rather than swallowed into "try again".
    toast(String(e.message || 'Could not add that address.'), 'error');
  }
}

async function simForgetAddress(simLegacyId, address) {
  if (!(await kcConfirm({
    title: 'Stop filing mail sent here?',
    body: `Carrier mail to <strong>${escHtml(address)}</strong> will stop being filed on this line, ` +
      `and will go back to the queue for someone to place by hand.<br><br>` +
      `Mail already filed by it stays where it is — use “Undo match” on a message to move that.`,
    okLabel: 'Remove the address',
    danger: true,
  }))) return;
  try {
    const res = await window.api.settleCarrierMail({ op: 'forgetAddress', simLegacyId, address });
    if (!res || !res.success) throw new Error(res?.error || 'failed');
    toast('Address removed.', 'success');
    loadSimMailInto(simLegacyId);
  } catch (e) {
    toast(String(e.message || 'Could not remove that.'), 'error');
  }
}

// Carrier mail filed on ONE SIM, loaded after the card paints. It is a
// secondary read: the card is about the plan and its charges, and waiting on
// the mail query to show either would be the wrong trade.
async function loadSimMailInto(simLegacyId) {
  const box = document.getElementById('simMailList');
  if (!box) return;
  const data = await window.api.getSimMail(simLegacyId);
  if (!document.getElementById('simMailList')) return;   // modal closed meanwhile
  if (!data || !data.success) {
    box.innerHTML = '<div style="color:var(--muted);font-size:var(--fs-small);padding:6px 0;">Couldn’t load carrier mail.</div>';
    return;
  }
  paintSimAddresses(simLegacyId, data.addresses);
  box.innerHTML = data.messages.length === 0
    ? '<div style="color:var(--muted);font-size:var(--fs-small);padding:6px 0;">No carrier mail filed on this SIM yet.</div>'
    : data.messages.map(m => `
        <div class="history-item">
          <span class="history-dot dot-blue"></span>
          <span class="history-desc">${escHtml(m.subject || '(no subject)')}${m.carrier ? ` · ${escHtml(m.carrier)}` : ''}</span>
          <span class="history-date">${escHtml(fmtDate(m.receivedAt) || '')}</span>
        </div>`).join('');
}

function openManageSimModal(id) {
  const s = sims.find(x => x.id === id);
  if (!s) return;
  const history = s.history || [];
  const totalCharged = history.reduce((sum, h) => sum + (h.amount || 0), 0);

  const historyHtml = history.length === 0
    ? `<div style="color:var(--muted);font-size:var(--fs-body);padding:10px 0;">No history yet.</div>`
    : history.slice().reverse().map(h => `
        <div class="history-item">
          <span class="history-dot dot-blue"></span>
          <span class="history-desc">${escHtml(h.desc)}</span>
          <span class="history-date">${escHtml(h.date || '')}</span>
          <span class="history-amount">${h.amount > 0 ? fmtGbp(h.amount) : '—'}</span>
          <button class="action-btn danger" style="margin-left:8px;padding:3px 8px;font-size:var(--fs-micro);"
            aria-label="Delete this charge" onclick="deleteSimCharge('${id}','${h.id}')">✕</button>
        </div>`).join('');

  showDynamicModal(`
    <div class="modal-title kc-ic kc-ic-card">${custNameLink(s.customerId, escHtml(capName(s.customerName)))} ${providerBadge(s.provider)}</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:16px;font-size:var(--fs-body);">
      <div style="color:var(--muted);">SIM Number</div><div style="font-weight:600;">${escHtml(s.simNumber||'—')}</div>
      <div style="color:var(--muted);">ICCID</div><div style="font-size:var(--fs-micro);">${escHtml(s.iccid||'—')}</div>
      <div style="color:var(--muted);">Email</div><div style="font-size:var(--fs-micro);">${escHtml(s.email||'—')}</div>
      <div style="color:var(--muted);">Plan</div><div>${escHtml(s.plan||'—')}</div>
      <div style="color:var(--muted);">Renewal</div><div>${fmtDate(s.renewalDate)}</div>
      <div style="color:var(--muted);">Payment</div><div>${s.paymentType === 'direct' ? '<i class="kc-ic kc-ic-user" aria-hidden="true"></i> Direct' : '<i class="kc-ic kc-ic-sync" aria-hidden="true"></i> Through me'}</div>
      ${s.paymentType !== 'direct' ? `
      <div style="color:var(--muted);">DD Day</div><div style="font-weight:600;">${s.ddDate ? `${s.ddDate}${s.ddDate===1?'st':s.ddDate===2?'nd':s.ddDate===3?'rd':'th'} of each month` : '—'}</div>
      <div style="color:var(--muted);">Next DD Amount</div><div style="font-weight:700;${s.simMonthlyCost ? 'color:var(--success);' : 'color:var(--muted);font-weight:400;'}">${s.simMonthlyCost ? fmtGbp(ddMonthlyAmount(s.simMonthlyCost)) : '—'}</div>
      ` : ''}
      <div style="color:var(--muted);">Status</div><div>${
        s.status === 'renewal_pending' ? '<span class="badge badge-renewal">Renewal due</span>'
        : s.status === 'suspended' ? '<span class="badge badge-suspended">Suspended</span>'
        : s.status === 'cancelled' ? '<span class="badge" style="background:rgba(107,114,128,0.15);color:var(--muted);">Cancelled</span>'
        : '<span class="badge badge-active">Active</span>'}</div>
    </div>

    <div class="section-divider">Service History</div>
    <div class="history-list" id="simHistoryList">${historyHtml}</div>

    <div class="section-divider">Carrier Mail</div>
    <div id="simMailAddresses"></div>
    <div class="history-list" id="simMailList">
      <div style="color:var(--muted);font-size:var(--fs-small);padding:6px 0;">Loading…</div>
    </div>

    <div style="background:var(--bg);border:1px solid var(--border);border-radius:10px;padding:14px;margin-bottom:16px;">
      <div class="section-divider" style="margin-top:0;">Add Charge</div>
      ${multiSimDiscountPct(sims, s.customerId) > 0
        ? `<div style="font-size:var(--fs-small);color:var(--gold);margin-bottom:8px;"><i class="kc-ic kc-ic-tag" aria-hidden="true"></i> 3+ active plans — ${multiSimDiscountPct(sims, s.customerId)}% off applied to monthly/annual prefills.</div>` : ''}
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;">
        <div style="display:flex;flex-direction:column;gap:4px;flex:2;min-width:min(100%, 28ch);">
          <label style="font-size:var(--fs-micro);color:var(--muted);font-weight:600;">Type</label>
          <select class="form-input" id="simChargeType" onchange="onSimChargeTypeChange('${id}')" style="font-size:var(--fs-body);">
            <option value="activation">🟢 Initial Setup — ${fmtGbp(simChargePrice('activation'))}</option>
            <!-- Service is the default: setup was already charged when the SIM was created. -->
            <option value="service" selected>🔧 Service (swap/roaming) — ${fmtGbp(simChargePrice('service'))}</option>
            <option value="sim-replacement">📦 SIM Replacement — ${fmtGbp(simChargePrice('sim-replacement'))}</option>
            <option value="monthly">${s.paymentType !== 'direct' && s.simMonthlyCost ? `📅 Monthly DD — ${fmtGbp(ddMonthlyAmount(s.simMonthlyCost))}` : '📅 Monthly Subscription'}</option>
            <option value="annual">📅 Annual Subscription — ${fmtGbp(simChargePrice('annual'))}</option>
            ${simMenu.map(m => `<option value="menu:${escHtml(String(m.id))}">${simMenuIcon(m.name)} ${escHtml(m.name)} — ${fmtGbp(m.price)}</option>`).join('')}
            <option value="custom">✏️ Custom</option>
          </select>
        </div>
        <div style="display:flex;flex-direction:column;gap:4px;width:80px;">
          <label style="font-size:var(--fs-micro);color:var(--muted);font-weight:600;">Amount £</label>
          <input class="form-input" id="simChargeAmount" aria-label="Charge amount, in pounds" type="number" value="${simChargePrice('service')}" min="0" step="0.5" style="font-size:var(--fs-body);">
        </div>
        <div style="display:flex;flex-direction:column;gap:4px;flex:2;min-width:140px;">
          <label style="font-size:var(--fs-micro);color:var(--muted);font-weight:600;">Note (optional)</label>
          <input class="form-input" id="simChargeNote" type="text" placeholder="e.g. SIM swap" style="font-size:var(--fs-body);">
        </div>
        <div style="display:flex;flex-direction:column;gap:4px;width:150px;">
          <label style="font-size:var(--fs-micro);color:var(--muted);font-weight:600;">Paid now?</label>
          <select class="form-input" id="simChargePay" style="font-size:var(--fs-body);">
            <option value="account">On account</option>
            <option value="cash">💵 Cash</option>
            <option value="card">💳 Card</option>
            <option value="bank_transfer">🏦 Bank transfer</option>
          </select>
        </div>
        <button class="btn btn-primary btn-sm" onclick="addSimCharge('${id}')">+ Add</button>
      </div>
    </div>

    <div style="display:flex;flex-wrap:wrap;gap:8px;justify-content:space-between;align-items:center;margin-top:4px;">
      <span style="font-size:var(--fs-body);color:var(--muted);">Total charged: <strong style="color:var(--success);">${fmtGbp(totalCharged)}</strong></span>
      <div class="modal-actions-group">
        <button class="btn btn-outline btn-sm kc-ic kc-ic-pencil" onclick="openEditSimModal('${id}');void(0)">Edit details</button>
        <button class="btn btn-outline btn-sm" onclick="closeDynamicModal()">Close</button>
      </div>
    </div>
  `);
  loadSimMailInto(id);
}

// SIM charge prices come from Settings (BUSINESS_RULES §2); numbers here are
// only the offline fallback and MUST mirror the seed.
function simChargePrice(type) {
  switch (type) {
    case 'activation':      return settingNum('sim_activation_fee', 20);
    case 'service':         return settingNum('sim_service_fee', 5);
    case 'sim-replacement': return settingNum('sim_replacement_fee', 10);
    case 'annual':          return settingNum('sim_annual_fee', 20);
    default:                return undefined;
  }
}

// Monthly DD through-me price: provider cost + max(pct%, £min).
function ddMonthlyAmount(cost) {
  // #30 — the SIM DD surcharge is a service fee for running the direct debit,
  // with its own keys. (The old rental "Pay later" surcharge was removed — a
  // charge for paying later is ribis — so there is no fallback to it now.)
  const pct = settingNum('sim_dd_surcharge_pct', 10) / 100;
  const min = settingNum('sim_dd_surcharge_min', 2);
  return round2(cost + Math.max(cost * pct, min));
}

const SIM_CHARGE_DESCS  = {
  activation: 'Initial SIM Setup',
  service: 'Service (roaming / swap / reactivation)',
  'sim-replacement': 'SIM Replacement',
  monthly: 'Monthly DD',
  annual: 'Annual Subscription',
};

function onSimChargeTypeChange(simId) {
  const type  = document.getElementById('simChargeType').value;
  const amtEl = document.getElementById('simChargeAmount');
  const s = simId ? sims.find(x => x.id === simId) : null;
  // Menu products (SIM-only monthlies, TomTom): prefill the menu price.
  if (type.startsWith('menu:')) {
    const m = simMenu.find(x => String(x.id) === type.slice(5));
    amtEl.value = m ? m.price : 0;
    return;
  }
  // 3+ active plans → 10% off the recurring (monthly/annual) prefills.
  const multiOff = s && (type === 'monthly' || type === 'annual')
    ? 1 - multiSimDiscountPct(sims, s.customerId) / 100 : 1;
  if (type === 'monthly') {
    if (s && s.paymentType !== 'direct' && s.simMonthlyCost) {
      amtEl.value = (ddMonthlyAmount(s.simMonthlyCost) * multiOff).toFixed(2);
    } else {
      amtEl.value = 0;
    }
  } else if (simChargePrice(type) !== undefined) {
    amtEl.value = type === 'annual'
      ? +(simChargePrice(type) * multiOff).toFixed(2)
      : simChargePrice(type);
  } else {
    amtEl.value = 0;
  }
}

async function addSimCharge(simId) {
  const s = sims.find(x => x.id === simId);
  if (!s) return;
  const type   = document.getElementById('simChargeType').value;
  const amount = parseFloat(document.getElementById('simChargeAmount').value) || 0;
  if (amount <= 0) { toast('Amount must be greater than £0', 'error'); return; }
  const note   = document.getElementById('simChargeNote').value.trim();
  const payMethod = document.getElementById('simChargePay')?.value || 'account';
  const payLabel = { cash: 'cash', card: 'card', bank_transfer: 'bank transfer' }[payMethod] || '';
  const menuItem = type.startsWith('menu:') ? simMenu.find(x => String(x.id) === type.slice(5)) : null;
  const baseDesc = menuItem?.name || SIM_CHARGE_DESCS[type] || 'Custom charge';
  const desc   = note ? `${baseDesc} — ${note}` : baseDesc;
  if (!(await kcConfirm({
    title: 'Confirm SIM charge',
    body: `<strong>${escName(s.customerName || 'Customer')}</strong><br>${escHtml(desc)}${payLabel ? `<br>Paid now — ${payLabel}` : ''}`,
    amount,
    okLabel: 'Add charge',
  }))) return;
  if (!s.history) s.history = [];
  const historyId = uid();
  s.history.push({
    id:     historyId,
    type, desc, amount,
    date: new Date().toLocaleDateString('en-GB', { day:'numeric', month:'short', year:'numeric' }),
  });
  if (type === 'monthly' && s.renewalDate) {
    const d = parseLocalDate(s.renewalDate);
    d.setMonth(d.getMonth() + 1);
    s.renewalDate = localISO(d);
  }
  saveSims(sims);
  // Post the charge to the wallet ledger (SIM money now shows in the balance
  // and arrears). "Paid now" then posts the matching payment — same mechanism
  // as the rental/repair flows — so the two rows net out at the counter.
  window.api.chargeSim({ simId: s.id, customerId: s.customerId, historyId, amount, description: desc })
    .then(res => {
      if (!res?.success) { toast(res?.error || 'Charge saved, but not billed to the wallet.', 'error'); return; }
      if (payMethod !== 'account') {
        return window.api.addLedgerEntry({ customerId: s.customerId, kind: 'payment', amount, method: payMethod, note: `Paid at counter — ${desc}`, clientRef: kcRef() })
          .then(pr => { if (!pr?.success) toast(pr?.error || 'Charge billed, but the payment was not recorded.', 'error'); });
      }
    })
    .catch(() => toast('Charge saved, but not billed to the wallet.', 'error'));
  toast(`Charge of ${fmtGbp(amount)} added${payMethod !== 'account' ? ` — settled by ${payLabel}` : ''}`, 'success', 'check');
  openManageSimModal(simId);
}

function deleteSimCharge(simId, chargeId) {
  const s = sims.find(x => x.id === simId);
  if (!s) return;
  s.history = (s.history || []).filter(h => h.id !== chargeId);
  saveSims(sims);
  toast('Charge removed.', 'warning');
  openManageSimModal(simId);
}

async function deleteSim(id) {
  const s = sims.find(x => x.id === id);
  if (!s) return;
  // #64 — money-affecting delete: confirm through the amount-aware modal.
  if (!(await kcConfirm({
    title: 'Delete SIM plan?',
    body: `<strong>${escHtml(capName(s.customerName) || 'SIM plan')}</strong>${s.provider ? ' · ' + escHtml(s.provider) : ''}<br>Any SIM charges on the wallet are reversed. This can’t be undone.`,
    okLabel: 'Delete SIM plan',
    danger: true,
  }))) return;
  sims = sims.filter(x => x.id !== id);
  const res = await saveSims(sims, [id]);
  renderSimsTab();
  if (res && res.success === false) return; // reportSave already warned
  toast('SIM plan deleted.', 'warning');
}

// ─────────────────────────────────────────────
//  HELPERS
// ─────────────────────────────────────────────
function setErr(id, msgOrFalse) {
  const el = document.getElementById(id);
  if (msgOrFalse) {
    el.textContent = typeof msgOrFalse === 'string' ? msgOrFalse : el.dataset.default || 'Required';
    el.classList.add('visible');
  } else {
    el.classList.remove('visible');
  }
}
function setInputErr(id, isErr) {
  const el = document.getElementById(id);
  el.classList.toggle('error', isErr);
  // Announce the invalid state to assistive tech; the field's aria-describedby
  // already points at its error text, so the reason is read out too.
  if (isErr) el.setAttribute('aria-invalid', 'true');
  else el.removeAttribute('aria-invalid');
}

// Placeholders get written for the desk, where the field is wide. On a phone
// the same box is a third of the width and the long ones are cut mid-word —
// the till's scan box showed "🔍 Scan a barc", which reads as a broken field
// rather than a hint. Ask for the short form when the screen is narrow.
// Evaluated when the field renders, which is when these two are opened.
function kcHint(long, short) {
  return window.matchMedia('(max-width: 640px)').matches ? short : long;
}

function escHtml(str) {
  return String(str)
    .replace(/&/g,'&amp;')
    .replace(/</g,'&lt;')
    .replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;');
}

// escHtml for people's names: also tidies capitals ("elishe halbershtam" →
// "Elishe Halbershtam"). The sheet/ELID imports stored names as the
// spreadsheets had them, and capName only runs when a name is SAVED through
// the form — so every table and title that echoes a stored name goes through
// this instead of plain escHtml. Display-only; the stored data is untouched.
function escName(str) {
  return escHtml(capName(str));
}

// Escape a name AND isolate its text direction. <bdi> stops a mixed
// Hebrew/Latin name (RTL) from visually reordering against adjacent LTR
// content — a badge, phone number, date or parenthetical. Inert for plain
// Latin names (no visual change), so it's safe to use everywhere a person's
// name is shown.
function nameHtml(str) { return `<bdi>${escHtml(str)}</bdi>`; }

// Escape a value placed inside a single-quoted JS string in an inline handler
// (onclick="fn('...')"). HTML-encoding ALONE is not enough there — the parser
// decodes entities before the JS runs, so a ' in the value would still break out.
// JS-escape backslash + quote first, then HTML-escape so it also survives the
// attribute. Use for every user-controlled value passed to an inline handler. U8.
function escJs(str) {
  return escHtml(String(str == null ? '' : str).replace(/\\/g, '\\\\').replace(/'/g, "\\'"));
}

// Skeleton loading — the wait mirrors the incoming layout instead of
// announcing itself (DESIGN.md §Loading). 'stats' ghosts the usual
// stats-row + table page; 'columns' ghosts a two-column card tab.
// Each tab passes its OWN shape. A skeleton is only worth having if it is the
// silhouette of the thing arriving — otherwise it is a second layout that
// flashes and is replaced, which reads as the page changing its mind. The two
// fixed shapes this used to offer meant Tasks (four cards, a toolbar and two
// columns) ghosted as three cards over one list, so nothing landed where the
// ghost had put it. TAB_SKELETON below carries the measured shape of every
// tab; passing a string still works for the two legacy kinds.
const TAB_SKELETON = {
  wallet:   { cards: 4, toolbar: true, cols: 2 },
  repairs:  { cards: 4, toolbar: true, cols: 1 },
  services: { cards: 3, toolbar: true, cols: 2 },
  shop:     { cards: 4, toolbar: true, cols: 1 },
  koltorah: { cards: 0, toolbar: true, cols: 1 },
  tasks:    { cards: 4, toolbar: true, cols: 2 },
  virtual:  { cards: 2, toolbar: true, cols: 1 },
  settings: { cards: 0, toolbar: true, cols: 1 },
  bank:     { cards: 0, toolbar: true, cols: 1 },
};

function skeletonHtml(shape = 'stats') {
  // The ghosts are aria-hidden noise, so a real (visually hidden) "Loading…"
  // rides along — the spinner it replaced announced itself as text, and a
  // screen reader must not land on an empty main region.
  const sr = `<span class="kc-sr-only" role="status">Loading…</span>`;
  const rows = (n, panel = '') =>
    `<div class="kc-skel-panel">${panel}${'<div class="kc-skel"></div>'.repeat(n)}</div>`;
  const card = `<div class="kc-skel-card"><div class="kc-skel kc-skel-label"></div><div class="kc-skel kc-skel-big"></div></div>`;
  const title = '<div class="kc-skel kc-skel-title"></div>';

  const cfg = typeof shape === 'string'
    ? (TAB_SKELETON[shape] || (shape === 'columns'
        ? { cards: 0, toolbar: false, cols: 2 }
        : { cards: 3, toolbar: false, cols: 1 }))
    : shape;

  // Enough rows to reach the bottom of the screen (owner, 17 Aug: "its also
  // only half of the page's length"). A ghost that stops halfway down reads as
  // a page that has given up rather than one still arriving — and the real
  // lists it stands in for do run to the fold.
  //
  // Measured, not guessed: the column starts 114px down and wants ~40px of air
  // under it, a stats row is 118px, a toolbar 54, and a panel spends 36px on
  // padding and 33 on its title. A row is 13px of bar and 9px of margin — the
  // two 9px margins COLLAPSE into one between rows, which is what made the
  // first attempt at this stop two-thirds of the way down.
  const vh = (typeof window !== 'undefined' ? window.innerHeight : 900);
  const room = vh - 114 - 40 - (cfg.cards ? 118 : 0) - (cfg.toolbar ? 54 : 0) - 69;
  const n = Math.max(4, Math.min(26, Math.round(room / 22)));

  const stats = cfg.cards ? `<div class="stats-row">${card.repeat(cfg.cards)}</div>` : '';
  const bar = cfg.toolbar ? '<div class="kc-skel kc-skel-bar"></div>' : '';
  const body = cfg.cols === 2
    ? `<div class="kc-skel-cols">${rows(n, title)}${rows(n, title)}</div>`
    : rows(n, title);
  return `${sr}<div class="kc-skel-wrap" aria-hidden="true">${stats}${bar}${body}</div>`;
}

// ── When a skeleton is worth showing at all ───────────────────────────────
//
// Owner, 17 Aug: "dont feel that this pre-loading thing is correct for each
// screen". Most of these loads come back in well under a quarter of a second,
// and a ghost layout that appears and is replaced inside 200ms does not read
// as loading — it reads as the page changing its mind. The measured advice is
// the same everywhere it has been studied: under ~250ms show nothing at all,
// because the eye reads a fast blank as "instant" and a fast flash as a fault.
//
// So the wait now starts EMPTY and the ghost only arrives if the wait is long
// enough to need explaining. Nothing else changes: a slow tab still ghosts in
// its own measured silhouette.
//
// Cancelling is automatic rather than something every render has to remember:
// the pending paint checks that its own render is still the current one, and
// that nothing has painted into the column since — the "Loading…" marker it
// left behind is still the only child. Either test failing means the real
// screen has arrived, or a newer one has started, and the ghost is dropped.
const KC_SKELETON_DELAY_MS = 250;
let kcSkelSeq = 0;

function kcSkeleton(shape = 'stats') {
  const content = document.getElementById('mainContent');
  if (!content) return;
  const seq = String(++kcSkelSeq);
  content.dataset.kcSkel = seq;
  content.innerHTML = '<span class="kc-sr-only" role="status">Loading…</span>';
  setTimeout(() => {
    if (content.dataset.kcSkel !== seq) return;                       // a newer render began
    const only = content.children.length === 1 && content.firstElementChild;
    if (!only || !only.classList.contains('kc-sr-only')) return;      // the real screen arrived
    content.innerHTML = skeletonHtml(shape);
  }, KC_SKELETON_DELAY_MS);
}

// An error state with a Retry — never a dead-end, and never a reassuring
// empty shell when the backend is actually unreachable. Retry re-renders the
// current tab.
function errorHtml(label = 'Couldn’t load this') {
  return `<div style="text-align:center;padding:48px 30px;color:var(--muted);">
    <div class="kc-ic kc-ic-alert" style="font-size:30px;margin-bottom:8px;"></div>
    <div style="font-size:var(--fs-lead);color:var(--text);margin-bottom:4px;">${escHtml(label)}</div>
    <div style="font-size:var(--fs-body);margin-bottom:16px;">Couldn’t reach the server. Your data is safe — this is just the view.</div>
    <button class="btn btn-primary" onclick="renderTab(currentTab)">↻ Try again</button>
  </div>`;
}

// Collision-safe id (#45): Date.now() alone collides when two records are
// minted in the same millisecond (unique legacy_id then rejects one).
//
// This mirrors lib/uid.mjs::uid exactly (canonical + unit-tested — see
// test/uid.test.mjs). Kept as a mirror here only because the browser has no
// bundler. Change both together — including the digit width, which is 6 and
// not 3 because a bulk import mints far more than two rows per millisecond.
function uid() {
  return String(Date.now()) + Math.floor(Math.random() * 1000000).toString().padStart(6, '0');
}

// Money with thousands separators — "£13,135.00", not "£13135.00".
function fmtGbp(v) {
  return '£' + (Number(v) || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// Light/dark theme. Applied pre-paint by an inline script in _document.js;
// this just flips + persists. Any toggle button re-labels via updateThemeBtns.
function toggleTheme() {
  const el = document.documentElement;
  const dark = el.getAttribute('data-theme') === 'dark';
  // 'light' is set, not removed: an absent attribute means "no choice yet",
  // which is what the OS-dark palettes on /welcome and the legal pages key on.
  if (dark) { el.setAttribute('data-theme', 'light'); try { localStorage.setItem('kcTheme', 'light'); } catch {} }
  else { el.setAttribute('data-theme', 'dark'); try { localStorage.setItem('kcTheme', 'dark'); } catch {} }
  updateThemeBtns();
}
function updateThemeBtns() {
  const dark = document.documentElement.getAttribute('data-theme') === 'dark';
  document.querySelectorAll('[data-theme-btn]').forEach(b => {
    // Icon-only, so this button's NAME lives on aria-label (set in AppShell)
    // and never in its text. Swapping classes instead of textContent keeps it
    // that way and lets the drawn icon follow the topbar's ink.
    b.textContent = '';
    b.classList.add('kc-ic');
    b.classList.toggle('kc-ic-sun', dark);
    b.classList.toggle('kc-ic-moon', !dark);
  });
}

// Simple Mode — text size. Three steps of one multiplier (--fs-scale in
// globals.css), which scales the whole type ramp and therefore the whole app,
// rather than a handful of hand-picked "make these bigger" rules that leave
// 15px body copy sitting beside 11px badges.
//
// A device preference like the theme, not an account setting: the counter
// tablet and the owner's laptop want different answers, and the same person
// signs in on both.
const TEXT_SIZES = [
  { key: 'standard', label: 'Standard', mark: '' },
  { key: 'large', label: 'Large', mark: 'large' },
  { key: 'largest', label: 'Largest', mark: 'largest' },
];

function currentTextSize() {
  const mark = document.documentElement.getAttribute('data-fs') || '';
  return TEXT_SIZES.find(s => s.mark === mark) || TEXT_SIZES[0];
}

// The button's face: an "Aa" that grows with the mode, and three pips filled to
// the level — so which of the three is set reads at a glance and in the
// absolute (a lone growing "Aa" has no reference to be judged against; the pips
// do). One builder, used by the topbar button, the till button, and the
// on-load/on-cycle refresh, so all three always show the same thing.
function textSizeBtnInner() {
  const idx = TEXT_SIZES.indexOf(currentTextSize());
  const pips = TEXT_SIZES.map((_, i) => `<i${i <= idx ? ' class="on"' : ''}></i>`).join('');
  return `<span class="kc-fs-aa">Aa</span><span class="kc-fs-steps" aria-hidden="true">${pips}</span>`;
}

// Cycles rather than opening a menu. Three steps is few enough that pressing
// through them is faster than choosing from a list, and the whole app resizing
// under the press is its own preview.
function cycleTextSize() {
  const next = TEXT_SIZES[(TEXT_SIZES.indexOf(currentTextSize()) + 1) % TEXT_SIZES.length];
  if (next.mark) document.documentElement.setAttribute('data-fs', next.mark);
  else document.documentElement.removeAttribute('data-fs');
  try { localStorage.setItem('kcTextSize', next.key); } catch {}
  updateTextSizeBtns();
  toast(`Text size: ${next.label}`, 'success');
}

function updateTextSizeBtns() {
  const size = currentTextSize();
  document.querySelectorAll('[data-textsize-btn]').forEach(b => {
    b.title = `Text size: ${size.label}`;
    // The label names the state, not the action, because the action is "cycle"
    // and "cycle text size" tells a screen-reader user nothing about where they
    // currently are.
    b.setAttribute('aria-label', `Text size: ${size.label}. Press to change.`);
    b.dataset.size = size.key;
    b.innerHTML = textSizeBtnInner();
  });
}

// Copy text to the clipboard with a confirmation toast. Used by the
// check-in passport details (airline forms need each value pasted).
function copyText(text, label) {
  const t = String(text == null ? '' : text);
  const done = () => toast(`Copied ${label || ''}`.trim() + (t.length < 30 ? ` — ${t}` : ''), 'success');
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(t).then(done).catch(() => fallbackCopy(t, done));
  } else fallbackCopy(t, done);
}
function fallbackCopy(t, done) {
  const ta = document.createElement('textarea');
  ta.value = t; ta.style.position = 'fixed'; ta.style.opacity = '0';
  document.body.appendChild(ta); ta.select();
  try { document.execCommand('copy'); done(); } catch { toast('Could not copy — select and copy manually.', 'error'); }
  ta.remove();
}

function toast(msg, type = 'success', icon = null) {
  const container = document.getElementById('toast-container');
  const el = document.createElement('div');
  el.className = `toast toast-${type}`;
  // The message is still set as TEXT — a toast carries customer names and
  // free-typed notes, and the day it starts parsing HTML is the day one of
  // those becomes markup. The icon therefore rides beside it as its own
  // element rather than inside the string, which is also why call sites pass
  // an icon NAME here instead of prefixing a glyph to msg.
  if (icon) {
    const ic = document.createElement('i');
    ic.className = `kc-ic kc-ic-${icon}`;
    ic.setAttribute('aria-hidden', 'true');
    el.appendChild(ic);
  }
  const body = document.createElement('span');
  body.textContent = msg;
  el.appendChild(body);
  // Errors AND warnings announce assertively (role=alert) and stay until
  // dismissed — the money-critical ones are warnings ("card machine approved
  // after the till gave up — re-ring the SAME items"), and a 3s clock threw
  // those away before they could be read. Success/info stay polite and
  // auto-clear, but on a timer that scales with reading time (~60ms/char)
  // instead of a flat 3s that truncated the long ones mid-sentence.
  const sticky = type === 'error' || type === 'warning';
  el.setAttribute('role', sticky ? 'alert' : 'status');
  // A real button, not just a click handler on the div: dismissal has to be
  // reachable from the keyboard, and one control here serves every call site.
  const x = document.createElement('button');
  x.type = 'button';
  x.className = 'toast-x';
  x.setAttribute('aria-label', 'Dismiss');
  x.textContent = '✕';
  x.addEventListener('click', (e) => { e.stopPropagation(); el.remove(); });
  el.appendChild(x);
  el.title = 'Click to dismiss';
  el.style.cursor = 'pointer';
  el.addEventListener('click', () => el.remove());
  if (!sticky) setTimeout(() => el.remove(), Math.min(12000, Math.max(3000, 900 + msg.length * 60)));
  container.appendChild(el);
}

// ── Undo toast (Gmail pattern) ──
// One pending destructive action at a time: the UI updates optimistically and
// the server call is HELD for a few seconds while a toast offers Undo. Undo →
// restore() puts the row back and nothing was ever sent. Timeout, starting a
// second undoable action, or leaving the page → commit() runs for real.
let kcUndoPending = null; // { timer, commit, el }
function kcUndoFlush() {
  const p = kcUndoPending;
  if (!p) return;
  kcUndoPending = null;
  clearTimeout(p.timer);
  if (p.el) p.el.remove();
  try { p.commit(); } catch { /* commit paths surface their own errors */ }
}
window.addEventListener('pagehide', kcUndoFlush);
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'hidden') kcUndoFlush();
});

function kcUndoable({ label, commit, restore, seconds = 6 }) {
  kcUndoFlush(); // at most one pending — a second action commits the first
  const container = document.getElementById('toast-container');
  const el = document.createElement('div');
  el.className = 'toast toast-warning kc-undo-toast';
  el.setAttribute('role', 'status');
  const txt = document.createElement('span');
  txt.textContent = label;
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'kc-undo-btn';
  btn.textContent = 'Undo';
  el.appendChild(txt);
  el.appendChild(btn);
  container.appendChild(el);
  const timer = setTimeout(kcUndoFlush, seconds * 1000);
  kcUndoPending = { timer, commit, el };
  btn.addEventListener('click', () => {
    if (kcUndoPending && kcUndoPending.el === el) {
      clearTimeout(kcUndoPending.timer);
      kcUndoPending = null;
    }
    el.remove();
    try { restore(); } catch { /* view re-renders on next action */ }
  });
}

// ─────────────────────────────────────────────
//  TICKETS & FLIGHTS (bookings)
// ─────────────────────────────────────────────
// Tables-native: rows live in the relational bookings table and creating a
// booking posts a BOOKING-<id> wallet charge to the append-only ledger.

const BOOKING_STATUSES = ['Booked', 'Ticketed', 'Completed', 'Cancelled'];

function bookingStatusBadge(status) {
  // Route through the themed .badge-* classes (each has a dark override) instead
  // of inline hex — inline colours didn't flip for dark theme, so "Booked" went
  // dark-on-dark in the evening. These four all clear AA in both themes.
  const cls = {
    Booked:    'badge-booking',
    Ticketed:  'badge-vn',
    Completed: 'badge-active',
    Cancelled: 'badge-cancelled',
  };
  // For flights, "Completed" reads more naturally as "Flown".
  //
  // The icon is TRUSTED MARKUP and the status is a VALUE, so they cannot travel
  // in the same string: this used to build `<i …></i> Flown` into `label` and
  // then run escHtml over the lot, which printed the tag as words in the
  // status column — `<i class="kc-ic kc-ic-plane" aria-hidden="true"></i> Flown`
  // on every flown booking (owner's screenshot, 28 Aug). Markup concatenated,
  // value escaped, and never the other way round.
  const icon = status === 'Completed' ? '<i class="kc-ic kc-ic-plane" aria-hidden="true"></i> ' : '';
  const label = status === 'Completed' ? 'Flown' : status;
  return `<span class="badge ${cls[status] || 'badge-booking'}">${icon}${escHtml(label)}</span>`;
}

// ── Tickets that arrived by email ─────────────────────────────────────────
//
// A confirmation forwarded out of the mailbox flights are booked in, parsed
// into the fields a booking needs and waiting for someone to say yes. Sits
// above the register because it is work, not history: every card here is a
// ticket the shop has bought and not yet charged for.
//
// It never books anything by itself. "Make the booking" opens the ordinary New
// Booking form with the fields filled in, so the wallet charge, the booking
// gate and the passenger rows all behave exactly as they do at the counter —
// and whoever presses save sees what they are charging before they charge it.
let tmData = null, tmAt = 0, tmBusy = false, tmPendingId = null;
const TM_TTL_MS = 60_000;

// Fetched OUT of renderBookingsTab, which is synchronous and re-entered after
// every edit. Loading inside it would make each keystroke wait on the network.
async function tmEnsure(force = false) {
  if (tmBusy) return;
  if (!force && tmData && Date.now() - tmAt < TM_TTL_MS) return;
  tmBusy = true;
  try {
    const data = await window.api.getTicketMail('pending');
    // A 403 (a helper without the bookings tab) or a database without the
    // table yet both come back unusable — leave the section out rather than
    // showing an error above an otherwise working register.
    tmData = data && data.success ? data : { counts: { pending: 0 }, tickets: [] };
    tmAt = Date.now();
  } catch { tmData = { counts: { pending: 0 }, tickets: [] }; }
  finally { tmBusy = false; }
  if (currentTab === 'bookings') renderBookingsTab();
}

// Force a re-read, past the one-minute cache. Says what it is doing while it
// does it, because the honest answer to "did it work?" is usually "nothing has
// arrived yet", and a button that flickers cannot tell you that.
async function tmRefresh() {
  const btn = document.getElementById('tmRefresh');
  if (btn) { btn.disabled = true; btn.textContent = 'Checking…'; }
  const before = tmData?.tickets?.length || 0;
  await tmEnsure(true);
  const after = tmData?.tickets?.length || 0;
  if (after === before) toast(after ? 'Nothing new has arrived.' : 'No tickets waiting.', 'info');
  else toast(`${after - before} new ticket${after - before === 1 ? '' : 's'}.`, 'success');
}

// ── Ticking off a queue ──────────────────────────────────────────────────
// Thirty airline circulars arrive, twenty-eight of them are nothing to do with
// a journey, and dismissing them one at a time is why a queue stops being read
// at all. Owner, 18 Aug: "a checkbox list should be applied … to tick a lot and
// dismiss multiple at once."
//
// Only DISMISS is offered in bulk, deliberately. Confirming a booking is a
// decision per ticket — money moves, a customer is charged, a gate is answered
// — and a bulk confirm would be a way to do thirty of those without reading
// one. Throwing away junk is the only action that is genuinely the same thirty
// times over.
let tmSelected = new Set();

function tmToggleSel(id, on) {
  if (on) tmSelected.add(String(id)); else tmSelected.delete(String(id));
  tmPaintBulk();
}
function tmSelectAll(on) {
  (tmData?.tickets || []).forEach(t => on ? tmSelected.add(String(t.id)) : tmSelected.delete(String(t.id)));
  if (currentTab === 'bookings') renderBookingsTab();
}
function tmPaintBulk() {
  const bar = document.getElementById('tmBulkBar');
  if (!bar) return;
  bar.style.display = tmSelected.size ? 'flex' : 'none';
  const n = document.getElementById('tmBulkCount');
  if (n) n.textContent = `${tmSelected.size} selected`;
}
async function tmDismissSelected() {
  const ids = [...tmSelected].filter(id => (tmData?.tickets || []).some(t => String(t.id) === id));
  if (!ids.length) return;
  if (!(await kcConfirm({
    title: `Dismiss ${ids.length} ticket email${ids.length === 1 ? '' : 's'}?`,
    body: 'They leave the queue and no booking is made. Nothing is deleted — a dismissed email is still on the record.',
    okLabel: `Dismiss ${ids.length}`,
  }))) return;
  try {
    const res = await window.api.settleTicketMail({ ids, op: 'dismiss', reason: 'Dismissed in bulk at the counter' });
    if (!res || !res.success) throw new Error(res?.error || 'failed');
    toast(`${res.dismissed || ids.length} dismissed.`, 'success');
  } catch { toast('Couldn’t dismiss those — try again.', 'error'); return; }
  tmSelected.clear();
  await tmEnsure(true);
  if (currentTab === 'bookings') renderBookingsTab();
}

// Mirrors bookingForReference/refKey in lib/ticketMail.mjs — main.js is a
// classic script and cannot import. test/ticketMailMirror.test.mjs holds the
// two copies to the same answers.
function refKey(ref) {
  return String(ref || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
}
function bookingForReference(reference, list) {
  const key = refKey(reference);
  if (key.length < 5) return null;
  for (const b of (list || [])) {
    if (!b || b.status === 'Cancelled') continue;
    const refs = [b.bookingReference, b.booking_reference,
      ...((b.legs || []).map(l => l && (l.bookingReference || l.booking_reference)))];
    if (refs.some(r => r && refKey(r) === key)) return b;
  }
  return null;
}

// Open or shut, remembered. Owner, 28 Aug: "a button to collapse the emails
// for tickets - now is taking over too much of the screen - i have to scroll
// alot in order to see the bookings". Two things fix that and they are
// different: the toggle puts it away entirely, and the capped height (CSS,
// .tm-list) stops it eating the page even when it is open. A queue of eleven
// unparsed confirmations was pushing the register below three screenfolds.
//
// Default is OPEN. These are tickets the shop has bought and not charged for,
// so hiding them by default would be the app deciding not to mention money.
const TM_COLLAPSE_KEY = 'kc_tm_collapsed';
function tmCollapsed() {
  try { return localStorage.getItem(TM_COLLAPSE_KEY) === '1'; } catch { return false; }
}
function tmToggleCollapse() {
  try { localStorage.setItem(TM_COLLAPSE_KEY, tmCollapsed() ? '0' : '1'); } catch { /* private mode */ }
  renderBookingsTab();
}

function tmQueueHtml() {
  if (!tmData || !tmData.tickets || !tmData.tickets.length) return '';
  const shut = tmCollapsed();
  return `
    <div class="card" id="tmPanel" style="margin-bottom:12px;">
      <div class="card-head">
        <h2 class="card-title"><i class="kc-ic kc-ic-mail" aria-hidden="true"></i> Tickets from email
          <span class="tm-count">${tmData.tickets.length}</span></h2>
        <span style="font-size:var(--fs-micro);color:var(--muted);">
          ${shut
            ? `${tmData.tickets.length} waiting — the bookings are below.`
            : `Read from the airline's own confirmation — confirm the details and it becomes a booking.`}</span>
        <button class="btn btn-outline btn-sm" id="tmCollapse" onclick="tmToggleCollapse()"
          aria-expanded="${shut ? 'false' : 'true'}" aria-controls="tmBody"
          title="${shut ? 'Show the tickets waiting to be confirmed' : 'Put these away and go straight to the bookings'}"
          >${shut ? '▸ Show' : '▾ Hide'}</button>
        <!-- The list is cached for a minute and refreshed when the tab is
             opened, which is right for reading and wrong for the case that
             actually happens: someone at the counter has just forwarded the
             confirmation and is waiting for it to appear. -->
        <button class="btn btn-outline btn-sm" id="tmRefresh" onclick="tmRefresh()"
          title="Check for tickets that have just arrived">↻ Check now</button>
      </div>
      <div id="tmBody"${shut ? ' hidden' : ''}>
      <div class="tm-bulk" id="tmBulkBar" style="display:${tmSelected.size ? 'flex' : 'none'};">
        <strong id="tmBulkCount" style="font-size:var(--fs-body);">${tmSelected.size} selected</strong>
        <button class="btn btn-outline btn-sm" onclick="tmDismissSelected()">✕ Dismiss selected</button>
        <button class="btn btn-outline btn-sm" onclick="tmSelected.clear();renderBookingsTab()">Deselect all</button>
      </div>
      <label style="display:flex;align-items:center;gap:8px;font-size:var(--fs-small);color:var(--muted);padding:2px 0 6px;">
        <input type="checkbox" class="tm-check"
          ${tmData.tickets.length && tmData.tickets.every(t => tmSelected.has(String(t.id))) ? 'checked' : ''}
          onclick="tmSelectAll(this.checked)"> Select all ${tmData.tickets.length}
      </label>
      <div class="tm-list">${tmData.tickets.map(tmCardHtml).join('')}</div>
      </div>
    </div>`;
}

function tmCardHtml(t) {
  // The label comes from the API (lib/ticketMail.mjs), so it cannot drift from
  // the classifier that produced it; the colour is presentation and lives here.
  // Cancellations and unpaid holds are red — both cost money if missed; a
  // change or an open check-in is amber; marketing is muted, because it should
  // not have reached the queue and is here only as a historical row.
  const kindColour = {
    cancellation: 'var(--danger-ink)', payment_due: 'var(--danger-ink)',
    change: 'var(--warning-ink)', checkin_open: 'var(--accent)',
    marketing: 'var(--muted)', other: 'var(--muted)',
  }[t.kind] || '';
  const kindLabel = t.kindLabel || '';
  const money = t.price === null ? ''
    : `${({ GBP: '£', EUR: '€', USD: '$', ILS: '₪' })[t.currency] || ''}${t.price.toFixed(2)}`;
  const foreign = t.price !== null && t.currency && t.currency !== 'GBP';

  const who = t.customerName
    ? `<span class="tm-who">${escName(t.customerName)}</span>
       <span class="tm-why">${t.customerConfidence === 'sure' ? 'flown before' : 'name match'}</span>`
    : t.candidates.length
      ? `<span class="tm-why">Which of these?</span> ${t.candidates.slice(0, 3).map(c =>
          `<button class="btn btn-outline btn-sm" onclick="tmSetCustomer(${t.id}, '${escHtml(String(c.id))}')"
             title="${escHtml(c.why || '')}">${escName(c.name)}</button>`).join('')}`
      : '<span class="tm-why">No customer matched — pick one when you book it.</span>';

  // Already on the books? Then this email is a copy — the airline resending it,
  // or the customer forwarding what the shop booked last week. Offering to
  // "confirm booking details" here opens a NEW booking form, and pressing it
  // charges the same journey twice.
  const already = bookingForReference(t.bookingReference, bookings);

  return `
    <div class="tm-row">
      <div class="tm-pick-col">
        <input type="checkbox" aria-label="Select this ticket email"
          ${tmSelected.has(String(t.id)) ? 'checked' : ''}
          onclick="tmToggleSel('${escJs(String(t.id))}', this.checked)">
      </div>
      <div class="tm-main">
        <div class="tm-head">
          <strong>${escHtml(t.airline || 'Airline')}</strong>
          ${t.bookingReference ? `<code class="tm-ref">${escHtml(t.bookingReference)}</code>` : ''}
          ${kindLabel ? `<span class="tm-kind" style="color:${kindColour}">${escHtml(kindLabel)}</span>` : ''}
          <span class="tm-when">${t.receivedAt ? escHtml(fmtWhen(t.receivedAt)) : ''}</span>
        </div>
        ${t.bookable === false
          // Not a booking, so the "fill in the flight" prompts (route? date?
          // pick a customer) would be asking staff to complete something that
          // should never become a booking. Show what the message IS instead.
          ? `<div class="tm-pax">${escHtml(t.subject || '(no subject)')}</div>`
          : `<div class="tm-flight">
          ${t.route ? `<span class="tm-route">${escHtml(t.route)}</span>` : '<span class="tm-gap">route?</span>'}
          ${t.travelDate ? `<span>${escHtml(fmtDate(t.travelDate))}</span>` : '<span class="tm-gap">date?</span>'}
          ${t.departureTime ? `<span class="tm-time">${escHtml(t.departureTime)}${t.arrivalTime ? ' → ' + escHtml(t.arrivalTime) : ''}</span>` : ''}
          ${money ? `<span class="tm-price">${escHtml(money)}</span>` : '<span class="tm-gap">price?</span>'}
          ${foreign ? '<span class="tm-gap">not GBP — check the rate</span>' : ''}
        </div>
        <div class="tm-pax">${t.passengers.length
          ? t.passengers.map(p => escName(p)).join(' · ')
          : '<span class="tm-gap">no passenger name in the mail</span>'}</div>
        ${t.returnDate ? `<div class="tm-pax kc-ic kc-ic-undo">Returns ${escHtml(fmtDate(t.returnDate))} — carried onto the booking.</div>` : ''}
        <div class="tm-cust">${who}</div>`}
        ${t.kind === 'payment_due' ? `<div class="tm-missing">Not paid yet — the airline is holding the seats and will cancel them if payment is not completed. Deal with the payment before booking it in.</div>` : ''}
        ${t.kind === 'checkin_open' ? `<div class="tm-note">Check-in is open for this flight. This is a reminder about a trip, not a new booking — find it in the register if it needs checking in.</div>` : ''}
        ${already ? `<div class="tm-booked">✓ <strong>${escHtml(t.bookingReference)}</strong> is already booked —
            <a href="#" onclick="event.preventDefault();tmOpenBooking('${escJs(String(already.id))}')">${escName(already.customerName || 'this booking')}${
              already.route ? ' · ' + escHtml(already.route) : ''}${
              already.travelDate ? ' · ' + escHtml(fmtDate(already.travelDate)) : ''}</a>.
            Nothing to book: say it is this one, or add it as another flight on it.</div>` : ''}
        ${/* Only where the gaps are actually on screen. A message that is not a
               booking shows its subject instead of route?/date?/price?, so this
               line pointed at red parts that were deliberately never rendered —
               on a Jet2 advert the only red thing on the card was the sentence
               claiming there were red things (owner, 20 Aug). */''}
        ${t.bookable !== false && t.missing.length
          ? `<div class="tm-missing">The red parts didn’t parse — fill them in on the form.</div>` : ''}
      </div>
      <div class="tm-actions">
        ${t.kind === 'cancellation'
          // A cancellation is not something to book. The register is where the
          // existing booking gets marked off, so booking is demoted here and
          // dismissing — after the refund is dealt with — is the normal end.
          ? `<button class="btn btn-outline btn-sm" onclick="tmBook(${t.id})">Confirm booking details</button>
             <button class="btn btn-outline btn-sm" onclick="tmShowMail(${t.id})">Read the email</button>
             <button class="btn btn-primary btn-sm" onclick="tmDismiss(${t.id})">Dealt with</button>`
          : t.bookable === false
          // Marketing, or a message nobody could classify. It is not a booking
          // to make, so it does not offer to become one — only to be read and
          // cleared. Before 18 Aug 2026 a privacy notice and a bag-drop advert
          // both showed "✈️ Confirm booking details" here.
          ? `<button class="btn btn-outline btn-sm" onclick="tmShowMail(${t.id})">Read the email</button>
             <button class="btn btn-primary btn-sm" onclick="tmDismiss(${t.id})">Dismiss</button>`
          : already
          // The reference is live on a booking already. The two honest answers
          // are "this email IS that booking" and "this is another flight on
          // it" — neither of which is a new booking, so that button is gone
          // rather than merely demoted.
          ? `<button class="btn btn-primary btn-sm" onclick="tmIsThisBooking(${t.id}, '${escJs(String(already.id))}')"
               title="File this email on the booking it belongs to">✓ It's this booking</button>
             <button class="btn btn-outline btn-sm" onclick="tmAttachTo(${t.id}, '${escJs(String(already.id))}')"
               title="Another flight on the same booking"><i class="kc-ic kc-ic-plus" aria-hidden="true"></i> Add as another flight</button>
             <button class="btn btn-outline btn-sm" onclick="tmShowMail(${t.id})">Read the email</button>
             <button class="btn btn-outline btn-sm" onclick="tmDismiss(${t.id})">Dismiss</button>`
          : `<button class="btn btn-primary btn-sm kc-ic kc-ic-plane" onclick="tmBook(${t.id})">Confirm booking details</button>
             ${t.passengers.length > 1 ? `<button class="btn btn-outline btn-sm kc-ic kc-ic-users" onclick="tmSplit(${t.id})" title="Each passenger pays their own">Split across payers</button>` : ''}
             <button class="btn btn-outline btn-sm" onclick="tmAttach(${t.id})" title="Another leg of a journey already booked"><i class="kc-ic kc-ic-plus" aria-hidden="true"></i> Add to a booking</button>
             <button class="btn btn-outline btn-sm" onclick="tmShowMail(${t.id})">Read the email</button>
             <button class="btn btn-outline btn-sm" onclick="tmDismiss(${t.id})">Dismiss</button>`}
      </div>
    </div>`;
}

// Open the ordinary booking form, filled in from the email. Everything stays
// editable — this is a head start, not a decision.
function tmBook(id) {
  const t = (tmData?.tickets || []).find(x => String(x.id) === String(id));
  if (!t) return;
  // Belt to the card's braces: this is also reachable from the split flow and
  // from a stale card rendered before the booking was made.
  const already = bookingForReference(t.bookingReference, bookings);
  if (already) {
    toast(`${t.bookingReference} is already booked — file this email on it instead of booking it again.`, 'error');
    return;
  }
  if (t.kind === 'cancellation') {
    toast('That email is a cancellation — check what it refers to before booking anything.', 'info');
  }
  openNewBookingModal(t.customerId || null, {
    ticketId: t.id,
    route: t.route,
    airline: t.airline,
    bookingReference: t.bookingReference,
    travelDate: t.travelDate,
    departureTime: t.departureTime,
    arrivalTime: t.arrivalTime,
    // A price in another currency is NOT put in the box: the box is pounds,
    // and converting it silently at whatever rate would be a made-up number.
    price: t.price !== null && (!t.currency || t.currency === 'GBP') ? t.price : null,
    passengers: t.passengers,
    // The return leg used to be written into the notes as prose, because there
    // was nowhere else for it. It has its own field now (owner, 18 Aug: "cant
    // we include roundtrips?!"), so the booking knows when they are back
    // instead of a human re-reading a sentence.
    returnDate: t.returnDate,
    notes: [
      t.bookingReference ? `From ${t.airline || 'airline'} email, ref ${t.bookingReference}` : 'From airline email',
      t.price !== null && t.currency && t.currency !== 'GBP' ? `airline charged ${t.currency} ${t.price.toFixed(2)}` : '',
    ].filter(Boolean).join(' · '),
  });
}

// A ticket task is a doorway, not a note. The task says "Confirm ticket:
// Shmuel Bleier — LTN → TLV, 12 Sept, £428.60"; pressing it should put that
// booking on the screen with the fields already in the boxes, rather than
// leaving someone to find the right card on another tab.
async function tmOpenFromTask(reference) {
  const id = String(reference || '').replace(/^TICKET-/, '');
  await goToTab('bookings');
  await tmEnsure(true);
  const t = (tmData?.tickets || []).find(x => String(x.id) === id);
  if (!t) { toast('That ticket email has already been dealt with.', 'info'); return; }
  tmBook(t.id);
}

// ── one ticket, several people, each paying their own ────────────────────
//
// Owner, 18 Aug: "sometimes its 2 passengers, each one chargable on his own,
// and sometimes its 2 people like family under same customer." The family case
// was always fine — those are passengers on one booking. This is the other one.
//
// The register shows the shop already doing it by hand: XU2WWH is three
// bookings, three customers, one PNR. That IS the right model — one booking is
// one wallet charge — so this does not invent a new shape, it just stops the
// job taking three passes and three chances to mistype the fee.
//
// THE FEE IS THE PART THAT NEEDED A DECISION, and it was the owner's to make
// (18 Aug): staff choose at the moment of confirming — a fee each, split
// evenly, or all on one payer. No stored rule, because the honest answer is
// that it depends on who asked for the trip.
let tsState = null;

function tmSplit(id) {
  const t = (tmData?.tickets || []).find(x => String(x.id) === String(id));
  if (!t) return;
  tsState = {
    ticketId: t.id,
    rows: (t.passengers.length ? t.passengers : ['']).map((name, i) => ({
      name, customerId: i === 0 ? (t.customerId || '') : '',
    })),
    price: t.price !== null && (!t.currency || t.currency === 'GBP') ? t.price : 0,
    feeEach: 25,
    feeMode: 'each',
    payment: 'account',
    route: t.route, airline: t.airline, bookingReference: t.bookingReference,
    travelDate: t.travelDate, returnDate: t.returnDate,
    departureTime: t.departureTime, arrivalTime: t.arrivalTime,
  };
  tsRender();
}

// Every payer's share, worked out in one place so the screen and the save
// cannot disagree. Pennies from an uneven division go to the FIRST payer —
// somebody has to carry them and it must be deterministic.
function tsShares() {
  const n = Math.max(1, tsState.rows.length);
  const price = Math.max(0, Number(tsState.price) || 0);
  const fee = Math.max(0, Number(tsState.feeEach) || 0);
  const split = (total) => {
    const each = Math.floor((total * 100) / n) / 100;
    const short = Math.round((total - each * n) * 100) / 100;
    return tsState.rows.map((_, i) => round2(each + (i === 0 ? short : 0)));
  };
  const ticketShare = split(price);
  const feeShare = tsState.feeMode === 'each' ? tsState.rows.map(() => fee)
    : tsState.feeMode === 'split' ? split(fee)
      : tsState.rows.map((_, i) => (i === 0 ? fee : 0));
  return tsState.rows.map((r, i) => ({ ...r, ticket: ticketShare[i], fee: feeShare[i] }));
}

function tsRender() {
  const shares = tsShares();
  const total = shares.reduce((s, r) => s + r.ticket + r.fee, 0);
  const mode = (v, label, hint) => `
    <label style="display:flex;gap:8px;align-items:flex-start;padding:6px 0;cursor:pointer;">
      <input type="radio" name="tsFeeMode" value="${v}" ${tsState.feeMode === v ? 'checked' : ''}
        onchange="tsState.feeMode=this.value; tsRender();" style="margin-top:3px;">
      <span><strong>${label}</strong><br>
        <span style="font-size:var(--fs-micro);color:var(--muted);">${hint}</span></span>
    </label>`;

  showStackedModal(`
    <div class="modal-title kc-ic kc-ic-users">Split this ticket across payers</div>
    <div style="font-size:var(--fs-small);color:var(--muted);margin-bottom:10px;">
      ${escHtml(tsState.airline || 'Flight')}${tsState.route ? ' · ' + escHtml(tsState.route) : ''}${
        tsState.travelDate ? ' · ' + escHtml(fmtDate(tsState.travelDate)) : ''}${
        tsState.bookingReference ? ' · ' + escHtml(tsState.bookingReference) : ''}
      <br>One booking each — one wallet charge each — sharing the reference.
    </div>

    <div class="form-group">
      <label class="form-label">Ticket total (£)</label>
      <input class="form-input" type="number" min="0" step="0.01" value="${escHtml(String(tsState.price))}"
        oninput="tsState.price=this.value; tsRender();" style="width:140px;">
    </div>

    <div class="form-group">
      <label class="form-label">Booking fee (£ per payer, before the rule below)</label>
      <input class="form-input" type="number" min="0" step="0.01" value="${escHtml(String(tsState.feeEach))}"
        oninput="tsState.feeEach=this.value; tsRender();" style="width:140px;">
    </div>

    <div class="form-group">
      <label class="form-label">Who pays the fee?</label>
      ${mode('each', 'A fee each', 'Every payer carries the full fee. What the register shows you doing today.')}
      ${mode('split', 'Split it evenly', 'One fee for the trip, divided between them.')}
      ${mode('one', 'All on the first payer', 'Whoever asked for the trip carries it; the rest pay only their ticket.')}
    </div>

    <div class="form-group form-full">
      <label class="form-label">Payers</label>
      ${shares.map((r, i) => `
        <div style="display:flex;gap:8px;align-items:flex-end;flex-wrap:wrap;margin-bottom:8px;padding-bottom:8px;border-bottom:1px dashed var(--border);">
          <label class="kt-fld" style="flex:1 1 160px;">Passenger
            <input class="form-input" value="${escName(r.name || '')}" oninput="tsState.rows[${i}].name=this.value"
              placeholder="Name on the ticket" style="min-height:0;padding:6px 9px;font-size:var(--fs-small);"></label>
          <div style="flex:2 1 220px;min-width:0;">
            <span style="font-size:var(--fs-micro);color:var(--muted);">Charge to</span>
            ${customerPicker('tsCust' + i, {
              selected: r.customerId,
              onPick: `tsState.rows[${i}].customerId=document.getElementById('tsCust${i}').value`,
              style: 'min-height:0;padding:6px 9px;font-size:var(--fs-small);',
              label: 'Customer paying for ' + (r.name || 'this passenger'),
            })}
          </div>
          <div style="font-size:var(--fs-small);white-space:nowrap;padding-bottom:7px;">
            ${fmtGbp(r.ticket)} + ${fmtGbp(r.fee)} = <strong>${fmtGbp(r.ticket + r.fee)}</strong>
          </div>
          ${tsState.rows.length > 1 ? `<button type="button" class="action-btn" style="margin-bottom:5px;"
            onclick="tsRemove(${i})" aria-label="Remove payer ${i + 1}">✕</button>` : ''}
        </div>`).join('')}
      <button type="button" class="btn btn-outline" onclick="tsAdd()"
        style="padding:5px 12px;font-size:var(--fs-small);">+ Add a payer</button>
    </div>

    <div class="form-group form-full">
      <label class="form-label">Payment</label>
      <select class="form-input" style="width:220px;" onchange="tsState.payment=this.value">
        <option value="account" ${tsState.payment === 'account' ? 'selected' : ''}>Put on account (wallet)</option>
        <option value="cash" ${tsState.payment === 'cash' ? 'selected' : ''}>Paid now — 💵 Cash</option>
        <option value="card" ${tsState.payment === 'card' ? 'selected' : ''}>Paid now — 💳 Card</option>
        <option value="bank_transfer" ${tsState.payment === 'bank_transfer' ? 'selected' : ''}>Paid now — 🏦 Transfer</option>
      </select>
      <div style="font-size:var(--fs-micro);color:var(--muted);margin-top:4px;">Applies to every booking made here.</div>
    </div>

    <div style="margin-top:8px;padding:10px;border-radius:8px;background:var(--bg-secondary);font-size:var(--fs-small);">
      <strong>${tsState.rows.length} booking${tsState.rows.length === 1 ? '' : 's'}</strong>,
      <strong>${fmtGbp(total)}</strong> charged in total.
      Each is a separate wallet charge and can be cancelled on its own.
    </div>

    <div class="modal-actions">
      <button class="btn btn-outline" onclick="closeStackedModal()">Cancel</button>
      <button class="btn btn-primary kc-ic kc-ic-users" onclick="tsSave()">Create ${tsState.rows.length} booking${tsState.rows.length === 1 ? '' : 's'}</button>
    </div>
  `, { width: 720 });
}

function tsAdd() { tsState.rows.push({ name: '', customerId: '' }); tsRender(); }
function tsRemove(i) { tsState.rows.splice(i, 1); tsRender(); }

async function tsSave() {
  const shares = tsShares();
  const missing = shares.findIndex(r => !r.customerId);
  if (missing > -1) { toast(`Pick who pays for ${shares[missing].name || 'payer ' + (missing + 1)}.`, 'error'); return; }
  if (!tsState.route) { toast('This ticket has no route — confirm it as a single booking instead.', 'error'); return; }
  if (!tsState.travelDate) { toast('This ticket has no travel date — confirm it as a single booking instead.', 'error'); return; }

  const total = shares.reduce((s, r) => s + r.ticket + r.fee, 0);
  // ONE confirmation for the whole split, not one per booking. Three passport
  // gates and three charge prompts for a single decision is how people start
  // clicking through them.
  if (!(await kcConfirm({
    title: `Charge ${shares.length} customers`,
    body: shares.map(r => {
      const c = customers.find(x => String(x.id) === String(r.customerId));
      return `<strong>${c ? escName(c.firstName + ' ' + (c.lastName || '')) : 'Customer'}</strong> — ${fmtGbp(r.ticket + r.fee)}`;
    }).join('<br>') + `<br><br>${escHtml(tsState.route)} · ${fmtDate(tsState.travelDate)}`,
    amount: total,
    okLabel: `Charge ${fmtGbp(total)}`,
  }))) return;

  const done = [];
  const failed = [];
  for (const r of shares) {
    const payload = {
      customerId: r.customerId,
      passenger: r.name || '',
      passengers: r.name ? [{ fullName: capName(r.name) }] : [],
      route: tsState.route,
      airline: tsState.airline || '',
      bookingReference: tsState.bookingReference || '',
      travelDate: tsState.travelDate,
      returnDate: tsState.returnDate || '',
      departureTime: tsState.departureTime || '',
      arrivalTime: tsState.arrivalTime || '',
      price: r.ticket,
      bookingFee: r.fee,
      payment: tsState.payment,
      notes: `Split booking — ${shares.length} payers on ${tsState.bookingReference || 'one ticket'}`,
      // Its own token, so a retry of ONE payer's booking cannot dedupe against
      // another's. This is the guarantee that makes a partial failure safe to
      // retry: the ones that succeeded stay exactly one charge each.
      clientRef: kcRef(),
    };
    try {
      const res = await window.api.addBooking(payload);
      if (res && res.success) done.push(res.booking); else failed.push({ r, error: res?.error });
    } catch (e) { failed.push({ r, error: 'network' }); }
  }

  done.forEach(b => { if (b && !bookings.some(x => x.id === b.id)) bookings.unshift(b); });

  if (done.length && !failed.length) {
    closeStackedModal();
    closeDynamicModal();
    // The whole email is settled by the first of them; the rest share its ref.
    if (tsState.ticketId && done[0]) {
      try { await window.api.settleTicketMail({ id: tsState.ticketId, op: 'booked', bookingId: done[0].id }); }
      catch { /* the bookings exist; the card simply stays in the queue */ }
    }
    toast(`✓ ${done.length} bookings created, ${fmtGbp(total)} charged`);
    await tmEnsure(true);
  } else if (done.length) {
    // Partial: say exactly which ones landed. Silently retrying the lot would
    // double-charge the ones that worked.
    toast(`${done.length} of ${shares.length} created — ${failed.length} failed. Add the rest by hand.`, 'error');
  } else {
    toast(failed[0]?.error || 'Could not create the bookings.', 'error');
  }
  if (currentTab === 'bookings') renderBookingsTab();
}

// ── this email is another flight on a booking that already exists ─────────
//
// A self-transfer journey arrives as two or four separate confirmations. The
// first becomes the booking; the rest are legs of it. Without this they sit in
// the queue asking to be booked when they have already been paid for — and
// somebody eventually books one twice.
function tmAttach(id) {
  const t = (tmData?.tickets || []).find(x => String(x.id) === String(id));
  if (!t) return;
  const today = localISO();
  // The customer's own bookings first, then anything else recent. A journey's
  // other legs are almost always for the same person and around the same date.
  const mine = t.customerId ? bookings.filter(b => String(b.customerId) === String(t.customerId)) : [];
  const rest = bookings.filter(b => !mine.includes(b) && b.status !== 'Cancelled' &&
    (!b.travelDate || tripLastDay(b) >= today));
  const near = (b) => t.travelDate && b.travelDate
    ? Math.abs(Date.parse(b.travelDate) - Date.parse(t.travelDate)) : Infinity;
  const candidates = [...mine, ...rest]
    .sort((a, b) => near(a) - near(b))
    .slice(0, 8);

  const row = (b) => `
    <button type="button" class="btn btn-outline" style="display:block;width:100%;text-align:start;margin-bottom:6px;white-space:normal;"
      onclick="tmAttachTo(${t.id}, '${escHtml(String(b.id))}')">
      <strong>${escName(b.customerName || 'Customer')}</strong> · ${escHtml(b.route || '')}
      ${b.travelDate ? ' · ' + escHtml(fmtDate(b.travelDate)) : ''}
      ${b.bookingReference ? ' · ' + escHtml(b.bookingReference) : ''}
      ${(b.legs || []).length ? `<span class="bk-legs"> · ${b.legs.length} flights already</span>` : ''}
    </button>`;

  showStackedModal(`
    <div class="modal-title"><i class="kc-ic kc-ic-plus" aria-hidden="true"></i> Add this flight to a booking</div>
    <div style="font-size:var(--fs-small);color:var(--muted);margin-bottom:10px;">
      ${escHtml(t.airline || 'This flight')}${t.route ? ' · ' + escHtml(t.route) : ''}${
        t.travelDate ? ' · ' + escHtml(fmtDate(t.travelDate)) : ''}${
        t.bookingReference ? ' · ' + escHtml(t.bookingReference) : ''}
      <br>It becomes a <strong>flight on that booking</strong> — no new charge, because the
      booking was already charged when it was made.
    </div>
    ${candidates.length ? candidates.map(row).join('')
      : '<div class="empty-state"><div class="emoji kc-ic kc-ic-plane"></div><p>No booking to add it to yet.</p><small>Confirm one of these tickets as a booking first, then add the other legs to it.</small></div>'}
    <div class="modal-actions"><button class="btn btn-outline" onclick="closeStackedModal()">Cancel</button></div>
  `, { width: 560 });
}

async function tmAttachTo(id, bookingId) {
  try {
    const res = await window.api.settleTicketMail({ id, op: 'attach', bookingId });
    if (!res || !res.success) throw new Error(res?.error || 'failed');
    closeStackedModal();
    toast(`✓ Added as flight ${res.position}${res.direction === 'return' ? ' (the way back)' : ''}`);
    // The booking's leg list changed, so the register has to be re-read.
    // Re-read the register: the booking's leg list changed under it. Same
    // loader the tab boot uses, so a failed read degrades the same way.
    const fresh = await safeLoadArray('bookings', '/api/bookings');
    if (fresh.length) bookings = fresh;
    await tmEnsure(true);
    if (currentTab === 'bookings') renderBookingsTab();
  } catch (e) { toast('Couldn’t add that flight — try again.', 'error'); }
}

// "It's this booking" — the email is the confirmation for something already on
// the books, so record the join and let it leave the queue. No money moves and
// no booking is created; this is filing, not booking.
async function tmIsThisBooking(id, bookingId) {
  try {
    const res = await window.api.settleTicketMail({ id, op: 'booked', bookingId });
    if (!res || !res.success) throw new Error(res?.error || 'failed');
    toast('✓ Filed on the booking it belongs to.', 'success');
    await tmEnsure(true);
    if (currentTab === 'bookings') renderBookingsTab();
  } catch { toast('Couldn’t file that — try again.', 'error'); }
}

// The booking the reference is already on, opened for a look before deciding.
function tmOpenBooking(bookingId) {
  const b = bookings.find(x => String(x.id) === String(bookingId));
  if (b) openEditBookingModal(b.id); else toast('That booking is no longer in the list.', 'error');
}

// Called from saveNewBooking: the email became this booking.
async function tmMarkBooked(bookingId) {
  const id = tmPendingId;
  tmPendingId = null;
  if (!id || !bookingId) return;
  try {
    await window.api.settleTicketMail({ id, op: 'booked', bookingId });
    await tmEnsure(true);
  } catch { /* the booking is saved; the card simply stays in the queue */ }
}

async function tmSetCustomer(id, customerId) {
  try {
    const res = await window.api.settleTicketMail({ id, customerId });
    if (!res || !res.success) throw new Error(res?.error || 'failed');
    toast('✓ Noted whose ticket it is');
    await tmEnsure(true);
  } catch { toast('Couldn’t save that — try again.', 'error'); }
}

async function tmDismiss(id) {
  const t = (tmData?.tickets || []).find(x => String(x.id) === String(id));
  if (!(await kcConfirm({
    title: 'Dismiss this ticket email?',
    body: `${escHtml(t?.airline || 'This email')}${t?.bookingReference ? ' · ' + escHtml(t.bookingReference) : ''}<br>
      It stays on file, but it stops asking to be booked. Do this when the
      booking is already in the app, or the email isn't ours.`,
    okLabel: 'Dismiss',
  }))) return;
  try {
    const res = await window.api.settleTicketMail({ id, op: 'dismiss', reason: 'Dismissed at the counter' });
    if (!res || !res.success) throw new Error(res?.error || 'failed');
    toast('Dismissed.');
    await tmEnsure(true);
  } catch { toast('Couldn’t dismiss that — try again.', 'error'); }
}

// The mail itself, for the times the parser missed something and someone needs
// to read what the airline actually wrote.
// ── KC_MAILBODY mirror start ──
// Mirrors lib/mailBody.mjs. Held to it by test/mailBodyMirror.test.mjs — the
// same arrangement as the pricing mirror. Change one, change both.
const KC_MAILBODY = (() => {
  const BRACKETED = /\(\s*(https?:\/\/[^\s()]+)\s*\)/g;
  const BARE = /(?<![("<])\bhttps?:\/\/[^\s<>()]+/g;
  function linkHost(url) {
    const m = String(url || '').match(/^https?:\/\/([^/?#]+)/i);
    return m ? m[1].replace(/^www\./i, '') : '';
  }
  function labelBefore(text) {
    const tail = String(text).split(/\n|\)\s*/).pop() || '';
    const label = tail.trim();
    if (!label || label.length > 60) return '';
    return label;
  }
  // Raw HTML that never got flattened on the way in — see lib/mailBody.mjs.
  const LOOKS_HTML = /<\s*(?:!doctype|html|head|body|table|tr|td|div|p|br|span|style|meta|a)\b/i;
  const ENTITY = {
    amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
    mdash: '\u2014', ndash: '\u2013', hellip: '\u2026', pound: '\u00a3', euro: '\u20ac',
    rsquo: '\u2019', lsquo: '\u2018', ldquo: '\u201c', rdquo: '\u201d',
  };
  function decodeEntities(t) {
    return String(t)
      .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
      .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
      .replace(/&([a-z]+);/gi, (m, name) => ENTITY[name.toLowerCase()] ?? m);
  }
  function htmlToText(body) {
    const src = String(body == null ? '' : body);
    if (!LOOKS_HTML.test(src)) return src;
    const text = src
      .replace(/<!--[\s\S]*?-->/g, ' ')
      .replace(/<(script|style|head|title)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, ' ')
      .replace(/<a\b[^>]*\bhref\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a\s*>/gi, (m, href, inner) => {
        const label = inner.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
        return label ? ` ${label} ( ${href} ) ` : ` ( ${href} ) `;
      })
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/(p|div|tr|table|h[1-6]|li|ul|ol|section|header|footer)\s*>/gi, '\n')
      .replace(/<[^>]+>/g, ' ');
    return decodeEntities(text)
      .replace(/[ \t\u00a0]+/g, ' ')
      .replace(/^[ \t]+|[ \t]+$/gm, '')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  }
  function segments(body) {
    const src = htmlToText(String(body == null ? '' : body));
    if (!src.trim()) return [];
    const out = [];
    const pushText = (t) => {
      if (!t) return;
      const last = out[out.length - 1];
      if (last && last.type === 'text') last.text += t;
      else out.push({ type: 'text', text: t });
    };
    let at = 0;
    BRACKETED.lastIndex = 0;
    for (let m = BRACKETED.exec(src); m; m = BRACKETED.exec(src)) {
      const before = src.slice(at, m.index);
      const label = labelBefore(before);
      const cutAt = label ? before.lastIndexOf(label) : before.length;
      pushText(before.slice(0, cutAt));
      out.push({ type: 'link', text: label || linkHost(m[1]), href: m[1] });
      at = m.index + m[0].length;
    }
    pushText(src.slice(at));
    const spread = [];
    for (const seg of out) {
      if (seg.type !== 'text') { spread.push(seg); continue; }
      let cut = 0;
      BARE.lastIndex = 0;
      for (let m = BARE.exec(seg.text); m; m = BARE.exec(seg.text)) {
        const lead = seg.text.slice(cut, m.index);
        if (lead) spread.push({ type: 'text', text: lead });
        spread.push({ type: 'link', text: linkHost(m[0]), href: m[0] });
        cut = m.index + m[0].length;
      }
      const tail = seg.text.slice(cut);
      if (tail) spread.push({ type: 'text', text: tail });
    }
    return spread.map((seg, i) => {
      if (seg.type !== 'text') return seg;
      let t = seg.text
        .replace(/[ \t]+/g, ' ')
        .replace(/ +([,.;:!?])/g, '$1')
        .replace(/\n{3,}/g, '\n\n')
        .replace(/[ \t]+\n/g, '\n');
      if (i === 0) t = t.replace(/^\s+/, '');
      if (i === spread.length - 1) t = t.replace(/\s+$/, '');
      return { type: 'text', text: t };
    }).filter(seg => seg.type !== 'text' || seg.text !== '');
  }
  const text = (body) => segments(body).map(s => s.text).join('');
  return { segments, text, linkHost, htmlToText };
})();
// ── KC_MAILBODY mirror end ──

/**
 * The message as HTML: prose as prose, every link on its own words.
 *
 * The link opens in a new tab and carries the destination in its title, so a
 * hover still answers "where does this actually go" — which matters when the
 * mail claims to be from an airline and might not be.
 */
function tmMailHtml(body) {
  const segs = KC_MAILBODY.segments(body);
  if (!segs.length) return '<span class="muted">(the message had no readable text)</span>';
  return segs.map(s => s.type === 'link'
    ? `<a class="tm-link" href="${escHtml(s.href)}" target="_blank" rel="noopener noreferrer"
         title="${escHtml(s.href)}">${escHtml(s.text)}</a>`
    : escHtml(s.text)).join('');
}

/** An airline email that needs a person rather than a parser. */
function tmMailTask(id) {
  const t = (tmData?.tickets || []).find(x => String(x.id) === String(id));
  if (!t) return;
  kcTaskFromHere({
    title: t.subject || 'Deal with an airline email',
    notes: `From ${t.from || 'unknown'}${t.receivedAt ? ` · ${fmtDate(t.receivedAt)}` : ''}` +
      `\n${KC_MAILBODY.text(t.body).slice(0, 300)}`,
    source: 'an airline email',
  });
}

function tmShowMail(id) {
  const t = (tmData?.tickets || []).find(x => String(x.id) === String(id));
  if (!t) return;
  // Wider than the default 460: an itinerary is a table of times and places,
  // and squeezing one into a phone-width column is how it became unreadable in
  // the first place. Capped by max-width:95vw like every other dialog.
  showStackedModal(`
    <div class="modal-title kc-ic kc-ic-mail">${escHtml(t.subject || '(no subject)')}</div>
    <div style="font-size:var(--fs-micro);color:var(--muted);margin-bottom:8px;">
      From ${escHtml(t.from || 'unknown')}${t.receivedAt ? ' · ' + escHtml(fmtDate(t.receivedAt)) : ''}</div>
    <pre class="tm-body" data-kc-scroller>${tmMailHtml(t.body)}</pre>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;">
      <button class="btn btn-outline btn-sm kc-ic kc-ic-edit-note" onclick="tmMailTask(${Number(t.id)})">Make this a task</button>
    </div>
  `, { width: 680 });
}

function renderBookingsTab() {
  const content = document.getElementById('mainContent');
  const today = localISO();
  const active = bookings.filter(b => b.status !== 'Cancelled');
  const upcoming = active.filter(b => b.travelDate && tripLastDay(b) >= today).length;
  const feesEarned = active.reduce((s, b) => s + (b.bookingFee || 0), 0);
  const totalCharged = active.reduce((s, b) => s + (b.price || 0) + (b.bookingFee || 0), 0);

  const bkBar = kcFilterSort('bookings', [
    { value: 'all', label: 'Filter: all bookings' },
    { value: 'upcoming', label: 'Upcoming travel', icon: 'plane', test: b => b.status !== 'Cancelled' && b.status !== 'Completed' && (!b.travelDate || tripLastDay(b) >= today) },
    { value: 'completed', label: '✓ Completed', test: b => b.status === 'Completed' },
    { value: 'cancelled', label: '✕ Cancelled', test: b => b.status === 'Cancelled' },
  ], [
    { value: 'travel', label: 'Sort: Travel (soonest)', cmp: (a, b) => String(a.travelDate || '9999').localeCompare(String(b.travelDate || '9999')) },
    { value: 'travel_desc', label: 'Travel (latest)', cmp: (a, b) => String(b.travelDate || '').localeCompare(String(a.travelDate || '')) },
    { value: 'name', label: 'Customer A–Z', cmp: kcCmpStr(b => b.customerName) },
    { value: 'recent', label: 'Recently added', cmp: kcCmpDate(b => b.createdAt || '', -1) },
    { value: 'price', label: 'Price (high–low)', cmp: kcCmpNum(b => (b.price || 0) + (b.bookingFee || 0)) },
  ], renderBookingsTab);
  const bkShown = kcViewApply('bookings', bookings);
  const liveBkIds = new Set(bookings.map(b => String(b.id)));
  [...bkSelected].forEach(id => { if (!liveBkIds.has(id)) bkSelected.delete(id); });
  bkVisibleIds = bkShown.map(b => String(b.id));
  const rows = loadFailed.bookings
    ? `<tr><td colspan="10">${errorHtml('Couldn’t load your bookings')}</td></tr>`
    : bkShown.length === 0
    ? `<tr><td colspan="10"><div class="empty-state"><div class="emoji kc-ic kc-ic-plane"></div><p>${bookings.length ? 'No bookings match this filter.' : 'No bookings yet.'}</p><small>${bookings.length ? 'Change the filter above.' : 'Click "New booking" to add the first one.'}</small>${kcClearFiltersBtn('bookings')}</div></td></tr>`
    : bkShown.map(b => `
      <tr style="cursor:pointer;" onclick="if(!event.target.closest('button,select,a,input'))openEditBookingModal('${escHtml(b.id)}')" title="Open booking">
        <td onclick="event.stopPropagation()">
          <input type="checkbox" aria-label="Select this booking" ${bkSelected.has(String(b.id)) ? 'checked' : ''}
            onclick="toggleBkSel('${escHtml(String(b.id))}', this.checked)"></td>
        <td><div class="customer-name">${custNameLink(b.customerId, escName(b.customerName || '—'))}</div>
            <div class="customer-email">${escName(b.passenger || '')}${(b.passengers || []).length ? ` · <i class="kc-ic kc-ic-users" aria-hidden="true"></i> ${b.passengers.length}` : ''}</div></td>
        <td style="white-space:nowrap;">${escHtml(b.route)}</td>
        <td>${(() => {
          // A self-transfer journey is several airlines and several PNRs. The
          // column still leads with the booking's own, because that is the
          // journey's name — but it must not imply there is only one.
          const legs = b.legs || [];
          const airlines = [...new Set(legs.map(l => l.airline).filter(Boolean))];
          const refs = [...new Set(legs.map(l => l.bookingReference).filter(Boolean))];
          // Count what is EXTRA to what is actually shown. When the booking
          // carries no airline of its own the first leg's becomes the headline,
          // and counting it as extra as well says "+3 refs" over three refs.
          const leadAir = b.airline || airlines[0] || '';
          const leadRef = b.bookingReference || refs[0] || '';
          const extraAir = airlines.filter(a => a && a !== leadAir).length;
          const extraRef = refs.filter(r => r && r !== leadRef).length;
          return `${escHtml(leadAir || '—')}${
            extraAir ? `<span class="bk-legs" title="${escHtml(airlines.join(' · '))}"> +${extraAir}</span>` : ''}
          <div class="customer-email">${escHtml(leadRef)}${
            extraRef ? `<span class="bk-legs" title="${escHtml(refs.join(' · '))}"> +${extraRef} ref${extraRef === 1 ? '' : 's'}</span>` : ''}${
            legs.length > 1 ? `<span class="bk-legs"> · ${legs.length} flights</span>` : ''}</div>`;
        })()}</td>
        <td class="kc-date">${b.travelDate ? fmtDateHeb(b.travelDate) : '—'}${
          b.returnDate ? `<span class="kc-ic kc-ic-undo" title="Returns ${escHtml(fmtDate(b.returnDate))}"></span>` : ''}
            <div class="customer-email">${b.returnDate
              ? `back ${escHtml(fmtDate(b.returnDate))}`
              : `${escHtml(b.departureTime || '')}${b.arrivalTime ? ' → ' + escHtml(b.arrivalTime) : ''}`}</div></td>
        <td>${fmtGbp((b.price || 0))}</td>
        <td>${fmtGbp((b.bookingFee || 0))}</td>
        <td>${bookingStatusBadge(b.status)}</td>
        <td style="cursor:pointer;" onclick="openCheckinModal('${escHtml(b.id)}')" title="Set check-in">${checkinChip(b)}</td>
        <td>
          ${/* Was four buttons and a status box — five controls, the widest row
                in the app (issue #24). Check-in is the one that stays: it is
                the only action here with a DEADLINE, it is what the sweep
                raises tasks about, and it is the reason the row carries a
                check-in chip at all. Passengers and Remind are things you go
                looking for; check-in is the thing that comes looking for you.

                The status box stays out of the menu too. It is not an action,
                it is the row's state — the same reason Kol Torah and Repairs
                keep their stage buttons on the row (DESIGN.md, row actions). */''}
          <div class="row-actions">
          <button class="action-btn kc-ic kc-ic-takeoff" onclick="openCheckinModal('${escHtml(b.id)}')" title="Online check-in" aria-label="Online check-in"></button>
          ${kcRowMenuHtml([
            { label: 'Passengers (DOB, passport)', icon: 'users', onclick: `openPassengersModal('${escHtml(b.id)}')` },
            { label: 'Remind me about this', icon: 'clock', onclick: `openRemindModal('booking','${escHtml(b.id)}')` },
            { label: 'Delete this booking', icon: 'trash', onclick: `deleteBookingRow('${escHtml(b.id)}')`, danger: true },
          ], { label: 'More for this booking' })}
          <select class="form-input" style="width:110px;padding:5px 8px;font-size:var(--fs-small);"
            aria-label="Status for ${escHtml(b.customerName || b.bookingRef || 'this booking')}"
            onchange="changeBookingStatus('${escHtml(b.id)}', this.value)">
            ${BOOKING_STATUSES.map(s => `<option value="${s}" ${b.status === s ? 'selected' : ''}>${s}</option>`).join('')}
          </select>
          </div>
        </td>
      </tr>`).join('');

  content.innerHTML = `
    <div class="stats-row">
      <div class="stat-card"><div class="stat-label">Total bookings</div><div class="stat-value">${bookings.length}</div></div>
      <div class="stat-card"><div class="stat-label">Upcoming travel</div><div class="stat-value">${upcoming}</div></div>
      <div class="stat-card"><div class="stat-label">Booking fees</div><div class="stat-value">${fmtGbp(feesEarned)}</div></div>
      <div class="stat-card"><div class="stat-label">Total charged</div><div class="stat-value">${fmtGbp(totalCharged)}</div></div>
    </div>
    ${tmQueueHtml()}
    <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:12px;flex-wrap:wrap;">
      ${bkBar}
    </div>
    <div id="bkBulkBar" style="display:${bkSelected.size ? 'flex' : 'none'};margin:0 0 10px;padding:8px 12px;border:1px solid var(--border);border-radius:8px;background:var(--bg-secondary);align-items:center;gap:10px;flex-wrap:wrap;">
      <strong id="bkBulkCount" style="font-size:var(--fs-body);">${bkSelected.size} booking${bkSelected.size === 1 ? '' : 's'} selected</strong>
      <button class="btn btn-outline btn-sm kc-ic kc-ic-trash" style="color:var(--danger-ink);border-color:var(--danger-ink);" onclick="deleteSelectedBookings()">Delete selected</button>
      <button class="btn btn-outline btn-sm" onclick="bkSelected.clear(); renderBookingsTab()">Deselect all</button>
    </div>
    <div class="table-card">
      <table>
        <thead><tr>
          <th style="width:28px;"><input type="checkbox" aria-label="Select every booking in this view"
            ${bkVisibleIds.length && bkVisibleIds.every(id => bkSelected.has(id)) ? 'checked' : ''}
            onclick="toggleAllBkSel(this.checked)"></th>
          <th>Customer</th><th>Route</th><th>Airline / Ref</th><th>Travel</th>
          <th>Price</th><th>Fee</th><th>Status</th><th>Check-in</th><th></th>
        </tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>`;

  // The email queue loads after the register paints, so a slow network delays
  // nothing that is already on the screen.
  tmEnsure();
}

// Bulk selection for bookings — same shape as rentals/SIMs. The single-row
// delete keeps its undo toast; the bulk path confirms once up front instead.
let bkSelected = new Set();
let bkVisibleIds = [];
function toggleBkSel(id, on) {
  if (on) bkSelected.add(id); else bkSelected.delete(id);
  const bar = document.getElementById('bkBulkBar');
  if (bar) {
    bar.style.display = bkSelected.size ? 'flex' : 'none';
    const count = document.getElementById('bkBulkCount');
    if (count) count.textContent = `${bkSelected.size} booking${bkSelected.size === 1 ? '' : 's'} selected`;
  }
}
function toggleAllBkSel(on) {
  bkVisibleIds.forEach(id => on ? bkSelected.add(id) : bkSelected.delete(id));
  renderBookingsTab();
}
async function deleteSelectedBookings() {
  const picked = bookings.filter(b => bkSelected.has(String(b.id)));
  if (!picked.length) return;
  const names = [...new Set(picked.map(b => b.customerName || b.route || '—'))];
  if (!(await kcConfirm({
    title: `Delete ${picked.length} bookings?`,
    body: `<strong>${escHtml(names.slice(0, 4).join(', '))}${names.length > 4 ? ` +${names.length - 4} more` : ''}</strong><br>This can't be undone.`,
    okLabel: `Delete ${picked.length} bookings`,
  }))) return;
  let failed = 0;
  for (const b of picked) {
    const res = await window.api.deleteBooking(b.id).catch(() => null);
    if (res && res.success) {
      bookings = bookings.filter(x => x.id !== b.id);
      bkSelected.delete(String(b.id));
    } else failed++;
  }
  renderBookingsTab();
  toast(failed ? `Deleted ${picked.length - failed}; ${failed} failed.` : `${picked.length} bookings deleted.`,
    failed ? 'error' : 'warning');
}

let ticketsMenu = [];

// ── Passengers editor (shared by New Booking + the 👥 modal) ──
// Working copy lives in bkPassengers while a modal is open; inputs write
// straight into it so re-renders (add/remove row) never lose typing.
// Passport fields are owner-only on reads: helpers can type them in, but
// existing values come back blank for them (blank = unchanged on save).
let bkPassengers = [];

// One card per passenger — everything the airline check-in form asks for.
// Passport № is hidden from helpers in this editor (they can still see it on
// the check-in screen); the merge-on-save keeps a blank from erasing it.
function paxEditorHtml() {
  const helperMasked = currentStaff && currentStaff.role !== 'owner';
  const fld = (label, inner) => `<label style="display:flex;flex-direction:column;gap:2px;font-size:var(--fs-micro);color:var(--muted);">${label}${inner}</label>`;
  return bkPassengers.map((p, i) => `
    <div style="border:1px solid var(--border);border-radius:8px;padding:8px 10px;margin-bottom:8px;">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">
        <strong style="font-size:var(--fs-small);">Passenger ${i + 1}</strong>
        ${bkPassengers.length > 1 ? `<button type="button" class="action-btn" onclick="bkRemovePax(${i})" title="Remove passenger ${i + 1}" aria-label="Remove passenger ${i + 1}">✕</button>` : ''}
      </div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;">
        ${fld('Full name (as on passport)', `<input class="form-input" value="${escName(p.fullName || '')}" oninput="bkPassengers[${i}].fullName=this.value" autocomplete="off" style="width:200px;">`)}
        ${fld('Date of birth', `<input class="form-input" type="date" value="${escHtml(p.dob || '')}" onchange="bkPassengers[${i}].dob=this.value" autocomplete="off" style="width:150px;">`)}
        ${fld('Nationality', `<input class="form-input" value="${escHtml(p.nationality || '')}" oninput="bkPassengers[${i}].nationality=this.value" autocomplete="off" placeholder="e.g. British" style="width:140px;">`)}
        ${fld('Passport №', `<input class="form-input" value="${escHtml(p.passportNumber || '')}" oninput="bkPassengers[${i}].passportNumber=this.value" autocomplete="off" placeholder="${helperMasked ? 'hidden — check-in screen' : ''}" style="width:150px;">`)}
        ${fld('Passport expiry', `<input class="form-input" type="date" value="${escHtml(p.passportExpiry || '')}" onchange="bkPassengers[${i}].passportExpiry=this.value" style="width:150px;">`)}
        ${fld('Issue date', `<input class="form-input" type="date" value="${escHtml(p.passportIssueDate || '')}" onchange="bkPassengers[${i}].passportIssueDate=this.value" style="width:150px;">`)}
        ${fld('Issuing country', `<input class="form-input" value="${escHtml(p.issuingCountry || '')}" oninput="bkPassengers[${i}].issuingCountry=this.value" placeholder="e.g. UK" style="width:140px;">`)}
      </div>
    </div>`).join('');
}

// ── Flight legs ───────────────────────────────────────────────────────────
//
// Owner, 18 Aug: "sometimes we do 2 airlines for there and 2 additional for
// back.. all for one person's one time 2-way journey." One booking, several
// flights, each with its own airline and its own reference.
//
// Deliberately OPTIONAL and out of the way. Most bookings are one flight and
// always will be — the register has 394 of them and five multi-stop routes —
// so this stays folded away until somebody says the journey has more than one
// leg. The booking's own Route/Airline/Reference keep describing the journey as
// a whole; these add the detail underneath.
let bkLegs = [];
let ebLegs = [];

const KC_LEG_DIRS = [['out', '→ Out'], ['return', '↩ Back']];

function legEditorHtml(legs, arrName) {
  const fld = (label, inner) => `<label style="display:flex;flex-direction:column;gap:2px;font-size:var(--fs-micro);color:var(--muted);">${label}${inner}</label>`;
  if (!legs.length) return `<div style="font-size:var(--fs-small);color:var(--muted);">One flight each way — nothing to add.</div>`;
  return legs.map((l, i) => `
    <div style="border:1px solid var(--border);border-radius:8px;padding:8px 10px;margin-bottom:8px;">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">
        <strong style="font-size:var(--fs-small);">Flight ${i + 1}</strong>
        <button type="button" class="action-btn" onclick="bkRemoveLeg('${arrName}',${i})"
          title="Remove flight ${i + 1}" aria-label="Remove flight ${i + 1}">✕</button>
      </div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;">
        ${fld('Direction', `<select class="form-input" onchange="${arrName}[${i}].direction=this.value" style="width:110px;">
          ${KC_LEG_DIRS.map(([v, lab]) => `<option value="${v}" ${l.direction === v ? 'selected' : ''}>${lab}</option>`).join('')}
        </select>`)}
        ${fld('Airline', `<input class="form-input" value="${escHtml(l.airline || '')}" oninput="${arrName}[${i}].airline=this.value" placeholder="e.g. Wizz Air" style="width:150px;">`)}
        ${fld('Reference', `<input class="form-input" value="${escHtml(l.bookingReference || '')}" oninput="${arrName}[${i}].bookingReference=this.value" placeholder="own PNR" style="width:120px;">`)}
        ${fld('From', `<input class="form-input" value="${escHtml(l.origin || '')}" oninput="${arrName}[${i}].origin=this.value" placeholder="LTN" style="width:80px;">`)}
        ${fld('To', `<input class="form-input" value="${escHtml(l.destination || '')}" oninput="${arrName}[${i}].destination=this.value" placeholder="TLV" style="width:80px;">`)}
        ${fld('Date', `<input class="form-input" type="date" value="${escHtml(l.flightDate || '')}" onchange="${arrName}[${i}].flightDate=this.value" style="width:150px;">`)}
        ${fld('Dep / Arr', `<span style="display:flex;gap:4px;">
          <input class="form-input" type="time" value="${escHtml(l.departureTime || '')}" onchange="${arrName}[${i}].departureTime=this.value" aria-label="Departure time for flight ${i + 1}" style="width:105px;">
          <input class="form-input" type="time" value="${escHtml(l.arrivalTime || '')}" onchange="${arrName}[${i}].arrivalTime=this.value" aria-label="Arrival time for flight ${i + 1}" style="width:105px;"></span>`)}
      </div>
    </div>`).join('');
}

function bkLegBlockHtml(arrName, targetId) {
  return `
    <div class="form-group form-full">
      <label class="form-label">Flights <span style="color:var(--muted);font-weight:400;">(only if the journey has more than one)</span></label>
      <div id="${targetId}">${legEditorHtml(arrName === 'bkLegs' ? bkLegs : ebLegs, arrName)}</div>
      <button type="button" class="btn btn-outline" onclick="bkAddLeg('${arrName}')"
        style="padding:5px 12px;font-size:var(--fs-small);margin-top:2px;">+ Add a flight</button>
    </div>`;
}

function kcLegArr(arrName) { return arrName === 'bkLegs' ? bkLegs : ebLegs; }
function kcLegTarget(arrName) { return arrName === 'bkLegs' ? 'bkLegEditor' : 'ebLegEditor'; }

function bkRenderLegs(arrName) {
  const el = document.getElementById(kcLegTarget(arrName));
  if (el) el.innerHTML = legEditorHtml(kcLegArr(arrName), arrName);
}
function bkAddLeg(arrName) {
  const arr = kcLegArr(arrName);
  // A second leg is almost always the way home; a fourth is the second half of
  // a self-transfer. Guessing the direction saves the commonest click.
  arr.push({ direction: arr.length >= 2 ? 'return' : 'out' });
  bkRenderLegs(arrName);
}
function bkRemoveLeg(arrName, i) {
  kcLegArr(arrName).splice(i, 1);
  bkRenderLegs(arrName);
}

function bkRenderPax() {
  const el = document.getElementById('bkPaxEditor');
  if (el) el.innerHTML = paxEditorHtml();
  // Keep the fee calculator's passenger count in step with the rows.
  const pax = document.getElementById('bkPax');
  if (pax) { pax.value = Math.max(1, bkPassengers.length); bkCalcFee(); }
}

function bkAddPax() { bkPassengers.push({}); bkRenderPax(); }
function bkRemovePax(i) { bkPassengers.splice(i, 1); if (!bkPassengers.length) bkPassengers.push({}); bkRenderPax(); }

// #48 — a family flies twice a year; don't retype six passports. When a
// customer is chosen, offer to reuse the passenger list from their most recent
// booking that had one. Only offered while the editor is still untouched
// (single blank row), so it never clobbers data already entered.
function bkLastTripPassengers(customerId) {
  const prior = bookings
    .filter(b => b.customerId === customerId && Array.isArray(b.passengers) && b.passengers.some(p => p && p.fullName))
    .sort((a, b) => String(b.travelDate || b.createdAt || '').localeCompare(String(a.travelDate || a.createdAt || '')));
  return prior.length ? prior[0] : null;
}
function bkOnCustomerChange() {
  const wrap = document.getElementById('bkReuseWrap');
  if (!wrap) return;
  const cid = document.getElementById('bkCustomer')?.value;
  const editorEmpty = bkPassengers.length <= 1 && !(bkPassengers[0] && bkPassengers[0].fullName);
  const last = cid ? bkLastTripPassengers(cid) : null;
  if (!last || !editorEmpty) { wrap.innerHTML = ''; return; }
  const n = last.passengers.filter(p => p && p.fullName).length;
  wrap.innerHTML = `
    <div style="display:flex;align-items:center;gap:10px;background:rgba(83,58,253,0.06);border:1px solid var(--primary-subdued);border-radius:8px;padding:7px 12px;font-size:var(--fs-small);">
      <span style="flex:1;">↻ Reuse ${n} passenger${n === 1 ? '' : 's'} from their last trip${last.route ? ' (' + escHtml(last.route) + ')' : ''}?</span>
      <button type="button" class="btn btn-outline btn-sm" style="font-size:var(--fs-micro);padding:4px 10px;" onclick="bkReuseLastTrip('${escHtml(String(cid))}')">Reuse passengers</button>
    </div>`;
}
function bkReuseLastTrip(customerId) {
  const last = bkLastTripPassengers(customerId);
  if (!last) return;
  // Deep copy so edits here never mutate the previous booking's records.
  bkPassengers = last.passengers.filter(p => p && p.fullName).map(p => ({ ...p }));
  if (!bkPassengers.length) bkPassengers = [{}];
  bkRenderPax();
  const wrap = document.getElementById('bkReuseWrap');
  if (wrap) wrap.innerHTML = `<div style="font-size:var(--fs-micro);color:var(--success);padding:2px 0;">✓ Reused ${bkPassengers.length} passenger${bkPassengers.length === 1 ? '' : 's'} — check passport expiry dates.</div>`;
}

// Post-creation editor: the 👥 button on each booking row.
function openPassengersModal(bookingId) {
  const b = bookings.find(x => x.id === bookingId);
  if (!b) return;
  bkPassengers = (b.passengers || []).map(p => ({ ...p }));
  if (!bkPassengers.length) bkPassengers.push({});
  showDynamicModal(`
    <div class="modal-title kc-ic kc-ic-users">Passengers — ${escHtml(b.route)} ${b.travelDate ? fmtDate(b.travelDate) : ''}</div>
    <div id="bkPaxEditor">${paxEditorHtml()}</div>
    <button type="button" class="btn btn-outline" onclick="bkAddPax()"
      style="padding:5px 12px;font-size:var(--fs-small);margin-top:2px;">+ Add passenger</button>
    <div class="modal-actions">
      <button class="btn btn-outline" onclick="closeDynamicModal()">Cancel</button>
      <button class="btn btn-primary" onclick="savePassengers('${escHtml(bookingId)}')">Save passengers</button>
    </div>
  `);
}

async function savePassengers(bookingId) {
  bkPassengers.forEach(p => { if (p.fullName) p.fullName = capName(p.fullName); });
  const res = await window.api.updateBooking({ id: bookingId, passengers: bkPassengers });
  if (!res.success) { toast(res.error || 'Could not save passengers.', 'error'); return; }
  const idx = bookings.findIndex(x => x.id === bookingId);
  if (idx !== -1) bookings[idx] = res.booking;
  closeDynamicModal();
  toast('Passengers saved.', 'success');
  renderBookingsTab();
}

/**
 * The New Booking form.
 *
 * `prefill` is how a ticket read out of an airline email gets here — route,
 * date, price and passengers already in the boxes. Every field stays editable
 * and nothing is charged until someone presses save and confirms the amount,
 * which is the whole point: the email saves the typing, the person makes the
 * decision.
 */
async function openNewBookingModal(preselectCustomerId = null, prefill = null) {
  bkLegs = Array.isArray(prefill?.legs) ? prefill.legs.map(l => ({ ...l })) : [];
  // Which ticket email this form is answering, if any. Set on EVERY open, so
  // abandoning a prefilled form and starting a fresh booking cannot file the
  // new one against the old email.
  tmPendingId = prefill?.ticketId || null;
  bkPassengers = (prefill?.passengers || []).length
    ? prefill.passengers.map(name => ({ fullName: name }))
    : [{}];
  if (!ticketsMenu.length) {
    ticketsMenu = await window.api.getServiceMenu('tickets').catch(() => []);
    if (!Array.isArray(ticketsMenu)) ticketsMenu = [];
  }
  const startFee = ticketsMenu.find(s => /start fee/i.test(s.name));
  const svcOptions = ticketsMenu
    .filter(s => !/start fee/i.test(s.name))
    .map(s => `<option value="${escHtml(s.id)}">${escHtml(s.name)} — ${fmtGbp(s.price)}</option>`)
    .join('');
  showDynamicModal(`
    <div class="modal-title kc-ic kc-ic-plane">${prefill ? 'Confirm booking details' : 'New booking'}</div>
    ${prefill ? `<div class="tm-prefill"><i class="kc-ic kc-ic-mail" aria-hidden="true"></i> Filled in from the ${escHtml(prefill.airline || 'airline')} email${
      prefill.bookingReference ? ` · ${escHtml(prefill.bookingReference)}` : ''
    } — this is what the app read, not what it decided. Change anything that is wrong, then save.${
      /* The fee is tiered per passenger and the email says how many. The
         calculator already prices for that count — but only once somebody
         picks the service, and nothing said so. Which service (£20 ready
         planned / £25 standard / £30 self-transfer) is a judgement about how
         much work the shop did, and no email can answer it. */
      (prefill.passengers || []).length > 1
        ? `<br><strong>${(prefill.passengers || []).length} passengers</strong> read from the email — pick the service below and the fee prices for all ${(prefill.passengers || []).length}.`
        : ''
    }${prefill.returnDate ? `<br><i class="kc-ic kc-ic-undo" aria-hidden="true"></i> Round trip — returning ${escHtml(fmtDate(prefill.returnDate))}.` : ''}</div>` : ''}
    <div class="form-grid">
      <div class="form-group form-full">
        <label class="form-label">Customer *</label>
        ${customerPicker('bkCustomer', { selected: preselectCustomerId, onPick: 'bkOnCustomerChange()' })}
      </div>
      <div class="form-group form-full">
        <label class="form-label">Passengers <span style="color:var(--muted);font-weight:400;">(name · date of birth · passport)</span></label>
        <div id="bkReuseWrap" style="margin-bottom:8px;"></div>
        <div id="bkPaxEditor">${paxEditorHtml()}</div>
        <button type="button" class="btn btn-outline" onclick="bkAddPax()"
          style="padding:5px 12px;font-size:var(--fs-small);margin-top:2px;">+ Add passenger</button>
      </div>
      <div class="form-group">
        <label class="form-label">Route *</label>
        <input class="form-input" id="bkRoute" placeholder="e.g. LTN → TLV">
      </div>
      <div class="form-group">
        <label class="form-label">Airline</label>
        <input class="form-input" id="bkAirline" placeholder="e.g. Wizz Air">
      </div>
      <div class="form-group">
        <label class="form-label">Booking Reference</label>
        <input class="form-input" id="bkRef" placeholder="Airline ref (may come later)">
      </div>
      <div class="form-group">
        <label class="form-label">Travel Date *</label>
        <input class="form-input" type="date" id="bkTravelDate" onchange="showHebrewDate('bkTravelDate','bkTravelHeb')">
        <div class="hebrew-date" id="bkTravelHeb"></div>
      </div>
      ${/* One booking, two dates — a return is one purchase with one reference
           and one fee, not two rows in the register. Optional, because most of
           the book is one-way. */''}
      <div class="form-group">
        <label class="form-label">Return Date <span style="color:var(--muted);font-weight:400;">(round trip only)</span></label>
        <input class="form-input" type="date" id="bkReturnDate" onchange="showHebrewDate('bkReturnDate','bkReturnHeb'); bkCheckinToggle();">
        <div class="hebrew-date" id="bkReturnHeb"></div>
      </div>
      <div class="form-group">
        <label class="form-label">Departure / Arrival</label>
        <div style="display:flex;gap:6px;">
          <input class="form-input" type="time" id="bkDep" aria-label="Departure time">
          <input class="form-input" type="time" id="bkArr" aria-label="Arrival time">
        </div>
      </div>
      <div class="form-group">
        <label class="form-label">Ticket Price (£) *</label>
        <input class="form-input" type="number" min="0" step="0.01" id="bkPrice">
      </div>
      <div class="form-group">
        <label class="form-label">Booking Fee (£)</label>
        <input class="form-input" type="number" min="0" step="0.01" id="bkFee" value="10">
      </div>
      <div class="form-group form-full">
        <label class="form-label">Payment</label>
        <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
          <select class="form-input" id="bkPay" style="width:200px;">
            <option value="account">Put on account (wallet)</option>
            <option value="cash">Paid now — 💵 Cash</option>
            <option value="card">Paid now — 💳 Card</option>
            <option value="card_on_file">Paid now — card on file (Stripe)</option>
            <option value="bank_transfer">Paid now — 🏦 Transfer</option>
          </select>
          <span style="font-size:var(--fs-micro);color:var(--muted);">"Paid now" settles it immediately — no wallet debt.</span>
        </div>
      </div>
      ${svcOptions ? `
      <div class="form-group form-full">
        <label class="form-label">Fee calculator <span style="color:var(--muted);font-weight:400;">(passenger tiers — fills Booking Fee)</span></label>
        <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
          <select class="form-input" id="bkSvc" onchange="bkCalcFee()" style="flex:2;min-width:200px;">
            <option value="">Choose service…</option>${svcOptions}
          </select>
          <input class="form-input" type="number" id="bkPax" value="1" min="1" step="1"
            oninput="bkCalcFee()" title="Passengers" style="width:80px;">
          ${startFee ? `<label style="display:flex;align-items:center;gap:6px;font-size:var(--fs-small);cursor:pointer;">
            <input type="checkbox" id="bkStartFee" onchange="bkCalcFee()"> + start fee ${fmtGbp(startFee.price)}
          </label>` : ''}
        </div>
        <div id="bkFeeBreakdown" role="status" style="font-size:var(--fs-micro);color:var(--muted);margin-top:4px;"></div>
      </div>` : ''}
      <div class="form-group">
        <label class="form-label">Passport photocopy held?</label>
        <div style="display:flex;gap:8px;align-items:center;">
          <input type="checkbox" id="bkPassport" onchange="document.getElementById('bkPassportExpiryWrap').style.display=this.checked?'block':'none'">
          <div id="bkPassportExpiryWrap" style="display:none;flex:1;">
            <input class="form-input" type="date" id="bkPassportExpiry" title="Passport expiry">
          </div>
        </div>
      </div>
      <div class="form-group form-full">
        <label class="form-label">Online check-in</label>
        <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
          <select class="form-input" id="bkCheckinBy" style="width:180px;" onchange="bkCheckinToggle()">
            <option value="customer">Customer does check-in</option>
            <option value="us">We do check-in</option>
          </select>
          <label style="display:flex;align-items:center;gap:6px;font-size:var(--fs-body);cursor:pointer;">
            <input type="checkbox" id="bkCheckinDone"> already done
          </label>
          <span id="bkCheckinDateWrap" style="display:none;align-items:center;gap:6px;">
            <span style="font-size:var(--fs-small);color:var(--muted);">out on</span>
            <input class="form-input" type="date" id="bkCheckinDate" style="width:150px;">
          </span>
          <span id="bkRetCheckinWrap" style="display:none;align-items:center;gap:6px;">
            <span class="kc-ic kc-ic-undo" style="font-size:var(--fs-small);color:var(--muted);">back on</span>
            <input class="form-input" type="date" id="bkRetCheckinDate" style="width:150px;">
          </span>
        </div>
        <div style="font-size:var(--fs-micro);color:var(--muted);margin-top:4px;">"We do check-in" + a date raises a task reminder for that day.</div>
      </div>
      ${bkLegBlockHtml('bkLegs', 'bkLegEditor')}
      <div class="form-group form-full">
        <label class="form-label">Notes</label>
        <input class="form-input" id="bkNotes">
      </div>
    </div>
    <div style="margin-top:8px;padding:10px;border-radius:8px;background:var(--bg-secondary);font-size:var(--fs-small);color:var(--muted);">
      Saving posts one wallet charge of <strong>price + fee</strong> to the customer's ledger (reference <code>BOOKING-…</code>).
    </div>
    <div class="modal-actions">
      <button class="btn btn-outline" onclick="closeDynamicModal()">Cancel</button>
      <button class="btn btn-primary kc-ic kc-ic-plane" onclick="saveNewBooking()">Save booking</button>
    </div>
  `);
  if (preselectCustomerId) bkOnCustomerChange(); // #48 — offer passenger reuse straight away

  // Filled after the markup exists, rather than interpolated into it: these
  // values come from an email, and a value that never touches the HTML cannot
  // carry markup into the form.
  if (prefill) {
    const put = (id, v) => { const el = document.getElementById(id); if (el && v) el.value = v; };
    put('bkRoute', prefill.route);
    put('bkAirline', prefill.airline);
    put('bkRef', prefill.bookingReference);
    put('bkTravelDate', prefill.travelDate);
    put('bkReturnDate', prefill.returnDate);
    put('bkDep', prefill.departureTime);
    put('bkArr', prefill.arrivalTime);
    put('bkPrice', prefill.price === null || prefill.price === undefined ? '' : String(prefill.price));
    put('bkNotes', prefill.notes);
    if (prefill.travelDate) showHebrewDate('bkTravelDate', 'bkTravelHeb');
    if (prefill.returnDate) showHebrewDate('bkReturnDate', 'bkReturnHeb');
    // The fee calculator counts passengers, and the email just supplied them.
    const pax = document.getElementById('bkPax');
    if (pax) pax.value = Math.max(1, bkPassengers.length);
  }
}

// Fee calculator: tiered service fee × passengers (+ optional start fee)
// → fills the Booking Fee field (still editable afterwards).
function bkCalcFee() {
  const svcId = document.getElementById('bkSvc')?.value;
  if (!svcId) { const bd = document.getElementById('bkFeeBreakdown'); if (bd) bd.textContent = ''; return; }
  const svc = ticketsMenu.find(s => String(s.id) === String(svcId));
  if (!svc) return;
  const n = Math.max(1, parseInt(document.getElementById('bkPax')?.value, 10) || 1);
  const startFee = document.getElementById('bkStartFee')?.checked
    ? (ticketsMenu.find(s => /start fee/i.test(s.name))?.price || 0) : 0;
  const fee = ticketFeeFor(svc, n) + startFee;
  document.getElementById('bkFee').value = fee.toFixed(2);
  const parts = [`1 × ${fmtGbp(svc.price)}`];
  if (n > 1 && svc.repeatPrice !== null) parts.push(`${Math.min(n - 1, 4)} × ${fmtGbp(Number(svc.repeatPrice))}`);
  if (n > 5 && svc.repeatPrice !== null) parts.push(`${n - 5} × ${fmtGbp(Number(svc.bulkPrice ?? svc.repeatPrice))}`);
  if (startFee) parts.push(`start ${fmtGbp(startFee)}`);
  document.getElementById('bkFeeBreakdown').textContent =
    `${n} passenger${n === 1 ? '' : 's'}: ${parts.join(' + ')} = ${fmtGbp(fee)}`;
}

// Show the check-in dates only when WE do the check-in, and default each to the
// day before its own flight (online check-in typically opens ~24h out). The
// return leg gets the same treatment: it is the one people forget, precisely
// because it is a month away when the booking is made.
const dayBefore = (iso) => {
  if (!iso) return '';
  const d = parseLocalDate(iso);
  d.setDate(d.getDate() - 1);
  return localISO(d);
};

function bkCheckinToggle() {
  const us = document.getElementById('bkCheckinBy')?.value === 'us';
  const wrap = document.getElementById('bkCheckinDateWrap');
  if (wrap) wrap.style.display = us ? 'inline-flex' : 'none';
  const retWrap = document.getElementById('bkRetCheckinWrap');
  const hasReturn = !!document.getElementById('bkReturnDate')?.value;
  if (retWrap) retWrap.style.display = us && hasReturn ? 'inline-flex' : 'none';

  const dateEl = document.getElementById('bkCheckinDate');
  if (us && dateEl && !dateEl.value) dateEl.value = dayBefore(document.getElementById('bkTravelDate')?.value);
  const retEl = document.getElementById('bkRetCheckinDate');
  if (us && retEl && !retEl.value) retEl.value = dayBefore(document.getElementById('bkReturnDate')?.value);
}

// The Booking Gate (owner, 08-16). Mirrors lib/bookingGate.mjs — change both
// together; test/bookingGate.test.mjs holds the rules.
//
// The app already NOTICED these problems: the daily sweep raises a task when a
// passport expires within 90 days of travel. But the customer is at the counter
// when the booking is made and long gone when the task appears, and a passport
// that runs out before the flight is not a task — it is a trip that will not
// happen. So the questions get asked here, at the only moment anyone can still
// answer them, on the same BLOCK / VERIFY pattern as the rental charge gate.
const BK_BLOCK = 'block', BK_VERIFY = 'verify', BK_PASS = 'pass';
const BK_SIX_MONTHS = 183;

function bookingGateFor(b, verifications = []) {
  const checks = [];
  const seen = new Set(verifications.map(String));
  const isDate = (x) => /^\d{4}-\d{2}-\d{2}$/.test(String(x || ''));
  const dayDiff = (x, y) => Math.round((Date.parse(x) - Date.parse(y)) / 86400000);
  const travelDate = b.travelDate || '';

  if (!b.passportOnFile) checks.push({
    key: 'passport-on-file',
    level: seen.has('passport-on-file') ? BK_PASS : BK_VERIFY,
    title: 'No passport copy on file',
    detail: 'Take a photocopy or scan now — chasing it later is how a booking becomes a problem.',
  });

  // The last day of the trip, not the departure: a passport that expires while
  // the customer is abroad is worse than one that expires before they go —
  // they are turned away at a gate 2,000 miles from here. Mirrors lastDayOf()
  // in lib/bookingGate.mjs.
  const returnDate = b.returnDate || '';
  const lastDay = isDate(returnDate) && (!isDate(travelDate) || returnDate > travelDate) ? returnDate : travelDate;
  const twoWay = isDate(lastDay) && lastDay !== travelDate;
  if (isDate(b.passportExpiry) && isDate(lastDay)) {
    const after = dayDiff(b.passportExpiry, lastDay);
    const n = Math.abs(after);
    if (after < 0) checks.push({
      key: 'passport-expired', level: BK_BLOCK,
      title: twoWay ? 'Passport expires before the trip is over' : 'Passport expires before the travel date',
      detail: twoWay
        ? `It runs out ${n} day${n === 1 ? '' : 's'} before they are due to fly home on ${fmtDate(lastDay)}. The trip cannot go ahead on this document.`
        : `It runs out ${n} day${n === 1 ? '' : 's'} before they fly. The trip cannot go ahead on this document.`,
    });
    else if (after < BK_SIX_MONTHS) checks.push({
      key: 'passport-thin',
      level: seen.has('passport-thin') ? BK_PASS : BK_VERIFY,
      title: `Passport valid only ${after} days after ${twoWay ? 'the return' : 'travel'}`,
      detail: 'Many destinations want six months beyond the return date. Check this one before booking.',
    });
  } else if (isDate(lastDay) && b.passportOnFile && !isDate(b.passportExpiry)) {
    checks.push({
      key: 'passport-expiry-unknown',
      level: seen.has('passport-expiry-unknown') ? BK_PASS : BK_VERIFY,
      title: 'Passport expiry not recorded',
      detail: 'Without it nobody can tell whether this passport outlives the trip.',
    });
  }

  const worst = checks.some(c => c.level === BK_BLOCK) ? BK_BLOCK
    : checks.some(c => c.level === BK_VERIFY) ? BK_VERIFY : BK_PASS;
  return { checks, worst, canProceed: worst !== BK_BLOCK };
}

// Ask before charging. Returns true when the booking may go ahead.
// A BLOCK has no "continue" button at all — the only way past it is to fix the
// record, which is the point.
async function bookingGatePrompt(payload) {
  const gate = bookingGateFor(payload);
  if (gate.worst === BK_PASS) return true;
  const open = gate.checks.filter(c => c.level !== BK_PASS);
  const blocked = gate.worst === BK_BLOCK;
  const rows = open.map(c => `
    <div class="kc-gate-row ${c.level === BK_BLOCK ? 'is-block' : ''}">
      <div class="kc-gate-text"><strong>${escHtml(c.title)}</strong><br>
        <span style="color:var(--muted);font-size:var(--fs-small);">${escHtml(c.detail)}</span></div>
    </div>`).join('');
  return await kcConfirm({
    title: blocked ? 'This booking cannot go ahead' : 'Before you book', icon: 'passport',
    body: rows + (blocked
      ? '<div style="margin-top:10px;color:var(--muted);font-size:var(--fs-small);">Fix the passport details and try again.</div>'
      : '<div style="margin-top:10px;color:var(--muted);font-size:var(--fs-small);">Booking anyway records that you checked.</div>'),
    okLabel: 'I have checked — book it',
    blocking: blocked,
  });
}

async function saveNewBooking() {
  const paxList = bkPassengers.filter(p => (p.fullName || '').trim());
  paxList.forEach(p => { p.fullName = capName(p.fullName); });
  // Read once: the payload sends it to the server, and the receipt needs it to
  // say HOW they paid. The API answers with paidNow as a boolean and no method,
  // so this is the only place that knows.
  const bkPayment = document.getElementById('bkPay').value;
  const payload = {
    customerId:       document.getElementById('bkCustomer').value,
    passenger:        paxList.map(p => p.fullName).join(', '),
    passengers:       paxList,
    route:            document.getElementById('bkRoute').value.trim(),
    airline:          document.getElementById('bkAirline').value.trim(),
    bookingReference: document.getElementById('bkRef').value.trim(),
    travelDate:       document.getElementById('bkTravelDate').value,
    returnDate:       document.getElementById('bkReturnDate')?.value || '',
    legs:             bkLegs,
    departureTime:    document.getElementById('bkDep').value,
    arrivalTime:      document.getElementById('bkArr').value,
    price:            parseFloat(document.getElementById('bkPrice').value),
    bookingFee:       parseFloat(document.getElementById('bkFee').value) || 0,
    passportOnFile:   document.getElementById('bkPassport').checked,
    passportExpiry:   document.getElementById('bkPassport').checked
                        ? document.getElementById('bkPassportExpiry').value : '',
    payment:          bkPayment,
    checkinBy:        document.getElementById('bkCheckinBy').value,
    checkinDone:      document.getElementById('bkCheckinDone').checked,
    checkinDate:      document.getElementById('bkCheckinBy').value === 'us'
                        ? document.getElementById('bkCheckinDate').value : '',
    returnCheckinDate: document.getElementById('bkCheckinBy').value === 'us'
                        ? (document.getElementById('bkRetCheckinDate')?.value || '') : '',
    notes:            document.getElementById('bkNotes').value.trim(),
  };
  if (!payload.customerId) { toast('Select a customer.', 'error'); return; }
  if (!payload.route)      { toast('Route is required.', 'error'); return; }
  if (!payload.travelDate) { toast('Travel date is required.', 'error'); return; }
  if (payload.returnDate && payload.returnDate < payload.travelDate) {
    toast('The return date is before the outbound date.', 'error'); return;
  }
  if (!Number.isFinite(payload.price) || payload.price < 0) { toast('Enter a valid ticket price.', 'error'); return; }

  // Idempotent booking: one token for this submit (dedupes a retry server-side) and
  // an in-flight guard so a double-click can't create two bookings / two charges.
  payload.clientRef = kcRef();
  const guardKey = 'booking:' + payload.customerId + ':' + payload.route + ':' + payload.travelDate;
  if (!kcBeginWrite(guardKey)) return;
  let res;
  try {
    // Passport questions BEFORE the money question: there is no point
    // confirming a charge for a trip that cannot happen.
    if (!(await bookingGatePrompt(payload))) return;
    const bkCust = customers.find(c => c.id === payload.customerId);
    if (!(await kcConfirm({
      title: 'Confirm booking charge',
      body: `<strong>${bkCust ? escName(bkCust.firstName) + ' ' + escName(bkCust.lastName) : 'Customer'}</strong><br>
        ${escHtml(payload.route)}${payload.airline ? ' · ' + escHtml(payload.airline) : ''} · ${fmtDate(payload.travelDate)}<br>
        Ticket ${fmtGbp(payload.price)}${payload.bookingFee ? ` + fee ${fmtGbp(payload.bookingFee)}` : ''}${payload.payment === 'paid' ? ' · paid now' : ' · on account'}`,
      amount: payload.price + (payload.bookingFee || 0),
      okLabel: 'Charge booking',
    }))) return;
    res = await window.api.addBooking(payload);
  } finally {
    kcEndWrite(guardKey);
  }
  if (!res.success) { toast(res.error || 'Could not save the booking.', 'error'); return; }
  if (res.duplicate) {
    closeDynamicModal();
    if (res.booking && !bookings.some(x => x.id === res.booking.id)) bookings.unshift(res.booking);
    // Same booking, so an email that produced it is still settled by it.
    await tmMarkBooked(res.booking?.id);
    toast('Already booked — no double charge.', 'info');
    renderBookingsTab();
    return;
  }

  bookings.unshift(res.booking);
  await maybeCheckinTask(res.booking);
  // If this booking came off a ticket email, that email is now dealt with and
  // its task closes with it.
  await tmMarkBooked(res.booking.id);
  closeDynamicModal();
  let chargeMsg = '';
  if (res.chargePosted) {
    chargeMsg = res.paidNow
      ? ` ${fmtGbp(res.charged)} paid in full.`
      : ` ${fmtGbp(res.charged)} on account — wallet balance ${fmtGbp(res.balance)}.`;
  }
  if (res.extras?.length) chargeMsg += ` Incl. ${res.extras.map(e => `${e.label} ${fmtGbp(e.amount)}`).join(', ')}.`;
  renderBookingsTab();
  const b = res.booking;
  const bc = customers.find(x => String(x.id) === String(b.customerId));
  showDonePanel({
    title: 'Booking saved', icon: 'plane',
    customerId: b.customerId,
    customerName: bc ? `${bc.firstName || ''} ${bc.lastName || ''}`.trim() : (b.customerName || ''),
    customerPhone: bc?.phone || '',
    summary: `${b.route || ''}${b.airline ? ' · ' + b.airline : ''}${b.travelDate ? ' · ' + fmtDate(b.travelDate) : ''}${b.bookingRef ? ' · ref ' + b.bookingRef : ''}`,
    total: Number.isFinite(res.charged) ? res.charged : b.price,
    payLine: res.chargePosted ? (res.paidNow ? 'paid in full' : 'on account') : 'not charged',
    method: null,
    paidNow: !!res.paidNow,
    lines: [{ name: `Flight ${b.route || ''}${b.travelDate ? ' · ' + fmtDate(b.travelDate) : ''}`, qty: 1, total: Number.isFinite(res.charged) ? res.charged : b.price }],
    // Names and dates are the two things worth checking on the day it is booked
    // — an airline charges to change a name and some will not change one at all
    // — so the email lays them out rather than burying them in a line item.
    receipt: {
      kind: 'booking', ref: String(b.id || ''),
      passenger: b.passenger || '', route: b.route || '', airline: b.airline || '',
      travelDate: b.travelDate || '', returnDate: b.returnDate || '',
      bookingRef: b.bookingRef || '',
      total: Number.isFinite(res.charged) ? res.charged : b.price,
      // A booking payment is all-or-nothing: pages/api/bookings.js posts one
      // payment for the whole total, or none. So paidNow settles the amount and
      // there is no part-paid state to carry here.
      paidAmount: res.paidNow ? (Number.isFinite(res.charged) ? res.charged : b.price) : 0,
      // HOW they paid, which the receipt could not say. The API returns paidNow
      // as a boolean and no method, so this comes from what the form submitted
      // — the same value the ledger row was written with. 'account' is not a
      // payment, so it stays null and the receipt asks for the money instead.
      method: res.paidNow && bkPayment !== 'account' ? bkPayment : null,
    },
    smsText: `Hi${bc?.firstName ? ' ' + bc.firstName : ''}, your flight is booked: ${b.route || ''}${b.travelDate ? ', ' + fmtDate(b.travelDate) : ''}${b.bookingRef ? '. Ref ' + b.bookingRef : ''}. Kosher Connect, 0161 531 1386.`,
    again: { label: 'Another booking', icon: 'plane', sub: bc?.firstName ? `for ${bc.firstName}` : 'new flight', run: () => openNewBookingModal(b.customerId) },
  });
}

// When WE own an unfinished check-in with a date, raise a High task on that
// day so it isn't forgotten. Idempotent-ish: keyed note so re-saves don't
// spam (best-effort — the tasks API dedups on nothing, so we only call this
// on explicit save/toggle).
// A round trip needs TWO reminders. The one nobody was getting is the second:
// the flight home, when the customer is abroad and least able to sort it out
// themselves. `checkin_by` covers both legs — if the shop does check-in, it
// does both — so only the dates and the done flags differ.
//
// Both are keyed (CHECKIN-<id> / CHECKINRET-<id>) so editing a booking three
// times leaves one task per leg rather than three.
async function maybeCheckinTask(b) {
  if (!b || b.checkinBy !== 'us') return;
  const who = (b.customerName || b.passenger || '').trim();
  const legs = [
    { on: b.checkinDate, done: b.checkinDone, ref: `CHECKIN-${b.id}`,
      label: '', flight: b.travelDate },
    { on: b.returnCheckinDate, done: b.returnCheckinDone, ref: `CHECKINRET-${b.id}`,
      label: ' (way back)', flight: b.returnDate },
  ];
  for (const leg of legs) {
    if (!leg.on || leg.done) continue;
    await window.api.addTask({
      title: `🛫 Check in ${who}${leg.label} — ${b.route}`.trim(),
      dueDate: leg.on,
      priority: 'High',
      notes: `Online check-in for flight ${b.route}${b.airline ? ' (' + b.airline + ')' : ''}`
        + `${leg.flight ? ' on ' + fmtDate(leg.flight) : ''}. Booking ref ${b.bookingReference || '—'}.`,
      customerId: b.customerId || null,
      snoozedUntil: leg.on,
      reference: leg.ref,
    }).catch(() => null);
  }
}

async function openCheckinModal(bookingId) {
  const b = bookings.find(x => x.id === bookingId);
  if (!b) return;
  // Pull the full, unmasked passenger details for the check-in itself.
  const detail = await kcFetch('/api/bookings?checkin=' + encodeURIComponent(bookingId))
    .then(r => r.json()).catch(() => null);
  const pax = detail?.success ? (detail.booking.passengers || []) : (b.passengers || []);
  // Each value is a click-to-copy chip (airline forms need them pasted one
  // by one), plus a "Copy all" that grabs the whole passenger block.
  // The copied value defaults to exactly what's shown (WYSIWYG) — pass `raw`
  // only when the copy should differ from the label. Dates therefore copy as
  // the displayed DD/MM/YYYY, never the raw ISO (YYYY-MM-DD).
  const cell = (lbl, val, raw) => val ? `
    <div style="display:flex;align-items:center;gap:6px;">
      <span style="color:var(--muted);">${lbl}:</span>
      <strong class="copy-val" tabindex="0" role="button" title="Click to copy ${lbl}"
        onclick="copyText('${escHtml(String(raw != null ? raw : val)).replace(/'/g, "\\'")}','${lbl}')">${escHtml(val)}</strong>
    </div>` : '';
  const paxAll = (p) => [
    p.fullName && `Name: ${p.fullName}`, p.dob && `DOB: ${fmtDate(p.dob)}`, p.nationality && `Nationality: ${p.nationality}`,
    p.passportNumber && `Passport: ${p.passportNumber}`, p.passportExpiry && `Expiry: ${fmtDate(p.passportExpiry)}`,
    p.passportIssueDate && `Issued: ${fmtDate(p.passportIssueDate)}`, p.issuingCountry && `Issuing country: ${p.issuingCountry}`,
  ].filter(Boolean).join('\n');
  const paxHtml = pax.length ? `
    <div class="section-divider" style="margin:4px 0 8px;">Passenger details <span style="color:var(--muted);font-weight:400;font-size:var(--fs-micro);">— click any value to copy</span></div>
    <div style="max-height:260px;overflow-y:auto;margin-bottom:12px;">
      ${pax.map((p, i) => `
        <div style="border:1px solid var(--border);border-radius:8px;padding:8px 10px;margin-bottom:8px;font-size:var(--fs-small);line-height:1.7;">
          <div style="display:flex;justify-content:space-between;align-items:center;">
            <strong class="copy-val" tabindex="0" role="button" style="font-size:var(--fs-body);" title="Click to copy name" onclick="copyText('${escJs(p.fullName || '')}','name')">${escName(p.fullName || '(no name)')}</strong>
            <button type="button" class="btn btn-outline btn-sm kc-ic kc-ic-clipboard" style="font-size:var(--fs-micro);padding:3px 10px;"
              onclick="copyText(paxCopyBlocks[${i}],'all details')">Copy all</button>
          </div>
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:2px 16px;margin-top:4px;">
            ${cell('DOB', p.dob && fmtDate(p.dob))}
            ${cell('Nationality', p.nationality)}
            ${cell('Passport №', p.passportNumber)}
            ${cell('Expiry', p.passportExpiry && fmtDate(p.passportExpiry))}
            ${cell('Issued', p.passportIssueDate && fmtDate(p.passportIssueDate))}
            ${cell('Issuing country', p.issuingCountry)}
          </div>
          ${(!p.passportNumber && !p.dob) ? '<div class="kc-ic kc-ic-alert" style="color:var(--warning);margin-top:4px;">Missing details — open <i class="kc-ic kc-ic-users" aria-hidden="true"></i> Passengers to fill them in.</div>' : ''}
        </div>`).join('')}
    </div>` : `<div style="font-size:var(--fs-small);color:var(--muted);margin-bottom:12px;">No passenger details yet — add them via the <i class="kc-ic kc-ic-users" aria-hidden="true"></i> button.</div>`;
  // Stash the copy-all text keyed by index (avoids quoting a multi-line
  // string into an inline handler).
  window.paxCopyBlocks = pax.map(paxAll);
  showDynamicModal(`
    <div class="modal-title kc-ic kc-ic-takeoff">Check-in — ${escHtml(b.route)} ${b.travelDate ? fmtDate(b.travelDate) : ''}</div>
    ${paxHtml}
    <div class="form-grid">
      <div class="form-group">
        <label class="form-label">Who checks in?</label>
        <select class="form-input" id="ciBy" onchange="ciToggle(this.value)">
          <option value="customer" ${b.checkinBy !== 'us' ? 'selected' : ''}>Customer does it</option>
          <option value="us" ${b.checkinBy === 'us' ? 'selected' : ''}>We do it</option>
        </select>
      </div>
      <div class="form-group" id="ciDateWrap" style="display:${b.checkinBy === 'us' ? 'block' : 'none'};">
        <label class="form-label">${b.returnDate ? 'Outbound — do it on' : 'Do it on'}</label>
        <input class="form-input" type="date" id="ciDate" value="${escHtml(b.checkinDate || '')}">
      </div>
      <div class="form-group form-full">
        <label style="display:flex;align-items:center;gap:8px;font-size:var(--fs-ui);cursor:pointer;">
          <input type="checkbox" id="ciDone" ${b.checkinDone ? 'checked' : ''}>
          <i class="kc-ic kc-ic-check" aria-hidden="true"></i> ${b.returnDate ? 'Outbound check-in is done' : 'Check-in is done'}
        </label>
      </div>
      ${b.returnDate ? `
      <div class="form-group" id="ciRetDateWrap" style="display:${b.checkinBy === 'us' ? 'block' : 'none'};">
        <label class="form-label kc-ic kc-ic-undo">Way back (${escHtml(fmtDate(b.returnDate))}) — do it on</label>
        <input class="form-input" type="date" id="ciRetDate" value="${escHtml(b.returnCheckinDate || '')}">
      </div>
      <div class="form-group form-full">
        <label style="display:flex;align-items:center;gap:8px;font-size:var(--fs-ui);cursor:pointer;">
          <input type="checkbox" id="ciRetDone" ${b.returnCheckinDone ? 'checked' : ''}>
          <i class="kc-ic kc-ic-check" aria-hidden="true"></i> Return check-in is done
        </label>
      </div>` : ''}
    </div>
    <div class="modal-actions">
      <button class="btn btn-outline" onclick="closeDynamicModal()">Cancel</button>
      <button class="btn btn-primary" onclick="saveCheckin('${escHtml(bookingId)}')">Save</button>
    </div>
  `);
}

// Both date fields belong to the same decision — who does the check-in.
function ciToggle(by) {
  for (const id of ['ciDateWrap', 'ciRetDateWrap']) {
    const el = document.getElementById(id);
    if (el) el.style.display = by === 'us' ? 'block' : 'none';
  }
}

async function saveCheckin(bookingId) {
  const by = document.getElementById('ciBy').value;
  const retDate = document.getElementById('ciRetDate');
  const retDone = document.getElementById('ciRetDone');
  const res = await window.api.updateBooking({
    id: bookingId,
    checkinBy: by,
    checkinDone: document.getElementById('ciDone').checked,
    checkinDate: by === 'us' ? document.getElementById('ciDate').value : '',
    ...(retDate ? {
      returnCheckinDate: by === 'us' ? retDate.value : '',
      returnCheckinDone: !!(retDone && retDone.checked),
    } : {}),
  });
  if (!res.success) { toast(res.error || 'Could not save check-in.', 'error'); return; }
  const idx = bookings.findIndex(x => x.id === bookingId);
  if (idx !== -1) bookings[idx] = res.booking;
  await maybeCheckinTask(res.booking);
  closeDynamicModal();
  toast('Check-in updated.', 'success');
  renderBookingsTab();
}

// Small status chip for a booking's check-in state.
function checkinChip(b) {
  // Icons, not glyphs — the chip's three states are drawn with the same masks
  // as the rest of the app (26 Aug: the done state had been converted, these
  // two had not, so one control was speaking in two alphabets). The task
  // maybeCheckinTask() raises keeps its 🛫: that string is a tasks.title in the
  // database, and a CSS class in a text column paints nothing.
  //
  // A round trip is two check-ins. "In" on a booking with the flight home
  // still to do would be the app saying the job is finished when it is half
  // finished — so the return only disappears from the chip once it is done too.
  const twoLegs = !!b.returnDate;
  const outDone = !!b.checkinDone;
  const backDone = !twoLegs || !!b.returnCheckinDone;

  if (outDone && backDone) return `<span class="badge badge-active kc-ic kc-ic-check" title="Check-in done${twoLegs ? ', both ways' : ''}">In${twoLegs ? ' ×2' : ''}</span>`;
  if (b.checkinBy === 'us') {
    const next = !outDone ? b.checkinDate : b.returnCheckinDate;
    const which = !outDone ? '' : ' back';
    return `<span class="badge badge-rental kc-ic kc-ic-takeoff" title="We check in${next ? ' on ' + fmtDate(next) : ''}${twoLegs ? ` · out ${outDone ? 'done' : 'to do'}, back ${backDone ? 'done' : 'to do'}` : ''}">us${which}${next ? ' ' + fmtDate(next).slice(0, 5) : ''}</span>`;
  }
  if (b.checkinBy === 'customer') return `<span class="badge kc-ic kc-ic-user" style="background:rgba(148,163,184,0.15);color:var(--muted);" title="Customer checks in">cust</span>`;
  return `<span class="badge" style="background:rgba(234,179,8,0.15);color:var(--warning-ink);" title="Check-in not set">?</span>`;
}

async function changeBookingStatus(id, status) {
  const res = await window.api.updateBooking({ id, status });
  if (!res.success) { toast(res.error || 'Could not update status.', 'error'); renderBookingsTab(); return; }
  const idx = bookings.findIndex(b => b.id === id);
  if (idx !== -1) bookings[idx] = res.booking;
  renderBookingsTab();
  toast(`Booking marked ${status}.`, 'success');
}

// Open a booking to edit its flight details. Money (price + fee) is shown
// read-only — corrections go through a wallet adjustment so the ledger
// stays honest. Passengers and check-in have their own dedicated editors.
// Delete a booking outright — for rows that should never have existed
// (imported junk, duplicates, typos). Real charged bookings are protected:
// the server refuses when wallet charges are linked and points at Cancelled,
// which reverses the money. Same undo-toast pattern as deletePhone: the row
// vanishes immediately, the server delete waits out the undo window.
function deleteBookingRow(id) {
  const idx = bookings.findIndex(x => x.id === id);
  const b = bookings[idx];
  if (!b) return;
  const putBack = () => {
    bookings.splice(Math.min(idx, bookings.length), 0, b);
    if (currentTab === 'bookings') renderBookingsTab();
  };
  bookings.splice(idx, 1);
  if (currentTab === 'bookings') renderBookingsTab();
  kcUndoable({
    label: `Booking ${b.route || ''} deleted.`.replace('  ', ' '),
    restore: putBack,
    commit: async () => {
      const res = await window.api.deleteBooking(id);
      if (!res || !res.success) {
        toast((res && res.error) || 'Could not delete the booking.', 'error');
        putBack();
      }
    },
  });
}

function openEditBookingModal(id) {
  const b = bookings.find(x => x.id === id);
  if (!b) return;
  ebLegs = Array.isArray(b.legs) ? b.legs.map(l => ({ ...l })) : [];
  showDynamicModal(`
    <div class="modal-title kc-ic kc-ic-plane">${custNameLink(b.customerId, escName(b.customerName || 'Booking'))} — ${escHtml(b.route || '')}</div>
    <div class="form-grid">
      <div class="form-group form-full">
        <label class="form-label">Passenger(s) summary</label>
        <input class="form-input" id="ebPassenger" value="${escName(b.passenger || '')}" placeholder="Names">
      </div>
      <div class="form-group"><label class="form-label">Route *</label>
        <input class="form-input" id="ebRoute" value="${escHtml(b.route || '')}"></div>
      <div class="form-group"><label class="form-label">Airline</label>
        <input class="form-input" id="ebAirline" value="${escHtml(b.airline || '')}"></div>
      <div class="form-group"><label class="form-label">Booking reference</label>
        <input class="form-input" id="ebRef" value="${escHtml(b.bookingReference || '')}"></div>
      <div class="form-group"><label class="form-label">Travel date</label>
        <input class="form-input" type="date" id="ebTravel" value="${escHtml(b.travelDate || '')}"></div>
      <div class="form-group"><label class="form-label">Return date <span style="color:var(--muted);font-weight:400;">(round trip only)</span></label>
        <input class="form-input" type="date" id="ebReturn" value="${escHtml(b.returnDate || '')}"></div>
      <div class="form-group"><label class="form-label">Departure / Arrival</label>
        <div style="display:flex;gap:6px;">
          <input class="form-input" type="time" id="ebDep" value="${escHtml(b.departureTime || '')}">
          <input class="form-input" type="time" id="ebArr" value="${escHtml(b.arrivalTime || '')}">
        </div></div>
      <div class="form-group"><label class="form-label">Status</label>
        <select class="form-input" id="ebStatus">
          ${BOOKING_STATUSES.map(s => `<option value="${s}" ${b.status === s ? 'selected' : ''}>${s === 'Completed' ? 'Completed / Flown' : s}</option>`).join('')}
        </select></div>
      <div class="form-group"><label class="form-label">Passport photocopy held?</label>
        <div style="display:flex;gap:8px;align-items:center;">
          <input type="checkbox" id="ebPassport" ${b.passportOnFile ? 'checked' : ''}
            onchange="document.getElementById('ebPExpWrap').style.display=this.checked?'block':'none'">
          <div id="ebPExpWrap" style="display:${b.passportOnFile ? 'block' : 'none'};flex:1;">
            <input class="form-input" type="date" id="ebPExp" value="${escHtml(b.passportExpiry || '')}" title="Passport expiry">
          </div>
        </div></div>
      ${bkLegBlockHtml('ebLegs', 'ebLegEditor')}
      <div class="form-group form-full"><label class="form-label">Notes</label>
        <textarea class="form-input" id="ebNotes" rows="2">${escHtml(b.notes || '')}</textarea></div>
    </div>
    <div style="margin-top:8px;padding:10px;border-radius:8px;background:var(--bg-secondary);font-size:var(--fs-small);color:var(--muted);"><i class="kc-ic kc-ic-pound" aria-hidden="true"></i> Price <strong>${fmtGbp((b.price || 0))}</strong> + fee <strong>${fmtGbp((b.bookingFee || 0))}</strong> (read-only — adjust money via the customer's wallet).
      &nbsp;·&nbsp; <a href="#" onclick="closeDynamicModal();openPassengersModal('${escHtml(b.id)}');return false;"><i class="kc-ic kc-ic-users" aria-hidden="true"></i> Passengers</a>
      &nbsp;·&nbsp; <a href="#" onclick="closeDynamicModal();openCheckinModal('${escHtml(b.id)}');return false;"><i class="kc-ic kc-ic-takeoff" aria-hidden="true"></i> Check-in</a>
      &nbsp;·&nbsp; <a href="#" onclick="closeDynamicModal();openTravelReqModal('${escHtml(b.id)}');return false;"><i class="kc-ic kc-ic-passport" aria-hidden="true"></i> Travel requirements</a>
    </div>
    <div class="modal-actions" style="justify-content:space-between;">
      <button class="btn btn-outline kc-ic kc-ic-trash" style="color:var(--danger);border-color:color-mix(in srgb, var(--danger) 40%, var(--border));"
        onclick="closeDynamicModal();deleteBookingRow('${escHtml(b.id)}')">Delete</button>
      <span class="modal-actions-group">
        <button class="btn btn-outline" onclick="closeDynamicModal()">Cancel</button>
        <button class="btn btn-primary kc-ic kc-ic-save" onclick="saveEditBooking('${escHtml(b.id)}')">Save</button>
      </span>
    </div>
  `);
}

async function saveEditBooking(id) {
  const route = document.getElementById('ebRoute').value.trim();
  if (!route) { toast('Route is required.', 'error'); return; }
  const passportOnFile = document.getElementById('ebPassport').checked;
  const res = await window.api.updateBooking({
    id,
    passenger: document.getElementById('ebPassenger').value.trim(),
    route,
    airline: document.getElementById('ebAirline').value.trim(),
    bookingReference: document.getElementById('ebRef').value.trim(),
    travelDate: document.getElementById('ebTravel').value,
    returnDate: document.getElementById('ebReturn')?.value || '',
    legs: ebLegs,
    departureTime: document.getElementById('ebDep').value,
    arrivalTime: document.getElementById('ebArr').value,
    status: document.getElementById('ebStatus').value,
    passportOnFile,
    passportExpiry: passportOnFile ? document.getElementById('ebPExp').value : '',
    notes: document.getElementById('ebNotes').value.trim(),
  });
  if (!res.success) { toast(res.error || 'Could not save the booking.', 'error'); return; }
  const idx = bookings.findIndex(x => x.id === id);
  if (idx !== -1) bookings[idx] = res.booking;
  closeDynamicModal();
  toast('Booking updated.', 'success');
  renderBookingsTab();
}

// ─────────────────────────────────────────────
//  TRAVEL REQUIREMENTS  (🛂)
// ─────────────────────────────────────────────
// Per-booking panel: for each passenger, what entry authorisation is needed
// (ESTA / eTA / ETA-IL / visa / none) given their nationality + the trip's
// destination, whether the passport is valid long enough, and whether a
// recorded authorisation covers the trip. The rules run server-side
// (lib/travelRules.mjs) — this only renders. Actions are DIY: an official
// link + a draft message for the customer. GUIDANCE ONLY — the panel always
// tells staff to confirm on the official site.

const KC_DEST_NAMES = { US: 'USA', IL: 'Israel', CA: 'Canada', EU: 'Europe (Schengen)', UK: 'United Kingdom' };
const KC_RECORDABLE = new Set(['ESTA', 'ETA_CA', 'ETA_IL', 'ETIAS', 'ETA_UK']);

// Badge text colour is ALWAYS a token, never a literal — a literal cannot flip
// for the dark theme, and a translucent wash over a dark card leaves dark text
// on a dark background. These five chips were #07639e (2.32:1 in dark) and the
// CHECK chip's brown-on-cream missed AA in *light* too, at 3.97:1 on 11px text.
function travelReqBadge(code, label) {
  const styles = {
    ESTA:   'background:rgba(7,99,158,0.14);color:var(--accent);',
    ETA_CA: 'background:rgba(7,99,158,0.14);color:var(--accent);',
    ETA_IL: 'background:rgba(7,99,158,0.14);color:var(--accent);',
    ETIAS:  'background:rgba(7,99,158,0.14);color:var(--accent);',
    ETA_UK: 'background:rgba(7,99,158,0.14);color:var(--accent);',
    VISA:   'background:rgba(239,68,68,0.14);color:var(--danger-ink);',
    NONE:   'background:rgba(34,197,94,0.15);color:var(--success-ink);',
    CHECK:  'background:var(--canvas-cream);color:var(--gold);',
  };
  return `<span class="badge" style="${styles[code] || styles.CHECK}">${escHtml(label)}</span>`;
}

async function openTravelReqModal(bookingId) {
  const res = await window.api.getTravelReqView(bookingId).catch(() => null);
  if (!res || !res.success) {
    toast((res && res.error) || 'Could not load travel requirements.', 'error');
    return;
  }
  const destSel = ['', 'US', 'IL', 'CA', 'EU', 'UK'].map(code =>
    `<option value="${code}" ${res.destination === code ? 'selected' : ''}>${code ? KC_DEST_NAMES[code] : '— choose destination —'}</option>`
  ).join('');
  const destName = KC_DEST_NAMES[res.destination] || '';

  const paxHtml = (res.passengers || []).filter(p => p.name).map((p, i) => {
    const r = p.requirement || {};
    const cov = p.coverage || {};
    const auth = (res.authorisations || []).find(a =>
      a.travellerName.trim().toLowerCase() === p.name.trim().toLowerCase() && a.type === r.code);
    // passport readiness line
    let pass = '';
    if (p.passport.ok === true) pass = `<span style="color:var(--success);">✓ Passport valid long enough</span>`;
    else if (p.passport.ok === false) pass = `<span class="kc-ic kc-ic-alert" style="color:var(--danger-ink);">${escHtml(p.passport.note)}</span>`;
    else pass = `<span style="color:var(--muted);">Passport expiry not on file</span>`;

    // coverage + actions
    let cover = '';
    const validity = r.validityMonths ? ` · valid ~${Math.round(r.validityMonths / 12)} yr${r.validityMonths >= 24 ? 's' : ''}` : '';
    const link = r.url ? `<a href="${escHtml(r.url)}" target="_blank" rel="noopener">Open official site</a>` : '';
    const draftBtn = r.code !== 'NONE'
      ? `<a href="#" onclick="copyTravelDraft(${JSON.stringify(destName)},${JSON.stringify(r.label)},${JSON.stringify(r.url || '')});return false;"><i class="kc-ic kc-ic-mail" aria-hidden="true"></i> Copy draft for customer</a>` : '';

    if (cov.status === 'not-needed') {
      cover = `<div style="color:var(--success);font-size:var(--fs-body);">No entry authorisation needed — passport only.</div>`;
    } else if (cov.status === 'check') {
      cover = `<div style="font-size:var(--fs-body);color:var(--gold);">${escHtml(r.note || 'Confirm the requirement on the official site before travel.')} ${link}</div>`;
    } else if (KC_RECORDABLE.has(r.code)) {
      const covLine = cov.status === 'covered'
        ? `<span style="color:var(--success);">✓ ${escHtml(r.label)} on file — valid until ${escHtml(cov.validUntil || '')}</span>`
        : cov.status === 'expiring'
          ? `<span class="kc-ic kc-ic-alert" style="color:var(--gold);">${escHtml(r.label)} ${cov.expiresDuringTrip ? 'runs out WHILE THEY ARE AWAY' : cov.expiresBeforeTravel ? 'expires BEFORE this trip' : 'expiring soon'} — valid until ${escHtml(cov.validUntil || '')}</span>`
          : `<span style="color:var(--danger-ink);">Not recorded yet — ${escHtml(r.label)} needed${validity}</span>`;
      cover = `
        <div style="font-size:var(--fs-body);margin-bottom:6px;">${covLine}</div>
        <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;">
          <input class="form-input" id="traUntil_${i}" type="date" value="${escHtml(auth ? auth.validUntil : '')}" title="Approved until" style="width:150px;">
          <input class="form-input" id="traRef_${i}" value="${escHtml(auth ? auth.reference : '')}" placeholder="Reference no." style="width:150px;">
          <button class="btn btn-outline btn-sm" style="font-size:var(--fs-small);padding:4px 10px;"
            onclick="recordTravelAuth('${escHtml(bookingId)}','${escHtml(res.customerId)}',${i},${JSON.stringify(p.name)},'${r.code}','${escHtml(res.destination)}')">
            ${auth ? 'Update' : 'Record'} approved-until</button>
          ${auth ? `<button class="btn btn-outline btn-sm" style="font-size:var(--fs-small);padding:4px 10px;color:var(--danger-ink);" onclick="deleteTravelAuthRow('${escHtml(bookingId)}','${escHtml(auth.id)}')">Remove</button>` : ''}
        </div>
        <div style="font-size:var(--fs-small);margin-top:6px;">${link} ${link && draftBtn ? '&nbsp;·&nbsp;' : ''} ${draftBtn}</div>`;
    } else {
      cover = `<div style="font-size:var(--fs-body);">${link} ${draftBtn}</div>`;
    }

    return `
      <div style="border:1px solid var(--border);border-radius:10px;padding:12px;margin-bottom:10px;">
        <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:6px;">
          <strong>${escHtml(p.name)}</strong>
          <span style="font-size:var(--fs-small);color:var(--muted);">${escHtml(p.nationality || 'nationality not set')}</span>
        </div>
        <div style="margin-bottom:6px;">${travelReqBadge(r.code, r.label)}${r.note && cov.status !== 'check' ? `<span style="font-size:var(--fs-small);color:var(--muted);margin-left:8px;">${escHtml(r.note)}</span>` : ''}</div>
        <div style="font-size:var(--fs-body);margin-bottom:8px;">${pass}</div>
        ${cover}
      </div>`;
  }).join('');

  showDynamicModal(`
    <div class="modal-title kc-ic kc-ic-passport">Travel requirements${res.route ? ` — ${escHtml(res.route)}` : ''}</div>
    <div class="form-group form-full">
      <label class="form-label">Destination</label>
      <select class="form-input" onchange="saveBookingDestination('${escHtml(bookingId)}', this.value)">${destSel}</select>
    </div>
    ${!res.destination ? `<div style="color:var(--muted);font-size:var(--fs-body);margin:6px 0 4px;">Choose the destination to see what each passenger needs.</div>` : ''}
    ${res.destination && !paxHtml ? `<div style="color:var(--muted);font-size:var(--fs-body);margin:6px 0;">No passengers on this booking yet — add them under <i class="kc-ic kc-ic-users" aria-hidden="true"></i> Passengers.</div>` : ''}
    <div style="margin-top:10px;">${paxHtml}</div>
    <div style="font-size:var(--fs-small);color:var(--muted);background:var(--bg-secondary);border-radius:8px;padding:8px 10px;margin-top:4px;">
      <i class="kc-ic kc-ic-help" aria-hidden="true"></i> Guidance based on the rules we've set for common routes — <strong>always confirm on the official site</strong> before travel. Requirements can change.
    </div>
    <div class="modal-actions">
      <button class="btn btn-primary" onclick="closeDynamicModal();openEditBookingModal('${escHtml(bookingId)}')">← Back to booking</button>
    </div>
  `);
}

async function saveBookingDestination(bookingId, value) {
  const res = await window.api.updateBooking({ id: bookingId, destinationCountry: value });
  if (!res.success) { toast(res.error || 'Could not save destination.', 'error'); return; }
  const idx = bookings.findIndex(x => x.id === bookingId);
  if (idx !== -1) bookings[idx] = res.booking;
  openTravelReqModal(bookingId);
}

async function recordTravelAuth(bookingId, customerId, i, name, type, country) {
  const validUntil = document.getElementById(`traUntil_${i}`)?.value || '';
  const reference = document.getElementById(`traRef_${i}`)?.value.trim() || '';
  if (!validUntil) { toast('Enter the “approved until” date.', 'error'); return; }
  const res = await window.api.saveTravelAuth({ customerId, travellerName: name, type, country, validUntil, reference });
  if (!res.success) { toast(res.error || 'Could not save the record.', 'error'); return; }
  toast('Saved ✓', 'success');
  openTravelReqModal(bookingId);
}

async function deleteTravelAuthRow(bookingId, id) {
  if (!(await kcConfirm({
    title: 'Remove this recorded authorisation?',
    body: 'It comes off this booking.',
    okLabel: 'Remove',
    danger: true,
  }))) return;
  const res = await window.api.deleteTravelAuth(id);
  if (!res.success) { toast(res.error || 'Could not remove it.', 'error'); return; }
  toast('Removed.', 'success');
  openTravelReqModal(bookingId);
}

function copyTravelDraft(destName, label, url) {
  const lines = [
    `Hi,`,
    ``,
    `For your trip${destName ? ` to ${destName}` : ''} you'll need ${label} before you travel.`,
    url ? `You can apply here (official site): ${url}` : `Please apply on the official government site before you travel.`,
    `It usually only takes a few minutes. Once it's approved, please let us know.`,
    ``,
    `Thank you,`,
    `Kosher Connect`,
  ];
  const text = lines.join('\n');
  navigator.clipboard.writeText(text).then(
    () => toast('Draft copied — paste it to the customer.', 'success'),
    () => toast('Could not copy — select and copy manually.', 'error'),
  );
}

// ─────────────────────────────────────────────
//  REPAIRS
// ─────────────────────────────────────────────
// Tables-native. Prices freeze into the ticket at open time; the wallet
// charge (REPAIR-<id>) posts once, when the repair is marked Collected.

let repairs = [];
let repairMenu = [];
// Mirrors lib/repairStatuses.mjs — change both together.
// Five system statuses that carry behaviour (Collected charges the wallet,
// Cancelled closes without charging, Ready drives the collection prompt) plus
// the owner's own stages from Settings, which sit where a repair really waits:
// after someone has looked at it, before it is done. A custom stage counts as
// an OPEN job everywhere for free, because every open-test in this file asks
// "not Collected and not Cancelled".
const SYSTEM_REPAIR_STATUSES = ['Open', 'In Progress', 'Ready', 'Collected', 'Cancelled'];
function repairStages() {
  const s = pricingConfig?.settings?.find(x => x.key === 'repair_stages');
  const isSystem = (n) => SYSTEM_REPAIR_STATUSES.some(x => x.toLowerCase() === String(n).trim().toLowerCase());
  return String(s?.textValue || '').split(',').map(x => x.trim()).filter(x => x && !isSystem(x));
}
function repairStatuses() {
  const custom = repairStages();
  return ['Open', 'In Progress', ...custom, 'Ready', 'Collected', 'Cancelled'];
}

function repairStatusBadge(status) {
  const styles = {
    // Was #4434d4 on a 45% lavender wash — 1.39:1 in dark, effectively invisible.
    'Open':        'background:rgba(0,96,168,0.10);color:var(--accent);',
    'In Progress': 'background:var(--canvas-cream);color:var(--gold);',
    'Ready':       'background:rgba(124,58,237,0.13);color:var(--vn);',
    'Collected':   'background:rgba(34,197,94,0.15);color:var(--success-ink);',
    'Cancelled':   'background:rgba(239,68,68,0.15);color:var(--danger-ink);',
  };
  // An owner-added stage gets its own neutral badge rather than borrowing
  // Open's blue — two different states that look identical are worse than one
  // that looks unfamiliar.
  const custom = 'background:rgba(148,163,184,0.18);color:var(--muted);';
  return `<span class="badge" style="${styles[status] || custom}">${escHtml(status)}</span>`;
}

async function renderRepairsTab() {
  const content = document.getElementById('mainContent');
  kcSkeleton('repairs');
  try {
    [repairs, repairMenu] = await Promise.all([
      window.api.getRepairs(),
      window.api.getServiceMenu('repair'),
    ]);
  } catch { content.innerHTML = errorHtml('Couldn’t load repairs'); return; }
  if (!Array.isArray(repairs)) repairs = [];

  const open = repairs.filter(r => r.status === 'Open' || r.status === 'In Progress');
  const ready = repairs.filter(r => r.status === 'Ready');
  const revenue = repairs.filter(r => r.status === 'Collected').reduce((s, r) => s + (r.total || 0), 0);

  const repBar = kcFilterSort('repairs', [
    { value: 'all', label: 'Filter: all tickets' },
    { value: 'active', label: 'Open / in progress', icon: 'wrench', test: r => r.status === 'Open' || r.status === 'In Progress' },
    { value: 'ready', label: 'Waiting for collection', icon: 'package', test: r => r.status === 'Ready' },
    { value: 'collected', label: '✓ Collected', test: r => r.status === 'Collected' },
    { value: 'cancelled', label: '✕ Cancelled', test: r => r.status === 'Cancelled' },
  ], [
    { value: 'recent', label: 'Sort: Recently opened', cmp: kcCmpDate(r => r.openedAt || '', -1) },
    { value: 'oldest', label: 'Oldest first', cmp: kcCmpDate(r => r.openedAt || '', 1) },
    { value: 'name', label: 'Customer A–Z', cmp: kcCmpStr(r => r.customerName) },
    { value: 'total', label: 'Total (high–low)', cmp: kcCmpNum(r => r.total || 0) },
    { value: 'status', label: 'Status', cmp: kcCmpStr(r => r.status) },
  ], renderRepairsTab);
  const shown = kcViewApply('repairs', repairs);
  const emptyMsg = repairs.length ? 'No repairs match this filter.' : 'No repairs yet.';
  const rows = shown.length === 0
    ? `<tr><td colspan="7"><div class="empty-state"><div class="emoji kc-ic kc-ic-wrench"></div><p>${emptyMsg}</p><small>${repairs.length ? 'Change the filter above.' : 'Click "New repair" to open the first ticket.'}</small>${kcClearFiltersBtn('repairs')}</div></td></tr>`
    : shown.map(r => `
      <tr>
        <td><div class="customer-name">${custNameLink(r.customerId, escName(r.customerName || '—'))}</div></td>
        <td>${escHtml(r.device || '—')}${r.kcPurchase ? ' <span class="badge" style="background:rgba(0, 96, 168,0.1);color:var(--accent);font-size:var(--fs-micro);">KC phone</span>' : ''}</td>
        <td style="font-size:var(--fs-small);">${r.services.map(s => escHtml(s.name)).join('<br>') || '—'}</td>
        <td><strong>${fmtGbp((r.total || 0))}</strong></td>
        ${/* The only date a repair row carries is the day it came in, and that
               IS the one said at the counter — "you brought it in on…". */''}
        <td class="kc-date">${r.openedAt ? fmtDateHeb(r.openedAt) : '—'}</td>
        <td>${repairStatusBadge(r.status)}</td>
        <td style="white-space:nowrap;">
          ${r.status === 'Ready' ? `<button class="action-btn kc-ic kc-ic-chat" onclick="openRepairSmsModal('${escHtml(r.id)}')" title="Ready-to-collect message"></button>
          <button class="action-btn kc-ic kc-ic-email" onclick="emailRepairReady(this, '${escHtml(r.id)}')" title="Email: ready to collect"></button>` : ''}
          <button class="action-btn kc-ic kc-ic-clock" onclick="openRemindModal('repair','${escHtml(r.id)}')" title="Remind me"></button>
          <select class="form-input" style="width:120px;padding:5px 8px;font-size:var(--fs-small);"
            aria-label="Status for ${escHtml([r.customerName, r.device].filter(Boolean).join(' — ') || 'this repair')}"
            onchange="changeRepairStatus('${escHtml(r.id)}', this.value)">
            ${repairStatuses().map(s => `<option value="${s}" ${r.status === s ? 'selected' : ''}>${s}</option>`).join('')}
          </select>
        </td>
      </tr>`).join('');

  content.innerHTML = `
    <div class="stats-row">
      <div class="stat-card"><div class="stat-label">Open tickets</div><div class="stat-value">${open.length}</div></div>
      <div class="stat-card"><div class="stat-label">Ready to collect</div><div class="stat-value">${ready.length}</div></div>
      <div class="stat-card"><div class="stat-label">Repairs revenue</div><div class="stat-value">${fmtGbp(revenue)}</div></div>
      <div class="stat-card"><div class="stat-label">Total tickets</div><div class="stat-value">${repairs.length}</div></div>
    </div>
    <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:12px;flex-wrap:wrap;">
      ${repBar}
    </div>
    <div class="table-card">
      <table>
        <thead><tr>
          <th>Customer</th><th>Device</th><th>Services</th><th>Total</th><th>Opened</th><th>Status</th><th></th>
        </tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>`;
}

function openNewRepairModal(preselectCustomerId = null) {
  const serviceChecks = repairMenu.map(m => `
    <label style="display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid var(--border);font-size:var(--fs-body);cursor:pointer;">
      <input type="checkbox" class="rpService" value="${escHtml(m.id)}"
        data-price="${m.price}" data-reg="${m.price}" data-kc="${m.kcPrice ?? ''}"
        onchange="updateRepairTotal()">
      <span style="flex:1;">${escHtml(m.name)}</span>
      <strong class="rpPriceLbl">${fmtGbp(m.price)}</strong>
    </label>`).join('');
  showDynamicModal(`
    <div class="modal-title kc-ic kc-ic-wrench">New repair</div>
    <div class="form-grid">
      <div class="form-group form-full">
        <label class="form-label">Customer *</label>
        ${customerPicker('rpCustomer', { selected: preselectCustomerId })}
      </div>
      <div class="form-group form-full">
        <label class="form-label">Device</label>
        <input class="form-input" id="rpDevice" placeholder="e.g. QIN F21, black">
      </div>
      <div class="form-group form-full" style="flex-direction:row;align-items:center;gap:10px;">
        <input type="checkbox" id="rpKC" onchange="rpKCToggle()"
          style="cursor:pointer;accent-color:var(--accent);">
        <label for="rpKC" style="font-size:var(--fs-body);cursor:pointer;"><i class="kc-ic kc-ic-tag" aria-hidden="true"></i> Phone purchased at Kosher Connect — discounted prices
        </label>
      </div>
      <div class="form-group form-full">
        <label class="form-label">Services * <span style="color:var(--muted);font-weight:400;">(prices frozen at open)</span></label>
        <div style="max-height:220px;overflow-y:auto;padding:0 4px;">${serviceChecks ||
          '<div style="color:var(--muted);font-size:var(--fs-body);">Price list unavailable.</div>'}</div>
      </div>
      <div class="form-group form-full">
        <label class="form-label">Notes</label>
        <input class="form-input" id="rpNotes">
      </div>
    </div>
    <div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px;">
      <div style="font-size:var(--fs-ui);" role="status">Total: <strong id="rpTotal" style="color:var(--success);">£0.00</strong>
        <span style="color:var(--muted);font-size:var(--fs-micro);">— charged to wallet on collection</span></div>
      <div class="modal-actions" style="margin:0;">
        <button class="btn btn-outline" onclick="closeDynamicModal()">Cancel</button>
        <button class="btn btn-primary kc-ic kc-ic-wrench" onclick="saveNewRepair()">Open ticket</button>
      </div>
    </div>
  `);
}

function updateRepairTotal() {
  const total = [...document.querySelectorAll('.rpService:checked')]
    .reduce((s, el) => s + (parseFloat(el.dataset.price) || 0), 0);
  document.getElementById('rpTotal').textContent = `${fmtGbp(total)}`;
}

// Swap the whole menu between regular and "Purchased at KC" prices. Jobs
// without a KC tier (e.g. FIG Touch Mini) keep the regular price.
function rpKCToggle() {
  const kc = document.getElementById('rpKC')?.checked;
  document.querySelectorAll('.rpService').forEach(el => {
    const useKc = kc && el.dataset.kc !== '';
    el.dataset.price = useKc ? el.dataset.kc : el.dataset.reg;
    const lbl = el.parentElement.querySelector('.rpPriceLbl');
    if (lbl) {
      const eff = parseFloat(el.dataset.price) || 0;
      const reg = parseFloat(el.dataset.reg) || 0;
      lbl.innerHTML = useKc
        ? `<span style="color:var(--muted);text-decoration:line-through;font-weight:400;">${fmtGbp(reg)}</span> ${fmtGbp(eff)}`
        : `${fmtGbp(reg)}`;
    }
  });
  updateRepairTotal();
}

async function saveNewRepair() {
  const customerId = document.getElementById('rpCustomer').value;
  const serviceIds = [...document.querySelectorAll('.rpService:checked')].map(el => el.value);
  if (!customerId) { toast('Select a customer.', 'error'); return; }
  if (!serviceIds.length) { toast('Pick at least one service.', 'error'); return; }
  const rpCust = customers.find(c => c.id === customerId);
  const rpTotal = [...document.querySelectorAll('.rpService:checked')]
    .reduce((s, el) => s + (parseFloat(el.dataset.price) || 0), 0);
  if (!(await kcConfirm({
    title: 'Confirm repair charge',
    body: `<strong>${rpCust ? escName(rpCust.firstName) + ' ' + escName(rpCust.lastName) : 'Customer'}</strong><br>
      ${serviceIds.length} service${serviceIds.length === 1 ? '' : 's'} · payable on collection`,
    amount: rpTotal,
    okLabel: 'Open ticket & charge',
  }))) return;
  const res = await window.api.addRepair({
    customerId,
    device: document.getElementById('rpDevice').value.trim(),
    serviceIds,
    kcPurchase: !!document.getElementById('rpKC')?.checked,
    notes: document.getElementById('rpNotes').value.trim(),
  });
  if (!res.success) { toast(res.error || 'Could not open the ticket.', 'error'); return; }
  closeDynamicModal();
  renderRepairsTab();
  const rc = customers.find(x => String(x.id) === String(customerId));
  const rDevice = res.repair.device || 'the device';
  showDonePanel({
    title: 'Repair ticket opened', icon: 'wrench',
    customerId,
    customerName: rc ? `${rc.firstName || ''} ${rc.lastName || ''}`.trim() : (res.repair.customerName || ''),
    customerPhone: rc?.phone || '',
    summary: `${rDevice}${res.repair.services?.length ? ' · ' + res.repair.services.map(x => x.name || x).join(', ') : ''}`,
    total: res.repair.total,
    payLine: 'due on collection',
    method: null,
    paidNow: false,
    lines: [{ name: `Repair — ${rDevice}`, qty: 1, total: res.repair.total }],
    // Booked in, not finished: the figure is an ESTIMATE and the email says so,
    // because "Total £45" on a job nobody has started yet is a promise the shop
    // has not made.
    receipt: {
      kind: 'repair', ref: String(res.repair.id || ''), ready: false,
      device: rDevice || '',
      services: (res.repair.services || []).map(x => x.name || x).join(', '),
      total: res.repair.total || 0, paidAmount: 0, method: null,
    },
    smsText: `Hi${rc?.firstName ? ' ' + rc.firstName : ''}, we've booked in ${rDevice} for repair. Estimate ${fmtGbp(res.repair.total)}, payable on collection. We'll message you when it's ready. Kosher Connect, 0161 531 1386.`,
    again: { label: 'Another repair', icon: 'wrench', sub: rc?.firstName ? `for ${rc.firstName}` : 'new ticket', run: () => openNewRepairModal(customerId) },
  });
}

async function changeRepairStatus(id, status) {
  // Collecting = charging: ask how it's paid so a repair settled at the
  // counter doesn't sit as wallet debt (same pattern as tickets).
  if (status === 'Collected') {
    const r = repairs.find(x => x.id === id);
    if ((r?.total || 0) > 0) { openCollectRepairModal(id); renderRepairsTab(); return; }
  }
  const res = await window.api.updateRepair({ id, status });
  if (!res.success) { toast(res.error || 'Could not update status.', 'error'); renderRepairsTab(); return; }
  toast(`Repair marked ${status}.`, 'success');
  renderRepairsTab();
  // Ready = time to tell the customer — draft the collect message straight away.
  if (status === 'Ready') openRepairSmsModal(id);
}

// Ready-to-collect message for a repair, drafted not sent (same HOLD
// discipline as the rental status SMS: staff copy it or open WhatsApp and
// press send themselves).
function buildRepairSms(r) {
  const first = (r.customerName || '').split(' ')[0] || 'there';
  const total = r.total || 0;
  return `Hi ${first}, Kosher Connect: your ${r.device || 'phone'} is repaired and ready to collect.${total > 0.005 ? ` ${fmtGbp(total)} on collection.` : ''} 0161 531 1386`;
}
function openRepairSmsModal(repairId) {
  const r = repairs.find(x => x.id === repairId);
  if (!r) return;
  const c = customers.find(x => x.id === r.customerId);
  showDynamicModal(`
    <div class="modal-title kc-ic kc-ic-mail">Ready to collect — ${custNameLink(r.customerId, escName(r.customerName || ''))}</div>
    <div style="font-size:var(--fs-small);color:var(--muted);margin-bottom:10px;">Edit it, then ${WHATSAPP_ENABLED ? 'copy or open WhatsApp' : 'copy it into your messages'} — <strong>nothing is sent</strong> from here.</div>
    <textarea class="form-input" id="rpsmsText" rows="4" style="font-family:inherit;">${escHtml(buildRepairSms(r))}</textarea>
    <div class="modal-actions">
      <button class="btn btn-outline" onclick="closeDynamicModal()">Close</button>
      ${c && waLink(c, '') ? `<button class="btn btn-outline kc-ic kc-ic-chat" onclick="waRepairSms('${escHtml(String(repairId))}')">Open in WhatsApp</button>` : ''}
      <button class="btn btn-primary kc-ic kc-ic-clipboard" onclick="copyRepairSms('${escHtml(String(repairId))}')">Copy message</button>
    </div>
  `);
}
async function copyRepairSms(repairId) {
  const r = repairs.find(x => x.id === repairId);
  const text = document.getElementById('rpsmsText')?.value || '';
  try { await navigator.clipboard.writeText(text); toast('Message copied — paste it into your messaging app.', 'success'); }
  catch { toast('Select the text and copy it manually.', 'warning'); return; }
  if (r?.customerId) recordComm(r.customerId, { type: 'message', text: 'Repair-ready message drafted & copied' });
  closeDynamicModal();
}
function waRepairSms(repairId) {
  const r = repairs.find(x => x.id === repairId);
  if (!r) return;
  const text = document.getElementById('rpsmsText')?.value || '';
  const c = customers.find(x => x.id === r.customerId);
  const url = c && waLink(c, text);
  if (!url) { toast('No usable phone number for WhatsApp.', 'warning'); return; }
  window.open(url, '_blank');
  if (r.customerId) recordComm(r.customerId, { type: 'message', text: 'Repair-ready message opened in WhatsApp' });
  closeDynamicModal();
}

function openCollectRepairModal(id) {
  const r = repairs.find(x => x.id === id);
  if (!r) return;
  showDynamicModal(`
    <div class="modal-title kc-ic kc-ic-wrench">Collect repair — ${custNameLink(r.customerId, escName(r.customerName || ''))}</div>
    <div style="font-size:var(--fs-ui);margin-bottom:12px;">${escHtml(r.device || 'device')} · total <strong>${fmtGbp((r.total || 0))}</strong></div>
    <div class="form-group">
      <label class="form-label">Payment</label>
      <select class="form-input" id="rcPay">
        <option value="account">Put on account (wallet)</option>
        <option value="cash">Paid now — 💵 Cash</option>
        <option value="card">Paid now — 💳 Card</option>
        <option value="card_on_file">Paid now — card on file (Stripe)</option>
        <option value="bank_transfer">Paid now — 🏦 Transfer</option>
      </select>
      <div style="font-size:var(--fs-micro);color:var(--muted);margin-top:4px;">"Paid now" settles it immediately — no wallet debt.</div>
    </div>
    <div class="modal-actions">
      <button class="btn btn-outline" onclick="closeDynamicModal()">Cancel</button>
      <button class="btn btn-primary kc-ic kc-ic-check" onclick="confirmCollectRepair('${escHtml(id)}')">Collect</button>
    </div>
  `);
}

async function confirmCollectRepair(id) {
  const res = await window.api.updateRepair({ id, status: 'Collected', payment: document.getElementById('rcPay').value });
  if (!res.success) { toast(res.error || 'Could not collect.', 'error'); return; }
  closeDynamicModal();
  if (res.chargePosted) {
    toast(res.paidNow
      ? `Collected — ${fmtGbp(res.repair.total)} paid in full.`
      : `Collected — ${fmtGbp(res.repair.total)} on account. Balance ${fmtGbp(res.balance)}.`, 'success');
  } else {
    toast('Repair collected.', 'success');
  }
  renderRepairsTab();
}

// ─────────────────────────────────────────────
//  ONLINE SERVICES (charging screen)
// ─────────────────────────────────────────────
// One order = one wallet charge (SVC-<uuid>), optionally paid on the spot
// (PAY-SVC-<uuid>). Repeat-application pricing per the customer price list.

let serviceOrders = [];
let onlineMenu = [];

// Price list rule (updated list: "First Application / 4 or more"): units
// below the threshold at the single price, units from the Nth at
// repeatPrice. The threshold lives in Settings (online_repeat_from, now 4 —
// it was 2 on the old list). Services without a repeat price charge every
// unit at the single price.
const onlineRepeatFrom = () => Math.max(2, settingNum('online_repeat_from', 4));
function onlineServiceTotal(svc, qty) {
  const n = Math.max(1, Math.floor(Number(qty)) || 1);
  const single = Number(svc.price) || 0;
  const rep = svc.repeatPrice === null || svc.repeatPrice === undefined
    ? single : Number(svc.repeatPrice);
  const from = onlineRepeatFrom();
  const atSingle = Math.min(n, from - 1);
  return atSingle * single + (n - atSingle) * rep;
}

// ── Help timer (Regular online service is billed per hour, min 10 min) ──
// Pausable: `elapsedMs` banks time already counted; `runningSince` is when
// the current run started (null while paused). Total = elapsedMs + (now −
// runningSince). Backwards-compatible with the old {startedAt} shape.
let svcTimerInterval = null;
const svcTimerState = () => { try { return JSON.parse(localStorage.getItem('kcSvcTimer')); } catch { return null; } };
const svcTimerSet = (s) => s ? localStorage.setItem('kcSvcTimer', JSON.stringify(s)) : localStorage.removeItem('kcSvcTimer');

function svcTimerElapsedMs(t) {
  if (!t) return 0;
  if (t.startedAt && t.elapsedMs === undefined) return Date.now() - t.startedAt; // legacy
  return (t.elapsedMs || 0) + (t.runningSince ? Date.now() - t.runningSince : 0);
}

function svcTimerCharge(t) {
  const minutes = Math.max(10, Math.ceil(svcTimerElapsedMs(t) / 60000)); // 10-minute minimum
  const rate = settingNum('online_hourly_rate', 45);
  return { minutes, amount: Math.round((minutes / 60) * rate * 100) / 100 };
}

function svcTimerStart() {
  const sel = document.getElementById('svcTimerCustomer');
  if (!sel?.value) { toast('Pick who you are helping.', 'error'); return; }
  const c = customers.find(x => x.id === sel.value);
  svcTimerSet({ customerId: sel.value, customerName: c ? `${c.firstName} ${c.lastName}` : '',
    elapsedMs: 0, runningSince: Date.now() });
  renderServicesTab();
}

function svcTimerPause() {
  const t = svcTimerState();
  if (!t || !t.runningSince) return;
  t.elapsedMs = (t.elapsedMs || 0) + (Date.now() - t.runningSince);
  t.runningSince = null;
  svcTimerSet(t);
  renderServicesTab();
}

function svcTimerResume() {
  const t = svcTimerState();
  if (!t || t.runningSince) return;
  t.runningSince = Date.now();
  svcTimerSet(t);
  renderServicesTab();
}

function svcTimerDiscard() {
  svcTimerSet(null);
  toast('Timer discarded — nothing charged.', 'warning');
  renderServicesTab();
}

function svcTimerStop() {
  const t = svcTimerState();
  if (!t) return;
  const { minutes, amount } = svcTimerCharge(t);
  svcTimerSet(null);
  openNewServiceModal();
  setTimeout(() => {
    kcPickerSet('svCustomer', t.customerId);
    const svcSel = document.getElementById('svService');
    const hourly = onlineMenu.find(m => /per hour|hourly|regular online/i.test(m.name));
    if (svcSel && hourly) svcSel.value = String(hourly.id);
    document.getElementById('svTotal').value = amount.toFixed(2);
    document.getElementById('svNotes').value = `Timed help — ${minutes} min`;
    svTimedBreakdown(minutes);
  }, 60);
}

// ── The timed-help line, with the minutes actually editable ───────────────
//
// Owner, 17 Aug, arrow pointing at the words "— editable": "where is it
// editable from - u see i treid to change in notes but no real effect on
// calc". Fair. The line claimed something was editable without saying WHAT or
// WHERE, the nearest box to it was the note, and editing a note quite rightly
// changes no money at all — so the app looked like it was ignoring them.
//
// What they were actually trying to do was charge 44 minutes instead of 43.
// So that is now the thing you can type into, and the money follows it. The
// Total stays editable in its own right for the times the answer is not about
// minutes at all, and the line says so in those words.
function svTimedBreakdown(minutes) {
  const bd = document.getElementById('svBreakdown');
  if (!bd) return;
  bd.innerHTML = `
    <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">
      <span class="kc-ic kc-ic-stopwatch" aria-hidden="true"></span>
      <input class="form-input kc-inline-num" id="svMins" type="number" min="1" step="1"
        value="${minutes}" aria-label="Minutes to charge for" oninput="svTimedRecalc()">
      <span>min at ${fmtGbp(settingNum('online_hourly_rate', 45))}/hr =</span>
      <strong id="svTimedAmount"></strong>
      <span id="svTimedNote" style="color:var(--muted);"></span>
    </div>
    <div style="margin-top:6px;">Change the minutes here and the total follows.
      To charge something else entirely, type straight into <strong>Total (£)</strong> above.</div>`;
  svTimedRecalc();
}

function svTimedCharge(typed) {
  const rate = settingNum('online_hourly_rate', 45);
  const minutes = Math.max(10, Math.max(1, Math.round(Number(typed) || 0)));  // 10-minute minimum
  return { minutes, rate, amount: Math.round((minutes / 60) * rate * 100) / 100 };
}

function svTimedRecalc() {
  const el = document.getElementById('svMins');
  if (!el) return;
  const typed = Math.max(1, Math.round(Number(el.value) || 0));
  const { minutes, amount } = svTimedCharge(typed);
  const total = document.getElementById('svTotal');
  if (total) { total.value = amount.toFixed(2); delete total.dataset.byHand; }
  const amt = document.getElementById('svTimedAmount');
  if (amt) amt.textContent = fmtGbp(amount);
  // Say it out loud rather than quietly charging more than the box shows.
  const note = document.getElementById('svTimedNote');
  if (note) note.textContent = typed < minutes ? `(10-minute minimum — charging ${minutes})` : '';
  // The note follows the minutes only while it is still the one the app wrote;
  // a note the operator has put their own words into is left alone.
  const notes = document.getElementById('svNotes');
  if (notes && /^Timed help — \d+ min$/.test(notes.value.trim())) {
    notes.value = `Timed help — ${minutes} min`;
  }
}

// Typing in Total wins — but the timed line must not go on claiming a sum that
// is no longer what will be charged.
function svTotalByHand() {
  const total = document.getElementById('svTotal');
  const amt = document.getElementById('svTimedAmount');
  if (!total || !amt) return;
  total.dataset.byHand = '1';
  const note = document.getElementById('svTimedNote');
  if (note) note.textContent = `— charging ${fmtGbp(Number(total.value) || 0)} instead`;
}

// ── Floating help-timer chip ──────────────────────────────────────────────
// A running (or paused) session stays visible in the bottom-right corner on
// EVERY tab, ticking once a second, so staff never lose a live timer behind
// another screen. Hidden on the Services tab itself (the full controls live
// there). Clicking the chip jumps to Services; the inline buttons pause/stop
// without leaving the current screen.
function svcTimerFloatFrame(t) {
  const paused = !t.runningSince;
  return `
    <div class="svc-float-main" onclick="if(!document.getElementById('svcTimerFloat')?.dataset.dragged)goToTab('services')" title="Open Services (drag to move)">
      <span class="svc-float-icon kc-ic ${paused ? 'kc-ic-pause' : 'kc-ic-stopwatch'}" aria-hidden="true"></span>
      <div class="svc-float-info">
        <div class="svc-float-name">${escName(t.customerName || 'customer')}</div>
        <div class="svc-float-time"><b id="svcFloatElapsed">0:00</b><span id="svcFloatProj" class="svc-float-proj"></span></div>
      </div>
    </div>
    <div class="svc-float-btns">
      ${paused
        ? `<button class="svc-float-btn kc-ic kc-ic-play" title="Resume" onclick="event.stopPropagation();svcTimerResume()"></button>`
        : `<button class="svc-float-btn kc-ic kc-ic-pause" title="Pause" onclick="event.stopPropagation();svcTimerPause()"></button>`}
      ${svcPipSupported()
        ? `<button class="svc-float-btn" title="Float on top of everything" onclick="event.stopPropagation();svcTimerPopOut()">⧉</button>`
        : ''}
      <button class="svc-float-btn svc-float-stop kc-ic kc-ic-stop" title="Stop &amp; charge" onclick="event.stopPropagation();svcTimerStop()"></button>
    </div>`;
}

// ── The timer, out of the app and in front of everything ──────────────────
//
// Owner, 17 Aug: "the timer should come up even when OUT of the app. like it
// should stay pinned (and movable) in front of pc even while doing the work on
// other sites. an extension maybe?"
//
// Not an extension. An extension can only draw INSIDE a browser tab, so it
// would vanish the moment the work moved to Photoshop, a PDF, or the phone
// tool — which is most of what "online help" actually is. What does the job is
// Document Picture-in-Picture: a real, small, always-on-top OS window that the
// page owns. It sits above every other window, browser or not, drags anywhere
// on the screen, resizes, and survives switching tabs, sites and desktops.
//
// The price: Chrome or Edge (Chromium 116+, which the shop's Mac runs), and
// the app's tab has to stay OPEN — it may be buried behind everything, but if
// it is closed the window that belongs to it goes with it. The button is
// simply not offered where the browser cannot do it.
//
// The window's document is a separate document but the SAME script realm, so
// the buttons in it call svcTimerPause/Resume/Stop directly — there is no
// message passing to get out of step, and the clock is driven by the one
// interval that already ticks the in-app chip.
let svcPipWin = null;

function svcPipSupported() {
  return typeof window !== 'undefined' && 'documentPictureInPicture' in window;
}

// The PiP document starts blank — no app stylesheet, no variables — so the
// tokens have to be carried across. They are COPIED from the live app rather
// than re-typed: this block used to declare its own palette, and what it had
// drifted to was Tailwind slate on a pure white ground (#ffffff, the one
// background globals.css argues at length against) — a near-miss of the brand
// that only --go ever matched. A second palette is a second thing to keep in
// step, and it was already out of step.
const SVC_PIP_TOKENS = ['--text', '--muted', '--surface', '--border', '--accent',
  '--warning-ink', '--on-accent'];

/** The app's own computed token values, as a :root block for another document. */
function svcPipTokenCss() {
  const cs = getComputedStyle(document.documentElement);
  const decls = SVC_PIP_TOKENS
    .map((name) => [name, cs.getPropertyValue(name).trim()])
    .filter(([, value]) => value)
    .map(([name, value]) => `${name}:${value}`);
  return `:root{${decls.join(';')}}`;
}

const SVC_PIP_CSS = `
  * { box-sizing: border-box; }
  body { margin:0; font:13px/1.35 -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
         background:var(--surface); color:var(--text); user-select:none; -webkit-user-select:none; }
  .w { padding:10px 12px; display:flex; flex-direction:column; gap:6px; height:100vh; }
  .who { font-weight:600; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
  .who small { font-weight:400; color:var(--muted); }
  .clock { font-size:30px; font-weight:700; font-feature-settings:'tnum'; line-height:1; letter-spacing:-0.5px; }
  .paused .clock { color:var(--warning-ink); }
  .sub { color:var(--muted); font-size:12px; }
  .btns { display:flex; gap:6px; margin-top:auto; }
  button { flex:1; font:inherit; font-weight:600; padding:7px 6px; border-radius:7px; cursor:pointer;
           border:1px solid var(--border); background:transparent; color:var(--text); min-height:32px; }
  button:hover { border-color:var(--accent); color:var(--accent); }
  button.stop { background:var(--accent); border-color:var(--accent); color:var(--on-accent); }
  button.stop:hover { filter:brightness(1.08); }
  button:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }
`;

async function svcTimerPopOut() {
  const t = svcTimerState();
  if (!t) return toast('Start a timer first.', 'warning');
  if (!svcPipSupported()) {
    return toast('This browser can’t float a window on top — Chrome or Edge can.', 'warning');
  }
  if (svcPipWin && !svcPipWin.closed) { svcPipWin.focus(); return; }
  try {
    // Must be the first await after the click: the browser only grants this
    // while the user's gesture is still live.
    svcPipWin = await documentPictureInPicture.requestWindow({ width: 250, height: 152 });
  // The in-page timer is still running — say so, or this reads as "the timer
  // has stopped" when all that failed is the extra window.
  } catch { return toast('Couldn’t open the floating timer — this browser would not allow it. The timer on this page is still running.', 'error'); }

  const d = svcPipWin.document;
  d.documentElement.setAttribute('data-theme', document.documentElement.getAttribute('data-theme') || 'light');
  d.title = 'Kosher Connect — help timer';
  const tokens = d.createElement('style');
  tokens.id = 'pipTokens';
  tokens.textContent = svcPipTokenCss();
  d.head.appendChild(tokens);
  const style = d.createElement('style');
  style.textContent = SVC_PIP_CSS;
  d.head.appendChild(style);
  d.body.innerHTML = `
    <div class="w" id="pipWrap">
      <div class="who" id="pipWho"></div>
      <div class="clock" id="pipClock">0:00</div>
      <div class="sub" id="pipSub"></div>
      <div class="btns">
        <button id="pipHold"></button>
        <button id="pipStop" class="stop kc-ic kc-ic-stop">Stop</button>
      </div>
    </div>`;

  // Same script realm as the app, so these are the app's own functions.
  d.getElementById('pipHold').addEventListener('click', () => {
    svcTimerState()?.runningSince ? svcTimerPause() : svcTimerResume();
    svcPipTick();
  });
  d.getElementById('pipStop').addEventListener('click', () => {
    // Stopping opens the charge form, which lives in the app — so bring the
    // app forward rather than leaving the operator wondering where it went.
    svcPipClose();
    window.focus();
    svcTimerStop();
  });

  svcPipWin.addEventListener('pagehide', () => { svcPipWin = null; svcTimerFloatTick(); });
  svcPipTick();
  svcTimerFloatTick();      // the in-app chip stands down while this is up
}

function svcPipClose() {
  if (svcPipWin && !svcPipWin.closed) svcPipWin.close();
  svcPipWin = null;
}

function svcPipTick() {
  if (!svcPipWin || svcPipWin.closed) return;
  const t = svcTimerState();
  if (!t) return svcPipClose();          // stopped or discarded from the app
  const d = svcPipWin.document;
  // Copied tokens are a snapshot, so the theme toggle has to re-take it —
  // otherwise a window opened in light stays light on a switched-to-dark app.
  const theme = document.documentElement.getAttribute('data-theme') || 'light';
  if (d.documentElement.getAttribute('data-theme') !== theme) {
    d.documentElement.setAttribute('data-theme', theme);
    const tk = d.getElementById('pipTokens');
    if (tk) tk.textContent = svcPipTokenCss();
  }
  const paused = !t.runningSince;
  const secs = Math.floor(svcTimerElapsedMs(t) / 1000);
  const { minutes, amount } = svcTimerCharge(t);
  d.getElementById('pipWrap')?.classList.toggle('paused', paused);
  const who = d.getElementById('pipWho');
  if (who) who.innerHTML = `${escName(t.customerName || 'customer')} <small>${paused ? '· paused' : ''}</small>`;
  const clock = d.getElementById('pipClock');
  if (clock) clock.textContent = `${Math.floor(secs / 60)}:${String(secs % 60).padStart(2, '0')}`;
  const sub = d.getElementById('pipSub');
  if (sub) sub.textContent = `${fmtGbp(amount)} · ${minutes} min at ${fmtGbp(settingNum('online_hourly_rate', 45))}/hr`;
  const hold = d.getElementById('pipHold');
  // ▶ is monochrome text and stays; ⏸ was a colour emoji, so the pause face
  // becomes a class. Both states set BOTH classes so neither can stick.
  if (hold) {
    hold.classList.add('kc-ic');
    hold.classList.toggle('kc-ic-pause', !paused);
    hold.classList.toggle('kc-ic-play', paused);
    hold.textContent = paused ? 'Resume' : 'Pause';
  }
}

function svcTimerFloatTick() {
  const t = svcTimerState();
  svcPipTick();
  let el = document.getElementById('svcTimerFloat');
  // Hidden with no session, outside the portal (login/portal-less), on
  // Services where the full timer card already shows, or while the floating
  // window is up — two clocks on one screen is one too many.
  if (!t || currentTab === 'services' || !document.getElementById('mainContent')
      || (svcPipWin && !svcPipWin.closed)) { if (el) el.remove(); return; }
  if (!el) {
    el = document.createElement('div'); el.id = 'svcTimerFloat'; el.className = 'svc-float';
    svcFloatRestorePos(el);
    el.addEventListener('pointerdown', svcFloatDragStart);
    document.body.appendChild(el);
  }
  const sig = `${t.customerId}|${t.runningSince ? 'run' : 'pause'}`;
  if (el.dataset.sig !== sig) {            // only rebuild the frame on a state change
    el.dataset.sig = sig;
    el.classList.toggle('paused', !t.runningSince);
    el.innerHTML = svcTimerFloatFrame(t);
  }
  const secs = Math.floor(svcTimerElapsedMs(t) / 1000);
  const e = document.getElementById('svcFloatElapsed');
  if (e) e.textContent = `${Math.floor(secs / 60)}:${String(secs % 60).padStart(2, '0')}`;
  const p = document.getElementById('svcFloatProj');
  if (p) { const { minutes, amount } = svcTimerCharge(t); p.textContent = `~${fmtGbp(amount)} · ${minutes}m`; }
}

function startSvcTimerFloat() {
  svcTimerFloatTick();
  if (!window.__svcFloat) window.__svcFloat = setInterval(svcTimerFloatTick, 1000);
}

// The chip can cover exactly the corner you need to read — so it's draggable.
// Grab anywhere that isn't a button; the spot sticks per browser. A plain
// click (under 5px of movement) still opens Services.
function svcFloatRestorePos(el) {
  try {
    const pos = JSON.parse(localStorage.getItem('kcTimerPos') || 'null');
    if (pos && Number.isFinite(pos.x) && Number.isFinite(pos.y)) {
      el.style.left = `${Math.min(Math.max(0, pos.x), window.innerWidth - 90)}px`;
      el.style.top = `${Math.min(Math.max(0, pos.y), window.innerHeight - 44)}px`;
      el.style.right = 'auto'; el.style.bottom = 'auto';
    }
  } catch { /* default bottom-right */ }
}
function svcFloatDragStart(e) {
  if (e.target.closest('button')) return;
  const el = document.getElementById('svcTimerFloat');
  if (!el) return;
  const r = el.getBoundingClientRect();
  const offX = e.clientX - r.left, offY = e.clientY - r.top;
  const startX = e.clientX, startY = e.clientY;
  let moved = false;
  const move = (ev) => {
    if (!moved && Math.hypot(ev.clientX - startX, ev.clientY - startY) < 5) return;
    moved = true;
    el.style.left = `${Math.min(Math.max(0, ev.clientX - offX), window.innerWidth - r.width)}px`;
    el.style.top = `${Math.min(Math.max(0, ev.clientY - offY), window.innerHeight - r.height)}px`;
    el.style.right = 'auto'; el.style.bottom = 'auto';
  };
  const up = () => {
    window.removeEventListener('pointermove', move);
    window.removeEventListener('pointerup', up);
    if (moved) {
      const r2 = el.getBoundingClientRect();
      try { localStorage.setItem('kcTimerPos', JSON.stringify({ x: r2.left, y: r2.top })); } catch { /* not fatal */ }
      el.dataset.dragged = '1';                    // swallow the click that follows the drop
      setTimeout(() => { delete el.dataset.dragged; }, 0);
    }
  };
  window.addEventListener('pointermove', move);
  window.addEventListener('pointerup', up);
}

async function renderServicesTab() {
  const content = document.getElementById('mainContent');
  kcSkeleton('services');
  if (svcTimerInterval) { clearInterval(svcTimerInterval); svcTimerInterval = null; }
  try {
    [serviceOrders, onlineMenu] = await Promise.all([
      window.api.getServiceOrders(),
      window.api.getServiceMenu('online'),
    ]);
  } catch { content.innerHTML = errorHtml('Couldn’t load services'); return; }
  if (!Array.isArray(serviceOrders)) serviceOrders = [];
  if (!Array.isArray(onlineMenu)) onlineMenu = [];

  const today = localISO();
  const todays = serviceOrders.filter(o => (o.createdAt || '').slice(0, 10) === today);
  const revenue = serviceOrders.reduce((s, o) => s + (o.total || 0), 0);

  const svcWeekAgo = localISO(new Date(Date.now() - 7 * 86400000));
  const svcBar = kcFilterSort('services', [
    { value: 'all', label: 'Filter: all orders' },
    { value: 'today', label: 'Today', icon: 'calendar', test: o => (o.createdAt || '').slice(0, 10) === today },
    { value: 'week', label: 'Last 7 days', icon: 'schedule', test: o => (o.createdAt || '').slice(0, 10) >= svcWeekAgo },
  ], [
    { value: 'recent', label: 'Sort: Most recent', cmp: kcCmpDate(o => o.createdAt || '', -1) },
    { value: 'oldest', label: 'Oldest first', cmp: kcCmpDate(o => o.createdAt || '', 1) },
    { value: 'name', label: 'Customer A–Z', cmp: kcCmpStr(o => o.customerName) },
    { value: 'total', label: 'Total (high–low)', cmp: kcCmpNum(o => o.total || 0) },
    { value: 'service', label: 'Service A–Z', cmp: kcCmpStr(o => o.serviceName) },
  ], renderServicesTab);
  const svcShown = kcViewApply('services', serviceOrders);
  const orderRows = svcShown.length === 0
    ? `<tr><td colspan="5"><div class="empty-state"><div class="emoji kc-ic kc-ic-printer"></div><p>${serviceOrders.length ? 'No orders match this filter.' : 'No services charged yet.'}</p>${serviceOrders.length ? '' : '<small>Press "+ Charge a service", top right, to record the first one.</small>'}${kcClearFiltersBtn('services')}</div></td></tr>`
    : svcShown.map(o => `
      <tr>
        <td><div class="customer-name">${custNameLink(o.customerId, escName(o.customerName || '—'))}</div></td>
        <td>${escHtml(o.serviceName)}${o.qty > 1 ? ` <span style="color:var(--muted);">× ${o.qty}</span>` : ''}</td>
        <td><strong>${fmtGbp((o.total || 0))}</strong></td>
        <td class="kc-date">${o.createdAt ? fmtDate(o.createdAt) : '—'}</td>
        <td style="font-size:var(--fs-small);color:var(--muted);">${escHtml(o.notes || '')}</td>
      </tr>`).join('');

  const menuRows = onlineMenu.map(m => `
    <tr>
      <td>${escHtml(m.name)}</td>
      <td>${fmtGbp(m.price)}</td>
      <td>${m.repeatPrice === null ? '—' : fmtGbp(m.repeatPrice)}</td>
    </tr>`).join('');

  content.innerHTML = `
    <div class="stats-row">
      <div class="stat-card"><div class="stat-label">Charged today</div>
        <div class="stat-value">${fmtGbp(todays.reduce((s, o) => s + (o.total || 0), 0))}</div>
        <div class="stat-sub">${todays.length} service${todays.length === 1 ? '' : 's'}</div></div>
      <div class="stat-card"><div class="stat-label">All-time revenue</div>
        <div class="stat-value">${fmtGbp(revenue)}</div></div>
      <div class="stat-card"><div class="stat-label">Orders</div><div class="stat-value">${serviceOrders.length}</div></div>
    </div>
    ${(() => {
      const t = svcTimerState();
      if (t) {
        const paused = !t.runningSince;
        return `
        <div class="table-card" style="margin-bottom:14px;padding:14px 18px;display:flex;align-items:center;gap:14px;flex-wrap:wrap;${paused ? 'border-color:var(--gold);' : ''}">
          <span class="kc-ic ${paused ? 'kc-ic-pause' : 'kc-ic-stopwatch'}" style="font-size:20px;" aria-hidden="true"></span>
          <div style="flex:1;min-width:180px;">
            <div style="font-weight:600;">Helping ${escName(t.customerName || 'customer')}</div>
            <div style="font-size:var(--fs-small);color:${paused ? 'var(--gold)' : 'var(--muted)'};">${paused ? 'paused — resume to keep counting' : 'running'}</div>
          </div>
          <strong id="svcTimerElapsed" style="font-size:var(--fs-h1);font-feature-settings:'tnum';">0:00</strong>
          <span id="svcTimerProj" style="font-size:var(--fs-body);color:var(--muted);"></span>
          ${paused
            ? `<button class="btn btn-outline kc-ic kc-ic-play" onclick="svcTimerResume()">Resume</button>`
            : `<button class="btn btn-outline kc-ic kc-ic-pause" onclick="svcTimerPause()">Pause</button>`}
          <button class="btn btn-primary kc-ic kc-ic-stop" onclick="svcTimerStop()">Stop &amp; charge</button>
          ${svcPipSupported()
            ? `<button class="btn btn-outline" onclick="svcTimerPopOut()" title="A small always-on-top window that stays in front of every other site and app">⧉ Float on top</button>`
            : ''}
          <button class="btn btn-outline btn-sm" onclick="svcTimerDiscard()">✕ Discard</button>
        </div>`;
      }
      return `
        <div class="table-card" style="margin-bottom:14px;padding:14px 18px;display:flex;align-items:center;gap:12px;flex-wrap:wrap;">
          <span class="kc-ic kc-ic-stopwatch" style="font-size:20px;" aria-hidden="true"></span>
          <span style="font-size:var(--fs-body);color:var(--muted);">Hourly help timer (${fmtGbp(settingNum('online_hourly_rate', 45))}/hr, 10-min minimum)</span>
          <!-- 230px is what "Who are you helping?" needs in this type. Below
               that the row squeezed it to 189px and truncated its own prompt to
               "Who are you helpi" — oddly only at 390px, since by 320 the Start
               button had already wrapped away and left it the whole row. -->
          <div style="flex:1;min-width:230px;">${customerPicker('svcTimerCustomer', {
            placeholder: 'Who are you helping?', label: 'Who are you helping?',
            style: 'min-height:0;padding:8px 12px;',
          })}</div>
          <button class="btn btn-primary kc-ic kc-ic-play" onclick="svcTimerStart()">Start timer</button>
        </div>`;
    })()}
    <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:12px;flex-wrap:wrap;">
      ${svcBar}
      ${/* The create action lives in the topbar, on every tab, in the same
             place (#58). It was ALSO here, in the same blue, so three screens
             carried two identical primary buttons ~250px apart — measured
             26 Aug: rentals, Online & Print, Virtual Numbers. Two loud buttons
             for one job is the "buttons which aren't really needed" the owner
             asked about, and the duplicate is the one that moves per screen. */''}
    </div>
    <div class="dash-cols">
      <div class="table-card">
        <div class="section-divider" style="margin:12px 14px 4px;">Recent orders</div>
        <table>
          <thead><tr><th>Customer</th><th>Service</th><th>Total</th><th>Date</th><th>Notes</th></tr></thead>
          <tbody>${orderRows}</tbody>
        </table>
      </div>
      <div class="table-card">
        <div class="section-divider" style="margin:12px 14px 4px;">Price list <span style="color:var(--muted);font-weight:400;">· first / ${onlineRepeatFrom()} or more</span></div>
        <table>
          <thead><tr><th>Service</th><th>First</th><th>${onlineRepeatFrom()}+</th></tr></thead>
          <tbody>${menuRows}</tbody>
        </table>
      </div>
    </div>`;

  // Live tick for the help timer (cleared on every tab re-render). Shows the
  // banked time even while paused; only advances when running.
  const running = svcTimerState();
  if (running) {
    const tick = () => {
      const el = document.getElementById('svcTimerElapsed');
      if (!el) { clearInterval(svcTimerInterval); svcTimerInterval = null; return; }
      const secs = Math.floor(svcTimerElapsedMs(running) / 1000);
      el.textContent = `${Math.floor(secs / 60)}:${String(secs % 60).padStart(2, '0')}`;
      const { minutes, amount } = svcTimerCharge(running);
      const p = document.getElementById('svcTimerProj');
      if (p) p.textContent = `≈ ${fmtGbp(amount)} (${minutes} min, 10-min minimum)`;
    };
    tick();
    if (running.runningSince) svcTimerInterval = setInterval(tick, 1000); // frozen while paused
  }
}

async function openNewServiceModal(preselectCustomerId = null) {
  // Callable from the customer card too — make sure the menu is loaded.
  if (!onlineMenu.length) {
    onlineMenu = await window.api.getServiceMenu('online').catch(() => []);
    if (!Array.isArray(onlineMenu)) onlineMenu = [];
  }
  const svcOptions = onlineMenu.map(m =>
    `<option value="${escHtml(String(m.id))}">${escHtml(m.name)} — ${fmtGbp(m.price)}${m.repeatPrice !== null ? ` (${onlineRepeatFrom()}+ ${fmtGbp(m.repeatPrice)})` : ''}</option>`).join('');
  showDynamicModal(`
    <div class="modal-title kc-ic kc-ic-printer">Charge a service</div>
    <div class="form-grid">
      <div class="form-group form-full">
        <label class="form-label">Customer *</label>
        ${customerPicker('svCustomer', { selected: preselectCustomerId })}
      </div>
      <div class="form-group form-full">
        <label class="form-label">Service *</label>
        <select class="form-input" id="svService" onchange="svUpdateTotal()">
          <option value="">Select service…</option>${svcOptions}
        </select>
      </div>
      <div class="form-group">
        <label class="form-label">Quantity / applications</label>
        <input class="form-input" type="number" id="svQty" value="1" min="1" step="1" oninput="svUpdateTotal()">
      </div>
      <div class="form-group">
        <label class="form-label">Total (£)</label>
        <input class="form-input" type="number" id="svTotal" min="0" step="0.01" value="0"
          oninput="svTotalByHand()">
      </div>
      <div class="form-group">
        <label class="form-label">Paid now?</label>
        <div style="display:flex;gap:8px;align-items:center;">
          <input type="checkbox" id="svPaid" checked
            onchange="document.getElementById('svMethod').style.display=this.checked?'':'none'"
            style="cursor:pointer;">
          <select class="form-input" id="svMethod" style="flex:1;">
            <option value="cash">💵 Cash</option>
            <option value="card">💳 Card</option>
            <option value="bank_transfer">🏦 Bank transfer</option>
            <option value="other">Other</option>
          </select>
        </div>
      </div>
      <div class="form-group form-full">
        <label class="form-label">Notes</label>
        <input class="form-input" id="svNotes" placeholder="e.g. passport ref, printout pages">
      </div>
    </div>
    <div style="margin-top:8px;padding:10px;border-radius:8px;background:var(--bg-secondary);font-size:var(--fs-small);color:var(--muted);" id="svBreakdown">
      The charge posts to the customer's wallet (reference <code>SVC-…</code>); ticking "paid now" records the payment alongside.
    </div>
    <div class="modal-actions">
      <button class="btn btn-outline" onclick="closeDynamicModal()">Cancel</button>
      <button class="btn btn-primary kc-ic kc-ic-printer" onclick="saveNewServiceOrder()">Charge</button>
    </div>
  `);
}

function svUpdateTotal() {
  const svc = onlineMenu.find(m => String(m.id) === document.getElementById('svService')?.value);
  if (!svc) return;
  const qty = Math.max(1, parseInt(document.getElementById('svQty')?.value, 10) || 1);
  const total = onlineServiceTotal(svc, qty);
  document.getElementById('svTotal').value = total.toFixed(2);
  const bd = document.getElementById('svBreakdown');
  if (!bd) return;
  const atSingle = Math.min(qty, onlineRepeatFrom() - 1);
  const atRepeat = qty - atSingle;
  bd.innerHTML = atRepeat > 0 && svc.repeatPrice !== null
    ? `${qty} applications: ${atSingle} × ${fmtGbp(svc.price)} + ${atRepeat} × ${fmtGbp(Number(svc.repeatPrice))} = <strong>${fmtGbp(total)}</strong>`
    : `${qty} × ${fmtGbp(svc.price)} = <strong>${fmtGbp(total)}</strong>`;
}

async function saveNewServiceOrder() {
  const customerId = document.getElementById('svCustomer').value;
  const serviceId = document.getElementById('svService').value;
  if (!customerId) { toast('Select a customer.', 'error'); return; }
  if (!serviceId) { toast('Select a service.', 'error'); return; }
  const svCust = customers.find(c => c.id === customerId);
  const svTotal = parseFloat(document.getElementById('svTotal').value);
  const svPaid = document.getElementById('svPaid').checked;
  const svLabel = document.getElementById('svService').selectedOptions[0]?.textContent || 'Service';
  // One token per submit (server dedupes a retry) + an in-flight guard against a
  // double-click posting the service charge twice.
  const guardKey = 'svc:' + customerId + ':' + serviceId;
  if (!kcBeginWrite(guardKey)) return;
  let res;
  try {
    if (!(await kcConfirm({
      title: 'Confirm service charge',
      body: `<strong>${svCust ? escName(svCust.firstName) + ' ' + escName(svCust.lastName) : 'Customer'}</strong><br>
        ${escHtml(svLabel.trim())}${svPaid ? ' · paid now' : ' · on account'}`,
      amount: Number.isFinite(svTotal) ? svTotal : 0,
      okLabel: 'Charge service',
    }))) return;
    res = await window.api.addServiceOrder({
      customerId,
      serviceId,
      qty: Math.max(1, parseInt(document.getElementById('svQty').value, 10) || 1),
      total: parseFloat(document.getElementById('svTotal').value),
      paidNow: document.getElementById('svPaid').checked,
      method: document.getElementById('svMethod').value,
      notes: document.getElementById('svNotes').value.trim(),
      clientRef: kcRef(),
    });
  } finally {
    kcEndWrite(guardKey);
  }
  if (!res.success) { toast(res.error || 'Could not charge the service.', 'error'); return; }
  closeDynamicModal();
  if (res.duplicate) { toast('Already charged — no double charge.', 'info'); renderServicesTab(); return; }
  const extraMsg = res.extras?.length ? ` Incl. ${res.extras.map(e => `${e.label} ${fmtGbp(e.amount)}`).join(', ')}.` : '';
  toast(`Charged ${fmtGbp(res.order.total)} — wallet balance ${fmtGbp(res.balance)}.${extraMsg}`, 'success');
  renderServicesTab();
}

// ─────────────────────────────────────────────
//  SHOP & STOCK (selling devices/accessories — separate from the rental fleet)
// ─────────────────────────────────────────────

let shopItems = [];
let shopSales = [];
// Buy side v1 — suppliers + returns going back to them (RMA).
let suppliers = [];
let supplierReturns = [];
const SUPPLIER_RETURN_STATUS = {
  awaiting_send: { label: 'To send', icon: 'package',     color: 'var(--danger-ink)' },
  sent:          { label: 'Sent', icon: 'postbox',        color: 'var(--warning-ink)' },
  credited:      { label: '✔ Credited',    color: 'var(--success-ink)' },
  replaced:      { label: 'Replaced', icon: 'repeat',    color: 'var(--success-ink)' },
  written_off:   { label: 'Written off', icon: 'trash', color: 'var(--muted)' },
};
const SUPPLIER_RETURN_OPEN = ['awaiting_send', 'sent'];
// Goods-in v2 — deliveries + the lightweight per-supplier balance
// (unpaid invoices minus credit notes; the shop's only AP record for now).
let goodsIn = [];
let goodsInBalances = {};

// MIRRORS lib/stockCategories.mjs — main.js is a classic browser script and
// cannot import. test/stockCategories.test.mjs holds the two to the same
// keys, labels and order. Owner-editable categories (BACKLOG) will merge a
// Settings list on top of these defaults.
// These labels keep their emoji, and it is not an oversight. Three reasons,
// any one of which is enough: they are DATA — a custom category's key IS its
// label (see stockCategories below), so the render sites escape them and
// markup would show as literal text, which is exactly what happened when this
// map was converted on 24 Aug; they are mirrored in lib/stockCategories.mjs
// with a test holding the two identical; and they fill the till's category
// <select>, where an option element cannot carry an icon anyway.
const STOCK_CATEGORY_LABELS = {
  phone: '📱 Phone', sim: '💳 SIM', charger: '🔌 Charger', cable: '🔗 Cable',
  earphones: '🎧 Earphones', case: '🛡️ Case & cover', powerbank: '🔋 Power bank',
  memory: '💾 Memory card', car: '🚗 Car accessory', repairpart: '🔧 Repair part',
  accessory: '🧩 Accessory', other: '📦 Other',
};

// The merged category list: the twelve built-in labels above, plus the owner's
// own from the stock_categories setting. MIRRORS mergeStockCategories in
// lib/stockCategories.mjs — test/stockCategories.test.mjs holds the two to the
// same output. A custom category's key IS its label, so the existing
// `STOCK_CATEGORY_LABELS[cat] || cat` label lookups render it with no change.
const kcBareCat = (s) => String(s || '').replace(/[^\p{L}\p{N}]+/gu, ' ').trim().toLowerCase();
function stockCategories() {
  const merged = Object.entries(STOCK_CATEGORY_LABELS);
  const taken = new Set();
  for (const [k, label] of merged) { taken.add(k.toLowerCase()); taken.add(kcBareCat(label)); }
  const csv = pricingConfig?.settings?.find(x => x.key === 'stock_categories')?.textValue || '';
  for (const raw of String(csv).split(',')) {
    const label = raw.replace(/[<>,]/g, '').replace(/\s+/g, ' ').trim().slice(0, 40).trim();
    const key = kcBareCat(label);
    if (!label || !key || taken.has(key)) continue;
    taken.add(key);
    merged.push([label, label]);
  }
  return merged;
}
// key → label for the shelf/dropdown; a custom key is its own label.
function stockCatLabel(cat) { return STOCK_CATEGORY_LABELS[cat] || cat; }

// Just the owner's own categories (everything the merged list holds beyond the
// twelve defaults) — for the Settings editor to show back what is saved.
function customStockCategoriesClient() {
  return stockCategories().slice(Object.keys(STOCK_CATEGORY_LABELS).length).map(([, l]) => l);
}

// Narrowing the shelf by several things at once (owner, 17 Aug — the Lightspeed
// products screen). Held at module scope so a re-render keeps what was typed.
let shopFacets = { q: '', category: 'all', brand: 'all' };

// Mirrors lib/shopFilter.mjs — change both together; test/shopFilter.test.mjs
// covers the canon. An empty facet narrows NOTHING: a filter that quietly
// excludes rows because a control sat on its default is how stock goes missing
// from a list and gets re-ordered by mistake.
function matchStockItem(item, facets = {}) {
  const { q = '', category = 'all', brand = 'all' } = facets || {};
  if (category && category !== 'all' && String(item?.category || '') !== String(category)) return false;
  if (brand && brand !== 'all' && String(item?.company || '') !== String(brand)) return false;
  const words = String(q || '').toLowerCase().split(/\s+/).filter(Boolean);
  if (!words.length) return true;
  const hay = [item.company, item.model, item.code, item.barcode, item.name]
    .filter(Boolean).join(' ').toLowerCase();
  return words.every(w => hay.includes(w));
}
function stockBrands(items = []) {
  const seen = new Set();
  for (const i of (Array.isArray(items) ? items : [])) {
    const b = String(i?.company || '').trim();
    if (b) seen.add(b);
  }
  return [...seen].sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' }));
}
function shopFacetsActive() {
  return !!String(shopFacets.q || '').trim() || shopFacets.category !== 'all' || shopFacets.brand !== 'all';
}
function shopSetFacet(key, value) {
  shopFacets = { ...shopFacets, [key]: value };
  renderShopRows();
}
function shopClearFacets() {
  shopFacets = { q: '', category: 'all', brand: 'all' };
  const box = document.getElementById('shopFacetQ');
  if (box) box.value = '';
  const cat = document.getElementById('shopFacetCat'); if (cat) cat.value = 'all';
  const br = document.getElementById('shopFacetBrand'); if (br) br.value = 'all';
  renderShopRows();
}
// What the shelf actually carries (owner's list) — offered as type-ahead
// suggestions when adding stock, so new items land with consistent names.
const STOCK_TYPE_SUGGESTIONS = [
  'MP3 player', 'Power bank', 'SD card', 'USB stick', 'Charger plug', 'Charging cable',
  'Phone case', 'International plug adapter', 'Air-con pay-as-you-go switch unit',
  'TomTom sat nav', 'Waze auto device', 'Tello SIM (USA)', 'US Mobile SIM (USA)',
  'Replacement screen', 'Phone battery', 'CD',
];

/**
 * The inventory rows, on their own so a facet change repaints the table rather
 * than the tab. renderShopTab() refetches the shop, returns and goods-in — on
 * every keystroke that would be three requests and a lost cursor.
 */
function shopRowsHtml() {
  const active = shopItems.filter(i => i.active);
  const faceted = active.filter(i => matchStockItem(i, shopFacets));
  const shopShown = kcViewApply('shop', faceted);
  if (shopShown.length === 0) {
    const narrowed = active.length > 0;
    return `<tr><td colspan="7"><div class="empty-state"><div class="emoji kc-ic kc-ic-bag"></div>
      <p>${narrowed ? 'No stock matches this view.' : 'No stock yet — add your first item.'}</p>
      ${narrowed && shopFacetsActive()
        ? '<button class="btn btn-outline btn-sm" style="margin-top:10px;" onclick="shopClearFacets()">✕ Clear the filters</button>'
        : (narrowed ? kcClearFiltersBtn('shop') : '')}</div></td></tr>`;
  }
  return shopShown.map(i => `
      <tr class="${i.quantity <= i.lowStockAt ? 'row-lowstock' : ''}">
        <td><strong>${escHtml([i.company, i.model].filter(Boolean).join(' '))}</strong>
          <div class="customer-email">${escHtml(i.code || '')}</div></td>
        <td>${STOCK_CATEGORY_LABELS[i.category] || escHtml(i.category)}</td>
        <td style="color:var(--muted);">${i.netPrice === null ? '—' : fmtGbp(i.netPrice)}</td>
        <td><strong>${fmtGbp((i.sellingPrice || 0))}</strong></td>
        <td style="color:${i.profit === null ? 'var(--muted)' : i.profit >= 0 ? 'var(--success)' : 'var(--danger-ink)'};">
          ${i.profit === null ? '—' : fmtGbp(i.profit)}</td>
        <td style="font-weight:700;${i.quantity <= i.lowStockAt ? 'color:var(--danger-ink);' : ''}">${i.quantity}</td>
        <td style="white-space:nowrap;">
          <button class="action-btn kc-ic kc-ic-pound" onclick="openSaleModal('${i.id}')">Sell</button>
          <button class="action-btn kc-ic kc-ic-pencil" aria-label="Edit ${escHtml(i.name || 'item')}" onclick="openStockItemModal('${i.id}')"></button>
        </td>
      </tr>`).join('');
}

function renderShopRows() {
  const tbody = document.getElementById('shopTableBody');
  if (tbody) tbody.innerHTML = shopRowsHtml();
  const count = document.getElementById('shopFacetCount');
  if (count) {
    const active = shopItems.filter(i => i.active);
    const shown = active.filter(i => matchStockItem(i, shopFacets));
    kcListCount(count, shown.length, active.length, 'item');
  }
}

// ── Purchase orders ───────────────────────────────────────────────────────
// The middle of the buy side: suppliers and goods-in were already here, the
// ORDER was not — so "what is on its way, and was it promised for when?" had
// no answer anywhere.
//
// Ordering is not a financial event. Nothing is charged and the shelf does not
// move; only RECEIVING moves stock, through one database function so the
// quantities and the order's status change together or not at all.
let purchaseOrders = [];

const PO_LABEL = {
  draft:     ['Draft', 'badge-rental', 'written up, not sent'],
  ordered:   ['On order', 'badge-sim', 'sent to the supplier, not here yet'],
  received:  ['Received', 'badge-active', 'arrived and on the shelf'],
  cancelled: ['Cancelled', '', 'not coming'],
};

function poRowsHtml() {
  const today = localISO();
  if (!purchaseOrders.length) {
    return `<div style="color:var(--muted);font-size:var(--fs-body);padding:8px 0;">
      Nothing on order. When stock is ordered from a wholesaler, write it here — then receiving it
      puts the quantities straight onto the shelf.</div>`;
  }
  return purchaseOrders.map(po => {
    const [label, cls, why] = PO_LABEL[po.status] || [po.status, '', ''];
    const late = po.status === 'ordered' && po.expectedAt && po.expectedAt < today;
    const total = po.lines.reduce((n, l) => n + (Number(l.qty) || 0) * (Number(l.unitCost) || 0), 0);
    const items = po.lines.reduce((n, l) => n + (Number(l.qty) || 0), 0);
    return `
      <div class="history-item history-flat">
        <div style="flex:1;min-width:0;">
          <div class="history-desc"><strong>${escHtml(po.supplierName || 'Supplier')}</strong>${
            po.reference ? ` — ${escHtml(po.reference)}` : ''}</div>
          <div style="font-size:var(--fs-micro);color:var(--muted);">
            <span class="badge ${cls}" title="${escHtml(why)}">${escHtml(label)}</span>
            ${po.lines.length} line${po.lines.length === 1 ? '' : 's'} · ${items} item${items === 1 ? '' : 's'}
            ${po.expectedAt ? ` · ${late ? '<strong style="color:var(--danger-ink);">due ' + fmtDate(po.expectedAt) + ' — late</strong>' : 'due ' + fmtDate(po.expectedAt)}` : ''}
            ${po.receivedAt ? ` · arrived ${fmtDate(po.receivedAt)}` : ''}
          </div>
        </div>
        <div class="history-amount" style="margin:0 10px;">${total ? fmtGbp(total) : '—'}</div>
        <div class="row-actions">
          ${po.status === 'draft' ? `<button class="action-btn kc-ic kc-ic-upload" onclick="poSetStatus('${escJs(po.id)}','ordered')">Mark ordered</button>` : ''}
          ${po.status === 'ordered' ? `<button class="action-btn kc-ic kc-ic-download" style="color:var(--success);font-weight:600;" onclick="poReceive('${escJs(po.id)}')">Receive</button>` : ''}
          ${po.status === 'draft' || po.status === 'ordered'
            ? kcRowMenuHtml([{ label: '✕ Cancel this order', onclick: `poSetStatus('${escJs(po.id)}','cancelled')`, danger: true }], { label: 'More for this order' })
            : ''}
        </div>
      </div>`;
  }).join('');
}

let poLines = [];

function openPurchaseOrderModal() {
  if (!suppliers.length) {
    toast('Add a supplier first — the Returns panel below has the box for it.', 'warning');
    return;
  }
  poLines = [{ stockItemId: '', qty: 1, unitCost: '' }];
  showDynamicModal(`
    <div class="modal-title kc-ic kc-ic-package">New purchase order</div>
    <div style="font-size:var(--fs-small);color:var(--muted);margin-bottom:12px;">
      What has been ordered from a wholesaler. Nothing is charged and the shelf does not move —
      receiving it later is what puts the quantities on.</div>
    <div class="form-grid">
      <div class="form-group">
        <label class="form-label" for="poSupplier">Supplier *</label>
        <select class="form-input" id="poSupplier">
          ${suppliers.filter(x => x.active !== false).map(x => `<option value="${escHtml(x.id)}">${escHtml(x.name)}</option>`).join('')}
        </select>
      </div>
      <div class="form-group">
        <label class="form-label" for="poRef">Their reference</label>
        <input class="form-input" id="poRef" type="text" placeholder="e.g. INV-4471" autocomplete="off">
      </div>
      <div class="form-group">
        <label class="form-label" for="poExpected">Expected</label>
        <input class="form-input" id="poExpected" type="date">
      </div>
      <div class="form-group form-full">
        <div class="section-divider" style="margin-bottom:8px;">What was ordered</div>
        <div id="poLines"></div>
        <button type="button" class="kc-add-more" onclick="poAddLine()">+ Add another line</button>
      </div>
      <div class="form-group form-full">
        <label class="form-label" for="poNotes">Notes</label>
        <input class="form-input" id="poNotes" type="text" placeholder="Anything to remember about this order" autocomplete="off">
      </div>
    </div>
    <div class="modal-actions">
      <span class="modal-actions-group">
        <button class="btn btn-outline" onclick="closeDynamicModal()">Cancel</button>
        <button class="btn btn-outline" onclick="poSave('draft')">Save as draft</button>
        <button class="btn btn-primary kc-ic kc-ic-upload" onclick="poSave('ordered')">Save &amp; mark ordered</button>
      </span>
    </div>
  `);
  poRenderLines();
}

function poRenderLines() {
  const box = document.getElementById('poLines');
  if (!box) return;
  const items = shopItems.filter(i => i.active);
  box.innerHTML = poLines.map((l, i) => `
    <div class="po-line">
      <select class="form-input" aria-label="Item" onchange="poLineSet(${i},'stockItemId',this.value)">
        <option value="">— free text —</option>
        ${items.map(it => `<option value="${escHtml(it.id)}"${l.stockItemId === it.id ? ' selected' : ''}>${
          escHtml([it.company, it.model].filter(Boolean).join(' '))}</option>`).join('')}
      </select>
      <input class="form-input" placeholder="or describe it" value="${escHtml(l.description || '')}"
        aria-label="Description" oninput="poLineSet(${i},'description',this.value)">
      <input class="form-input po-qty" type="number" min="1" step="1" value="${escHtml(String(l.qty))}"
        aria-label="Quantity" oninput="poLineSet(${i},'qty',this.value)">
      <input class="form-input po-cost" type="number" min="0" step="0.01" placeholder="£ each" value="${escHtml(String(l.unitCost ?? ''))}"
        aria-label="Cost each" oninput="poLineSet(${i},'unitCost',this.value)">
      ${poLines.length > 1 ? `<button type="button" class="action-btn danger" aria-label="Remove this line" onclick="poRemoveLine(${i})">✕</button>` : ''}
    </div>`).join('');
}
function poLineSet(i, key, value) { if (poLines[i]) poLines[i][key] = value; }
function poAddLine() { poLines.push({ stockItemId: '', qty: 1, unitCost: '' }); poRenderLines(); }
function poRemoveLine(i) { poLines.splice(i, 1); poRenderLines(); }

async function poSave(status) {
  const payload = {
    supplierId: document.getElementById('poSupplier')?.value,
    reference: document.getElementById('poRef')?.value || '',
    expectedAt: document.getElementById('poExpected')?.value || '',
    notes: document.getElementById('poNotes')?.value || '',
    status,
    lines: poLines.map(l => ({
      stockItemId: l.stockItemId || null,
      description: l.description || '',
      qty: parseInt(l.qty, 10),
      unitCost: l.unitCost === '' ? null : parseFloat(l.unitCost),
    })),
  };
  const res = await kcFetch('/api/purchase-orders', {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload),
  }).then(r => r.json()).catch(() => null);
  if (!res || !res.success) { toast(res?.error || 'Could not save that order.', 'error'); return; }
  closeDynamicModal();
  toast(status === 'ordered' ? 'Order saved and marked as ordered.' : 'Draft order saved.', 'success');
  renderShopTab();
}

async function poSetStatus(id, status) {
  const res = await kcFetch('/api/purchase-orders', {
    method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ id, status }),
  }).then(r => r.json()).catch(() => null);
  if (!res || !res.success) { toast(res?.error || 'Could not update that order.', 'error'); return; }
  toast(status === 'cancelled' ? 'Order cancelled.' : 'Marked as ordered.', 'success');
  renderShopTab();
}

// Receiving is the one step that moves stock, so it asks first and says
// exactly what will land on the shelf.
async function poReceive(id) {
  const po = purchaseOrders.find(x => x.id === id);
  if (!po) return;
  const onShelf = po.lines.filter(l => l.stockItemId);
  const names = onShelf.map(l => {
    const it = shopItems.find(x => x.id === l.stockItemId);
    return `${l.qty} × ${escHtml(it ? [it.company, it.model].filter(Boolean).join(' ') : 'an item')}`;
  });
  const ok = await kcConfirm({
    title: 'Everything on this order arrived?',
    body: names.length
      ? `This adds to the shelf:<br><strong>${names.join('<br>')}</strong>${
          po.lines.length > onShelf.length ? `<br><span style="color:var(--muted);">${po.lines.length - onShelf.length} free-text line(s) are not counted — add those by hand.</span>` : ''}`
      : 'None of these lines is linked to a stock item, so nothing will be added to the shelf — the order just closes.',
    okLabel: 'Receive it',
  });
  if (!ok) return;
  const res = await kcFetch('/api/purchase-orders', {
    method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ id, status: 'received' }),
  }).then(r => r.json()).catch(() => null);
  if (!res || !res.success) { toast(res?.error || 'Could not receive that order.', 'error'); return; }
  toast('Received — the stock is on the shelf.', 'success');
  renderShopTab();
}

async function renderShopTab() {
  const content = document.getElementById('mainContent');
  kcSkeleton('shop');
  const [data, retData, giData] = await Promise.all([
    kcFetch('/api/shop').then(r => r.json()).catch(() => null),
    // Returns and goods-in are additive: if either fetch fails the shop still renders.
    kcFetch('/api/supplier-returns').then(r => r.json()).catch(() => null),
    kcFetch('/api/goods-in').then(r => r.json()).catch(() => null),
  ]);
  if (!data || !data.success) {
    content.innerHTML = errorHtml(data?.error || 'Couldn’t load the shop');
    return;
  }
  shopItems = data.items; shopSales = data.sales;
  if (retData?.success) { suppliers = retData.suppliers; supplierReturns = retData.returns; }
  const poData = await kcFetch('/api/purchase-orders').then(r => r.json()).catch(() => null);
  // Shape-checked, not just success-checked: a success with no orders array
  // would blank the list and throw on the next render. (The offline harness
  // answers unknown paths with a bare {success:true}, which is exactly that
  // case, and is how this was caught rather than shipped.)
  if (Array.isArray(poData?.orders)) purchaseOrders = poData.orders;
  if (giData?.success) { goodsIn = giData.deliveries; goodsInBalances = giData.balances; }

  const today = localISO();
  const active = shopItems.filter(i => i.active);
  const inStock = active.reduce((s, i) => s + i.quantity, 0);
  const low = active.filter(i => i.quantity <= i.lowStockAt);
  const todaySales = shopSales.filter(s => (s.createdAt || '').slice(0, 10) === today);
  const revenue = shopSales.reduce((s, x) => s + x.total, 0);

  const lowBanner = low.length ? `
    <div class="banner-lowstock">
      <i class="kc-ic kc-ic-alert" aria-hidden="true"></i> <strong>Low stock:</strong> ${low.map(i => `${escHtml(i.model)} (${i.quantity} left)`).join(' · ')}
    </div>` : '';

  const shopBar = kcFilterSort('shop', [
    { value: 'all', label: 'Filter: all stock' },
    { value: 'low', label: '⚠ Low / out of stock', test: i => i.quantity <= i.lowStockAt },
    { value: 'instock', label: 'In stock', icon: 'package', test: i => i.quantity > 0 },
  ], [
    { value: 'name', label: 'Sort: Name A–Z', cmp: kcCmpStr(i => [i.company, i.model].filter(Boolean).join(' ')) },
    { value: 'qty_asc', label: 'Qty (low→high)', cmp: (a, b) => (a.quantity || 0) - (b.quantity || 0) },
    { value: 'qty_desc', label: 'Qty (high→low)', cmp: kcCmpNum(i => i.quantity || 0) },
    { value: 'price', label: 'Price (high–low)', cmp: kcCmpNum(i => i.sellingPrice || 0) },
    { value: 'profit', label: 'Profit (high–low)', cmp: kcCmpNum(i => i.profit || 0) },
  ], renderShopTab);
  const itemRows = shopRowsHtml();

  // Returns to supplier: open ones first (the bag by the counter), then the
  // last few settled ones for reference. Money shown is a claim, not ledger.
  const openReturns = supplierReturns.filter(r => SUPPLIER_RETURN_OPEN.includes(r.status));
  const doneReturns = supplierReturns.filter(r => !SUPPLIER_RETURN_OPEN.includes(r.status));
  const openClaim = openReturns.reduce((s, r) => s + (r.claimedValue || 0), 0);
  const returnRow = (r) => {
    const st = SUPPLIER_RETURN_STATUS[r.status] || { label: r.status, color: 'var(--muted)' };
    return `
      <div class="history-item history-flat">
        <div style="flex:1;min-width:0;">
          <div class="history-desc"><strong>${escHtml(r.supplierName || '?')}</strong> — ${escHtml(r.items)}</div>
          <div style="font-size:var(--fs-micro);color:var(--muted);">
            <span style="color:${st.color};font-weight:600;">${st.label}</span>
            ${r.sentAt ? ' · sent ' + fmtDate(r.sentAt) : ''}${r.resolvedAt ? ' · settled ' + fmtDate(r.resolvedAt) : ''}
            ${r.notes ? ' · ' + escHtml(r.notes) : ''}
          </div>
        </div>
        <div class="history-amount" style="margin:0 10px;">${r.claimedValue === null ? '—' : fmtGbp(r.claimedValue)}</div>
        <button class="action-btn" aria-label="Manage return to ${escHtml(r.supplierName || 'supplier')}"
          onclick="openSupplierReturnModal('${r.id}')" title="Edit this return"></button>
      </div>`;
  };
  const returnRows = supplierReturns.length === 0
    ? `<div style="color:var(--muted);font-size:var(--fs-body);padding:8px 0;">Nothing waiting to go back. When defective stock has to return to a wholesaler, record it here so it isn't forgotten.</div>`
    : openReturns.map(returnRow).join('') + doneReturns.slice(0, 5).map(returnRow).join('');

  // Goods in: recent deliveries with a paid/unpaid toggle, headed by the
  // per-supplier balance line ("we owe" = unpaid invoices − credit notes).
  const oweEntries = suppliers
    .map(s => ({ name: s.name, owed: goodsInBalances[s.id] || 0 }))
    .filter(e => Math.abs(e.owed) >= 0.005);
  const totalOwed = oweEntries.reduce((s, e) => s + e.owed, 0);
  const balanceLine = oweEntries.length
    ? `<div style="font-size:var(--fs-small);margin:2px 0 8px;color:var(--muted);">
        ${oweEntries.map(e => `${escHtml(e.name)}: <strong style="color:${e.owed > 0 ? 'var(--danger-ink)' : 'var(--success-ink)'};">${e.owed > 0 ? fmtGbp(e.owed) + ' owed' : fmtGbp(-e.owed) + ' credit'}</strong>`).join(' · ')}
      </div>` : '';
  const deliveryRow = (d) => `
    <div class="history-item history-flat">
      <div style="flex:1;min-width:0;">
        <div class="history-desc"><strong>${escHtml(d.supplierName || '?')}</strong>${d.invoiceRef ? ' — ' + escHtml(d.invoiceRef) : ''}
          — ${d.lines.map(l => `${l.qty}× ${escHtml(l.description)}`).join(', ')}</div>
        <div style="font-size:var(--fs-micro);color:var(--muted);">
          ${fmtDate(d.deliveryDate)}${d.paid ? ` · <span class="kc-ic kc-ic-check" style="color:var(--success-ink);font-weight:600;">Paid${d.paidAt ? ' ' + fmtDate(d.paidAt) : ''}</span>` : d.invoiceTotal !== null ? ' · <span style="color:var(--warning-ink);font-weight:600;"><i class="kc-ic kc-ic-hourglass" aria-hidden="true"></i> Unpaid</span>' : ''}
          ${d.notes ? ' · ' + escHtml(d.notes) : ''}
        </div>
      </div>
      <div class="history-amount" style="margin:0 10px;">${d.invoiceTotal === null ? '—' : fmtGbp(d.invoiceTotal)}</div>
      ${d.invoiceTotal !== null ? `<button class="action-btn" aria-label="Mark delivery from ${escHtml(d.supplierName || 'supplier')} ${d.paid ? 'unpaid' : 'paid'}"
        onclick="markGoodsInPaid('${d.id}', ${d.paid ? 'false' : 'true'})">${d.paid ? '<i class="kc-ic kc-ic-undo" aria-hidden="true"></i>' : '<i class="kc-ic kc-ic-pound" aria-hidden="true"></i> Pay'}</button>` : ''}
    </div>`;
  const goodsRows = goodsIn.length === 0
    ? `<div style="color:var(--muted);font-size:var(--fs-body);padding:8px 0;">No deliveries recorded yet. When stock arrives from a wholesaler, record it here — quantities and cost prices update themselves.</div>`
    : goodsIn.slice(0, 8).map(deliveryRow).join('');
  const unpaidCount = goodsIn.filter(d => !d.paid && d.invoiceTotal !== null).length;

  const saleRows = shopSales.length === 0
    ? `<div style="color:var(--muted);font-size:var(--fs-body);padding:8px 0;">No sales recorded yet.</div>`
    : shopSales.slice(0, 25).map(s => `
      <div class="history-item history-flat">
        <div style="flex:1;min-width:0;">
          <div class="history-desc"><strong>${escHtml(s.item)}</strong>${s.qty > 1 ? ` × ${s.qty}` : ''} — ${escName(s.customerName || 'Walk-in')}</div>
          <div style="font-size:var(--fs-micro);color:var(--muted);">${s.imei ? 'IMEI ' + escHtml(s.imei) + ' · ' : ''}${escHtml(s.notes || '')}</div>
        </div>
        <div class="history-date" style="margin:0 12px;">${fmtDate(s.createdAt)}</div>
        <div class="history-amount">${fmtGbp(s.total)}</div>
      </div>`).join('');

  content.innerHTML = `
    <div class="stats-row">
      <div class="stat-card"><div class="stat-label">Units in stock</div><div class="stat-value">${inStock}</div></div>
      <div class="stat-card"><div class="stat-label">Low stock</div>
        <div class="stat-value" style="color:${low.length ? 'var(--danger-ink)' : 'var(--success)'};">${low.length}</div></div>
      <div class="stat-card"><div class="stat-label">Sold today</div>
        <div class="stat-value">${fmtGbp(todaySales.reduce((s, x) => s + x.total, 0))}</div>
        <div class="stat-sub">${todaySales.length} sale${todaySales.length === 1 ? '' : 's'}</div></div>
      <div class="stat-card"><div class="stat-label">All-time sales</div><div class="stat-value">${fmtGbp(revenue)}</div></div>
    </div>
    ${lowBanner}
    <div style="display:flex;gap:10px;margin-bottom:14px;flex-wrap:wrap;">
      <button class="btn btn-primary kc-ic kc-ic-receipt" onclick="openSaleModal()">Open till</button>
      <button class="btn btn-outline kc-ic kc-ic-money" onclick="openCashupModal()">Cash up</button>
      <button class="btn btn-outline kc-ic kc-ic-plus" onclick="openStockItemModal()">Add item</button>
      <button class="btn btn-outline kc-ic kc-ic-undo" onclick="openSupplierReturnModal()">Return to supplier</button>
      <button class="btn btn-outline kc-ic kc-ic-package" onclick="openGoodsInModal()">Goods in</button>
    </div>
    <div class="dash-cols dash-cols-table">
      <div class="table-card">
        <div style="padding:0 14px;">
          ${/* The count sits with the HEADING, the way "Customer List 569" and
                "Phone Inventory 4" do. In the controls row it needed an auto
                margin to hold the right edge, which pushed "Save view" onto a
                line of its own — an orphaned button under a row of filters,
                which is the shape of the complaint this whole change is
                answering. */''}
          <div class="section-divider" style="margin:12px 0 4px;">Inventory
            <span id="shopFacetCount" style="font-size:var(--fs-small);color:var(--muted);font-weight:400;margin-left:8px;text-transform:none;letter-spacing:0;">${active.length} item${active.length === 1 ? '' : 's'}</span></div>
        </div>
        ${/* Narrow by several things at once, the way the Lightspeed products
             screen does. Each control repaints the table in place — the search
             box especially, which would otherwise refetch the whole tab and
             lose the cursor on every keystroke.
             ONE ROW, not two. The shared filter/sort control used to ride on the
             right of the "Inventory" heading while the search and the two facets
             sat underneath — two sets of controls for one list, in two rows that
             did not line up, and the owner's screenshot on 28 Aug has an arrow
             pointing at each of them. They are one thought to whoever is using
             them, so they are one row now: narrow it, then order it, then how
             many are left. */''}
        <div class="kc-facets">
          <input class="form-input kc-facet-q" id="shopFacetQ" type="search" autocomplete="off"
            placeholder="Item, code or barcode…" value="${escHtml(shopFacets.q)}"
            oninput="shopSetFacet('q', this.value)">
          <select class="form-input" id="shopFacetCat" aria-label="Category" onchange="shopSetFacet('category', this.value)">
            <option value="all">Every category</option>
            ${stockCategories().map(([k, label]) =>
              `<option value="${escHtml(k)}"${shopFacets.category === k ? ' selected' : ''}>${escHtml(label)}</option>`).join('')}
          </select>
          <select class="form-input" id="shopFacetBrand" aria-label="Brand" onchange="shopSetFacet('brand', this.value)">
            <option value="all">Every brand</option>
            ${stockBrands(active).map(bnd =>
              `<option value="${escHtml(bnd)}"${shopFacets.brand === bnd ? ' selected' : ''}>${escHtml(bnd)}</option>`).join('')}
          </select>
          ${shopBar}
          ${shopFacetsActive() ? '<button class="btn btn-outline btn-sm" onclick="shopClearFacets()">✕ Clear</button>' : ''}
        </div>
        <table>
          <thead><tr><th>Item</th><th>Category</th><th>Cost</th><th>Price</th><th>Profit</th><th>Qty</th><th></th></tr></thead>
          <tbody id="shopTableBody">${itemRows}</tbody>
        </table>
      </div>
      <div>
        <div class="table-card" style="padding:8px 18px 14px;margin-bottom:14px;">
          <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;">
            <div class="section-divider" style="margin-top:12px;">On order</div>
            <button class="btn btn-outline btn-sm kc-ic kc-ic-package" onclick="openPurchaseOrderModal()">New order</button>
          </div>
          ${poRowsHtml()}
        </div>

        <div class="table-card" id="shopReturns" style="padding:8px 18px 14px;margin-bottom:14px;">
          <div class="section-divider" style="margin-top:12px;">Returns to supplier${openReturns.length
            ? ` <span style="color:var(--danger-ink);font-weight:600;">· ${openReturns.length} open${openClaim ? ' · ' + fmtGbp(openClaim) + ' claimed' : ''}</span>` : ''}</div>
          <div>${returnRows}</div>
        </div>
        <div class="table-card" style="padding:8px 18px 14px;margin-bottom:14px;">
          <div class="section-divider" style="margin-top:12px;">Goods in${totalOwed > 0.005
            ? ` <span style="color:var(--danger-ink);font-weight:600;">· ${fmtGbp(totalOwed)} owed${unpaidCount ? ` · ${unpaidCount} invoice${unpaidCount === 1 ? '' : 's'}` : ''}</span>` : ''}</div>
          ${balanceLine}
          <div>${goodsRows}</div>
        </div>
        <div class="table-card" style="padding:8px 18px 14px;">
          <div class="section-divider" style="margin-top:12px;">Recent sales</div>
          <div>${saleRows}</div>
        </div>
      </div>
    </div>`;
}

// ── Returns to supplier (RMA) — create + manage in one modal ──
function openSupplierReturnModal(retId = null) {
  const r = retId ? supplierReturns.find(x => x.id === retId) : null;
  if (!r) srPicked = []; // a fresh return starts with an empty list
  const supplierOptions = suppliers.filter(s => s.active || (r && s.id === r.supplierId))
    .map(s => `<option value="${s.id}" ${r?.supplierId === s.id ? 'selected' : ''}>${escHtml(s.name)}</option>`).join('');
  showDynamicModal(`
    <div class="modal-title">${r ? '<i class="kc-ic kc-ic-upload" aria-hidden="true"></i> Manage Return' : '<i class="kc-ic kc-ic-upload" aria-hidden="true"></i> Return to Supplier'}</div>
    <div class="form-grid">
      <div class="form-group form-full">
        <label class="form-label">Supplier *</label>
        <select class="form-input" id="srSupplier" onchange="document.getElementById('srNewSupplierWrap').style.display = this.value === '__new' ? '' : 'none'">
          ${supplierOptions}
          <option value="__new" ${suppliers.length === 0 ? 'selected' : ''}>➕ New supplier…</option>
        </select>
      </div>
      <div class="form-group form-full" id="srNewSupplierWrap" style="${suppliers.length === 0 && !r ? '' : 'display:none;'}">
        <label class="form-label">New supplier name *</label>
        <input class="form-input" id="srNewSupplier" placeholder="e.g. TechTrade Wholesale">
      </div>
      ${r ? `
      <div class="form-group form-full">
        <label class="form-label">What's going back *</label>
        <textarea class="form-input" id="srItems" rows="2"
          placeholder="e.g. 6× Nokia 105, screens dead">${escHtml(r?.items || '')}</textarea>
      </div>` : `
      <div class="form-group form-full">
        <label class="form-label">What's going back *</label>
        <!-- A PICKER, not a text box (owner, 23 Aug): "it should only let
             anything which is already in stock and only the amount we have."
             A return of six phones the shelf never held is a claim the
             supplier will bounce and the stock count cannot absorb. Only
             active items with quantity > 0 are offered, and the amount is
             clamped to the shelf. Free prose stays where it belongs — the
             fault goes in Notes. Editing an OLDER return keeps the plain text
             above: its lines were written before the picker existed, and
             rewriting history is not this form's job. -->
        <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;">
          <select class="form-input" id="srPickItem" style="flex:1;min-width:170px;" onchange="srPickClamp()">
            ${shopItems.filter(i => i.active && (i.quantity || 0) > 0).map(i =>
              `<option value="${escHtml(String(i.id))}" data-max="${i.quantity}">${escHtml(`${i.company || ''} ${i.model || ''}`.trim())} — ${i.quantity} in stock</option>`).join('')
            || '<option value="">Nothing is in stock to return</option>'}
          </select>
          <input class="form-input" type="number" id="srPickQty" min="1" step="1" value="1" style="width:84px;" aria-label="How many to return" title="How many to return" onchange="srPickClamp()">
          <button class="btn btn-outline" onclick="srPickAdd()">＋ Add</button>
        </div>
        <div id="srLines" style="display:grid;gap:4px;margin-top:8px;"></div>
      </div>`}
      <div class="form-group form-full">
        <label class="form-label">IMEIs <span style="color:var(--muted);font-weight:400;">(optional, one per line)</span></label>
        <textarea class="form-input" id="srImeis" rows="2" style="direction:ltr;">${escHtml(r?.imeis || '')}</textarea>
      </div>
      <div class="form-group">
        <label class="form-label">Claimed value £</label>
        <input class="form-input" type="number" step="0.01" min="0" id="srValue" value="${r?.claimedValue ?? ''}">
      </div>
      ${r ? `
      <div class="form-group">
        <label class="form-label">Status</label>
        <select class="form-input" id="srStatus">
          ${Object.entries(SUPPLIER_RETURN_STATUS).map(([k, v]) =>
            `<option value="${k}" ${r.status === k ? 'selected' : ''}>${v.label}</option>`).join('')}
        </select>
      </div>` : `
      <div class="form-group">
        <label class="form-label">&nbsp;</label>
        <div style="font-size:var(--fs-small);color:var(--muted);padding-top:8px;">Starts as “<i class="kc-ic kc-ic-package" aria-hidden="true"></i> To send”.</div>
      </div>`}
      <div class="form-group form-full">
        <label class="form-label">Notes</label>
        <input class="form-input" id="srNotes" value="${escHtml(r?.notes || '')}" placeholder="courier ref, who agreed the return…">
      </div>
    </div>
    <div class="modal-actions">
      <button class="btn btn-outline" onclick="closeDynamicModal()">Cancel</button>
      <button class="btn btn-primary kc-ic kc-ic-save" onclick="saveSupplierReturn(${r ? `'${r.id}'` : 'null'})">Save</button>
    </div>
  `);
}

// The picker's lines for a NEW return. Serialised into the same `items` text
// the API has always stored — the constraint lives at ENTRY, where it can
// still be answered, and nothing downstream changes shape.
let srPicked = [];
function srPickClamp() {
  const sel = document.getElementById('srPickItem');
  const qty = document.getElementById('srPickQty');
  const max = Number(sel?.selectedOptions[0]?.dataset.max || 0);
  if (!qty) return;
  qty.max = max || 1;
  const v = Math.round(Number(qty.value) || 1);
  qty.value = Math.min(Math.max(1, v), Math.max(1, max));
}
function srPickAdd() {
  const sel = document.getElementById('srPickItem');
  const id = sel?.value;
  const item = shopItems.find(x => String(x.id) === String(id));
  if (!item) return;
  srPickClamp();
  const qty = Math.round(Number(document.getElementById('srPickQty')?.value) || 1);
  const already = srPicked.find(l => String(l.id) === String(id));
  const onShelf = item.quantity || 0;
  // The cap counts what is ALREADY on this return: two lines of 3 against a
  // shelf of 4 is the same over-claim as one line of 6.
  const room = onShelf - (already ? already.qty : 0);
  if (qty > room) { toast(`Only ${onShelf} on the shelf${already ? ` and ${already.qty} already on this return` : ''}.`, 'warning'); return; }
  if (already) already.qty += qty;
  else srPicked.push({ id: item.id, code: item.code || '', name: `${item.company || ''} ${item.model || ''}`.trim(), qty });
  srPickRender();
}
function srPickRemove(i) { srPicked.splice(i, 1); srPickRender(); }
function srPickRender() {
  const el = document.getElementById('srLines');
  if (!el) return;
  el.innerHTML = srPicked.map((l, i) => `
    <div style="display:flex;gap:8px;align-items:center;font-size:var(--fs-body);padding:4px 8px;background:var(--bg-secondary);border-radius:6px;">
      <strong>${l.qty}×</strong><span style="flex:1;">${escHtml(l.name)}${l.code ? ` <span style="color:var(--muted);">(${escHtml(l.code)})</span>` : ''}</span>
      <button class="btn btn-outline btn-sm" style="min-height:0;padding:2px 8px;" onclick="srPickRemove(${i})" aria-label="Remove ${escHtml(l.name)}">✕</button>
    </div>`).join('');
}

async function saveSupplierReturn(retId) {
  // New returns carry the picker's lines; edits keep their original text.
  let srItemsText = '';
  if (!retId) {
    if (!srPicked.length) { toast('Add what is going back — pick the item and the amount.', 'warning'); return; }
    srItemsText = srPicked.map(l => `${l.qty}× ${l.name}${l.code ? ` (${l.code})` : ''}`).join(', ');
  }
  let supplierId = document.getElementById('srSupplier').value;
  if (supplierId === '__new') {
    const name = document.getElementById('srNewSupplier').value.trim();
    if (!name) { toast('Give the new supplier a name.', 'error'); return; }
    const res = await kcFetch('/api/supplier-returns', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ op: 'supplier', name }),
    }).then(r => r.json()).catch(() => null);
    if (!res || !res.success) { toast(res?.error || 'Could not add the supplier.', 'error'); return; }
    supplierId = res.supplier.id;
  }
  const payload = {
    op: 'return',
    supplierId,
    items: retId ? document.getElementById('srItems').value.trim() : srItemsText,
    imeis: document.getElementById('srImeis').value.trim(),
    claimedValue: document.getElementById('srValue').value === '' ? null : parseFloat(document.getElementById('srValue').value),
    notes: document.getElementById('srNotes').value.trim(),
  };
  if (!payload.items) { toast('Say what is going back.', 'error'); return; }
  if (retId) {
    payload.id = retId;
    payload.status = document.getElementById('srStatus').value;
    delete payload.supplierId; // v1: a return stays with the supplier it was recorded against
  }
  const res = await kcFetch('/api/supplier-returns', {
    method: retId ? 'PUT' : 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  }).then(r => r.json()).catch(() => null);
  if (!res || !res.success) { toast(res?.error || 'Could not save the return.', 'error'); return; }
  closeDynamicModal();
  toast(retId ? 'Return updated.' : 'Return recorded — it will nag from the dashboard until settled.', 'success');
  renderShopTab();
}

// ── Goods in — record a delivery; linked lines bump stock + cost ──
function giLineRowHtml(idx) {
  const itemOptions = shopItems.filter(i => i.active)
    .map(i => `<option value="${i.id}">${escHtml([i.company, i.model].filter(Boolean).join(' '))}</option>`).join('');
  return `
    <div class="gi-line" style="display:flex;gap:6px;margin-bottom:6px;flex-wrap:wrap;">
      <select class="form-input" data-gi="item" style="flex:2;min-width:130px;" aria-label="Stock item for line ${idx + 1}"
        onchange="giItemPicked(this)">
        <option value="">✍️ Not in stock list</option>
        ${itemOptions}
      </select>
      <input class="form-input" data-gi="desc" style="flex:3;min-width:140px;" placeholder="What arrived *" aria-label="Description for line ${idx + 1}">
      <input class="form-input" data-gi="qty" type="number" min="1" step="1" value="1" style="width:64px;" aria-label="Quantity for line ${idx + 1}">
      <input class="form-input" data-gi="cost" type="number" min="0" step="0.01" placeholder="£/unit" style="width:88px;" aria-label="Unit cost for line ${idx + 1}">
    </div>`;
}

function giItemPicked(sel) {
  const item = shopItems.find(i => i.id === sel.value);
  const row = sel.closest('.gi-line');
  const desc = row.querySelector('[data-gi="desc"]');
  const cost = row.querySelector('[data-gi="cost"]');
  if (item) {
    if (!desc.value.trim()) desc.value = [item.company, item.model].filter(Boolean).join(' ');
    if (!cost.value && item.netPrice !== null) cost.value = item.netPrice;
  }
}

function giAddLine() {
  const wrap = document.getElementById('giLines');
  wrap.insertAdjacentHTML('beforeend', giLineRowHtml(wrap.querySelectorAll('.gi-line').length));
}

function openGoodsInModal() {
  const supplierOptions = suppliers.filter(s => s.active)
    .map(s => `<option value="${s.id}">${escHtml(s.name)}</option>`).join('');
  showDynamicModal(`
    <div class="modal-title kc-ic kc-ic-download">Goods In</div>
    <div class="form-grid">
      <div class="form-group">
        <label class="form-label">Supplier *</label>
        <select class="form-input" id="giSupplier" onchange="document.getElementById('giNewSupplierWrap').style.display = this.value === '__new' ? '' : 'none'">
          ${supplierOptions}
          <option value="__new" ${suppliers.length === 0 ? 'selected' : ''}>➕ New supplier…</option>
        </select>
      </div>
      <div class="form-group">
        <label class="form-label">Delivery date</label>
        <input class="form-input" type="date" id="giDate" value="${localISO()}">
      </div>
      <div class="form-group form-full" id="giNewSupplierWrap" style="${suppliers.length === 0 ? '' : 'display:none;'}">
        <label class="form-label">New supplier name *</label>
        <input class="form-input" id="giNewSupplier" placeholder="e.g. TechTrade Wholesale">
      </div>
      <div class="form-group form-full">
        <label class="form-label">Lines * <span style="color:var(--muted);font-weight:400;">(pick a stock item to update its quantity and cost, or free-type)</span></label>
        <div id="giLines">${giLineRowHtml(0)}</div>
        <button type="button" class="btn btn-outline" style="padding:4px 10px;font-size:var(--fs-small);" onclick="giAddLine()">Add line</button>
      </div>
      <div class="form-group">
        <label class="form-label">Invoice ref</label>
        <input class="form-input" id="giRef" placeholder="INV-1234">
      </div>
      <div class="form-group">
        <label class="form-label">Invoice total £</label>
        <input class="form-input" type="number" step="0.01" min="0" id="giTotal">
      </div>
      <div class="form-group form-full">
        <label class="form-label" style="display:flex;align-items:center;gap:8px;">
          <input type="checkbox" id="giPaid"> Already paid
        </label>
      </div>
      <div class="form-group form-full">
        <label class="form-label">Notes</label>
        <input class="form-input" id="giNotes" placeholder="who delivered, part-order…">
      </div>
    </div>
    <div class="modal-actions">
      <button class="btn btn-outline" onclick="closeDynamicModal()">Cancel</button>
      <button class="btn btn-primary kc-ic kc-ic-save" onclick="saveGoodsIn()">Save</button>
    </div>
  `);
}

async function saveGoodsIn() {
  let supplierId = document.getElementById('giSupplier').value;
  if (supplierId === '__new') {
    const name = document.getElementById('giNewSupplier').value.trim();
    if (!name) { toast('Give the new supplier a name.', 'error'); return; }
    const res = await kcFetch('/api/supplier-returns', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ op: 'supplier', name }),
    }).then(r => r.json()).catch(() => null);
    if (!res || !res.success) { toast(res?.error || 'Could not add the supplier.', 'error'); return; }
    supplierId = res.supplier.id;
  }
  const lines = [...document.querySelectorAll('#giLines .gi-line')].map(row => ({
    itemId: row.querySelector('[data-gi="item"]').value || null,
    description: row.querySelector('[data-gi="desc"]').value.trim(),
    qty: row.querySelector('[data-gi="qty"]').value,
    unitCost: row.querySelector('[data-gi="cost"]').value === '' ? null : parseFloat(row.querySelector('[data-gi="cost"]').value),
  })).filter(l => l.description);
  if (!lines.length) { toast('Add at least one line — what arrived?', 'error'); return; }
  const res = await kcFetch('/api/goods-in', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      supplierId,
      deliveryDate: document.getElementById('giDate').value,
      invoiceRef: document.getElementById('giRef').value.trim(),
      invoiceTotal: document.getElementById('giTotal').value === '' ? null : parseFloat(document.getElementById('giTotal').value),
      paid: document.getElementById('giPaid').checked,
      notes: document.getElementById('giNotes').value.trim(),
      lines,
    }),
  }).then(r => r.json()).catch(() => null);
  if (!res || !res.success) { toast(res?.error || 'Could not save the delivery.', 'error'); return; }
  closeDynamicModal();
  toast(res.warning || 'Delivery recorded — stock and costs updated.', res.warning ? 'error' : 'success');
  renderShopTab();
}

async function markGoodsInPaid(id, paid) {
  const res = await kcFetch('/api/goods-in', {
    method: 'PUT', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ id, paid }),
  }).then(r => r.json()).catch(() => null);
  if (!res || !res.success) { toast(res?.error || 'Could not update the invoice.', 'error'); return; }
  toast(paid ? 'Marked paid.' : 'Marked unpaid.', 'success');
  renderShopTab();
}

function openStockItemModal(itemId = null) {
  const i = itemId ? shopItems.find(x => x.id === itemId) : null;
  showDynamicModal(`
    <div class="modal-title">${i ? '<i class="kc-ic kc-ic-pencil" aria-hidden="true"></i> Edit Item' : '<i class="kc-ic kc-ic-plus" aria-hidden="true"></i> Add Stock Item'}</div>
    <div class="form-grid">
      <div class="form-group">
        <label class="form-label">Category</label>
        <select class="form-input" id="siCategory">
          ${stockCategories().map(([k, l]) =>
            `<option value="${escHtml(k)}" ${i?.category === k ? 'selected' : ''}>${escHtml(l)}</option>`).join('')}
        </select>
      </div>
      <div class="form-group">
        <label class="form-label">Code</label>
        <input class="form-input" id="siCode" value="${escHtml(i?.code || '')}" placeholder="e.g. AC-01">
      </div>
      <div class="form-group form-full">
        <label class="form-label">Barcode <span style="color:var(--muted);font-weight:400;">(click, then scan the packaging)</span></label>
        <input class="form-input" id="siBarcode" value="${escHtml(i?.barcode || '')}" placeholder="EAN / UPC"
          inputmode="numeric" autocomplete="off">
      </div>
      <div class="form-group">
        <label class="form-label">Brand / company</label>
        <input class="form-input" id="siCompany" value="${escHtml(i?.company || '')}" placeholder="e.g. Anker">
      </div>
      <div class="form-group">
        <label class="form-label">Model / name *</label>
        <input class="form-input" id="siModel" value="${escHtml(i?.model || '')}" placeholder="e.g. Powerbank 10000" list="siModelList">
        <datalist id="siModelList">${STOCK_TYPE_SUGGESTIONS.map(s => `<option value="${s}">`).join('')}</datalist>
      </div>
      <div class="form-group">
        <label class="form-label">Cost (net) £</label>
        <input class="form-input" type="number" step="0.01" min="0" id="siNet" value="${i?.netPrice ?? ''}">
      </div>
      <div class="form-group">
        <label class="form-label">Selling price £ *</label>
        <input class="form-input" type="number" step="0.01" min="0" id="siSell" value="${i?.sellingPrice ?? ''}">
      </div>
      <div class="form-group">
        <label class="form-label">Quantity</label>
        <input class="form-input" type="number" step="1" min="0" id="siQty" value="${i?.quantity ?? 0}">
      </div>
      <div class="form-group">
        <label class="form-label">Warn when below</label>
        <input class="form-input" type="number" step="1" min="0" id="siLow" value="${i?.lowStockAt ?? 1}">
      </div>
    </div>
    <div class="modal-actions" style="justify-content:space-between;">
      <span>${i ? `<button class="btn btn-outline kc-ic kc-ic-trash" onclick="retireStockItem('${i.id}')">Retire</button>
        <button class="btn btn-outline kc-ic kc-ic-scroll" onclick="openStockStory('${i.id}')" title="Every recorded movement behind this count">Story</button>` : ''}</span>
      <span class="modal-actions-group">
        <button class="btn btn-outline" onclick="closeDynamicModal()">Cancel</button>
        <button class="btn btn-primary kc-ic kc-ic-save" onclick="saveStockItem(${i ? `'${i.id}'` : 'null'})">Save</button>
      </span>
    </div>
  `);
}

async function saveStockItem(itemId) {
  const payload = {
    op: 'item',
    category: document.getElementById('siCategory').value,
    code: document.getElementById('siCode').value.trim(),
    barcode: document.getElementById('siBarcode').value.trim(),
    company: document.getElementById('siCompany').value.trim(),
    model: document.getElementById('siModel').value.trim(),
    netPrice: document.getElementById('siNet').value === '' ? undefined : parseFloat(document.getElementById('siNet').value),
    sellingPrice: parseFloat(document.getElementById('siSell').value),
    quantity: parseInt(document.getElementById('siQty').value, 10) || 0,
    lowStockAt: parseInt(document.getElementById('siLow').value, 10) || 0,
  };
  if (!payload.model) { toast('Model / name is required.', 'error'); return; }
  if (!Number.isFinite(payload.sellingPrice)) { toast('Enter a selling price.', 'error'); return; }
  const res = await kcFetch('/api/shop', {
    method: itemId ? 'PUT' : 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(itemId ? { ...payload, id: itemId } : payload),
  }).then(r => r.json()).catch(() => null);
  if (!res || !res.success) { toast(res?.error || 'Could not save the item.', 'error'); return; }
  closeDynamicModal();
  toast('Item saved.', 'success');
  renderShopTab();
}

// The stock story (E4 from the Epos Now read): every recorded movement behind
// the count — goods in on one side, sales on the other — with the
// reconciliation said in words. Derived from records that already exist
// (lib/stockStory.mjs + the KC_STOCKSTORY mirror), never stored twice; what
// deriving cannot itemise is confessed in the opening figure, and an
// arithmetic that cannot end at the shelf number is called out as a proven
// discrepancy rather than smoothed over.
async function openStockStory(itemId) {
  const item = shopItems.find(x => String(x.id) === String(itemId));
  if (!item) return;
  // The dialog opens BEFORE the read, on the house never-wait rule: a button
  // that answers only after the network answers reads as a button that did
  // nothing, and gets pressed twice. The shell paints now; the records fill it
  // when they land — and only if this dialog is still the one on screen.
  const itemName = escHtml(`${item.company || ''} ${item.model || ''}`.trim() || 'Stock item');
  // STACKED, not the base dialog: the 📜 button lives inside the item-edit
  // form, and showDynamicModal would REPLACE that form — taking a half-typed
  // quantity with it, and dropping the operator back at the tab instead of the
  // edit they were in. The stacked layer closes back onto the form, values
  // intact, which is the whole reason the button is there.
  showStackedModal(`
    <div class="modal-title kc-ic kc-ic-scroll">${itemName} — the story of the count</div>
    <div id="storyBody" data-item="${escHtml(String(itemId))}"><div style="color:var(--muted);font-size:var(--fs-body);">Reading the records…</div></div>
    <div class="modal-actions"><button class="btn btn-outline" onclick="closeStackedModal()">Close</button></div>
  `, { width: 520 });
  const d = await kcFetch('/api/shop?story=' + encodeURIComponent(itemId))
    .then(r => r.json()).catch(() => null);
  const body = document.getElementById('storyBody');
  // Closed, replaced by another dialog, or replaced by ANOTHER ITEM'S story —
  // the last one is the sharp edge: a slow answer for item A must never paint
  // itself under item B's title. The body carries the id it was opened for.
  if (!body || body.dataset.item !== String(itemId)) return;
  if (!d || !d.success) {
    body.innerHTML = `<div style="color:var(--warning-ink);font-size:var(--fs-body);">Could not read the records — check the connection and try again.</div>`;
    return;
  }
  const story = KC_STOCKSTORY.buildStockStory({ quantityNow: item.quantity, sales: d.sales, goodsIn: d.goodsIn });
  const line = KC_STOCKSTORY.stockStoryLine(story, item.quantity);
  const rows = story.moves.map(m => `
    <div style="display:flex;gap:10px;align-items:baseline;padding:5px 0;border-bottom:1px solid var(--border-subtle);font-size:var(--fs-body);">
      <span style="color:var(--muted);font-size:var(--fs-small);min-width:86px;">${escHtml(fmtDate(m.when))}</span>
      <span style="min-width:34px;font-weight:700;${m.kind === 'in' ? 'color:var(--success-ink);' : ''}">${m.kind === 'in' ? '+' : '−'}${m.qty}</span>
      <span style="flex:1;">${escHtml(m.label)}</span>
    </div>`).join('');
  body.innerHTML = `
    <div style="font-size:var(--fs-ui);line-height:1.6;margin-bottom:12px;${story.impossible ? 'color:var(--warning-ink);font-weight:600;' : 'color:var(--muted);'}">${escHtml(line)}</div>
    ${d.capped ? `<div style="font-size:var(--fs-small);color:var(--warning-ink);margin-bottom:8px;">Only the most recent 1,000 of each kind are shown — the reconciliation above may be off by what fell outside them.</div>` : ''}
    <div style="max-height:320px;overflow-y:auto;">${rows || '<div style="color:var(--muted);font-size:var(--fs-body);">Nothing recorded yet.</div>'}</div>`;
}

async function retireStockItem(itemId) {
  const ok = await window.api.confirmDelete('Retire this item?\n\nIt disappears from the shop but past sales keep their history.', 'Retire');
  if (!ok) return;
  const res = await kcFetch('/api/shop', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ op: 'item', id: itemId, active: false }),
  }).then(r => r.json()).catch(() => null);
  if (!res || !res.success) { toast(res?.error || 'Could not retire the item.', 'error'); return; }
  closeDynamicModal();
  toast('Item retired.', 'warning');
  renderShopTab();
}

// ── POS (shopfloor till): full-screen till — scan/tap → receipt → tender ──
let posBasket = []; // [{itemId, qty, imei}]
// null = no category chosen yet (owner, 23 Aug: the till opens on LARGE
// colour-coded category buttons, and an item only shows once its category is
// pressed). Scanning and typing stay the fast path — a query shows its matches
// whatever the category state.
let posCat = null;
let posMethod = 'cash';
let posWallet = 0;  // £ of the sale drawn from the customer's wallet credit (split tender)
// One idempotency token per HANDOVER, minted on the first Charge press and kept
// through failed attempts — a re-ring after a lost response replays the SAME
// token, so the server can dedupe instead of double-charging. Cleared only on
// success/duplicate (and when the till opens fresh).
let posSaleRef = null;
let posLastSale = null; // { total, change } — shown as a banner until the next action

function openSaleModal(preselectItemId = null) { // name kept: every Sell button calls it
  const sellable = shopItems.filter(i => i.active && i.quantity > 0);
  if (!sellable.length) { toast('Nothing in stock to sell — add quantities first.', 'warning'); return; }
  posBasket = preselectItemId ? [{ itemId: preselectItemId, qty: 1, imei: '' }] : [];
  posCat = null;
  posMethod = 'cash';
  posWallet = 0;
  posSaleRef = null;   // fresh till session = fresh handover token
  posLastSale = null;
  kcEposProbe();       // learn (once) whether the cloud terminal lane is on
  renderPosView();
}


function closePosView() {
  document.body.classList.remove('pos-mode');
  // Bounce back to the card the till was OPENED from (owner, 23 Aug: "yes,
  // bounce back to the card when done") — only on the explicit Exit, and only
  // when the visit started at a card. A sidebar navigation away is a person
  // choosing somewhere else to be, and is left alone (renderTab clears
  // pos-mode without coming through here).
  if (posReturnCustomer != null) {
    const backTo = posReturnCustomer;
    posReturnCustomer = null;
    goToTab('customers');
    setTimeout(() => renderDetailPanel(backTo), 150);
    return;
  }
  renderShopTab();
}

function renderPosView() {
  const content = document.getElementById('mainContent');
  // Full-screen takeover: hide the sidebar/topbar so the till fills the
  // display like a real POS. Any tab switch clears it (renderTab guard).
  document.body.classList.add('pos-mode');
  const cats = [...new Set(shopItems.filter(i => i.active && i.quantity > 0).map(i => i.category))];
  const parkedN = posParkedCount();
  content.innerHTML = `
    <div class="pos-shell">
      <div id="posParkedMenu" hidden></div>
      <div class="pos-main">
        <div style="display:flex;gap:8px;align-items:center;">
          <button class="btn btn-outline" onclick="closePosView()" style="white-space:nowrap;">← Exit till</button>
          <button id="posParkedBtn" class="btn btn-outline kc-ic kc-ic-pause" onclick="posToggleParked()" title="Resume a held sale"
            style="white-space:nowrap;${parkedN ? '' : 'display:none;'}">Parked (<span id="posParkedN">${parkedN}</span>)</button>
          ${/* The hero control on the till, and until 26 Aug it promised
                something the shop could not do: it read "Scan a barcode" while
                not one of the fifteen stock lines had a barcode on it. The
                field for them has been in the stock form all along, with the
                right words on it — the items were simply entered without.
                So the placeholder now reads the catalogue and says whichever
                is true. Typing still finds an item either way. */''}
          <input class="form-input pos-scan" id="posScan" placeholder="${posCanScan()
            ? kcHint('🔍 Scan a barcode, or type to search…', '🔍 Scan or search')
            : kcHint('🔍 Type to find an item…', '🔍 Find an item')}"
            autocomplete="off" oninput="posRenderTiles()"
            onkeydown="if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();saveSale();}else if(event.key==='Enter'){event.preventDefault();posScanEnter();}">
          <button class="theme-toggle" data-theme-btn onclick="toggleTheme()" title="Light / dark mode"
            aria-label="Toggle light or dark mode" class="kc-ic ${document.documentElement.getAttribute('data-theme') === 'dark' ? 'kc-ic-sun' : 'kc-ic-moon'}"></button>
          <button class="theme-toggle kc-textsize" data-textsize-btn onclick="cycleTextSize()"
            data-size="${escHtml(currentTextSize().key)}" title="Text size: ${escHtml(currentTextSize().label)}"
            aria-label="Text size: ${escHtml(currentTextSize().label)}. Press to change.">${textSizeBtnInner()}</button>
        </div>
        <div class="pos-cats" id="posCats">${posCatsHtml(cats)}</div>
        <div id="posTiles" class="pos-tiles pos-tiles-full"></div>
      </div>
      <div class="pos-side">
        <div class="pos-receipt-head"><i class="kc-ic kc-ic-receipt" aria-hidden="true"></i> Current sale</div>
        <div id="posLastSale"></div>
        <div id="posBasket" class="pos-receipt"></div>
        <div class="pos-summary">
          ${customerPicker('posCustomer', {
            special: { value: 'walkin', label: 'Walk-in', icon: 'walk' }, label: 'Customer',
            onPick: 'posCustomerChange()', style: 'min-height:0;padding:8px 12px;',
          })}
          </select>
          <div style="display:flex;gap:6px;align-items:center;margin-bottom:8px;">
            <label style="display:flex;align-items:center;gap:6px;font-size:var(--fs-body);cursor:pointer;flex-shrink:0;">
              <input type="checkbox" id="posPaid" checked onchange="posRenderTender()"> Paid now</label>
            <div class="pos-methods" id="posMethods">${posMethodsHtml()}</div>
          </div>
          <div id="posTender"></div>
          <div class="pos-total-row"><span>TOTAL</span><strong id="posTotal">£0.00</strong></div>
          ${/* Both start disabled and stay so until something is in the basket
                 (owner, 20 Aug). They used to sit lit on an empty till, and the
                 only answer to pressing one was an error toast — which on a
                 busy counter reads as "something went wrong", not as "you have
                 not scanned anything yet". The guards inside saveSale and
                 posParkSale STAY: Ctrl+Enter reaches saveSale without touching
                 this button at all, so disabling it is the appearance and the
                 guard is the rule. */''}
          <button class="btn btn-primary pos-charge kc-ic kc-ic-pound" id="posChargeBtn" onclick="saveSale()" disabled
            title="Scan or tap something first — then Ctrl+Enter from the scan box">Charge<span class="kc-chord">Ctrl ⏎</span></button>
          <button class="btn btn-outline kc-ic kc-ic-pause" id="posParkBtn" onclick="posParkSale()" style="width:100%;margin-top:8px;" disabled
            title="Hold this sale to serve someone else, then resume it later">Park sale</button>
        </div>
      </div>
    </div>`;
  posRenderTiles();
  posRenderBasket();
  posRenderTender();
  document.getElementById('posScan').focus();
}

function posMethodsHtml() {
  const m = [['cash', '<i class="kc-ic kc-ic-cash" aria-hidden="true"></i> Cash'], ['card', '<i class="kc-ic kc-ic-card" aria-hidden="true"></i> Card'], ['bank_transfer', '<i class="kc-ic kc-ic-bank" aria-hidden="true"></i> Transfer']];
  return m.map(([k, label]) =>
    `<button class="pos-method${posMethod === k ? ' on' : ''}" onclick="posSetMethod('${k}')">${label}</button>`).join('');
}

function posSetMethod(m) {
  posMethod = m;
  const el = document.getElementById('posMethods');
  if (el) el.innerHTML = posMethodsHtml();
  posRenderTender();
  document.getElementById('posScan')?.focus();
}

function posSetCat(c) {
  posCat = c;
  // Rebuild rather than toggle: posCatsHtml computes .on from posCat, and one
  // renderer means the strip and the big choosing grid can never disagree.
  const strip = document.getElementById('posCats');
  if (strip) strip.innerHTML = posCatsHtml();
  posRenderTiles();
  document.getElementById('posScan')?.focus();
}

// Tender area: an optional wallet-split row (real customer only) + the cash
// change helper. The wallet portion draws down the customer's credit — no cash
// moves for it; the remainder is paid by the method above, or left on account.
function posRenderTender() {
  const el = document.getElementById('posTender');
  if (!el) return;
  const custVal = document.getElementById('posCustomer')?.value || 'walkin';
  const paid = document.getElementById('posPaid')?.checked;
  const total = posTotalNow();
  let html = '';

  if (custVal && custVal !== 'walkin') {
    const cust = customers.find(c => String(c.id) === String(custVal));
    const bal = cust ? customerLedgerBalance(cust) : null;
    const credit = (typeof bal === 'number' && bal > 0) ? bal : 0;
    const maxW = Math.min(credit, total);
    html += `
      <div style="display:flex;gap:6px;align-items:center;margin-bottom:6px;flex-wrap:wrap;">
        <label style="font-size:var(--fs-body);flex-shrink:0;"><i class="kc-ic kc-ic-purse" aria-hidden="true"></i> From wallet £</label>
        <input class="form-input" id="posWalletIn" type="number" min="0" step="0.01"
          value="${posWallet ? posWallet.toFixed(2) : ''}" placeholder="0.00"
          oninput="posWalletInput()" style="width:96px;min-height:0;padding:7px 10px;">
        <button class="pos-note" onclick="posWalletMax(${maxW.toFixed(2)})" ${maxW > 0 ? '' : 'disabled'}>Max</button>
        <span style="font-size:var(--fs-small);color:var(--muted);margin-left:auto;">${credit > 0 ? `credit ${fmtGbp(credit)}` : 'no credit'}</span>
      </div>
      <div id="posSplitInfo" style="font-size:var(--fs-small);color:var(--ink-secondary);margin-bottom:8px;min-height:15px;">${posSplitText()}</div>`;

    // The Epos Now Customer Credit idea, KC-shaped: a per-customer limit on
    // how far on account, said HERE — at the moment it is decided, same as
    // the walk-in rule below — and warned, never refused: the counter can
    // see the person standing there, the till cannot.
    const overBy = posOverCreditLimit(cust, paid, total);
    if (overBy !== null) {
      html += `
      <div class="kc-popnote" style="margin:0 0 8px;">Past their credit limit — this sale on account
        leaves ${escName(capName(cust.firstName || ''))} owing ${fmtGbp(overBy.owing)}, and their limit is
        ${fmtGbp(overBy.limit)}. It still goes through if you say so.</div>`;
    }
  }

  if (paid && posMethod === 'cash') {
    html += `
      <div style="display:flex;gap:6px;align-items:center;margin-bottom:8px;flex-wrap:wrap;">
        <input class="form-input" id="posTenderIn" type="number" min="0" step="0.01" placeholder="Cash given £"
          oninput="posChangeCalc()" style="width:132px;min-height:0;padding:7px 10px;">
        ${[5, 10, 20, 50].map(n => `<button class="pos-note" onclick="posTenderQuick(${n})">${fmtGbp(n)}</button>`).join('')}
        <!-- Change due. Computed from what was tendered, and until now
             announced to nobody. -->
        <span id="posChange" role="status" style="font-weight:700;font-size:var(--fs-ui);margin-left:auto;"></span>
      </div>`;
  }
  // The on-account rule, said at the moment it is DECIDED rather than at the
  // charge (E6's remaining half). Unticking "Paid now" on a walk-in used to
  // read as accepted — the operator scanned on, pressed 💷 Charge, and only
  // then met the refusal, with the queue watching. The hard stop in saveSale
  // (and in pages/api/shop.js — the browser is not the only caller) stands
  // unchanged; this is the same sentence, earlier, where it costs nothing.
  if (!paid && (!custVal || custVal === 'walkin')) {
    html += `
      <div class="kc-popnote" style="margin:0 0 8px;">On account needs a customer — a walk-in has
        no account to put it on. Pick who it is above, or tick "Paid now".</div>`;
  }
  el.innerHTML = html;
  posChangeCalc();
}

// Would putting this sale on account leave the customer past their credit
// limit? null = no (paid now, no limit set, walk-in, or within it); otherwise
// { owing, limit } for the warning and the confirm to read the same numbers.
// The portion landing on account is total minus the wallet slice — identical
// arithmetic to posCashDue, on the unpaid branch.
function posOverCreditLimit(cust, paid, total) {
  if (paid || !cust) return null;
  const limit = Number(cust.creditLimit);
  if (!Number.isFinite(limit) || limit <= 0) return null;
  const bal = customerLedgerBalance(cust);
  const onAccount = Math.max(0, +(total - Math.min(Math.max(posWallet, 0), total)).toFixed(2));
  if (onAccount <= 0) return null;
  const after = (typeof bal === 'number' ? bal : 0) - onAccount;
  if (after >= -limit) return null;
  return { owing: -after, limit };
}

// £ still to settle at the till after the wallet portion (the cash/card due).
function posCashDue() {
  const total = posTotalNow();
  return Math.max(0, +(total - Math.min(posWallet, total)).toFixed(2));
}

// One-line split summary: "👛 Wallet £20 · Cash £10" / "· On account £10".
function posSplitText() {
  const total = posTotalNow();
  const w = Math.min(posWallet, total);
  if (w <= 0) return '';
  const rest = posCashDue();
  const paid = document.getElementById('posPaid')?.checked;
  const restLabel = rest <= 0 ? '' : ` · ${paid ? (METHOD_LABELS[posMethod] || posMethod) : 'On account'} ${fmtGbp(rest)}`;
  return `<i class="kc-ic kc-ic-purse" aria-hidden="true"></i> Wallet ${fmtGbp(w)}${restLabel}`;
}

// One visit, one place (owner, 23 Aug: a customer wanted a rental, tickets
// AND a few items, "but i couldnt do it all from one place"). Every other
// service already starts from the customer card with the person pre-filled;
// this is the till's version: land on the Shop tab with them attached, so
// their wallet credit, usual payment method, credit limit and pop-up note
// all arrive with them — posCustomerChange is the same code path the till
// itself runs when a customer is picked by hand.
let posReturnCustomer = null; // bounce target: set only by the card's button
function posOpenForCustomer(custId) {
  try { closeCustomerCard(); } catch { /* card may not be open — palette path */ }
  // The till is what the Shop tab BECOMES (pos-mode), so it has to be opened,
  // not merely navigated to — the customer picker does not exist until then.
  openOnTab('shop', () => {
    openSaleModal();
    kcPickerSet('posCustomer', String(custId));
    posCustomerChange();
    // Set AFTER arriving: the nav that brings us here is the same guard that
    // clears stale bounce targets, and setting first meant it wiped itself.
    posReturnCustomer = custId;
  });
}

function posCustomerChange() {
  posWallet = 0;            // wallet credit is per-customer — reset on switch
  // Start on how this customer usually pays (their card, owner 08-17). The
  // till is the one place this is safe to preselect: a sale here is always
  // being tendered by one of these three, so the default saves a tap and can
  // never record a payment that did not happen. Forms that can also put a
  // charge ON ACCOUNT are left alone deliberately — preselecting "paid now"
  // there would mean an unnoticed default books money nobody handed over.
  const id = document.getElementById('posCustomer')?.value;
  const c = id && id !== 'walkin' ? customers.find(x => String(x.id) === String(id)) : null;
  if (c?.defaultPaymentMethod) posSetMethod(c.defaultPaymentMethod);
  // The pop-up note fires the moment the customer is attached — the Epos Now
  // Pop Up Notes idea. A toast, not a modal: the counter is mid-sale and the
  // note must interrupt the EYE, not the hands.
  if (c?.popNote) toast(`${c.popNote}`, 'warning', 'pin');
  posRenderTender();
  // Straight back to scanning once someone is chosen — but not while the
  // operator is still typing a name, which also lands here the moment the
  // first keystroke invalidates the previous pick.
  if (document.activeElement?.id !== 'posCustomer_search') document.getElementById('posScan')?.focus();
}

// Update on wallet-field keystrokes WITHOUT re-rendering (keeps the field
// focused). Stores the RAW typed value — every reader (posCashDue, the split
// summary, submit) clamps against the LIVE total, so growing the basket after
// typing honours the full typed amount instead of a stale clamp.
function posWalletInput() {
  const el = document.getElementById('posWalletIn');
  let v = parseFloat(el?.value);
  if (!Number.isFinite(v) || v < 0) v = 0;
  posWallet = v;
  const info = document.getElementById('posSplitInfo');
  if (info) info.textContent = posSplitText();
  posChangeCalc();
}

function posWalletMax(v) {
  posWallet = Math.max(0, Number(v) || 0);
  const el = document.getElementById('posWalletIn');
  if (el) el.value = posWallet ? posWallet.toFixed(2) : '';
  posRenderTender();
}

function posTotalNow() {
  return posBasket.reduce((s, l) => {
    const i = shopItems.find(x => x.id === l.itemId);
    return s + (i ? (i.sellingPrice || 0) * l.qty : 0);
  }, 0);
}

function posTenderQuick(n) {
  const el = document.getElementById('posTenderIn');
  if (!el) return;
  el.value = ((parseFloat(el.value) || 0) + n).toFixed(2);
  posChangeCalc();
}

function posChangeCalc() {
  const out = document.getElementById('posChange');
  if (!out) return;
  const given = parseFloat(document.getElementById('posTenderIn')?.value);
  if (!Number.isFinite(given)) { out.textContent = ''; return; }
  const change = given - posCashDue();   // change is against the cash due, not the gross total
  out.style.color = change < 0 ? 'var(--danger-ink)' : 'var(--success)';
  out.textContent = change < 0 ? `${fmtGbp(Math.abs(change))} short` : `Change ${fmtGbp(change)}`;
}

function posFindItem(q) {
  const digits = q.replace(/\D/g, '');
  return shopItems.find(i => i.active && i.quantity > 0 && i.barcode && i.barcode === q)
    || shopItems.find(i => i.active && i.quantity > 0 && (
      (i.code && i.code.toLowerCase() === q.toLowerCase()) ||
      (digits.length >= 5 && ((i.barcode || '').replace(/\D/g, '') === digits ||
                              (i.code || '').replace(/\D/g, '') === digits)) ||
      [i.company, i.model].filter(Boolean).join(' ').toLowerCase() === q.toLowerCase()
    ));
}

/** Is there anything in the shop a scanner could actually match? */
function posCanScan() {
  return shopItems.some(i => i.active && String(i.barcode || '').trim());
}

function posScanEnter() {
  const el = document.getElementById('posScan');
  const q = el.value.trim();
  if (!q) return;
  // Exact barcode/code/name hit, or the single visible tile.
  const shown = shopItems.filter(i => i.active && i.quantity > 0 && posTileMatch(i, q));
  const item = posFindItem(q) || (shown.length === 1 ? shown[0] : null);
  if (item) { posAdd(item.id); el.value = ''; posRenderTiles(); }
  // "No matching item" is true and useless when the answer is that NOTHING has
  // a barcode yet: a scan will fail on every product in the shop, and the
  // person at the counter has no way to tell that from a mis-scan.
  else if (!posCanScan() && /^\d{8,}$/.test(q)) {
    toast('Nothing in the shop has a barcode yet, so scanning cannot find anything — add one on the item in Shop, or type the name.', 'warning');
  }
  else toast('No matching item.', 'warning');
}

// One hue per category, spread by the golden angle so the twelve built-ins
// and any owner-added ones stay tellable-apart without a hand-pinned palette.
// The CSS reads --cat-h; light and dark each mix their own lightness from it.
function posCatHue(c, cats) {
  const i = Math.max(0, cats.indexOf(c));
  return Math.round((i * 137.5) % 360);
}
function posCatsHtml(cats) {
  cats = cats || stockCategories().map(([k]) => k).filter(k => shopItems.some(i => i.active && i.quantity > 0 && i.category === k));
  const btn = (val, label) => `<button class="pos-cat${posCat === val ? ' on' : ''}"
    style="--cat-h:${val === 'all' ? 215 : posCatHue(val, cats)};" onclick="posSetCat('${escJs(val)}')">${label}</button>`;
  return btn('all', 'Everything') + cats.map(c => btn(c, STOCK_CATEGORY_LABELS[c] || escHtml(c))).join('');
}
function posTileMatch(i, q) {
  if (posCat && posCat !== 'all' && i.category !== posCat) return false;
  if (!q) return true;
  const hay = `${i.barcode || ''} ${i.code || ''} ${i.company || ''} ${i.model || ''}`.toLowerCase();
  return hay.includes(q.toLowerCase());
}

function posRenderTiles() {
  const q = document.getElementById('posScan')?.value.trim() || '';
  const el = document.getElementById('posTiles');
  if (!el) return;
  // No category picked and nothing typed → the choosing state: the tile area
  // IS the category buttons, big. A keystroke in the scan box overrides it —
  // whoever is scanning barcodes must never have to touch a category first.
  if (!posCat && !q) {
    const cats = stockCategories().map(([k]) => k).filter(k => shopItems.some(i => i.active && i.quantity > 0 && i.category === k));
    el.innerHTML = `<div class="pos-cat-choose">${posCatsHtml(cats)}</div>`;
    const strip = document.getElementById('posCats'); if (strip) strip.innerHTML = '';
    return;
  }
  { const strip = document.getElementById('posCats'); if (strip && !strip.childElementCount) strip.innerHTML = posCatsHtml(); }
  const list = shopItems.filter(i => i.active && i.quantity > 0 && posTileMatch(i, q)).slice(0, 60);
  el.innerHTML = list.map(i => `
    <div class="pos-tile" onclick="posAdd('${i.id}')">
      <div class="pos-tile-name">${escHtml([i.company, i.model].filter(Boolean).join(' '))}</div>
      <div style="display:flex;justify-content:space-between;align-items:flex-end;margin-top:6px;">
        <span style="color:var(--muted);font-size:var(--fs-small);">${i.quantity} left</span>
        <span class="pos-tile-price">${fmtGbp((i.sellingPrice || 0))}</span>
      </div>
    </div>`).join('') || '<div style="color:var(--muted);font-size:var(--fs-body);padding:6px;">No matching items.</div>';
}

function posAdd(itemId) {
  const item = shopItems.find(i => i.id === itemId);
  if (!item) return;
  if (posLastSale) { posLastSale = null; posShowLastSale(); } // new customer, clear the banner
  const line = posBasket.find(l => l.itemId === itemId);
  const inBasket = line ? line.qty : 0;
  if (inBasket + 1 > item.quantity) { toast(`Only ${item.quantity} in stock.`, 'warning'); return; }
  if (line) line.qty++;
  else posBasket.push({ itemId, qty: 1, imei: '' });
  posRenderBasket();
}

function posQty(itemId, delta) {
  const line = posBasket.find(l => l.itemId === itemId);
  if (!line) return;
  const item = shopItems.find(i => i.id === itemId);
  line.qty += delta;
  if (line.qty <= 0) posBasket = posBasket.filter(l => l !== line);
  else if (item && line.qty > item.quantity) { line.qty = item.quantity; toast(`Only ${item.quantity} in stock.`, 'warning'); }
  posRenderBasket();
}

function posImei(itemId, v) {
  const line = posBasket.find(l => l.itemId === itemId);
  if (line) line.imei = v.trim();
}

/**
 * Charge and Park follow the basket.
 *
 * One place, because three things change them: the basket being painted, a
 * card charge finishing, and a parked sale being resumed. Left to each of
 * those to set the flag themselves, they would disagree — and the way they
 * would disagree is a live Charge button on an empty till, which is the thing
 * being fixed.
 */
function posSyncActionButtons() {
  const has = posBasket.length > 0;
  const charge = document.getElementById('posChargeBtn');
  const park = document.getElementById('posParkBtn');
  if (charge) {
    charge.disabled = !has;
    charge.title = has ? 'Ctrl+Enter from the scan box' : 'Scan or tap something first';
  }
  if (park) {
    park.disabled = !has;
    park.title = has ? 'Hold this sale to serve someone else, then resume it later' : 'Nothing to park yet';
  }
}

function posRenderBasket() {
  const el = document.getElementById('posBasket');
  if (!el) return;
  posSyncActionButtons();
  let total = 0;
  // Says the same thing the scan box says. When nothing in the shop carries a
  // barcode the box stops offering a scan (c3781c4), and an empty basket that
  // still said "Scan a barcode" would put the promise straight back two
  // inches to the right.
  el.innerHTML = posBasket.length === 0
    ? `<div style="color:var(--muted);font-size:var(--fs-body);padding:10px 2px;">${
        posCanScan() ? 'Scan a barcode or tap an item to start.' : 'Tap an item to start, or type its name above.'}</div>`
    : posBasket.map(l => {
        const i = shopItems.find(x => x.id === l.itemId);
        if (!i) return '';
        const lineTotal = (i.sellingPrice || 0) * l.qty;
        total += lineTotal;
        return `
        <div class="pos-line">
          <div style="flex:1;min-width:0;">
            <div style="font-size:var(--fs-body);">${escHtml([i.company, i.model].filter(Boolean).join(' '))}</div>
            <div style="font-size:var(--fs-micro);color:var(--muted);">${fmtGbp((i.sellingPrice || 0))} each</div>
            ${i.category === 'phone' ? `<input class="form-input" placeholder="IMEI (scan)" value="${escHtml(l.imei)}"
              oninput="posImei('${i.id}', this.value)" style="width:100%;min-height:0;padding:4px 8px;font-size:var(--fs-micro);margin-top:3px;">` : ''}
          </div>
          <button class="action-btn" style="min-width:40px;min-height:40px;font-size:var(--fs-title);line-height:1;" aria-label="One fewer ${escHtml(i.name || 'item')}" onclick="posQty('${i.id}',-1)">−</button>
          <strong style="min-width:26px;text-align:center;font-size:var(--fs-lead);">${l.qty}</strong>
          <button class="action-btn" style="min-width:40px;min-height:40px;font-size:var(--fs-title);line-height:1;" aria-label="One more ${escHtml(i.name || 'item')}" onclick="posQty('${i.id}',1)">+</button>
          <strong style="min-width:58px;text-align:right;font-feature-settings:'tnum';">${fmtGbp(lineTotal)}</strong>
          <button class="action-btn" style="min-width:40px;min-height:40px;color:var(--danger-ink);font-size:var(--fs-lead);" title="Void line" aria-label="Remove ${escHtml(i.name || 'item')} from the sale"
            onclick="posQty('${i.id}',-999)">✕</button>
        </div>`;
      }).join('');
  const totalEl = document.getElementById('posTotal');
  if (totalEl) totalEl.textContent = `${fmtGbp(total)}`;
  // Basket edits change the split — keep the wallet summary + change live.
  const splitInfo = document.getElementById('posSplitInfo');
  if (splitInfo) splitInfo.textContent = posSplitText();
  posChangeCalc();
}

function posShowLastSale() {
  const el = document.getElementById('posLastSale');
  if (!el) return;
  if (!posLastSale) { el.innerHTML = ''; return; }
  const canEmail = !!posLastSale.customerId;
  el.innerHTML = `
    <div class="pos-done">
      <i class="kc-ic kc-ic-check" aria-hidden="true"></i> ${fmtGbp(posLastSale.total)} taken${posLastSale.change !== null
        ? ` — <strong>change ${fmtGbp(posLastSale.change)}</strong>` : ''}
      ${canEmail ? `<button class="btn btn-secondary" style="margin-top:8px;width:100%;"
        onclick="emailSaleReceipt(this)" ${posLastSale.emailed ? 'disabled' : ''}>
        ${posLastSale.emailed === 'test' ? '<i class="kc-ic kc-ic-mail" aria-hidden="true"></i> Sent to the test inbox' : posLastSale.emailed ? '<i class="kc-ic kc-ic-mail" aria-hidden="true"></i> Receipt sent' : '<i class="kc-ic kc-ic-mail" aria-hidden="true"></i> Email receipt'}</button>` : ''}
    </div>`;
}

// ── Park / hold an open sale ─────────────────────────────────────────────
// Suspend an in-progress till sale so the cashier can serve someone else, then
// resume it — the Loyverse "hold ticket" pattern. Purely PRE-charge: it snapshots
// the basket + selections to localStorage; nothing is charged, no ledger/stock
// write happens until the resumed sale hits Charge (saveSale), which keeps its own
// server-side atomic stock guard. Parked sales survive Exit till + reload.
const POS_PARKED_KEY = 'kc_parked_sales';
function posGetParked() {
  try { const a = JSON.parse(localStorage.getItem(POS_PARKED_KEY) || '[]'); return Array.isArray(a) ? a : []; }
  catch { return []; }
}
function posSetParked(a) {
  try { localStorage.setItem(POS_PARKED_KEY, JSON.stringify(a || [])); } catch {}
}
function posParkedCount() { return posGetParked().length; }
function posSyncParkedButton() {
  const n = posParkedCount();
  const span = document.getElementById('posParkedN'); if (span) span.textContent = n;
  const btn = document.getElementById('posParkedBtn'); if (btn) btn.style.display = n ? '' : 'none';
}

// Snapshot the current sale and clear the till for the next customer.
// silent=true is used when auto-holding the current sale before resuming another,
// so nothing is ever lost — no toast, no menu, but the same reset.
function posParkSale(silent) {
  if (!posBasket.length) { if (!silent) toast('Nothing to park — the basket is empty.', 'warning'); return; }
  const custEl = document.getElementById('posCustomer');
  const custId = custEl ? custEl.value : 'walkin';
  let custName = 'Walk-in';
  if (custId && custId !== 'walkin') {
    const c = customers.find(x => String(x.id) === String(custId));
    if (c) custName = `${c.firstName || ''} ${c.lastName || ''}`.trim() || 'Customer';
  }
  const paidEl = document.getElementById('posPaid');
  const entry = {
    id: 'pk_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
    at: Date.now(),
    customerId: custId,
    customerName: custName,
    method: posMethod,
    paidNow: paidEl ? !!paidEl.checked : true,
    basket: posBasket.map(l => ({ itemId: l.itemId, qty: l.qty, imei: l.imei || '' })),
    total: posTotalNow(),
    count: posBasket.reduce((s, l) => s + l.qty, 0),
  };
  posSetParked([entry, ...posGetParked()].slice(0, 20)); // cap the hold queue
  // Reset the current sale in place (don't rebuild the whole view — that would
  // drop an in-progress customer selection when resuming/discarding elsewhere).
  posBasket = []; posWallet = 0; posLastSale = null;
  if (custEl) custEl.value = 'walkin';
  if (paidEl) paidEl.checked = true;
  posRenderBasket(); posShowLastSale(); posRenderTender(); posSyncParkedButton();
  if (!silent) {
    const menu = document.getElementById('posParkedMenu'); if (menu) { menu.hidden = true; menu.innerHTML = ''; }
    toast(`Sale parked — ${custName}, ${fmtGbp(entry.total)}.`, 'success');
    document.getElementById('posScan')?.focus();
  }
}

// Load a parked sale back into the till. The current basket (if any) is parked
// first, so switching between customers never loses a basket.
function posResumeSale(id) {
  const target = posGetParked().find(p => p.id === id);
  if (!target) { posRenderParkedMenu(); return; }
  if (posBasket.length) posParkSale(true);          // hold the current one first
  posSetParked(posGetParked().filter(p => p.id !== id));
  posBasket = (target.basket || []).map(l => ({ itemId: l.itemId, qty: l.qty, imei: l.imei || '' }));
  posMethod = target.method || 'cash';
  posWallet = 0; posLastSale = null;
  kcPickerSet('posCustomer', target.customerId || 'walkin');
  const paidEl = document.getElementById('posPaid'); if (paidEl) paidEl.checked = target.paidNow !== false;
  const methodsEl = document.getElementById('posMethods'); if (methodsEl) methodsEl.innerHTML = posMethodsHtml();
  posRenderBasket(); posShowLastSale(); posRenderTender(); posSyncParkedButton();
  const menu = document.getElementById('posParkedMenu'); if (menu) { menu.hidden = true; menu.innerHTML = ''; }
  toast(`Sale resumed — ${target.customerName || 'Walk-in'}.`, 'success');
  document.getElementById('posScan')?.focus();
}

function posDiscardParked(id) {
  posSetParked(posGetParked().filter(p => p.id !== id));
  posSyncParkedButton();
  posRenderParkedMenu(); // re-render (auto-hides when the queue empties)
}

function posToggleParked() {
  const el = document.getElementById('posParkedMenu');
  if (!el) return;
  if (!el.hidden) { el.hidden = true; el.innerHTML = ''; return; }
  posRenderParkedMenu();
}

function posRenderParkedMenu() {
  const el = document.getElementById('posParkedMenu');
  if (!el) return;
  const parked = posGetParked();
  if (!parked.length) { el.hidden = true; el.innerHTML = ''; return; }
  const pad2 = (n) => String(n).padStart(2, '0');
  const rows = parked.map(p => {
    const d = new Date(p.at || Date.now());
    const hm = `${pad2(d.getHours())}:${pad2(d.getMinutes())}`;
    return `
      <div style="display:flex;align-items:center;gap:10px;padding:10px 12px;border-top:1px solid var(--border);">
        <div style="flex:1;min-width:0;">
          <div style="font-size:var(--fs-body);font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escName(p.customerName || 'Walk-in')}</div>
          <div style="font-size:var(--fs-micro);color:var(--muted);">${p.count} item${p.count === 1 ? '' : 's'} · ${fmtGbp(p.total || 0)} · held ${hm}</div>
        </div>
        <button class="btn btn-primary" style="padding:6px 12px;" onclick="posResumeSale('${p.id}')">Resume</button>
        <button class="action-btn" style="min-width:36px;min-height:36px;color:var(--danger-ink);" title="Discard this held sale" onclick="posDiscardParked('${p.id}')">✕</button>
      </div>`;
  }).join('');
  el.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between;padding:12px 12px 8px;">
      <span style="font-size:var(--fs-small);font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--muted);">Parked sales</span>
      <button class="action-btn" style="min-width:32px;min-height:32px;" title="Close" onclick="posToggleParked()">✕</button>
    </div>
    ${rows}`;
  el.style.cssText = 'position:fixed;top:64px;left:50%;transform:translateX(-50%);z-index:1000;width:min(440px,92vw);background:var(--bg-secondary);border:1px solid var(--border);border-radius:10px;box-shadow:0 10px 40px rgba(0,0,0,.28);max-height:70vh;overflow:auto;';
  el.hidden = false;
}

async function emailSaleReceipt(btn) {
  if (!posLastSale || !posLastSale.customerId) return;
  if (btn) { btn.disabled = true; btn.textContent = 'Sending…'; }
  const res = await kcFetch('/api/email', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      kind: 'sale',
      customerId: posLastSale.customerId,
      lines: posLastSale.lines,
      total: posLastSale.total,
      method: posLastSale.method,
      paidNow: posLastSale.paidNow,
    }),
  }).then(r => r.json()).catch(() => null);
  if (res && res.success && res.held) {
    toast(res.note || 'Email is on hold — receipt not sent.', 'warning');
  } else if (res && res.success && res.redirected) {
    posLastSale.emailed = 'test';   // the customer got nothing — say so on the chip
    toast(res.note || `Test mode — sent to ${res.sentTo}.`, 'warning');
  } else if (res && res.success) {
    posLastSale.emailed = true;
    toast(`Receipt emailed to ${res.sentTo}.`, 'success');
  } else {
    toast(res?.error || 'Could not send the receipt.', 'error');
  }
  posShowLastSale();
}

// ── myPOS terminal bridge — two lanes, one contract ──────────────────────
// Lane 1 (Android wrapper): the native side injects window.KCTill with
// charge(amountPence, chargeReference) — it starts a sale on the terminal
// and reports back by calling window.kcTillResult({ chargeReference,
// approved, myposRef, stan, authCode, brand, last4, error }).
// Lane 2 (ePOS API, cloud): no wrapper needed — /api/pos/terminal pushes the
// amount to the shop terminal over myPOS's ePOS API and the till polls for
// the outcome, then reports through the SAME window.kcTillResult, so the
// approval cache, re-ring guard and card_receipts recording are one code
// path for both lanes. With neither lane available the manual card flow is
// unchanged.
const kcTillPending = {};
// Approved terminal charges per reference WITH the approved amount: a re-ring
// after a lost sale POST reuses the approval instead of charging the card
// twice — but ONLY for the same total. If the basket changed, the operator is
// blocked and told to re-ring the original total or refund on the machine.
const kcTillApproved = {};   // ref → { result, amountPence }
const kcTillAmounts = {};    // ref → requested pence (survives the timeout)
let kcEposEnabled = false;
let kcEposProbed = false;
async function kcEposProbe() {
  if (kcEposProbed) return;
  kcEposProbed = true;
  try {
    const d = await (await kcFetch('/api/pos/terminal')).json();
    kcEposEnabled = !!(d && d.success && d.enabled);
  } catch { kcEposEnabled = false; }
}
function kcWrapperAvailable() { return !!(window.KCTill && typeof window.KCTill.charge === 'function'); }
function kcTillAvailable() { return kcWrapperAvailable() || kcEposEnabled; }
function kcTillCharge(amountPence, chargeReference) {
  const cached = kcTillApproved[chargeReference];
  if (cached) {
    if (cached.amountPence === amountPence) return Promise.resolve(cached.result);
    return Promise.resolve({ approved: false, mismatch: true, approvedAmount: cached.amountPence });
  }
  kcTillAmounts[chargeReference] = amountPence;
  if (!kcWrapperAvailable()) return kcEposCharge(amountPence, chargeReference);
  return new Promise((resolve) => {
    // Terminal interactions are slow (card tap, PIN, issuer) — 3 minutes, then
    // give up with "no answer" so the operator checks the machine itself.
    const timer = setTimeout(() => { delete kcTillPending[chargeReference]; resolve(null); }, 180000);
    kcTillPending[chargeReference] = (result) => { clearTimeout(timer); resolve(result); };
    try { window.KCTill.charge(amountPence, chargeReference); }
    catch (e) {
      clearTimeout(timer);
      delete kcTillPending[chargeReference];
      resolve({ approved: false, error: String((e && e.message) || e) });
    }
  });
}
// ePOS lane: start the payment server-side, poll every 2s until the terminal
// answers, then report through window.kcTillResult like the wrapper does.
// Transient poll failures are tolerated (the terminal is mid-interaction);
// if the till's 3-minute patience runs out first, the loop notices its
// pending slot is gone, stops, and best-effort cancels so the terminal
// doesn't sit waiting for a sale the till already abandoned.
function kcEposCharge(amountPence, chargeReference) {
  return new Promise((resolve) => {
    const timer = setTimeout(() => { delete kcTillPending[chargeReference]; resolve(null); }, 180000);
    kcTillPending[chargeReference] = (result) => { clearTimeout(timer); resolve(result); };
    (async () => {
      let paymentId = null;
      const finish = (r) => window.kcTillResult({ chargeReference, ...r });
      const cancelUpstream = () => {
        if (!paymentId) return;
        kcFetch('/api/pos/terminal', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ op: 'cancel', paymentId }),
        }).catch(() => {});
      };
      try {
        const r = await kcFetch('/api/pos/terminal', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ op: 'charge', chargeReference, amountPence }),
        });
        const d = await r.json();
        if (!d.success) { finish({ approved: false, error: d.error || 'The card machine could not be started.' }); return; }
        paymentId = d.paymentId;
        while (true) {
          await new Promise((z) => setTimeout(z, 2000));
          if (!kcTillPending[chargeReference]) {
            // Till gave up: try to free the terminal, then look ONCE more —
            // if the card was actually approved in the gap, report it late so
            // the approval cache blocks a second charge (same protection as
            // the wrapper's late kcTillResult callback).
            cancelUpstream();
            try {
              const s = await (await kcFetch(`/api/pos/terminal?paymentId=${encodeURIComponent(paymentId)}`)).json();
              if (s && s.success && s.done && s.approved) finish({ approved: true, myposRef: paymentId });
            } catch { /* nothing to salvage */ }
            return;
          }
          try {
            const s = await (await kcFetch(`/api/pos/terminal?paymentId=${encodeURIComponent(paymentId)}`)).json();
            if (s && s.success && s.done) {
              finish({ approved: !!s.approved, myposRef: paymentId, error: s.approved ? null : (s.error || 'Declined') });
              return;
            }
          } catch { /* one missed poll is fine — keep waiting */ }
        }
      } catch (e) {
        cancelUpstream();
        finish({ approved: false, error: String((e && e.message) || e) });
      }
    })();
  });
}
window.kcTillResult = (result) => {
  const ref = result && result.chargeReference;
  if (!ref) return;
  // Cache and audit-log EVERY approval — even one arriving after the till
  // gave up — so the card can never be tapped twice for this reference, and
  // card_receipts shows the terminal charge whether or not the sale posted
  // (an approved row with no ledger match = "card taken, sale missing").
  if (result.approved && !kcTillApproved[ref]) {
    const amountPence = kcTillAmounts[ref];
    kcTillApproved[ref] = { result, amountPence };
    if (Number.isFinite(amountPence)) kcTillRecordResult(ref, amountPence / 100, result);
  }
  const done = kcTillPending[ref];
  if (done) { delete kcTillPending[ref]; done(result); return; }
  if (result.approved) {
    toast('The card machine approved after the till gave up — re-ring the SAME items now, on this screen and without refreshing, to record the sale; this till will reuse the approval instead of charging the card again.', 'warning');
  }
};
// Attach the terminal's references to the ledger payment row (reconciliation).
// Non-fatal: the money is already on the ledger; a miss only loses metadata.
function kcTillRecordResult(payRef, amount, r) {
  return kcFetch('/api/pos/card-result', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      chargeReference: payRef, approved: true, amount,
      myposRef: r.myposRef, stan: r.stan, authCode: r.authCode, brand: r.brand, last4: r.last4,
    }),
  }).then(res => res.json())
    .then(res => { if (!res || !res.success) throw new Error('save failed'); })
    .catch(() => toast('Card taken, but the terminal reference didn’t save for reconciliation.', 'warning'));
}

async function saveSale() {
  if (!posBasket.length) { toast('The basket is empty.', 'error'); return; }
  const paidNow = document.getElementById('posPaid').checked;
  // ON ACCOUNT NEEDS AN ACCOUNT.
  //
  // Untick "Paid now" on a walk-in and the charge posts against the built-in
  // Walk-in customer — a debt belonging to nobody, on a record no one will ever
  // open, which cannot be chased and cannot be attached to a person afterwards.
  // The till gives no other way back: a sale is saved once.
  //
  // It has not happened yet (the walkin account's six ledger rows net to zero),
  // which is why this is a guard and not a repair. Refused here AND in
  // pages/api/shop.js — the browser is not the only caller, and a rule that
  // lives only in a screen is not a rule.
  const custNow = document.getElementById('posCustomer')?.value || 'walkin';
  if (!paidNow && (!custNow || custNow === 'walkin')) {
    toast('A sale left on account needs a customer — a walk-in has no account to put it on. Pick who it is, or tick "Paid now".', 'error');
    document.getElementById('posCustomer_search')?.focus();
    return;
  }
  const given = parseFloat(document.getElementById('posTenderIn')?.value);
  const totalBefore = posTotalNow();
  const walletAmount = Math.min(Math.max(posWallet, 0), totalBefore);
  const cashDue = Math.max(0, +(totalBefore - walletAmount).toFixed(2));
  if (paidNow && posMethod === 'cash' && Number.isFinite(given) && given < cashDue) {
    toast(`Cash given (${fmtGbp(given)}) is less than the ${fmtGbp(cashDue)} due.`, 'error');
    return;
  }
  // The credit-limit line, held at the charge as well as shown in the tender
  // panel — the panel warning can scroll past a busy counter; this one cannot.
  // Red button: pressing on IS the money-moving choice (#19's rule applied).
  if (!paidNow && custNow !== 'walkin') {
    const custObj = customers.find(c => String(c.id) === String(custNow));
    const over = posOverCreditLimit(custObj, false, totalBefore);
    if (over) {
      const ok = await kcConfirm({
        title: 'Past their credit limit',
        body: `${escName(capName(`${custObj.firstName || ''} ${custObj.lastName || ''}`.trim()))} would owe `
            + `<strong>${fmtGbp(over.owing)}</strong> after this sale — their limit is ${fmtGbp(over.limit)}.`,
        okLabel: 'Put it on account anyway',
        danger: true,
      });
      if (!ok) return;
    }
  }
  // Guard against a double-tap firing two sales; the per-HANDOVER token (kept
  // across failed attempts, cleared on success/duplicate) makes an operator
  // re-ring after a lost response replay the same token — the server dedupes
  // instead of charging twice. audit U3/A2.
  // A blocked re-tap used to return in total silence, which reads exactly like
  // a dead button to the operator standing at the counter.
  if (!kcBeginWrite('sale')) { toast('Still working on the last one — give it a moment.', 'info'); return; }
  if (!posSaleRef) posSaleRef = kcRef();
  // Terminal lane: inside the K300 wrapper a card payment goes to the machine
  // FIRST — only an approved tap records the sale. The result is keyed to the
  // same reference as the ledger payment row (PAY-SALE-<ref>-now) so the
  // settlement can be reconciled line by line.
  const payRef = `PAY-SALE-${posSaleRef}-now`;
  let tillResult = null;
  let res;
  // A tap/PIN/issuer round trip is ~10-40s. Without a busy state the button
  // stays live and the screen says nothing, so the operator cannot tell
  // "waiting on the machine" from "my tap didn't register" — well past the
  // ~10s threshold where a persistent indicator is required. Every other
  // write in this file already does disabled + relabel; this one was the
  // outlier, on the most-repeated action in the shop.
  const chargeBtn = document.querySelector('.pos-charge');
  const chargeIdle = chargeBtn ? chargeBtn.textContent : '';
  const setCharging = (on, label) => {
    if (!chargeBtn) return;
    chargeBtn.textContent = on ? label : chargeIdle;
    // Coming OUT of a charge, the basket decides — not this function. A sale
    // that succeeded has just emptied it, so blindly re-enabling here would
    // light the button back up on an empty till.
    if (on) chargeBtn.disabled = true;
    else posSyncActionButtons();
  };
  try {
    if (paidNow && posMethod === 'card' && cashDue > 0 && kcTillAvailable()) {
      toast(`Take ${fmtGbp(cashDue)} on the card machine…`, 'info');
      setCharging(true, '<i class="kc-ic kc-ic-hourglass" aria-hidden="true"></i> Waiting for the card machine…');
      tillResult = await kcTillCharge(Math.round(cashDue * 100), payRef);
      if (!tillResult) {
        toast('No answer from the card machine — nothing was recorded. Check the terminal and try again.', 'error');
        return;
      }
      if (tillResult.mismatch) {
        toast(`This sale already has a ${fmtGbp(tillResult.approvedAmount / 100)} card approval pending. Re-ring exactly that total to record it, or refund it on the machine and start fresh (Exit till).`, 'error');
        return;
      }
      if (!tillResult.approved) {
        toast(`Card ${tillResult.error ? 'error: ' + tillResult.error : 'declined'} — nothing was recorded.`, 'error');
        return;
      }
    }
    setCharging(true, '<i class="kc-ic kc-ic-hourglass" aria-hidden="true"></i> Recording the sale…');
    res = await kcFetch('/api/shop', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        op: 'sale',
        lines: posBasket,
        customerId: document.getElementById('posCustomer').value,
        paidNow,
        method: posMethod,
        walletAmount,
        clientRef: posSaleRef,
      }),
    }).then(r => r.json()).catch(() => null);
  } finally {
    // Restores on every exit, including the early returns for a declined,
    // mismatched or unanswered terminal.
    setCharging(false);
    kcEndWrite('sale');
  }
  // NOTE: on a failed POST after an approved tap, posSaleRef and the cached
  // approval are both kept — the operator's re-ring replays the same sale
  // without touching the card again.
  if (!res || !res.success) { toast(res?.error || 'Could not record the sale.', 'error'); return; }
  // The terminal metadata was already audit-logged at approval time
  // (kcTillResult) — here we only retire the approval now the sale is real.
  if (tillResult) {
    delete kcTillApproved[payRef];
    delete kcTillAmounts[payRef];
  }
  if (res.duplicate) {
    posBasket = []; posWallet = 0; posSaleRef = null;
    posRenderTiles(); posRenderBasket(); posRenderTender();
    toast('Sale already recorded — no double charge.', 'info');
    const scan = document.getElementById('posScan');
    if (scan) { scan.value = ''; scan.focus(); }
    return;
  }

  // Stay in the till for the next customer: update local stock, clear the
  // basket, show the change banner, keep the scanner focused.
  posBasket.forEach(l => {
    const i = shopItems.find(x => x.id === l.itemId);
    if (i) i.quantity = Math.max(0, i.quantity - l.qty);
  });
  const custId = document.getElementById('posCustomer').value;
  const receiptLines = posBasket.map(l => {
    const i = shopItems.find(x => x.id === l.itemId);
    return {
      name: i ? [i.company, i.model].filter(Boolean).join(' ') : 'Item',
      qty: l.qty,
      total: Number.isFinite(Number(l.total)) ? Number(l.total) : (i ? (i.sellingPrice || 0) * l.qty : 0),
    };
  });
  posLastSale = {
    total: res.total,
    change: paidNow && posMethod === 'cash' && Number.isFinite(given) ? Math.max(0, given - cashDue) : null,
    customerId: custId && custId !== 'walkin' ? custId : null,
    lines: receiptLines,
    method: posMethod,
    paidNow,
    emailed: false,
  };
  // Keep the till's view of this customer's credit fresh for the next sale.
  if (custId && custId !== 'walkin' && customerLedgerBal && typeof res.balance === 'number') {
    customerLedgerBal.set(String(custId), Number(res.balance));
  }
  posBasket = []; posWallet = 0; posSaleRef = null;
  const walletNote = res.walletApplied > 0 ? ` (${fmtGbp(res.walletApplied)} from wallet)` : '';
  toast(`Sold ${res.lines} item${res.lines === 1 ? '' : 's'} — ${fmtGbp(res.total)}${walletNote}.`, 'success');
  // Credit turned out smaller than the agreed split — the uncovered part stayed
  // on the customer's account. Loud, persistent (error toasts stay until clicked).
  if (res.walletShortfall > 0) {
    toast(`Heads up: only ${fmtGbp(res.walletApplied)} credit was available — ${fmtGbp(res.walletShortfall)} left on the customer's account.`, 'error');
  }
  posRenderTiles();
  posRenderBasket();
  posRenderTender();
  posShowLastSale();
  const scan = document.getElementById('posScan');
  if (scan) { scan.value = ''; scan.focus(); }
}

// ─────────────────────────────────────────────
//  KOL TORAH — CD catalogue, shul consignment, settlements, conversion jobs
// ─────────────────────────────────────────────
// The recently-acquired audio business. Money follows the house rules: a
// settlement on a wallet-linked shul posts stock_sale + payment ledger rows;
// collecting a priced job charges the customer's wallet (KT-JOB-<id>).
let ktData = null;
let ktJobRef = null;          // idempotency token for the in-flight new job
const ktSettleRefs = {};      // per-shul settlement tokens, kept across retries
const ktMoveRefs = {};        // per-(shul,title,kind,qty) movement tokens, ditto
const ktEditShuls = new Set();

const KT_JOB_KINDS = { cd_to_mp3: 'CD → MP3', cd_to_sd: 'CD → SD card', cd_copy: 'CD copying', audio_other: 'Audio work' };
const KT_JOB_BADGE = {
  open:      'background:rgba(59,130,246,0.14);color:var(--accent);',
  ready:     'background:rgba(14,138,82,0.14);color:var(--success-ink);',
  collected: 'background:rgba(148,163,184,0.18);color:var(--muted);',
  cancelled: 'background:rgba(239,68,68,0.12);color:var(--danger-ink);',
};

function ktSectionHead(title, sub) {
  // The row wraps and the heading does not: without this the h3 was the item
  // that shrank, so on a phone "Conversion jobs" broke across two lines while
  // its one-line description sat beside it. Now the description drops under it.
  return `<div style="display:flex;flex-wrap:wrap;align-items:baseline;gap:2px 10px;margin:18px 2px 8px;">
    <h3 style="font-size:var(--fs-ui);font-weight:700;white-space:nowrap;">${title}</h3>
    <span style="font-size:var(--fs-small);color:var(--muted);">${sub || ''}</span></div>`;
}

async function renderKolTorahTab() {
  const content = document.getElementById('mainContent');
  kcSkeleton('koltorah');
  const res = await kcFetch('/api/kol-torah').then(r => r.json()).catch(() => null);
  if (!res || !res.success) { content.innerHTML = errorHtml('Couldn’t load Kol Torah'); return; }
  ktData = res;
  if (currentTab !== 'koltorah') return; // user navigated away mid-load
  const d = ktData;

  const activeTitles = d.titles.filter(t => t.active);
  const openJobs = d.jobs.filter(j => j.status === 'open' || j.status === 'ready');
  const outQty = d.stock.reduce((s, r) => s + r.qty, 0);
  const received30 = d.settlements
    .filter(s => Date.now() - new Date(s.createdAt).getTime() < 30 * 86400000)
    .reduce((s, x) => s + x.received, 0);

  const titleOptions = activeTitles.map(t =>
    `<option value="${t.id}">${escHtml(t.name)}${t.price ? ` — ${fmtGbp(t.price)}` : ''}</option>`).join('');

  // ── Jobs ────────────────────────────────────────────────────────────────
  // The loud button is the NEXT step, not always the last one.
  //
  // 'Collected' was btn-primary at every stage, so a job still OPEN — a CD
  // dropped off and not yet converted — drew the eye to the button that marks
  // it handed back, skipping the work. The quiet outline button beside it was
  // the one that actually came next. Measured 26 Aug on a live open job.
  //
  // Collected stays reachable from open, because a job done and handed over in
  // one visit is a real thing; it simply stops being the loudest thing on the
  // row when it is not what happens next.
  const jobBtns = (j) => {
    const b = [];
    const nextIs = (stage) => j.status === stage ? 'btn btn-primary' : 'btn btn-outline';
    if (j.status === 'open') b.push(['ready', 'Ready', `${nextIs('open')} kc-ic kc-ic-check`]);
    if (j.status === 'open' || j.status === 'ready') {
      b.push(['collected', '<i class="kc-ic kc-ic-upload" aria-hidden="true"></i> Collected',
        j.status === 'ready' ? 'btn btn-primary' : 'btn btn-outline']);
      b.push(['cancelled', '✕', 'action-btn danger']);
    }
    if (j.status === 'ready') b.push(['open', '', 'btn btn-outline kc-ic kc-ic-undo']);
    if (j.status === 'cancelled') b.push(['open', 'Reopen', 'btn btn-outline kc-ic kc-ic-undo']);
    return b.map(([to, label, cls]) =>
      `<button class="${cls}" style="font-size:var(--fs-micro);padding:4px 8px;" onclick="ktJobStatus('${j.id}','${to}')">${label}</button>`).join(' ');
  };
  const jobRows = d.jobs.length === 0
    ? `<tr><td colspan="6"><div class="empty-state"><div class="emoji kc-ic kc-ic-headphones" aria-hidden="true"></div><p>No conversion jobs yet — add the first drop-off above.</p></div></td></tr>`
    : d.jobs.map(j => `
      <tr>
        <td><div class="customer-name">${escName(j.customerName)}</div>
            <div style="font-size:var(--fs-micro);color:var(--muted);">${fmtDate(j.createdAt)}</div></td>
        <td style="white-space:nowrap;">${escHtml(KT_JOB_KINDS[j.kind] || j.kind)}${j.qty > 1 ? ` <span style="color:var(--muted);">× ${j.qty}</span>` : ''}</td>
        <td data-label="Details" style="max-width:260px;">${escHtml(j.details || '—')}</td>
        <td data-label="Price"><strong>${fmtGbp(j.price)}</strong></td>
        <td><span class="badge" style="${KT_JOB_BADGE[j.status] || ''}">${escHtml(j.status)}</span></td>
        <td style="white-space:nowrap;">${jobBtns(j)}</td>
      </tr>`).join('');

  // ── Consignment cards ───────────────────────────────────────────────────
  const shulCards = d.shuls.filter(s => s.active).map(s => {
    const rows = d.stock.filter(r => r.shulId === s.id && r.qty > 0);
    const held = rows.reduce((n, r) => n + r.qty, 0);
    const chips = rows.length
      ? rows.map(r => {
          const t = d.titles.find(x => x.id === r.titleId);
          const nm = t ? t.name : '(retired)';
          // A chip never wraps (the flag SVG is why), so a real shiur title —
          // "Shiur — Parshas Devarim, R' Shloime Taussig, Elul 5786 series" —
          // used to run straight off a 320px screen. The count is the half you
          // scan, so it holds its ground and the title takes the ellipsis.
          return `<span class="badge badge-clip" style="background:var(--bg-secondary);color:var(--ink-secondary);"
            title="${escHtml(`${r.qty} × ${nm}`)}"><span class="badge-fix">${r.qty} ×</span><span class="badge-text">${escHtml(nm)}</span></span>`;
        }).join(' ')
      : '<span style="font-size:var(--fs-small);color:var(--muted);">nothing on consignment</span>';
    const editing = ktEditShuls.has(s.id);
    return `
      <div style="border:1px solid var(--border);border-radius:8px;padding:12px 14px;background:var(--surface);">
        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">
          <strong>${escHtml(s.name)}</strong>
          ${s.contact ? `<span style="font-size:var(--fs-small);color:var(--muted);">${escHtml(s.contact)}</span>` : ''}
          ${s.customerName ? `<span class="badge" style="background:rgba(14,138,82,0.14);color:var(--success-ink);" title="Settlements post to this wallet">👛 ${escName(s.customerName)}</span>`
            : '<span class="badge" style="background:rgba(239,68,68,0.1);color:var(--danger-ink);" title="Link a customer record so settlements hit the ledger">no wallet link</span>'}
          <span style="margin-left:auto;font-size:var(--fs-small);color:var(--muted);">${held} CD${held === 1 ? '' : 's'} out</span>
          <button class="btn btn-outline" style="font-size:var(--fs-micro);padding:4px 8px;" onclick="ktToggleShulEdit('${s.id}')">${editing ? 'Close' : '✎ Edit'}</button>
        </div>
        <div style="margin:8px 0;display:flex;flex-wrap:wrap;gap:5px;">${chips}</div>
        ${editing ? `
        <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin:8px 0;padding:8px;border-radius:6px;background:var(--bg-secondary);">
          <input class="form-input" id="ktShulContact_${s.id}" value="${escHtml(s.contact || '')}" placeholder="Contact / gabbai" style="min-height:0;padding:6px 9px;font-size:var(--fs-small);min-width:170px;">
          <div style="max-width:220px;">${customerPicker(`ktShulCust_${s.id}`, {
            selected: s.customerId, special: { value: '', label: 'No wallet link' },
            label: 'Wallet link', style: 'min-height:0;padding:6px 9px;font-size:var(--fs-small);',
          })}</div>
          <button class="btn btn-outline btn-sm kc-ic kc-ic-save" style="font-size:var(--fs-micro);" onclick="ktSaveShul('${s.id}')">Save</button>
        </div>` : ''}
        <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;">
          <select class="form-input" id="ktMoveTitle_${s.id}" aria-label="Title to move for ${escHtml(s.name)}" style="min-height:0;padding:6px 9px;font-size:var(--fs-small);max-width:min(330px, 100%);">${titleOptions}</select>
          <label class="kt-fld">How many
            <input class="form-input" id="ktMoveQty_${s.id}" type="number" min="1" step="1" value="1" style="width:74px;min-height:0;padding:6px 9px;font-size:var(--fs-small);"></label>
          <button class="btn btn-outline kc-ic kc-ic-package" style="font-size:var(--fs-micro);padding:5px 9px;" onclick="ktMove('${s.id}','delivery')">Deliver</button>
          <button class="btn btn-outline kc-ic kc-ic-disc" style="font-size:var(--fs-micro);padding:5px 9px;" onclick="ktMove('${s.id}','sold')">Sold</button>
          <button class="btn btn-outline kc-ic kc-ic-undo" style="font-size:var(--fs-micro);padding:5px 9px;" onclick="ktMove('${s.id}','return')">Return</button>
        </div>
        ${/* Labels above the boxes, not placeholders inside them. "£ collected"
             did not fit its own 98px box and rendered as "£ collectec" — and a
             placeholder is a poor label anyway: it is the field's only name for
             a screen reader, and it disappears the moment anyone types, exactly
             when "which box was the money we got?" is being asked. */''}
        <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;margin-top:8px;padding-top:8px;border-top:1px dashed var(--border);">
          <span style="font-size:var(--fs-small);color:var(--muted);padding-bottom:7px;">Settle:</span>
          <label class="kt-fld">Sold
            <input class="form-input" id="ktSettleSold_${s.id}" type="number" min="0" step="0.01" placeholder="£" style="width:84px;min-height:0;padding:6px 9px;font-size:var(--fs-small);"></label>
          <label class="kt-fld">Collected
            <input class="form-input" id="ktSettleRecv_${s.id}" type="number" min="0" step="0.01" placeholder="£" style="width:84px;min-height:0;padding:6px 9px;font-size:var(--fs-small);"></label>
          <select class="form-input" id="ktSettleMethod_${s.id}" aria-label="Settlement method for ${escHtml(s.name)}" style="min-height:0;padding:6px 9px;font-size:var(--fs-small);width:110px;">
            <option value="cash">💵 Cash</option><option value="bank_transfer">🏦 Transfer</option><option value="card">💳 Card</option><option value="other">Other</option>
          </select>
          <button class="btn btn-primary kc-ic kc-ic-receipt" style="font-size:var(--fs-micro);padding:5px 10px;" onclick="ktSettle('${s.id}')">Settle</button>
        </div>
      </div>`;
  }).join('');

  // ── Titles table ────────────────────────────────────────────────────────
  const titleRows = d.titles.map(t => `
    <tr style="${t.active ? '' : 'opacity:0.55;'}">
      <td data-label="Code"><input class="form-input" id="ktT_code_${t.id}" value="${escHtml(t.code || '')}" style="width:74px;min-height:0;padding:5px 8px;font-size:var(--fs-small);"></td>
      <td data-label="Title"><input class="form-input" id="ktT_name_${t.id}" value="${escHtml(t.name)}" style="min-width:170px;min-height:0;padding:5px 8px;font-size:var(--fs-small);"></td>
      <td data-label="Speaker"><input class="form-input" id="ktT_speaker_${t.id}" value="${escHtml(t.speaker || '')}" style="min-width:130px;min-height:0;padding:5px 8px;font-size:var(--fs-small);"></td>
      <td data-label="£"><input class="form-input" id="ktT_price_${t.id}" type="number" min="0" step="0.01" value="${t.price.toFixed(2)}" style="width:84px;min-height:0;padding:5px 8px;font-size:var(--fs-small);"></td>
      <td data-label="Active"><input type="checkbox" id="ktT_active_${t.id}" ${t.active ? 'checked' : ''} style="accent-color:var(--accent);cursor:pointer;"></td>
      <td><button class="btn btn-outline kc-ic kc-ic-save" style="font-size:var(--fs-small);padding:5px 10px;" aria-label="Save title" onclick="ktSaveTitle('${t.id}')"></button></td>
    </tr>`).join('');

  content.innerHTML = `
    <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:4px;">
      ${[
        ['disc', `${activeTitles.length}`, 'titles in the catalogue'],
        ['institution', `${d.shuls.filter(s => s.active).length}`, 'shuls stocked'],
        ['package', `${outQty}`, 'CDs out on consignment'],
        ['headphones', `${openJobs.length}`, 'open jobs'],
        ['pound', fmtGbp(received30), 'collected, last 30 days'],
      ].map(([ico, big, label]) => `
        <div style="flex:1;min-width:140px;border:1px solid var(--border);border-radius:8px;padding:10px 14px;background:var(--surface);">
          <div class="kc-ic kc-ic-${ico}" style="font-size:var(--fs-title);font-weight:800;">${big}</div>
          <div style="font-size:var(--fs-micro);color:var(--muted);">${label}</div>
        </div>`).join('')}
    </div>

    ${ktSectionHead('Conversion jobs', 'CD → MP3 / SD and audio work — drop-off to collection')}
    ${'' /* The new-job form used to live inside the table's first row, which on
          a phone meant composing a job by scrolling sideways through cells.
          Same panel pattern as "Add a shul": the controls wrap instead. Ids
          unchanged — ktAddJob() reads the same fields. */}
    <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;margin-bottom:8px;padding:10px 12px;border:1px dashed var(--border);border-radius:8px;">
      <span style="font-size:var(--fs-small);font-weight:700;color:var(--accent);padding-bottom:7px;" class="kc-ic kc-ic-plus">New job</span>
      <div style="min-width:150px;max-width:180px;">${customerPicker('ktJobCust', {
        special: { value: 'walkin', label: 'Walk-in', icon: 'walk' }, label: 'Customer for this job',
        style: 'min-height:0;padding:6px 9px;font-size:var(--fs-small);',
      })}</div>
      <input class="form-input" id="ktJobName" placeholder="Name if walk-in" style="min-height:0;padding:6px 9px;font-size:var(--fs-small);min-width:140px;max-width:180px;">
      <select class="form-input" id="ktJobKind" style="min-height:0;padding:6px 9px;font-size:var(--fs-small);min-width:132px;">
        ${Object.entries(KT_JOB_KINDS).map(([k, l]) => `<option value="${k}">${l}</option>`).join('')}</select>
      ${/* The two number boxes were a bare "1" and a bare "£" sitting in a row
             of eight controls — the same nameless-box problem the Settle row
             had. A wrapping label names them on screen AND to a screen reader.
             The details box keeps its placeholder: that one is an EXAMPLE, not
             a label, which is what a placeholder is actually for. */''}
      <label class="kt-fld">How many
        <input class="form-input" id="ktJobQty" type="number" min="1" step="1" value="1" style="width:74px;min-height:0;padding:6px 9px;font-size:var(--fs-small);"></label>
      ${/* data-ph="example": this placeholder TEACHES THE FORMAT rather than
             naming the field, and "of R' Shloime" is the part that shows you
             can name the person. Owner kept it as it is on 18 Aug. The clipped
             sweep skips examples for that reason and counts them out loud, so
             the decision stays visible instead of becoming an exception
             nobody remembers. */''}
      <input class="form-input" id="ktJobDetails" data-ph="example" placeholder="e.g. 3 CDs of R' Shloime onto one SD" style="flex:1;min-width:180px;min-height:0;padding:6px 9px;font-size:var(--fs-small);">
      <label class="kt-fld">Price
        <input class="form-input" id="ktJobPrice" type="number" min="0" step="0.01" placeholder="£" style="width:80px;min-height:0;padding:6px 9px;font-size:var(--fs-small);"></label>
      <button class="btn btn-primary btn-sm" onclick="ktAddJob()">+ Add job</button>
    </div>
    <div class="table-wrap kc-stack-sm"><table>
      <thead><tr><th>Customer</th><th>Job</th><th>Details</th><th>£</th><th>Status</th><th></th></tr></thead>
      <tbody>
        ${jobRows}
      </tbody></table></div>

    ${ktSectionHead('Consignment by shul', 'deliver / sold / return moves the count; Settle records the money')}
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(min(340px,100%),1fr));gap:10px;">
      ${shulCards || '<div class="empty-state" style="grid-column:1/-1;"><div class="emoji kc-ic kc-ic-institution"></div><p>No shuls yet — add the first one below.</p></div>'}
    </div>
    <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-top:8px;padding:10px 12px;border:1px dashed var(--border);border-radius:8px;">
      <span style="font-size:var(--fs-small);font-weight:700;color:var(--accent);" class="kc-ic kc-ic-plus">Add a shul</span>
      <input class="form-input" id="ktNewShulName" placeholder="Shul name" style="min-height:0;padding:6px 9px;font-size:var(--fs-small);min-width:170px;">
      <input class="form-input" id="ktNewShulContact" placeholder="Contact / gabbai (optional)" style="min-height:0;padding:6px 9px;font-size:var(--fs-small);min-width:170px;">
      <div style="max-width:210px;" title="Link a customer record so settlements hit the ledger">${
        customerPicker('ktNewShulCust', {
          special: { value: '', label: 'No wallet link yet' }, label: 'Wallet link',
          style: 'min-height:0;padding:6px 9px;font-size:var(--fs-small);',
        })}</div>
      <button class="btn btn-outline btn-sm" onclick="ktSaveShul()">+ Add shul</button>
    </div>

    ${ktSectionHead('Titles catalogue', 'code · title · speaker · price — retire with the tick')}
    <div class="table-wrap kc-stack-sm"><table>
      <thead><tr><th>Code</th><th>Title</th><th>Speaker</th><th>£</th><th>Active</th><th></th></tr></thead>
      <tbody>
        ${titleRows}
      </tbody></table></div>
    ${'' /* Same move as the new-job form: composing in table cells means
          sideways scrolling on a phone. Ids unchanged — ktSaveTitle() reads
          the same fields. */}
    <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-top:8px;padding:10px 12px;border:1px dashed var(--border);border-radius:8px;">
      <span style="font-size:var(--fs-small);font-weight:700;color:var(--accent);" class="kc-ic kc-ic-plus">Add a title</span>
      <input class="form-input" id="ktNewT_code" placeholder="KT-…" style="width:74px;min-height:0;padding:5px 8px;font-size:var(--fs-small);">
      <input class="form-input" id="ktNewT_name" placeholder="Title" style="flex:1;min-width:150px;min-height:0;padding:5px 8px;font-size:var(--fs-small);">
      <input class="form-input" id="ktNewT_speaker" placeholder="Speaker" style="min-width:130px;min-height:0;padding:5px 8px;font-size:var(--fs-small);">
      <input class="form-input" id="ktNewT_price" type="number" min="0" step="0.01" placeholder="£" style="width:84px;min-height:0;padding:5px 8px;font-size:var(--fs-small);">
      <button class="btn btn-primary btn-sm" onclick="ktSaveTitle()">+ Add</button>
    </div>

    ${ktSectionHead('Takings — recent settlements', 'what each shul sold and what was collected')}
    <div class="table-wrap"><table>
      <thead><tr><th>Date</th><th>Shul</th><th>£ sold</th><th>£ collected</th><th>Method</th><th>Note</th></tr></thead>
      <tbody>${d.settlements.length === 0
        ? '<tr><td colspan="6"><div class="empty-state"><div class="emoji kc-ic kc-ic-receipt"></div><p>No settlements recorded yet.</p></div></td></tr>'
        : d.settlements.map(x => `
          <tr>
            <td class="kc-date">${fmtDate(x.createdAt)}</td>
            <td>${escHtml(x.shulName)}</td>
            <td>${fmtGbp(x.soldValue)}</td>
            <td><strong>${fmtGbp(x.received)}</strong></td>
            <td>${escHtml(x.method || '—')}</td>
            <td style="max-width:240px;font-size:var(--fs-small);color:var(--muted);">${escHtml(x.note || '')}</td>
          </tr>`).join('')}</tbody></table></div>`;
}

function ktFocusNewJob() {
  const el = document.getElementById('ktJobCust_search');
  if (el) { el.scrollIntoView({ behavior: 'smooth', block: 'center' }); el.focus(); }
}

function ktToggleShulEdit(id) {
  if (ktEditShuls.has(id)) ktEditShuls.delete(id); else ktEditShuls.add(id);
  // The current wallet link is preselected IN the option markup: the old
  // post-render sel.value assignment was lost on any intervening re-render,
  // and saving with the picker silently back on "No wallet link" unlinked
  // the shul's wallet (sweep 2026-08-02 #20).
  renderKolTorahTab();
}

async function ktPost(body) {
  return kcFetch('/api/kol-torah', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  }).then(r => r.json()).catch(() => null);
}

async function ktSaveTitle(id) {
  const v = (f) => document.getElementById(id ? `ktT_${f}_${id}` : `ktNewT_${f}`)?.value;
  const name = (v('name') || '').trim();
  if (!name) { toast('The title needs a name.', 'error'); return; }
  if (!kcBeginWrite('kt')) return;
  let res;
  try {
    res = await ktPost({
      op: 'title-save', id: id || undefined, code: v('code'), name, speaker: v('speaker'),
      price: parseFloat(v('price')) || 0,
      active: id ? !!document.getElementById(`ktT_active_${id}`)?.checked : true,
    });
  } finally { kcEndWrite('kt'); }
  if (!res || !res.success) { toast(res?.error || 'Could not save the title.', 'error'); return; }
  toast(id ? 'Title saved.' : 'Title added.', 'success');
  renderKolTorahTab();
}

async function ktSaveShul(id) {
  const name = id
    ? ktData?.shuls.find(s => s.id === id)?.name
    : (document.getElementById('ktNewShulName')?.value || '').trim();
  if (!name) { toast('The shul needs a name.', 'error'); return; }
  const contact = document.getElementById(id ? `ktShulContact_${id}` : 'ktNewShulContact')?.value;
  const customerId = document.getElementById(id ? `ktShulCust_${id}` : 'ktNewShulCust')?.value || null;
  if (!kcBeginWrite('kt')) return;
  let res;
  try {
    res = await ktPost({ op: 'shul-save', id: id || undefined, name, contact, customerId });
  } finally { kcEndWrite('kt'); }
  if (!res || !res.success) { toast(res?.error || 'Could not save the shul.', 'error'); return; }
  ktEditShuls.delete(id);
  toast(id ? 'Shul saved.' : 'Shul added.', 'success');
  renderKolTorahTab();
}

async function ktMove(shulId, kind) {
  const titleId = document.getElementById(`ktMoveTitle_${shulId}`)?.value;
  const qty = parseInt(document.getElementById(`ktMoveQty_${shulId}`)?.value, 10);
  if (!titleId) { toast('Add a title to the catalogue first.', 'error'); return; }
  if (!Number.isFinite(qty) || qty < 1) { toast('Quantity must be at least 1.', 'error'); return; }
  if (!kcBeginWrite('kt')) return;
  // Same-token retry per exact movement: a lost response replays the SAME
  // token and the server short-circuits, so "Deliver 10" can't land twice.
  // Changing any part of the movement (qty, title, kind) mints a fresh token.
  const fp = `${shulId}|${titleId}|${kind}|${qty}`;
  if (!ktMoveRefs[fp]) ktMoveRefs[fp] = kcRef();
  let res;
  try {
    res = await ktPost({ op: 'move', shulId, titleId, kind, qty, clientRef: ktMoveRefs[fp] });
  } finally { kcEndWrite('kt'); }
  if (!res || !res.success) { toast(res?.error || 'Could not record the movement.', 'error'); return; }
  delete ktMoveRefs[fp];
  if (res.duplicate) { toast('Movement already recorded — no double count.', 'info'); renderKolTorahTab(); return; }
  const verb = { delivery: 'Delivered', sold: 'Marked sold', return: 'Returned' }[kind] || 'Adjusted';
  toast(`${verb} ${qty} — ${res.qty} now at the shul.`, 'success');
  renderKolTorahTab();
}

async function ktSettle(shulId) {
  const shul = ktData?.shuls.find(s => s.id === shulId);
  const sold = parseFloat(document.getElementById(`ktSettleSold_${shulId}`)?.value) || 0;
  const received = parseFloat(document.getElementById(`ktSettleRecv_${shulId}`)?.value) || 0;
  const method = document.getElementById(`ktSettleMethod_${shulId}`)?.value || 'cash';
  if (sold <= 0 && received <= 0) { toast('Enter the £ sold and/or the £ collected.', 'error'); return; }
  if (!(await kcConfirm({
    title: 'Confirm settlement',
    body: `<strong>${escHtml(shul?.name || 'Shul')}</strong><br>
      CDs sold: ${fmtGbp(sold)} · collected now: ${fmtGbp(received)}
      ${shul?.customerName ? '<br>Posts to the linked wallet.' : '<br><em>No wallet link — recorded in Kol Torah only.</em>'}`,
    amount: received,
    okLabel: 'Record settlement',
  }))) return;
  if (!kcBeginWrite('kt')) return;
  // Same-token retry: a lost response replays the SAME settlement, the server
  // dedupes, and the shul is never settled twice.
  if (!ktSettleRefs[shulId]) ktSettleRefs[shulId] = kcRef();
  let res;
  try {
    res = await ktPost({ op: 'settle', shulId, soldValue: sold, received, method, clientRef: ktSettleRefs[shulId] });
  } finally { kcEndWrite('kt'); }
  if (!res || !res.success) { toast(res?.error || 'Could not record the settlement.', 'error'); return; }
  delete ktSettleRefs[shulId];
  toast(res.duplicate ? 'Settlement already recorded — no double post.' : 'Settlement recorded.', 'success');
  renderKolTorahTab();
}

async function ktAddJob() {
  const custId = document.getElementById('ktJobCust')?.value || 'walkin';
  const customerName = (document.getElementById('ktJobName')?.value || '').trim();
  if (custId === 'walkin' && !customerName) { toast('Pick a customer or type a name.', 'error'); return; }
  const kind = document.getElementById('ktJobKind')?.value;
  const qty = parseInt(document.getElementById('ktJobQty')?.value, 10) || 1;
  const details = document.getElementById('ktJobDetails')?.value;
  const price = parseFloat(document.getElementById('ktJobPrice')?.value) || 0;
  if (!kcBeginWrite('kt')) return;
  if (!ktJobRef) ktJobRef = kcRef();
  let res;
  try {
    res = await ktPost({
      op: 'job-save', customerId: custId === 'walkin' ? null : custId,
      customerName, kind, qty, details, price, clientRef: ktJobRef,
    });
  } finally { kcEndWrite('kt'); }
  if (!res || !res.success) { toast(res?.error || 'Could not save the job.', 'error'); return; }
  ktJobRef = null;
  toast(res.duplicate ? 'Job already saved — no double entry.' : 'Job added.', 'success');
  renderKolTorahTab();
}

async function ktJobStatus(id, to) {
  const job = ktData?.jobs.find(j => j.id === id);
  // Never act on a job we can't show: the collect confirm displays the amount,
  // and skipping it on stale data would charge without a confirmation.
  if (!job) { toast('That job needs a refresh — try again.', 'warning'); renderKolTorahTab(); return; }
  if (to === 'cancelled' && !(await kcConfirm({
    title: 'Cancel this job?',
    body: `<strong>${escHtml(job?.customerName || '')}</strong> — ${escHtml(KT_JOB_KINDS[job?.kind] || '')}.<br>Nothing has been charged; the job is just closed.`,
    okLabel: 'Cancel job',
  }))) return;
  if (to === 'collected' && job && job.price > 0 && !(await kcConfirm({
    title: 'Confirm collection',
    body: `<strong>${escName(job.customerName)}</strong> — ${escHtml(KT_JOB_KINDS[job.kind] || '')}${job.qty > 1 ? ` × ${job.qty}` : ''}.<br>${job.customerId ? 'Charges their wallet on collection.' : '<em>Walk-in — take the money at the till.</em>'}`,
    amount: job.price,
    okLabel: 'Mark collected',
  }))) return;
  if (!kcBeginWrite('kt')) return;
  let res;
  try {
    res = await ktPost({ op: 'job-status', id, status: to });
  } finally { kcEndWrite('kt'); }
  if (!res || !res.success) { toast(res?.error || 'Could not update the job.', 'error'); return; }
  toast('Job updated.', 'success');
  renderKolTorahTab();
}

// ─────────────────────────────────────────────
//  TASKS
// ─────────────────────────────────────────────
// Tables-native to-do list. Also displays the keyed auto-tasks the system
// raises (BALANCE-<id> arrears, passport expiry, overdue rentals).

let tasksList = [];

function taskPriorityBadge(p) {
  const styles = {
    High:   'background:rgba(239,68,68,0.15);color:var(--danger-ink);',
    Normal: 'background:rgba(0,96,168,0.10);color:var(--accent);',
    Low:    'background:rgba(148,163,184,0.15);color:var(--muted);',
  };
  return `<span class="badge" style="${styles[p] || styles.Normal}">${escHtml(p)}</span>`;
}

// ── Remind-me everywhere (the Slack pattern) ─────────────────────────────
// A ⏰ on any row creates a task that sleeps (snoozed) until its date, then
// surfaces in the Now lane pointing back at the thing.

function remindContextFor(kind, id) {
  switch (kind) {
    case 'customer': { const c = customers.find(x => x.id === id);
      return c && { label: `Follow up with ${c.firstName} ${c.lastName}`, customerId: c.id }; }
    case 'rental': { const r = rentals.find(x => x.id === id);
      return r && { label: `Check rental — ${r.customerName} (${r.phoneNumber})`, customerId: r.customerId }; }
    case 'booking': { const b = bookings.find(x => x.id === id);
      return b && { label: `Booking ${b.route} — ${b.customerName || b.passenger || ''}`.trim(), customerId: b.customerId }; }
    case 'repair': { const r = repairs.find(x => x.id === id);
      return r && { label: `Repair — ${r.customerName} (${r.device || 'device'})`, customerId: r.customerId }; }
    case 'sim': { const s = sims.find(x => x.id === id);
      return s && { label: `SIM — ${s.customerName} (${s.provider || 'plan'})`, customerId: s.customerId }; }
    case 'vn': { const v = virtualNumbers.find(x => x.id === id);
      return v && { label: `Virtual number ${v.number}${v.customerName ? ' — ' + v.customerName : ''}`, customerId: v.customerId }; }
    case 'note': // free-standing reminder not tied to a record
      return { label: 'Reminder', customerId: null };
  }
  return null;
}

// Same-day reminders: fire as an in-app popup (toast + browser notification)
// while the app is open; a matching task due today is the safety net.
function localReminders() {
  try { return JSON.parse(localStorage.getItem('kcLocalReminders') || '[]'); } catch { return []; }
}

async function saveQuickReminder(kind, id, minutes) {
  const ctx = remindContextFor(kind, id);
  if (!ctx) return;
  const list = localReminders();
  list.push({ at: Date.now() + minutes * 60000, label: ctx.label });
  localStorage.setItem('kcLocalReminders', JSON.stringify(list));
  if ('Notification' in window && Notification.permission === 'default') Notification.requestPermission();
  // Safety net if the tab closes: a task in today's Now lane.
  await window.api.addTask({
    title: `⏰ ${ctx.label}`,
    dueDate: localISO(),
    priority: 'High',
    notes: `quick reminder — ${minutes} min, set ${new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}`,
    customerId: ctx.customerId || null,
  }).catch(() => null);
  closeDynamicModal();
  toast(`Will pop up in ${minutes >= 60 ? (minutes / 60) + ' hour' + (minutes > 60 ? 's' : '') : minutes + ' minutes'}.`, 'success', 'clock');
}

function checkLocalReminders() {
  const list = localReminders();
  const due = list.filter(r => r.at <= Date.now());
  if (!due.length) return;
  localStorage.setItem('kcLocalReminders', JSON.stringify(list.filter(r => r.at > Date.now())));
  for (const r of due) {
    toast(`REMINDER: ${r.label}`, 'warning', 'clock');
    if ('Notification' in window && Notification.permission === 'granted') {
      new Notification('Kosher Connect — reminder', { body: r.label, icon: '/logo.png' });
    }
  }
}

function openRemindModal(kind, id) {
  const ctx = remindContextFor(kind, id);
  if (!ctx) return;
  const tomorrow = parseLocalDate(localISO());
  tomorrow.setDate(tomorrow.getDate() + 1);
  showDynamicModal(`
    <div class="modal-title kc-ic kc-ic-clock">Remind me</div>
    <div style="font-size:var(--fs-body);color:var(--muted);margin-bottom:14px;">${escHtml(ctx.label)}</div>
    <div style="display:flex;gap:8px;align-items:center;margin-bottom:14px;flex-wrap:wrap;">
      <span style="font-size:var(--fs-small);color:var(--muted);">Quick (pops up in-app):</span>
      <button type="button" class="btn btn-outline btn-sm" onclick="saveQuickReminder('${escHtml(kind)}','${escHtml(String(id))}',30)">30 min</button>
      <button type="button" class="btn btn-outline btn-sm" onclick="saveQuickReminder('${escHtml(kind)}','${escHtml(String(id))}',60)">1 hour</button>
      <button type="button" class="btn btn-outline btn-sm" onclick="saveQuickReminder('${escHtml(kind)}','${escHtml(String(id))}',180)">3 hours</button>
    </div>
    <div class="section-divider" style="margin:0 0 10px;">or at a date &amp; time</div>
    <div class="form-grid">
      <div class="form-group">
        <label class="form-label">Date</label>
        <input class="form-input" type="date" id="rmDate" value="${localISO(tomorrow)}">
      </div>
      <div class="form-group">
        <label class="form-label">Time <span style="color:var(--muted);font-weight:400;">(optional — pops up at this exact time)</span></label>
        <input class="form-input" type="time" id="rmTime">
      </div>
      <div class="form-group">
        <label class="form-label">Priority</label>
        <select class="form-input" id="rmPriority">
          <option value="Normal">📋 Next</option>
          <option value="High">🔥 Now</option>
          <option value="Low">🌙 Later</option>
        </select>
      </div>
      <div class="form-group form-full">
        <label class="form-label">Note (optional)</label>
        <input class="form-input" id="rmNote" placeholder="What should you remember?">
      </div>
    </div>
    <div class="modal-actions">
      <button class="btn btn-outline" onclick="closeDynamicModal()">Cancel</button>
      <button class="btn btn-primary kc-ic kc-ic-clock" onclick="saveReminder('${escHtml(kind)}','${escHtml(String(id))}')">Set reminder</button>
    </div>
  `);
}

async function saveReminder(kind, id) {
  const ctx = remindContextFor(kind, id);
  if (!ctx) return;
  const date = document.getElementById('rmDate').value;
  if (!date) { toast('Pick a date.', 'error'); return; }
  const time = document.getElementById('rmTime').value; // HH:MM or ''
  const note = document.getElementById('rmNote').value.trim();
  // A free-standing 'note' reminder uses the note itself as its label.
  if (kind === 'note' && !note) { toast('Type what to remind you about.', 'error'); return; }
  const baseLabel = (kind === 'note') ? note : ctx.label;

  // With a time, schedule an exact-moment popup (fires while the app is
  // open) on top of the backup task; without one it's a plain day reminder.
  if (time) {
    const [hh, mm] = time.split(':').map(Number);
    const target = parseLocalDate(date);
    target.setHours(hh || 0, mm || 0, 0, 0);
    if (target.getTime() <= Date.now()) { toast('That time is in the past.', 'error'); return; }
    const list = localReminders();
    list.push({ at: target.getTime(), label: (kind !== 'note' && note) ? `${baseLabel} — ${note}` : baseLabel });
    localStorage.setItem('kcLocalReminders', JSON.stringify(list));
    if ('Notification' in window && Notification.permission === 'default') Notification.requestPermission();
  }

  const res = await window.api.addTask({
    title: `⏰ ${baseLabel}${time ? ' @ ' + time : ''}`,
    dueDate: date,
    priority: document.getElementById('rmPriority').value,
    notes: note,
    customerId: ctx.customerId || null,
    snoozedUntil: date, // sleeps until its day, then lands in the Now lane
  });
  if (!res.success) { toast(res.error || 'Could not set the reminder.', 'error'); return; }
  closeDynamicModal();
  toast(time ? `<i class="kc-ic kc-ic-clock" aria-hidden="true"></i> Will pop up ${fmtDate(date)} at ${time}.` : `Reminder set for ${fmtDate(date)}.`, 'success');
}

// ── Business summary ─────────────────────────────────────────────────────
// Ledger entry_types collapsed into the services the owner thinks in.
// entry_type → [icon, name]. The name is separate from the icon, and that is
// the whole point: these values used to BE the display markup, and the same
// string was doing three jobs — the bar's label, the row's grouping key, and
// the tooltip via escHtml(). The third job shipped
//   title="<i class="kc-ic kc-ic-phone" aria-hidden="true">…"
// into the business summary. Markup is not words; a value that has to be read
// as words carries them itself.
const REVENUE_CATS = {
  rental: ['phone', 'Rentals'], rental_loss: ['phone', 'Rentals'], rental_adjustment: ['phone', 'Rentals'],
  sim_charge: ['signal', 'SIM plans'], sim_annual: ['signal', 'SIM plans'], sim_additional: ['signal', 'SIM plans'],
  sim_replacement: ['signal', 'SIM plans'], sim_service: ['signal', 'SIM plans'],
  repair: ['wrench', 'Repairs'],
  booking: ['plane', 'Flights & tickets'],
  online_service: ['printer', 'Print & online'],
  phone_sale: ['trolley', 'Shop'], stock_sale: ['trolley', 'Shop'],
  virtual_number: ['digits', 'Virtual numbers'],
  extra_charge: ['plus', 'Extra charges'],
  manual_adjustment: ['pencil', 'Adjustments'],
};
// name → icon, so a row that has been grouped by its words can still draw one.
const REVENUE_CAT_ICONS = Object.fromEntries(Object.values(REVENUE_CATS).map(([ic, name]) => [name, ic]));
function groupRevenue(byType) {
  const groups = {};
  const otherTypes = [];
  for (const [type, amt] of Object.entries(byType || {})) {
    const cat = REVENUE_CATS[type];
    if (!cat) otherTypes.push(`${type.replace(/_/g, ' ')} ${fmtGbp(amt)}`);
    const key = cat ? cat[1] : 'Other';
    groups[key] = (groups[key] || 0) + amt;
  }
  const rows = Object.entries(groups).sort((a, b) => b[1] - a[1]);
  // "Other" used to be an unexplained bar. Whatever fell into it is named in
  // the row's tooltip, so an unrecognised entry_type is a question you can
  // answer rather than a mystery you have to live with.
  return { rows, otherTypes };
}

// A report window is "everything since <date>", so a discrete period is the
// difference of two of them. One shape, used for months and for weeks.
const bizDiff = (a, b) => {
  if (!a) return null;
  if (!b) return a;
  const byType = { ...(a.byType || {}) };
  for (const [k, v] of Object.entries(b.byType || {})) {
    byType[k] = Math.round(((byType[k] || 0) - v) * 100) / 100;
    if (byType[k] <= 0) delete byType[k];
  }
  const n = (x) => Math.round((x || 0) * 100) / 100;
  return {
    byType,
    charged: n(a.charged - b.charged), received: n(a.received - b.received),
    refunded: n(a.refunded - b.refunded), refundsOwed: n(a.refundsOwed),
  };
};
const bizMonthStart = (back) => {
  const d = new Date();
  d.setDate(1); d.setMonth(d.getMonth() - back);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-01`;
};
const bizMonthLabel = (back) => {
  const d = new Date();
  d.setDate(1); d.setMonth(d.getMonth() - back);
  return d.toLocaleDateString('en-GB', { month: 'short' });
};

let bizData = null;
let bizPeriod = 'month';
// A range the owner picks, held apart from the fixed periods so switching to
// "This week" and back does not lose it. Fetched on demand — the fixed periods
// are pre-fetched when the summary opens, this one cannot be.
let bizCustom = null;   // { from, to, now, prev, prevLabel }

async function openBusinessSummary() {
  showDynamicModal(`
    <div class="modal-title kc-ic kc-ic-chart">Business summary</div>
    <div id="bizSummaryBody" style="color:var(--muted);padding:20px 4px;">Loading…</div>`);

  const rep = (from) => kcFetch('/api/ledger?report=1&from=' + from)
    .then(r => r.json()).catch(() => null);
  const day = (back) => localISO(new Date(Date.now() - back * 86400000));
  // Six month-starts (this month back to five ago) + two week anchors. Every
  // discrete period below is a difference of two of these, so the numbers can
  // never disagree with each other the way two independent queries can.
  const months = [0, 1, 2, 3, 4, 5, 6].map(bizMonthStart);
  const [w0, w1, ...ms] = await Promise.all([
    rep(day(6)), rep(day(13)), ...months.map(rep),
  ]);
  const body = document.getElementById('bizSummaryBody');
  if (!body) return;
  if (!ms[0]?.success) {
    body.innerHTML = `<div style="color:var(--danger-ink);padding:6px 0;">${ms[0]?.error || 'Could not load the summary.'}</div>`;
    return;
  }
  bizData = {
    week: w0, prevWeek: bizDiff(w1, w0),
    month: ms[0], prevMonth: bizDiff(ms[1], ms[0]),
    months: ms,
  };
  body.style.color = 'var(--text)';
  body.style.padding = '0';
  renderBizSummary();
}

// The periods on offer, in one place: the screen renders from this and the CSV
// exports from it, so a file can never describe a period the screen doesn't.
function bizPeriods() {
  const d = bizData;
  if (!d) return {};
  return {
    week:  { label: 'This week',  now: d.week,  prev: d.prevWeek,  prevLabel: 'previous 7 days' },
    month: { label: 'This month', now: d.month, prev: d.prevMonth, prevLabel: 'last month' },
    last:  { label: 'Last month', now: d.prevMonth, prev: bizDiff(d.months[2], d.months[1]), prevLabel: 'the month before' },
    ...(bizCustom ? { custom: {
      label: `${fmtDate(bizCustom.from)} → ${fmtDate(bizCustom.to)}`,
      now: bizCustom.now, prev: bizCustom.prev, prevLabel: bizCustom.prevLabel,
    } } : {}),
  };
}
// The window a period covers, as two dates. The money tiles get their figures
// by subtracting two "since" snapshots; the customer figures need the window
// itself, and this is the one place that says what each period means.
function bizPeriodRange(key = bizPeriod) {
  const today = localISO();
  const back = (n) => localISO(new Date(Date.now() - n * 86400000));
  if (key === 'custom' && bizCustom) return { from: bizCustom.from, to: bizCustom.to };
  if (key === 'week') return { from: back(6), to: today };
  if (key === 'last') {
    const thisMonth = bizMonthStart(0);
    return { from: bizMonthStart(1), to: localISO(new Date(new Date(`${thisMonth}T00:00:00`).getTime() - 86400000)) };
  }
  return { from: bizMonthStart(0), to: today };   // this month
}

let bizPeople = {};   // period key → the customer figures, fetched once each

async function bizLoadPeople(key = bizPeriod) {
  if (bizPeople[key]) return bizPeople[key];
  const { from, to } = bizPeriodRange(key);
  const r = await kcFetch(`/api/ledger?customers=1&from=${from}&to=${to}`)
    .then(x => x.json()).catch(() => null);
  if (r?.success) { bizPeople[key] = r; renderBizSummary(); }
  return r;
}

/**
 * Who the shop served, under the money it took from them.
 *
 * "Served" counts a CHARGE, not a payment — settling an old debt is not being
 * served again — and "new" means a first-ever charge rather than a record
 * created date, because 604 of these customers were imported from a
 * spreadsheet and none of them were new the day the import ran.
 */
function bizPeopleHtml() {
  const p = bizPeople[bizPeriod];
  if (!p) { bizLoadPeople(); return ''; }
  if (!p.served) return `<div class="biz-people"><span class="biz-people-empty">Nobody was charged in this period.</span></div>`;
  const cell = (label, value, sub = '') =>
    `<div class="biz-person"><div class="biz-person-val">${value}</div>
      <div class="biz-person-lbl">${escHtml(label)}</div>${sub ? `<div class="biz-person-sub">${sub}</div>` : ''}</div>`;
  return `<div class="section-divider" style="margin:18px 0 8px;">Who was served</div>
    <div class="biz-people">
      ${cell('customers served', p.served, `${p.returningCustomers} came back · ${p.newCustomers} new`)}
      ${cell('average each', fmtGbp(p.averageSpend))}
      ${cell('biggest', fmtGbp(p.topCustomerCharged), p.topCustomer ? escName(p.topCustomer) : '')}
    </div>`;
}

function bizCurrentPeriod() {
  const all = bizPeriods();
  return all[bizPeriod] || all.month || null;
}

function bizSetPeriod(p) { bizPeriod = p; renderBizSummary(); }

/**
 * Show any two dates the owner picks.
 *
 * The report endpoint answers "everything since DATE", so a discrete period is
 * the difference of two of those — exactly what bizDiff already does for the
 * fixed tabs. A range therefore needs no new endpoint and, more importantly,
 * cannot disagree with the tabs beside it.
 *
 * The comparison is the equal-length run-up immediately before, so a fortnight
 * is measured against the fortnight before it.
 */
async function bizApplyRange() {
  const from = document.getElementById('bizFrom')?.value || '';
  const to = document.getElementById('bizTo')?.value || '';
  if (!from || !to) { toast('Pick both dates.', 'warning'); return; }
  if (to < from) { toast('The end is before the start.', 'warning'); return; }

  const dayAfter = (iso) => localISO(new Date(new Date(`${iso}T00:00:00`).getTime() + 86400000));
  const days = Math.round((new Date(`${to}T00:00:00`) - new Date(`${from}T00:00:00`)) / 86400000) + 1;
  const before = localISO(new Date(new Date(`${from}T00:00:00`).getTime() - days * 86400000));
  const rep = (d) => kcFetch('/api/ledger?report=1&from=' + d).then(r => r.json()).catch(() => null);

  const [sinceFrom, sinceAfterTo, sinceBefore] = await Promise.all([rep(from), rep(dayAfter(to)), rep(before)]);
  if (!sinceFrom?.success) { toast('Could not load that range — check the connection and try again.', 'error'); return; }
  bizCustom = {
    from, to,
    now: bizDiff(sinceFrom, sinceAfterTo),
    prev: bizDiff(sinceBefore, sinceFrom),
    prevLabel: `the ${days} day${days === 1 ? '' : 's'} before`,
  };
  bizPeriod = 'custom';
  delete bizPeople.custom;      // same key, different dates behind it
  renderBizSummary();
}

/**
 * The figures on screen, as a file — the one thing an accountant always asks
 * for. Built from what is RENDERED rather than re-queried, so the file and the
 * screen can never differ.
 */
function bizExportCsv() {
  if (!bizData) return;
  const P = bizCurrentPeriod();
  if (!P || !P.now) { toast('Nothing to export yet.', 'warning'); return; }
  const esc = (v) => `"${String(v ?? '').replace(/"/g, '""')}"`;
  const money = (v) => (Math.round((Number(v) || 0) * 100) / 100).toFixed(2);
  const { rows } = groupRevenue(P.now.byType);
  const lines = [
    ['Kosher Connect — business summary'],
    ['Period', P.label],
    ['Compared with', P.prevLabel || ''],
    ['Generated', new Date().toLocaleString('en-GB')],
    [],
    ['Service', 'Billed £', 'Previous £'],
    ...rows.map(([label, amt]) => {
      const prevRow = P.prev ? Object.fromEntries(groupRevenue(P.prev.byType).rows)[label] : '';
      return [label.replace(/^• /, ''), money(amt), prevRow === undefined ? '' : money(prevRow)];
    }),
    [],
    ['Billed total', money(P.now.charged)],
    ['Received', money(P.now.received)],
    ['Still owed', money(Math.max(0, (P.now.charged || 0) - (P.now.received || 0)))],
    ['Refunds issued', money(P.now.refunded)],
    ['Refunds still to pay out', money(P.now.refundsOwed)],
  ];
  const csv = lines.map(r => (r.length ? r.map(esc).join(',') : '')).join('\r\n');
  const stamp = bizCustom && bizPeriod === 'custom' ? `${bizCustom.from}_${bizCustom.to}` : bizPeriod;
  kcDownload(`kosher-connect-summary-${stamp}.csv`, csv, 'text/csv;charset=utf-8');
  toast('Exported.', 'success');
}

// Hand the browser a file. One place, so every export behaves the same and the
// object URL is always released.
function kcDownload(filename, content, mime = 'text/plain') {
  const blob = new Blob(['\ufeff' + content], { type: mime });   // BOM: Excel reads £ properly
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function renderBizSummary() {
  const body = document.getElementById('bizSummaryBody');
  if (!body || !bizData) return;
  const d = bizData;
  const PERIODS = bizPeriods();
  const P = bizCurrentPeriod();
  const now = P.now || { byType: {}, charged: 0, received: 0, refunded: 0, refundsOwed: 0 };
  const prev = P.prev;

  // ── KPI row. A handful of headline numbers is a row of stat tiles, not a
  // chart — and each carries its change against the comparable period, which
  // is the question a total always raises next.
  const delta = (a, b) => {
    if (!prev || !Number.isFinite(b) || b === 0) return '';
    const pct = Math.round(((a - b) / Math.abs(b)) * 100);
    if (!Number.isFinite(pct) || pct === 0) return `<span class="biz-delta flat">— level vs ${P.prevLabel}</span>`;
    const up = pct > 0;
    return `<span class="biz-delta ${up ? 'up' : 'down'}">${up ? '▲' : '▼'} ${Math.abs(pct)}% vs ${P.prevLabel}</span>`;
  };
  const rate = now.charged > 0 ? Math.min(100, Math.round((now.received / now.charged) * 100)) : 0;
  const prevRate = prev && prev.charged > 0 ? Math.round((prev.received / prev.charged) * 100) : null;
  const owed = Math.max(0, (now.charged || 0) - (now.received || 0));

  const tiles = `
    <div class="biz-kpis">
      <div class="biz-kpi">
        <div class="biz-kpi-label">Billed</div>
        <div class="biz-kpi-val">${fmtGbp(now.charged)}</div>
        ${delta(now.charged, prev?.charged)}
      </div>
      <div class="biz-kpi">
        <div class="biz-kpi-label">Received</div>
        <div class="biz-kpi-val">${fmtGbp(now.received)}</div>
        ${delta(now.received, prev?.received)}
      </div>
      <div class="biz-kpi">
        <div class="biz-kpi-label">Collected</div>
        <div class="biz-kpi-val">${rate}%</div>
        <div class="biz-meter" role="img" aria-label="${rate}% of what was billed has been received">
          <div class="biz-meter-fill" style="width:${rate}%;"></div>
        </div>
        ${prevRate === null ? ''
          : rate === prevRate ? `<span class="biz-delta flat">— level vs ${P.prevLabel}</span>`
          : `<span class="biz-delta ${rate > prevRate ? 'up' : 'down'}">${rate > prevRate ? '▲' : '▼'} ${Math.abs(rate - prevRate)} pts vs ${P.prevLabel}</span>`}
      </div>
      <div class="biz-kpi">
        <div class="biz-kpi-label">Still owed</div>
        <div class="biz-kpi-val ${owed > 0 ? 'owed' : ''}">${fmtGbp(owed)}</div>
        <span class="biz-delta flat">billed but not yet in</span>
      </div>
    </div>`;

  // ── Revenue by service. Magnitude by category: one hue, values labelled
  // directly, so identity never rests on colour. Share is spelled out because
  // "how much of the month is rentals" is the question the bars invite.
  const { rows, otherTypes } = groupRevenue(now.byType);
  const total = rows.reduce((n, [, a]) => n + a, 0);
  const max = Math.max(1, ...rows.map(([, a]) => a));
  const prevByCat = prev ? Object.fromEntries(groupRevenue(prev.byType).rows) : null;
  const bars = rows.length ? rows.map(([label, amt]) => {
    const share = total > 0 ? Math.round((amt / total) * 100) : 0;
    const was = prevByCat ? prevByCat[label] : undefined;
    const move = (was === undefined || was === 0) ? '' :
      (amt > was ? '<span class="biz-move up" aria-hidden="true">▲</span>'
       : amt < was ? '<span class="biz-move down" aria-hidden="true">▼</span>' : '');
    const other = label === 'Other' && otherTypes.length
      ? ` — ${otherTypes.join(', ')}` : '';
    const wasNote = was === undefined ? '' : ` — was ${fmtGbp(was)} ${P.prevLabel}`;
    return `
      <div class="bizbar-row" title="${escHtml(label + wasNote + other)}">
        <span class="bizbar-label kc-ic kc-ic-${REVENUE_CAT_ICONS[label] || 'tag'}">${escHtml(label)}</span>
        <div class="bizbar-track"><div class="bizbar-fill" style="width:${Math.max(3, (amt / max) * 100).toFixed(1)}%;"></div></div>
        <span class="bizbar-val">${move}${fmtGbp(amt)}<span class="bizbar-share">${share}%</span></span>
      </div>`;
  }).join('') : '<div class="biz-empty">Nothing charged in this period.</div>';

  // ── Six months, billed against received. Same hue, two shades: this is one
  // measure and the part of it that came in, not two competing series.
  // Each anchor is "everything since", so an EARLIER anchor covers more time.
  // Month i on its own is therefore months[i] minus months[i-1] — the later
  // one is the subtrahend. Getting this backwards paints six negative columns.
  const mv = [0, 1, 2, 3, 4, 5].map(i => ({
    label: bizMonthLabel(i),
    ...(i === 0 ? d.months[0] : bizDiff(d.months[i], d.months[i - 1])) || { charged: 0, received: 0 },
  })).reverse();
  const mMax = Math.max(1, ...mv.map(m => m.charged));
  // Six empty columns and six £0.00 labels is a chart of nothing taking up a
  // third of the card. Only a brand-new shop sees it, and what it should say
  // is that there is no history yet.
  const trend = mv.every(m => !(m.charged > 0) && !(m.received > 0)) ? `
    <div class="biz-empty">No billing history yet — the first six months will chart here.</div>` : `
    <div class="biz-trend" role="img" aria-label="Billed and received for each of the last six months">
      ${mv.map(m => `
        <div class="biz-tcol" title="${escHtml(m.label)} — billed ${fmtGbp(m.charged)}, received ${fmtGbp(m.received)}">
          <div class="biz-tstack">
            <div class="biz-tbilled" style="height:${Math.max(2, (m.charged / mMax) * 100).toFixed(1)}%;">
              <div class="biz-treceived" style="height:${m.charged > 0 ? Math.min(100, (m.received / m.charged) * 100).toFixed(1) : 0}%;"></div>
            </div>
          </div>
          <div class="biz-tlabel">${escHtml(m.label)}</div>
          <div class="biz-tval">${fmtGbp(m.charged)}</div>
        </div>`).join('')}
    </div>
    <div class="biz-legend">
      <span><i class="biz-sw billed"></i> Billed</span>
      <span><i class="biz-sw received"></i> Received</span>
    </div>`;

  // A period with no money in it at all — an ordinary thing to open on a
  // Sunday morning. Four £0.00 tiles, a 0% meter and "Nothing charged in this
  // period" say the same nothing five times over, and the eye has to read all
  // five to learn it. Say it once. The six-month trend stays below, because
  // that is where an empty week gets its meaning. Refunds count as money
  // moving, so a period with only refunds is NOT blank.
  const emptyPeriod = !(now.charged > 0) && !(now.received > 0) && !(now.refunded > 0);

  body.innerHTML = `
    <div class="biz-tabs" role="tablist">
      ${Object.entries(PERIODS).map(([k, v]) => `
        <button class="biz-tab${k === bizPeriod ? ' active' : ''}" role="tab"
          aria-selected="${k === bizPeriod}" onclick="bizSetPeriod('${k}')">${escHtml(v.label)}</button>`).join('')}
    </div>
    ${/* Any two dates, and the same comparison the fixed periods get — against
         the run-up of equal length immediately before, so "the fortnight of
         Succos" is measured against the fortnight before it rather than
         against nothing. Built from the same endpoint the fixed periods use
         (a difference of two open-ended snapshots), so the numbers cannot
         disagree with the tabs above them. */''}
    <div class="biz-range">
      <label class="biz-range-lbl">From <input class="form-input" type="date" id="bizFrom" value="${escHtml(bizCustom?.from || '')}"></label>
      <label class="biz-range-lbl">To <input class="form-input" type="date" id="bizTo" value="${escHtml(bizCustom?.to || '')}"></label>
      <button class="btn btn-outline btn-sm" onclick="bizApplyRange()">Show this range</button>
      <button class="btn btn-outline btn-sm" style="margin-inline-start:auto;" onclick="bizExportCsv()">⤓ Export CSV</button>
    </div>
    ${emptyPeriod ? `
    <div class="biz-blank">
      <div class="biz-blank-mark kc-ic kc-ic-postbox" aria-hidden="true"></div>
      <div>
        <div class="biz-blank-title">Nothing billed or received ${escHtml(P.label.toLowerCase())}</div>
        <div class="biz-blank-sub">No charge and no payment has landed in this period yet.</div>
      </div>
    </div>` : `
    ${tiles}
    <div class="biz-section">Revenue by service · ${P.label.toLowerCase()}</div>
    <div class="bizbars">${bars}</div>
    ${now.refunded ? `<div class="biz-note">Refunds issued ${fmtGbp(now.refunded)}${now.refundsOwed ? ` · ${fmtGbp(now.refundsOwed)} still to be paid back out` : ' · all paid out'}</div>` : ''}
    ${bizPeopleHtml()}`}
    <div class="biz-section">Last six months</div>
    ${trend}
    <div class="biz-foot">“Billed” is what was charged; “Received” is money actually taken in (payments and top-ups). Every period is measured off the same running totals, so the figures always add up against each other.</div>`;
}

// ── Command palette (Ctrl/Cmd+K) ─────────────────────────────────────────
// One box that finds anything: customers, phones (by number / IMEI / ICCID —
// the barcode scanner types straight into it), rentals, bookings, and quick
// commands. Keyboard: ↑↓ + Enter, Esc closes.

let paletteIndex = 0;
let paletteResults = [];

// A tab-scoped create: navigate to the tab first, then open its modal, so the
// view underneath (and any post-save re-render) matches the record type — the
// same pattern the "New Customer" command has always used.
const openOnTab = (tab, fn) => { goToTab(tab); setTimeout(() => fn(), 130); };

// Apply a saved-filter view, then jump to its tab. Filters persist exactly
// like the on-page dropdowns — the tab's own "Clear" button resets them.
const filterView = (tab, apply, reRender) => { apply(); goToTab(tab); if (reRender) setTimeout(reRender, 60); };

// ── "How do I…?" — the curated walk-throughs ──────────────────────────────
// Owner's standard, 08-17: "If a screen needs explaining, it has failed.
// Anyone should understand any screen on first sight, with no training and no
// manual." This panel is the honest admission that no system clears that bar
// every day, and the safety net for the afternoon when someone new is covering
// the counter.
//
// The steps live in lib/guides.mjs and arrive here as public/guides.js,
// generated at build time — one place to edit a guide, and no chance of the
// counter reading a step that was corrected somewhere else.
function openHowToModal(prefill = '') {
  showDynamicModal(`
    <div class="modal-title kc-ic kc-ic-help">Help</div>
    <div style="font-size:var(--fs-small);color:var(--muted);margin-bottom:10px;">
      Every job in the shop, step by step. Ask in your own words — "someone brought a phone back",
      "the writing is too small".</div>
    <input class="form-input" id="howToSearch" placeholder="What do you want to do?" autocomplete="off"
      oninput="renderHowTo()" onkeydown="if(event.key==='Enter')renderHowTo()">
    <!-- The other two kinds of help, ABOVE the list. Below it they sat under
         twenty guides and were only ever seen by someone who had already
         scrolled past the answer they came for. Different questions, and the
         labels say which is which rather than leaving it to an emoji: these
         steps are "how do I do this job", the assistant is "what do the
         numbers say". Whatever has been typed is carried across, so a question
         the guides missed does not have to be typed twice. -->
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin:10px 0 4px;">
      <button class="btn btn-outline btn-sm kc-ic kc-ic-bot" style="white-space:normal;text-align:left;"
        onclick="closeDynamicModal();openAssistantModal(document.getElementById('howToSearch')?.value || '')">Ask about the shop's numbers</button>
      <a class="btn btn-outline btn-sm" href="/manual" target="_blank" rel="noopener"><i class="kc-ic kc-ic-book" aria-hidden="true"></i> The full manual</a>
    </div>
    <div id="howToOut" style="margin-top:12px;"></div>
  `);
  setTimeout(() => {
    const i = document.getElementById('howToSearch');
    if (i) { if (prefill) i.value = prefill; i.focus(); }
    renderHowTo();
  }, 40);
}

function howToGuides() { return Array.isArray(window.KC_GUIDES) ? window.KC_GUIDES : []; }

function renderHowTo() {
  const out = document.getElementById('howToOut');
  if (!out) return;
  const all = howToGuides();
  if (!all.length) {
    out.innerHTML = `<div class="empty-state"><div class="emoji kc-ic kc-ic-help"></div><p>The guides did not load.</p>
      <small>Reload the page — and Ctrl+K → “Ask” still reaches the assistant meanwhile.</small></div>`;
    return;
  }
  const q = (document.getElementById('howToSearch')?.value || '').trim();
  // Where they are standing is the best guess at what they are stuck on. With
  // nothing typed the panel leads with this screen's jobs; while searching it
  // is only a tie-break (lib/guides.mjs), so asking about a payment from the
  // Rentals screen still finds the payment guide.
  const list = q
    ? (window.kcMatchGuides ? window.kcMatchGuides(q, all, { limit: 6, boostTab: currentTab }) : [])
    : all;

  if (!list.length) {
    // An honest miss beats a confident wrong answer — hand it to the model,
    // which is good at questions about DATA, and say which is which.
    out.innerHTML = `<div class="customer-dropdown-empty" style="padding:0 0 10px;">
        Nothing in the guides matches “${escHtml(q)}”.</div>
      <button class="btn btn-primary kc-ic kc-ic-bot" style="white-space:normal;text-align:left;"
        onclick="closeDynamicModal();openAssistantModal('${escJs(q)}')">Ask the assistant instead</button>
      <div style="font-size:var(--fs-micro);color:var(--muted);margin-top:6px;">
        It answers questions about the shop's own numbers — who owes, what is overdue.</div>`;
    return;
  }

  const item = (g, open) => `
    <details class="kc-howto" ${open ? 'open' : ''}>
      <summary>${escHtml(g.q)}</summary>
      <ol class="kc-howto-steps">${g.steps.map(st => `<li>${escHtml(st)}</li>`).join('')}</ol>
      <button class="btn btn-primary btn-sm" onclick="howToTakeMeThere('${escJs(g.id)}')">→ ${escHtml(g.go)}</button>
    </details>`;

  if (q) {
    out.innerHTML = list.map((g, i) => item(g, list.length === 1 || i === 0)).join('');
    return;
  }

  // Nothing typed: this screen's jobs first, under a heading that says so, then
  // everything else. The heading matters — without it the reordering is
  // invisible and reads as an arbitrary order.
  const split = window.kcGuidesByScreen
    ? window.kcGuidesByScreen(currentTab, all)
    : { here: [], rest: all };
  const head = (t) => `<div style="font-size:var(--fs-micro);font-weight:700;text-transform:uppercase;
    letter-spacing:.04em;color:var(--muted);margin:2px 0 6px;">${escHtml(t)}</div>`;
  out.innerHTML =
    (split.here.length
      ? head(`On this screen — ${TAB_META[currentTab]?.label || 'here'}`)
        + split.here.map(g => item(g, split.here.length === 1)).join('')
        + head('Everything else')
      : '')
    + split.rest.map(g => item(g, false)).join('');
}

// "Take me there": the answer ends where the work starts, not with the reader
// hunting for the screen it just described.
function howToTakeMeThere(id) {
  const g = howToGuides().find(x => x.id === id);
  if (!g) return;
  closeDynamicModal();
  goToTab(g.tab);
  // The tab's own primary button is the action the guide was describing, so
  // the guides never repeat a list of button names that could go stale.
  const primary = TAB_META[g.tab]?.primary;
  if (primary && /^(Open (New|the till)|Open Tickets|Open Repairs|Open SIM|Open Virtual|Open Customers)/.test(g.go)) {
    setTimeout(() => primary.run(), 200);
  }
}

// ── In-house AI assistant — "Ask / do anything" ──
// Gemini (server) turns plain language into ONE structured action; the client
// answers reads from data it already holds, and shows a confirm card for any
// write before running it through the app's existing flow. Money actions are
// owner-only. Gemini proposes; only a human tap makes anything happen.
let assistantBusy = false;
let assistantPending = null;

function openAssistantModal(prefill) {
  showDynamicModal(`
    <div class="modal-title kc-ic kc-ic-bot">Ask Kosher Connect</div>
    <div style="font-size:var(--fs-small);color:var(--muted);margin-bottom:10px;">Ask a question or say what you want to do — e.g. “who owes money?”, “overdue rentals”, “what's Abraham Diamant's balance?”, “draft a reminder for Yoel Kahana”, “create a £50 payment link for Shloime Grinfeld”, “add a task to order chargers”. Anything that makes a change is shown for you to confirm first.</div>
    <div style="display:flex;gap:8px;align-items:flex-end;">
      <input class="form-input" id="askInput" placeholder="Type here…" style="flex:1;" onkeydown="if(event.key==='Enter')runAssistant()">
      <button class="btn btn-primary" id="askGo" onclick="runAssistant()">Ask</button>
    </div>
    <div id="askOut" style="margin-top:14px;"></div>
  `);
  setTimeout(() => { const i = document.getElementById('askInput'); if (i) { if (prefill) i.value = prefill; i.focus(); if (prefill) runAssistant(); } }, 40);
}
async function runAssistant() {
  if (assistantBusy) return;
  const input = document.getElementById('askInput');
  const msg = input && input.value.trim();
  const out = document.getElementById('askOut');
  if (!msg) return;
  // A "how do I…" question is answered from the curated library first — no
  // network, no cost, and the same right answer every time. The model is good
  // at questions about the shop's DATA; it is the wrong thing to ask how the
  // shop works, because the person asking cannot tell a confident wrong answer
  // from a right one. (owner, 08-17)
  const guide = window.kcBestGuide ? window.kcBestGuide(msg) : null;
  if (guide && /\b(how|where|what).{0,30}\b(do|does|is|are|can)\b/i.test(msg)) {
    if (out) out.innerHTML = `
      <div style="font-size:var(--fs-body);font-weight:600;margin-bottom:8px;">${escHtml(guide.q)}</div>
      <ol class="kc-howto-steps">${guide.steps.map(st => `<li>${escHtml(st)}</li>`).join('')}</ol>
      <button class="btn btn-primary btn-sm" onclick="howToTakeMeThere('${escJs(guide.id)}')">→ ${escHtml(guide.go)}</button>
      <button class="btn btn-outline btn-sm" style="margin-left:6px;" onclick="closeDynamicModal();openHowToModal()">All guides</button>`;
    return;
  }
  assistantBusy = true; assistantPending = null;
  const btn = document.getElementById('askGo'); if (btn) { btn.disabled = true; btn.textContent = '…'; }
  if (out) out.innerHTML = '<div style="color:var(--muted);font-size:var(--fs-body);">Thinking…</div>';
  try {
    const r = await kcFetch('/api/assistant/ask', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ message: msg }) });
    const j = await r.json().catch(() => ({}));
    if (!r.ok || !j.success) { if (out) out.innerHTML = `<div style="color:var(--danger-ink);font-size:var(--fs-body);">${escHtml(j.error || 'Could not understand that.')}</div>`; return; }
    await dispatchAssistant(j.plan, out);
  } catch { if (out) out.innerHTML = '<div style="color:var(--danger-ink);font-size:var(--fs-body);">Could not reach the assistant.</div>'; }
  finally { assistantBusy = false; if (btn) { btn.disabled = false; btn.textContent = 'Ask'; } }
}
async function dispatchAssistant(plan, out) {
  if (!out) return;
  if (!plan) { out.textContent = 'No answer.'; return; }
  const reply = plan.reply ? `<div style="font-size:var(--fs-body);margin-bottom:10px;">${escHtml(plan.reply)}</div>` : '';
  const a = plan.action || 'none';
  if (a === 'who_owes') { out.innerHTML = reply + await assistantWhoOwes(); return; }
  if (a === 'customer_info') { out.innerHTML = reply + await assistantCustomerInfo(plan.args && plan.args.name); return; }
  if (a === 'overdue_rentals') { out.innerHTML = reply + assistantOverdue(); return; }
  // There is no 'cashup' TAB — it's a modal. goToTab() clicked a nav item that
  // doesn't exist and optional chaining swallowed the miss, so the announced
  // action did nothing, every time.
  if (a === 'todays_takings') { out.innerHTML = reply + '<div style="font-size:var(--fs-body);">Opening the cash-up screen…</div>'; setTimeout(() => { closeDynamicModal(); openCashupModal(); }, 700); return; }
  if (['draft_reminder', 'create_payment_link', 'add_task', 'mark_task_done'].includes(a)) { out.innerHTML = reply + await assistantConfirmCard(plan); return; }
  out.innerHTML = reply || '<div style="font-size:var(--fs-body);color:var(--muted);">I can help with balances, who owes, overdue rentals, reminders, payment links and tasks.</div>';
}
function assistantNameOf(id) { const c = customers.find(x => String(x.id) === String(id)); return c ? `${c.firstName || ''} ${c.lastName || ''}`.trim() : ('#' + id); }
async function assistantWhoOwes() {
  try {
    const r = await kcFetch('/api/ledger');
    const j = await r.json().catch(() => ({}));
    if (!r.ok || !j.success) return '<div style="color:var(--danger-ink);font-size:var(--fs-body);">Could not load balances.</div>';
    const owers = (j.arrears || []).slice().sort((a, b) => Math.abs(Number(b.balance)) - Math.abs(Number(a.balance)));
    if (!owers.length) return '<div style="color:var(--success);font-size:var(--fs-body);">Nobody is in debt right now.</div>';
    const total = owers.reduce((s, b) => s + Math.abs(Number(b.balance) || 0), 0);
    const rows = owers.slice(0, 40).map((b) =>
      `<div style="display:flex;justify-content:space-between;gap:8px;padding:5px 0;border-bottom:1px solid var(--border);font-size:var(--fs-body);">
        <button style="background:none;border:0;color:var(--accent);cursor:pointer;padding:0;text-align:start;" onclick="openCustomerById('${escHtml(String(b.customerId))}')">${escHtml(assistantNameOf(b.customerId))}</button>
        <span style="color:var(--danger-ink);font-weight:600;">${fmtGbp(Math.abs(Number(b.balance)))}</span>
      </div>`).join('');
    return `<div style="font-size:var(--fs-small);color:var(--muted);margin-bottom:6px;">${owers.length} owing · ${fmtGbp(total)} total</div><div style="max-height:280px;overflow:auto;">${rows}</div>`;
  } catch { return '<div style="color:var(--danger-ink);font-size:var(--fs-body);">Could not load balances.</div>'; }
}
async function assistantCustomerInfo(name) {
  const res = assistantResolve(name);
  if (res.none) return `<div style="color:var(--muted);font-size:var(--fs-body);">I couldn’t find a customer called “${escHtml(name || '')}”.</div>`;
  if (res.choices) return `<div style="font-size:var(--fs-body);margin-bottom:6px;">A few match — open one:</div>${assistantChooserHtml(res.choices)}`;
  const c = res.customer;
  let bal = null;
  if (customerLedgerBal && customerLedgerBal.has(String(c.id))) bal = customerLedgerBal.get(String(c.id));
  else { try { const r = await kcFetch('/api/ledger'); const j = await r.json().catch(() => ({})); if (j && j.success) { const hit = [...(j.arrears || []), ...(j.credits || [])].find((b) => String(b.customerId) === String(c.id)); if (hit) bal = Number(hit.balance); } } catch {} }
  const owes = bal != null && bal < 0;
  const balHtml = bal == null ? '<span style="color:var(--muted);">settled / no balance on file</span>'
    : `<span style="color:${owes ? 'var(--danger-ink)' : 'var(--success)'};font-weight:700;">${escHtml(KC_MONEY.moneySayShort({ balance: bal }).text)}</span>`;
  return `<div style="border:1px solid var(--border);border-radius:10px;padding:12px 14px;font-size:var(--fs-body);">
    <div style="font-weight:600;margin-bottom:4px;">${escHtml(`${c.firstName || ''} ${c.lastName || ''}`.trim())}</div>
    <div style="margin-bottom:8px;">${balHtml}</div>
    <button class="btn btn-outline btn-sm" onclick="openCustomerById('${escHtml(String(c.id))}')">Open customer</button>
  </div>`;
}
function assistantOverdue() {
  const od = rentals.filter((r) => r.status === 'overdue');
  if (!od.length) return '<div style="color:var(--success);font-size:var(--fs-body);">No overdue rentals.</div>';
  const rows = od.map((r) =>
    `<div style="display:flex;justify-content:space-between;gap:8px;padding:5px 0;border-bottom:1px solid var(--border);font-size:var(--fs-body);">
      <button style="background:none;border:0;color:var(--accent);cursor:pointer;padding:0;text-align:start;" onclick="openCustomerById('${escHtml(String(r.customerId))}')">${escHtml(assistantNameOf(r.customerId))}</button>
      <span style="color:var(--muted);">${r.phoneNumber ? escHtml(r.phoneNumber) + ' · ' : ''}due ${r.toDate ? fmtDate(r.toDate) : '—'}</span>
    </div>`).join('');
  return `<div style="font-size:var(--fs-small);color:var(--muted);margin-bottom:6px;">${od.length} overdue</div><div style="max-height:280px;overflow:auto;">${rows}</div>`;
}
function assistantResolve(name) {
  const q = String(name || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').trim();
  if (!q) return { none: true };
  const scored = customers.map((c) => {
    const full = `${c.firstName || ''} ${c.lastName || ''}`.toLowerCase().replace(/[^a-z0-9 ]/g, '').trim();
    let score = 0;
    if (full === q) score = 100;
    else if (full.startsWith(q) || q.startsWith(full)) score = 70;
    else if (full.includes(q) || q.split(' ').every((w) => w && full.includes(w))) score = 50;
    return { c, score };
  }).filter((x) => x.score > 0).sort((a, b) => b.score - a.score);
  if (!scored.length) return { none: true };
  const top = scored[0];
  const ties = scored.filter((x) => x.score === top.score);
  if (top.score === 100 || ties.length === 1) return { customer: top.c };
  if (ties.length > 6) return { customer: top.c };
  return { choices: ties.map((x) => x.c) };
}
function assistantChooserHtml(choices) {
  return choices.map((c) => `<button style="display:block;width:100%;text-align:start;background:none;border:1px solid var(--border);border-radius:8px;padding:6px 10px;margin-bottom:4px;color:var(--accent);cursor:pointer;" onclick="openCustomerById('${escHtml(String(c.id))}')">${escHtml(`${c.firstName || ''} ${c.lastName || ''}`.trim())}</button>`).join('');
}
async function assistantConfirmCard(plan) {
  const built = await assistantBuildAction(plan);
  if (built.error) return `<div style="color:var(--danger-ink);font-size:var(--fs-body);">${built.error}</div>`;
  if (built.choicesHtml) return built.choicesHtml;
  assistantPending = built;
  return `<div style="border:1px solid var(--border);border-radius:10px;padding:12px 14px;">
    <div style="font-size:var(--fs-body);margin-bottom:10px;">${built.summary}</div>
    <div style="display:flex;gap:8px;">
      <button class="btn btn-primary btn-sm" onclick="assistantConfirm()">✓ Do it</button>
      <button class="btn btn-outline btn-sm" onclick="assistantPending=null;var o=document.getElementById('askOut');if(o)o.innerHTML='';">Cancel</button>
    </div>
  </div>`;
}
function assistantConfirm() {
  const p = assistantPending; assistantPending = null;
  if (p && typeof p.run === 'function') p.run();
}
async function assistantBuildAction(plan) {
  const a = plan.action; const args = plan.args || {};
  const needsCust = (a === 'draft_reminder' || a === 'create_payment_link' || (a === 'add_task' && args.name));
  let cust = null;
  if (needsCust) {
    const res = assistantResolve(args.name);
    if (res.none) return { error: `I couldn’t find a customer called “${escHtml(args.name || '')}”.` };
    if (res.choices) return { choicesHtml: `<div style="font-size:var(--fs-body);margin-bottom:6px;">Several match “${escHtml(args.name)}” — say the surname too, or open one:</div>${assistantChooserHtml(res.choices)}` };
    cust = res.customer;
  }
  const cn = cust ? `${cust.firstName || ''} ${cust.lastName || ''}`.trim() : '';
  if (a === 'draft_reminder') {
    return { summary: `Open a <strong>reminder draft</strong> for <strong>${escHtml(cn)}</strong>${args.note ? ` about “${escHtml(String(args.note))}”` : ''}. Nothing is sent.`,
      run: () => { closeDynamicModal(); openDraftReminderModal(cust.id); } };
  }
  if (a === 'create_payment_link') {
    if (currentStaff && currentStaff.role !== 'owner') return { error: 'Only the owner can create payment links.' };
    const amt = Number(args.amount);
    const hasAmt = Number.isFinite(amt) && amt > 0;
    return { summary: `Create a <strong>Stripe payment link</strong> for <strong>${escHtml(cn)}</strong>${hasAmt ? ` for <strong>${fmtGbp(amt)}</strong>` : ''}${args.description ? ` (${escHtml(String(args.description))})` : ''}.`,
      run: () => { closeDynamicModal(); openPaymentLinkModal(cust.id); setTimeout(() => { const el = document.getElementById('plAmount'); if (el && hasAmt) el.value = amt.toFixed(2); const de = document.getElementById('plDesc'); if (de && args.description) de.value = String(args.description).slice(0, 120); }, 150); } };
  }
  if (a === 'add_task') {
    const title = String(args.title || '').trim();
    if (!title) return { error: 'What should the task say?' };
    return { summary: `Add a task: <strong>${escHtml(title)}</strong>${cust ? ` (linked to ${escHtml(cn)})` : ''}.`,
      run: async () => { try { const r = await window.api.addTask({ title, customerId: cust ? cust.id : undefined }); if (r && (r.success || r.task)) { toast('Task added.', 'success'); if (currentTab === 'tasks') renderTasksTab(); const o = document.getElementById('askOut'); if (o) o.innerHTML = '<div style="color:var(--success);font-size:var(--fs-body);">✓ Task added.</div>'; } else toast('Could not add task.', 'error'); } catch { toast('Could not add task.', 'error'); } } };
  }
  if (a === 'mark_task_done') {
    const hint = String(args.task || '').toLowerCase().trim();
    if (!hint) return { error: 'Which task?' };
    let list = [];
    try { const t = await window.api.getTasks(); if (Array.isArray(t)) list = t.filter((x) => !x.done); } catch {}
    const matches = list.filter((x) => { const tl = String(x.title || '').toLowerCase(); return tl.includes(hint) || hint.split(' ').every((w) => w && tl.includes(w)); });
    if (!matches.length) return { error: `I couldn’t find an open task matching “${escHtml(hint)}”.` };
    if (matches.length > 1) return { error: `Several open tasks match “${escHtml(hint)}” — please be more specific.` };
    const tk = matches[0];
    return { summary: `Mark done: <strong>${escHtml(tk.title)}</strong>.`,
      run: async () => { try { const r = await window.api.updateTask({ id: tk.id, done: true }); if (r && (r.success || r.task)) { toast('Marked done.', 'success'); if (currentTab === 'tasks') renderTasksTab(); const o = document.getElementById('askOut'); if (o) o.innerHTML = '<div style="color:var(--success);font-size:var(--fs-body);">✓ Done.</div>'; } else toast('That task is still open — try again.', 'error'); } catch { toast('That task is still open — check the connection and try again.', 'error'); } } };
  }
  return { error: 'I’m not sure how to do that yet.' };
}

